    public string Login(HttpContext context, string? error = null)
    {
        var returnUrl = context.Request.Query["returnUrl"].ToString();
        var returnUrlField = string.IsNullOrWhiteSpace(returnUrl)
            ? ""
            : $"""<input type="hidden" name="returnUrl" value="{A(returnUrl)}">""";
        var de = Language(context) == "de";
        var query = context.Request.Query;
        var sso = context.RequestServices.GetService<Services.SsoSettings>();
        error ??= query["sso"].ToString() switch
        {
            "failed" => de ? "Die Anmeldung über den Dienst hat nicht geklappt. Versuch es noch einmal." : "Signing in through the service did not work. Please try again.",
            "disabled" => de ? "Dieses Konto ist in Matgate gesperrt." : "This account is disabled in Matgate.",
            _ => null,
        };
        var errorHtml = string.IsNullOrWhiteSpace(error)
            ? ""
            : $"""<div class="notice error">{E(error)}</div>""";
        var linking = query["link"] == "1";
        if (linking)
        {
            errorHtml += $"""<div class="notice" data-sso-link-notice>{E(de
                ? "Für diese Adresse gibt es in Matgate schon ein Konto. Melde dich einmal mit dessen Passwort an - danach geht es auch über den Dienst."
                : "There already is a Matgate account for this address. Sign in with its password once - from then on the service works as well.")}</div>""";
        }

        var ssoButtons = sso is null || sso.Providers.Count == 0 || linking
            ? ""
            : $$"""
                <div class="login-sso" data-login-sso>
                    {{string.Join("", sso.Providers.Select(provider => $$"""<a class="button login-sso-button" href="/login/sso/{{provider.Key}}{{(string.IsNullOrWhiteSpace(returnUrl) ? "" : "?returnUrl=" + Uri.EscapeDataString(returnUrl))}}" data-sso="{{provider.Key}}">{{Icon(provider.Key == Services.SsoProvider.Entra ? "grid" : "shield")}}{{E(de ? $"Mit {provider.Label} anmelden" : $"Sign in with {provider.Label}")}}</a>"""))}}
                </div>
                """;
        // Only the services, when so configured - the form stays reachable with ?local=1 (and for linking).
        var showForm = sso is null || !sso.SsoOnly || linking || query["local"] == "1";
        var divider = ssoButtons.Length > 0 && showForm ? $"""<div class="login-divider"><span>{E(de ? "oder mit Passwort" : "or with a password")}</span></div>""" : "";

        var body = $$"""
            <section class="login-shell">
                <div class="login-card">
                    {{LoginAside(context)}}
                    <div class="login-pane">
                    <h1 class="login-title">{{T(context, "Sign in")}}</h1>
                    <p class="login-sub">{{(Language(context) == "de" ? "Melde dich an, um deine Verbindungen zu öffnen." : "Sign in to open your connections.")}}</p>
                    {{errorHtml}}
                    {{ssoButtons}}
                    {{divider}}
                    <style>
                        .login-sso { display: grid; gap: 8px; margin: 4px 0 8px; }
                        .login-form[hidden] { display: none; }
                        .login-sso-button { justify-content: center; min-height: 44px; width: 100%; }
                        .login-divider { align-items: center; color: var(--muted); display: flex; font-size: 13px; gap: 10px; margin: 10px 0; }
                        .login-divider::before, .login-divider::after { border-top: 1px solid var(--line); content: ""; flex: 1; }
                    </style>
                    <form method="post" action="/login" class="login-form"{{(showForm ? "" : " hidden")}}>
                        {{returnUrlField}}
                        <label class="login-field"><span>{{T(context, "Username or email")}}</span>
                            <span class="login-input-wrap">{{Icon("user")}}<input name="username" autocomplete="username" required autofocus></span>
                        </label>
                        <label class="login-field"><span>{{T(context, "Password")}}</span>
                            <span class="login-input-wrap">{{Icon("key")}}<input name="password" type="password" autocomplete="current-password" required></span>
                        </label>
                        <button type="submit" class="login-submit">{{Icon("arrow-right")}}{{T(context, "Sign in")}}</button>
                    </form>
                    </div>
                </div>
            </section>
            """;

        return Layout(context, null, "Login", body, "login-main");
    }

    // The brand's side of the sign-in pages: the mark, the name, and in three lines what this is.
    private static string LoginAside(HttpContext context)
    {
        var de = Language(context) == "de";
        return $$"""
            <aside class="login-aside">
                <div class="login-brand">
                    <span class="login-glyph" aria-hidden="true"><svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg"><path d="M17 48 V16 H47 V48 H40 V23 H24 V48 Z" fill="currentColor"/></svg></span>
                    <span class="login-word"><span>MAT</span>GATE</span>
                </div>
                <p class="login-tagline">{{(de ? "Deine Rechner, Dateien und Seiten – von überall, im Browser." : "Your machines, files and pages – from anywhere, in the browser.")}}</p>
                <ul class="login-points">
                    <li>{{Icon("monitor")}}<span>{{(de ? "RDP, VNC und SSH ohne Client" : "RDP, VNC and SSH without a client")}}</span></li>
                    <li>{{Icon("folder")}}<span>{{(de ? "Dateien über SFTP, SMB, FTP und WebDAV" : "Files over SFTP, SMB, FTP and WebDAV")}}</span></li>
                    <li>{{Icon("globe")}}<span>{{(de ? "Ein Browser im eigenen Netz" : "A browser inside your network")}}</span></li>
                </ul>
            </aside>
            """;
    }

    // The second step of signing in. Nobody is signed in here yet - what brings the browser here
    // is a short-lived, signed ticket in a cookie of its own, not half a session. That is also why
    // no name is shown: whoever does not have the password should not learn from this page whether
    // an account exists.
    public string TotpChallenge(HttpContext context, string? error = null)
    {
        var de = Language(context) == "de";
        var errorHtml = string.IsNullOrWhiteSpace(error)
            ? ""
            : $"""<div class="notice error">{E(error)}</div>""";

        var body = $$"""
            <section class="login-shell">
                <div class="login-card">
                    {{LoginAside(context)}}
                    <div class="login-pane">
                    <h1 class="login-title">{{(de ? "Zweiter Schritt" : "Second step")}}</h1>
                    <p class="login-sub">{{(de
                        ? "Der sechsstellige Code aus deiner Authenticator-App. Ein Wiederherstellungs-Code geht auch."
                        : "The six-digit code from your authenticator app. A recovery code works too.")}}</p>
                    {{errorHtml}}
                    <form method="post" action="/login/totp" class="login-form">
                        <label class="login-field"><span>{{(de ? "Code" : "Code")}}</span>
                            <span class="login-input-wrap">{{Icon("key")}}<input name="code" inputmode="numeric" autocomplete="one-time-code" autofocus required spellcheck="false"></span>
                        </label>
                        <button type="submit" class="login-submit">{{Icon("arrow-right")}}{{T(context, "Sign in")}}</button>
                    </form>
                    <p class="login-sub"><a href="/login">{{(de ? "Noch einmal von vorn" : "Start over")}}</a></p>
                    </div>
                </div>
            </section>
            """;

        return Layout(context, null, "Login", body, "login-main");
    }

    // First-run setup wizard: shown only while no user exists (see /setup endpoints); creates the
    // administrator account with username + email + password.
    public string Setup(HttpContext context, string? error = null, string? userName = null, string? email = null)
    {
        var errorHtml = string.IsNullOrWhiteSpace(error)
            ? ""
            : $"""<div class="notice error">{E(error)}</div>""";

        var body = $$"""
            <section class="login-shell">
                <div class="login-card login-card-wide">
                    {{LoginAside(context)}}
                    <div class="login-pane">
                    <h1 class="login-title">{{T(context, "Initial setup")}}</h1>
                    <p class="login-sub">{{T(context, "Welcome to Matgate! Create the administrator account to get started.")}}</p>
                    {{errorHtml}}
                    <form method="post" action="/setup" class="login-form">
                        <label class="login-field"><span>{{T(context, "Username")}}</span>
                            <span class="login-input-wrap">{{Icon("user")}}<input name="username" autocomplete="username" required autofocus minlength="3" maxlength="64" value="{{A(userName ?? "")}}"></span>
                        </label>
                        <label class="login-field"><span>{{T(context, "Email")}}</span>
                            <span class="login-input-wrap">{{Icon("mail")}}<input name="email" type="email" autocomplete="email" required maxlength="200" value="{{A(email ?? "")}}"></span>
                        </label>
                        <label class="login-field"><span>{{T(context, "Password")}}</span>
                            <span class="login-input-wrap">{{Icon("key")}}<input name="password" type="password" autocomplete="new-password" minlength="10" required></span>
                        </label>
                        <label class="login-field"><span>{{T(context, "Confirm password")}}</span>
                            <span class="login-input-wrap">{{Icon("key")}}<input name="passwordConfirm" type="password" autocomplete="new-password" minlength="10" required></span>
                        </label>
                        <button type="submit" class="login-submit">{{Icon("arrow-right")}}{{T(context, "Create admin account")}}</button>
                    </form>
                    </div>
                </div>
            </section>
            """;

        return Layout(context, null, T(context, "Initial setup"), body, "login-main");
    }

    public string Dashboard(HttpContext context, MatgateUser user, IReadOnlyList<ServerEndpoint> servers)
    {
        var cards = servers.Count == 0
            ? $"""<div class="empty">{T(context, "No global servers yet. An administrator can create servers and grant access.")}</div>"""
            : string.Join("", servers.Select(server => $$"""
                <article class="card">
                    <div class="row split">
                        <div class="server-title">
                            {{ServerIcon(server)}}
                            <div>
                                <span class="badge">{{E(ServerProtocolLabel(server.Protocol))}}</span>
                                {{ServerScopeBadge(context, server, currentUser: user)}}
                                <h2>{{E(server.Name)}}</h2>
                            </div>
                        </div>
                        <a class="button primary" href="/sessions?open={{server.Id}}">{{Icon("play")}}{{(server.Protocol == ServerProtocol.Website ? T(context, "Open") : T(context, "Connect"))}}</a>
                    </div>
                    <p class="target">{{E(ServerTargetValue(server))}}</p>
                    <p class="muted">{{E(server.Notes)}}</p>
                </article>
                """));

        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Home")}}</p>
                    <h1>{{T(context, "Connections")}}</h1>
                </div>
            </section>
            <section class="grid">
                {{cards}}
            </section>
            """;

        return Layout(context, user, T(context, "Home"), body);
    }

    public string Users(HttpContext context, MatgateUser currentUser, IReadOnlyList<MatgateUser> users)
    {
        var rows = users.Count == 0
            ? $"""<tr><td colspan="4" class="muted">{T(context, "No users created yet.")}</td></tr>"""
            : string.Join("", users.OrderBy(user => user.UserName).Select(user => $$"""
                <tr>
                    <td><a href="/admin/users/{{user.Id}}">{{E(user.UserName)}}</a></td>
                    <td>{{E(user.DisplayName)}}</td>
                    <td>{{RoleLabels(context, user)}}</td>
                    <td>{{(user.IsEnabled ? T(context, "Active") : T(context, "Locked"))}}</td>
                </tr>
                """));

        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Administration")}}</p>
                    <h1>{{T(context, "Users")}}</h1>
                </div>
                <a class="button primary" href="/admin/users/new">{{Icon("plus")}}{{T(context, "Create user")}}</a>
            </section>
            <section class="panel">
                <h2>{{T(context, "Existing users")}}</h2>
                <div class="table-wrap">
                    <table>
                        <thead><tr><th>{{T(context, "Name")}}</th><th>{{T(context, "Display")}}</th><th>{{T(context, "Roles")}}</th><th>{{T(context, "Status")}}</th></tr></thead>
                        <tbody>{{rows}}</tbody>
                    </table>
                </div>
            </section>
            """;

        return Layout(context, currentUser, T(context, "Users"), body);
    }

    public string UserCreate(HttpContext context, MatgateUser currentUser)
    {
        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "User")}}</p>
                    <h1>{{T(context, "Create user")}}</h1>
                </div>
                <a class="button" href="/admin/users">{{Icon("users")}}{{T(context, "Users")}}</a>
            </section>
            <form method="post" action="/admin/users" class="stack">
                {{Csrf(context)}}
                <section class="panel">
                    <h2>{{T(context, "Profile")}}</h2>
                    <div class="form-grid">
                        <label><span>{{T(context, "Username")}}<span class="req" aria-hidden="true">*</span></span>
                            <input name="username" required aria-required="true" minlength="3" maxlength="64">
                        </label>
                        <label>{{T(context, "Email (optional)")}}
                            <input name="email" type="email" maxlength="200">
                        </label>
                        <label>{{T(context, "Display name")}}
                            <input name="displayName">
                        </label>
                        <label><span>{{T(context, "Initial password")}}<span class="req" aria-hidden="true">*</span></span>
                            <input name="password" type="password" minlength="10" required aria-required="true">
                        </label>
                    <label>{{T(context, "Preferred language")}}
                        <select name="preferredLanguage">
                            {{LanguageOptions(context, "en")}}
                        </select>
                    </label>
                    <label>{{T(context, "Preferred theme")}}
                        <select name="preferredTheme">
                            {{ThemeOptions(context, "system")}}
                        </select>
                    </label>
                </div>
            </section>
                <section class="panel">
                    <h2>{{T(context, "Permissions")}}</h2>
                    <div class="form-grid">
                        <label class="check"><input type="checkbox" name="isAdmin"> {{T(context, "Administrator")}}</label>
                        <label class="check"><input type="checkbox" name="canManageServers"> {{T(context, "Manage servers")}}</label>
                        <label class="check"><input type="checkbox" name="canCreateServers"> {{T(context, "Can create own servers")}}</label>
                        <label class="check"><input type="checkbox" name="canQuickConnect"> {{(Language(context) == "de" ? "Quick-Connect erlauben" : "Allow quick connect")}}</label>
                        <label class="check"><input type="checkbox" name="fileShareGlobal"> {{(Language(context) == "de" ? "Ordner \"Global\" (für alle Benutzer)" : "\"Global\" folder (shared with everyone)")}}</label>
                        <label class="check"><input type="checkbox" name="fileShareConnection"> {{(Language(context) == "de" ? "Ordner \"Connection\" (je Verbindung)" : "\"Connection\" folder (one per connection)")}}</label>
                        <label class="check"><input type="checkbox" name="fileSharePersonal" checked> {{(Language(context) == "de" ? "Ordner \"User\" (eigener Ordner)" : "\"User\" folder (their own)")}}</label>
                    </div>
                </section>
                <div class="actions">
                    <button type="submit" class="primary">{{Icon("plus")}}{{T(context, "Create")}}</button>
                </div>
            </form>
            """;

        return Layout(context, currentUser, T(context, "Create user"), body);
    }

    public string UserDetail(
        HttpContext context,
        MatgateUser currentUser,
        MatgateUser editedUser,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<UserGroup>? groups = null,
        IReadOnlyList<AccessGrant>? grants = null)
    {
        var de = Language(context) == "de";
        groups ??= [];
        grants ??= [];
        var mine = grants.Where(grant => grant.PrincipalKind == AccessPrincipalKind.User && grant.PrincipalId == editedUser.Id).ToList();
        var disabled = editedUser.IsAdmin ? " disabled" : "";
        var sharedServers = servers.Where(server => server.OwnerUserId is null)
            .OrderBy(server => server.FolderName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(server => server.Name, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var allLevel = mine.FirstOrDefault(grant => grant.TargetKind == AccessTargetKind.All)?.Level ?? AccessLevel.None;
        var accessRows = sharedServers.Count == 0
            ? $"""<tr><td colspan="6" class="muted">{T(context, "No global servers created yet.")}</td></tr>"""
            : string.Join("", sharedServers.Select(server =>
            {
                var direct = mine.FirstOrDefault(grant => grant.Targets(AccessTargetKind.Server, server.Id))?.Level ?? AccessLevel.None;
                var reasons = Services.AccessResolver.Reasons(editedUser, server);
                var level = Services.AccessResolver.Highest(reasons);
                var isFile = ServerEndpoint.IsFileProtocol(server.Protocol);
                var rule = editedUser.FileAccessRules?.FirstOrDefault(r => r.ServerId == server.Id);
                var fileCell = isFile
                    ? $$"""
                        <label class="check access-file-check"><input type="checkbox" name="readonly_{{server.Id:N}}"{{Checked(rule?.ReadOnly ?? false)}}{{disabled}}> <span>{{(de ? "Immer nur lesen" : "Always read-only")}}</span></label>
                        <input type="text" name="subpath_{{server.Id:N}}" value="{{A(rule?.SubPath ?? "")}}" placeholder="{{A(de ? "Unterordner (optional)" : "Subfolder (optional)")}}"{{disabled}}>
                        """
                    : """<span class="muted">-</span>""";
                return $$"""
                    <tr data-user-access-row="{{A(server.Name)}}" data-effective-level="{{level}}">
                        <td>
                            <span class="server-name-cell">{{ServerIcon(server, "small")}}<a href="/admin/servers/{{server.Id}}">{{E(server.Name)}}</a></span>
                            {{(string.IsNullOrWhiteSpace(server.FolderName) ? "" : $"""<small class="muted">{E(server.FolderName)}</small>""")}}
                        </td>
                        <td><span class="badge">{{E(ServerProtocolLabel(server.Protocol))}}</span></td>
                        <td>{{AccessLevelSelect("level_" + server.Id.ToString("N"), direct, de, withNone: true, disabled)}}</td>
                        <td>{{AccessLevelBadge(level, de)}}</td>
                        <td><div class="access-reasons">{{AccessReasonsHtml(reasons, de)}}</div></td>
                        <td>{{fileCell}}</td>
                    </tr>
                    """;
            }));
        var groupChecks = groups.Count == 0
            ? $"""<p class="muted">{E(de ? "Es gibt noch keine Gruppe." : "There is no group yet.")}</p>"""
            : string.Join("", groups.OrderBy(group => group.Name, StringComparer.OrdinalIgnoreCase).Select(group => $$"""
                <label class="group-check"><input type="checkbox" name="groups" value="{{group.Id}}"{{Checked(group.MemberIds.Contains(editedUser.Id))}}{{disabled}}><span><strong>{{E(group.Name)}}</strong>{{(string.IsNullOrWhiteSpace(group.Description) ? "" : $"""<small class="muted">{E(group.Description)}</small>""")}}</span></label>
                """));

        var deleteButton = currentUser.Id == editedUser.Id
            ? $"""<button type="button" disabled>{Icon("trash")}{T(context, "Cannot delete own user")}</button>"""
            : $"""<button type="submit" class="danger">{Icon("trash")}{T(context, "Delete user")}</button>""";

        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Users")}}</p>
                    <h1>{{E(editedUser.UserName)}}</h1>
                </div>
                <a class="button" href="{{A(AdminUsersUrl(editedUser.Id))}}">{{T(context, "Back")}}</a>
            </section>
            <section class="panel">
                <h2>{{T(context, "Profile")}}</h2>
                <form method="post" action="/admin/users/{{editedUser.Id}}/update" class="settings-form">
                    {{Csrf(context)}}
                    <fieldset class="settings-group">
                        <legend>{{(de ? "Angaben" : "Details")}}</legend>
                        <div class="form-grid">
                            <label>{{T(context, "Display name")}}
                                <input name="displayName" value="{{A(editedUser.DisplayName)}}">
                            </label>
                            <label>{{T(context, "Email (optional)")}}
                                <input name="email" type="email" maxlength="200" value="{{A(editedUser.Email)}}">
                            </label>
                            <label>{{T(context, "Preferred language")}}
                                <select name="preferredLanguage">
                                    {{LanguageOptions(context, editedUser.PreferredLanguage)}}
                                </select>
                            </label>
                            <label>{{T(context, "Preferred theme")}}
                                <select name="preferredTheme">
                                    {{ThemeOptions(context, editedUser.PreferredTheme)}}
                                </select>
                            </label>
                        </div>
                        <label class="check"><input type="checkbox" name="isEnabled"{{Checked(editedUser.IsEnabled)}}> <span>{{T(context, "Enabled")}}</span></label>
                    </fieldset>
                    <fieldset class="settings-group">
                        <legend>{{(de ? "Was dieser Benutzer darf" : "What this user may do")}}</legend>
                        <p class="muted settings-hint">{{(de
                            ? "Ein Administrator darf ohnehin alles - die übrigen Haken fallen dann nicht mehr ins Gewicht."
                            : "An administrator may do everything anyway - the other ticks then no longer carry weight.")}}</p>
                        <label class="check"><input type="checkbox" name="isAdmin"{{Checked(editedUser.IsAdmin)}}> <span>{{T(context, "Administrator")}}</span></label>
                        <label class="check"><input type="checkbox" name="canManageServers"{{Checked(editedUser.CanManageServers)}}> <span>{{T(context, "Manage servers")}}</span></label>
                        <label class="check"><input type="checkbox" name="canCreateServers"{{Checked(editedUser.CanCreateServers)}}> <span>{{T(context, "Can create own servers")}}</span></label>
                        <label class="check"><input type="checkbox" name="canQuickConnect"{{Checked(editedUser.CanQuickConnect)}}> <span>{{(de ? "Quick-Connect erlauben" : "Allow quick connect")}}</span></label>
                    </fieldset>
                    <fieldset class="settings-group">
                        <legend>{{(de ? "Ablagen" : "Places")}}</legend>
                        <p class="muted settings-hint">{{(de
                            ? "Welche Ordner dieser Benutzer im Dateimanager und auf dem umgeleiteten Laufwerk sieht. Eine Änderung wirkt erst, wenn er eine Sitzung neu aufbaut - laufende Sitzungen behalten ihre Ordner."
                            : "Which folders this user sees in the file manager and on the redirected drive. A change takes effect the next time they connect; sessions already running keep their folders.")}}</p>
                        <label class="check"><input type="checkbox" name="fileShareGlobal"{{Checked(editedUser.FileShare.Global)}}> <span>{{(de ? "Ordner \"Global\" (für alle Benutzer)" : "\"Global\" folder (shared with everyone)")}}</span></label>
                        <label class="check"><input type="checkbox" name="fileShareConnection"{{Checked(editedUser.FileShare.Connection)}}> <span>{{(de ? "Ordner \"Connection\" (je Verbindung)" : "\"Connection\" folder (one per connection)")}}</span></label>
                        <label class="check"><input type="checkbox" name="fileSharePersonal"{{Checked(editedUser.FileShare.Personal)}}> <span>{{(de ? "Ordner \"User\" (eigener Ordner)" : "\"User\" folder (their own)")}}</span></label>
                    </fieldset>
                    <div class="actions"><button type="submit" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button></div>
                </form>
            </section>
            <section class="panel" data-user-access>
                <h2>{{(de ? "Gruppen und Zugriff" : "Groups and access")}}</h2>
                <p class="muted settings-lead">{{(de
                    ? (editedUser.IsAdmin
                        ? "Administratoren dürfen ohnehin alles - hier ist deshalb nichts einzustellen."
                        : "Was dieser Benutzer darf, kommt aus seinen Gruppen, aus Freigaben auf Ordnern und aus dem, was er hier direkt bekommt. „Darf“ zeigt, was am Ende gilt, und „Warum“ jeden Grund dafür. Eigene Verbindungen gehören immer ihrem Besitzer.")
                    : (editedUser.IsAdmin
                        ? "Administrators may do everything anyway - so there is nothing to set here."
                        : "What this user may do comes from their groups, from entries on folders and from what they are given here directly. \"May\" shows what holds in the end, \"Why\" every reason for it. Own connections always belong to their owner."))}}</p>
                <form method="post" action="/admin/users/{{editedUser.Id}}/access" class="stack">
                    {{Csrf(context)}}
                    <h3>{{(de ? "Gruppen" : "Groups")}}</h3>
                    <div class="group-checks">{{groupChecks}}</div>
                    <label class="access-all">{{(de ? "Direkt auf alle Verbindungen" : "Directly on all connections")}}{{AccessLevelSelect("level_all", allLevel, de, withNone: true, disabled)}}</label>
                    <div class="table-wrap">
                        <table class="access-table" data-user-access-table>
                            <thead>
                                <tr>
                                    <th>{{T(context, "Name")}}</th>
                                    <th>{{T(context, "Type")}}</th>
                                    <th>{{(de ? "Direkt" : "Directly")}}</th>
                                    <th>{{(de ? "Darf" : "May")}}</th>
                                    <th>{{(de ? "Warum" : "Why")}}</th>
                                    <th>{{(de ? "Dateien" : "Files")}}</th>
                                </tr>
                            </thead>
                            <tbody>{{accessRows}}</tbody>
                        </table>
                    </div>
                    <div class="actions"><button type="submit" class="primary"{{disabled}} data-user-access-save>{{Icon("save")}}{{T(context, "Save access")}}</button></div>
                </form>
            </section>
            {{ExternalLoginsPanel(context, editedUser)}}
            {{AccessStyles}}
            <style>
                .group-checks { display: grid; gap: 6px; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); margin: 6px 0 12px; }
                .group-check { align-items: flex-start; border: 1px solid var(--line); border-radius: 10px; cursor: pointer; display: flex; gap: 10px; padding: 8px 10px; }
                .group-check:has(input:checked) { background: color-mix(in srgb, var(--accent) 10%, var(--surface)); border-color: var(--accent); }
                .group-check span { display: grid; min-width: 0; }
                .access-all { align-items: center; display: flex; flex-wrap: wrap; gap: 10px; margin: 4px 0 10px; }
                .access-file-check { font-size: 13px; margin-bottom: 4px; }
                [data-user-access-table] td small { display: block; }
            </style>
            <section class="panel" id="password">
                <h2>{{T(context, "Password")}}</h2>
                <p class="muted settings-lead">{{(de
                    ? "Mindestens 10 Zeichen. Der Benutzer bleibt angemeldet, wo er es schon ist - sag ihm das neue Passwort auf einem anderen Weg als per Mail."
                    : "At least 10 characters. The user stays signed in where they already are - tell them the new password by some route other than email.")}}</p>
                <form method="post" action="/admin/users/{{editedUser.Id}}/password" class="form-grid">
                    {{Csrf(context)}}
                    <label>{{T(context, "New password")}}
                        <input name="password" type="password" minlength="10" required>
                    </label>
                    <div class="actions"><button type="submit" class="primary">{{Icon("key")}}{{T(context, "Set password")}}</button></div>
                </form>
            </section>
            <section class="panel">
                <h2>{{(Language(context) == "de" ? "Zwei-Faktor-Anmeldung" : "Two-factor sign-in")}}</h2>
                {{(editedUser.TotpEnabled
                    ? $$"""
                        <p class="muted settings-lead">{{(Language(context) == "de"
                            ? $"Eingeschaltet, {editedUser.TotpRecoveryHashes.Count} Wiederherstellungs-Codes übrig. Abschalten hilft, wenn Telefon und Codes weg sind - danach ist das Konto wieder nur durch das Passwort geschützt, bis es neu eingerichtet wird."
                            : $"On, {editedUser.TotpRecoveryHashes.Count} recovery codes left. Switching it off helps when the phone and the codes are gone - after that the account is protected by the password alone until it is set up again.")}}</p>
                        <form method="post" action="/admin/users/{{editedUser.Id}}/totp-reset">
                            {{Csrf(context)}}
                            <div class="actions"><button type="submit" class="danger">{{Icon("x")}}{{(Language(context) == "de" ? "Zwei-Faktor abschalten" : "Turn two-factor off")}}</button></div>
                        </form>
                        """
                    : $$"""<p class="muted settings-lead">{{(Language(context) == "de" ? "Nicht eingeschaltet. Einrichten kann sie nur der Benutzer selbst - das Geheimnis darf niemand sonst zu sehen bekommen." : "Not on. Only the user can set it up - nobody else may get to see the secret.")}}</p>""")}}
            </section>
            <section class="panel danger-zone">
                <h2>{{T(context, "Remove")}}</h2>
                <form method="post" action="/admin/users/{{editedUser.Id}}/delete">
                    {{Csrf(context)}}
                    {{deleteButton}}
                </form>
            </section>
            """;

        return Layout(context, currentUser, Language(context) == "de" ? "Benutzer bearbeiten" : "Edit user", body);
    }

    // Unified admin: one tabbed page (Servers | Users | Workspaces) built on the reusable
    // Tabs + DataTable controls. Create/edit stay on separate sub-pages; rows offer open/edit
    // links and an inline (confirmed) delete.
    public string AdminHome(
        HttpContext context,
        MatgateUser currentUser,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<MatgateUser> users,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        BrowserAdminData? browser = null,
        IReadOnlyList<UserGroup>? groups = null,
        IReadOnlyList<FolderDefinition>? folderObjects = null,
        IReadOnlyList<AccessGrant>? grants = null,
        string connectionsAccess = "")
    {
        var de = Language(context) == "de";
        var openLabel = T(context, "Open");
        var editLabel = de ? "Bearbeiten" : "Edit";
        var deleteLabel = de ? "Löschen" : "Delete";
        var confirmDelete = de ? "Wirklich löschen?" : "Delete this entry?";

        string DeleteForm(string action) => $$"""<form method="post" action="{{action}}" data-confirm="{{A(confirmDelete)}}">{{Csrf(context)}}<button type="submit" class="icon-button danger-action" title="{{A(deleteLabel)}}" aria-label="{{A(deleteLabel)}}">{{Icon("trash")}}</button></form>""";
        string EditLink(string href) => $$"""<a class="icon-button" href="{{href}}" title="{{A(editLabel)}}" aria-label="{{A(editLabel)}}">{{Icon("edit")}}</a>""";

        var serverRows = string.Join("", servers.Select(server => $$"""
            <tr>
                <td><span class="server-name-cell">{{ServerIcon(server, "small")}}<a href="/admin/servers/{{server.Id}}">{{E(server.Name)}}</a></span></td>
                <td>{{ServerScopeBadge(context, server, users)}}</td>
                <td>{{(string.IsNullOrWhiteSpace(server.FolderName) ? "<span class=\"muted\">-</span>" : ServerFolderBadge(context, server))}}</td>
                <td data-sort-value="{{A(ServerProtocolLabel(server.Protocol))}}"><span class="badge">{{E(ServerProtocolLabel(server.Protocol))}}</span></td>
                <td>{{E(ServerTargetValue(server))}}</td>
                <td>{{(server.IsEnabled ? T(context, "Active") : T(context, "Off"))}}</td>
                <td class="table-actions"><div class="row-actions"><a class="icon-button" href="/connect/{{server.Id}}" data-shell-open-tab="1" data-shell-title="{{A(server.Name)}}" data-shell-description="{{A(T(context, "Connection"))}}" title="{{A(openLabel)}}" aria-label="{{A(openLabel)}}">{{Icon("play")}}</a>{{EditLink($"/admin/servers/{server.Id}")}}{{DeleteForm($"/admin/servers/{server.Id}/delete")}}</div></td>
            </tr>
            """));
        var serverHeaders = $$"""<th data-sortable>{{T(context, "Name")}}</th><th data-sortable>{{T(context, "Scope")}}</th><th data-sortable>{{T(context, "Folder")}}</th><th data-sortable>{{T(context, "Type")}}</th><th data-sortable>{{T(context, "Target")}}</th><th data-sortable>{{T(context, "Status")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";
        var serverTable = DataTable(de ? "Server suchen..." : "Search servers...", serverHeaders, serverRows, T(context, "No servers yet."), 7, 15, "", "");

        // Gallery view: the same connection cards as the start page (icon, badges, name, target),
        // with admin actions (edit gear top-right, open + delete below). Toggle List/Gallery below.
        var serverCards = servers.Count == 0
            ? $"""<p class="muted">{E(T(context, "No servers yet."))}</p>"""
            : string.Join("", servers.Select(server => $$"""
                <article class="connection-choice" data-admin-card="1" data-search="{{A($"{server.Name} {ServerTargetValue(server)} {server.FolderName} {ServerProtocolLabel(server.Protocol)}".ToLowerInvariant())}}" style="--proto: {{ProtocolAccent(server.Protocol)}}">
                    <div class="connection-choice-body">
                        <div class="server-title connection-choice-title">
                            {{ServerIcon(server)}}
                            <div class="connection-choice-copy">
                                <div class="connection-choice-badges">
                                    <span class="badge">{{E(ServerProtocolLabel(server.Protocol))}}</span>
                                    {{(string.IsNullOrWhiteSpace(server.FolderName) ? "" : ServerFolderBadge(context, server))}}
                                    {{ServerScopeBadge(context, server, users)}}
                                    {{(server.IsEnabled ? "" : $"<span class=\"badge muted\">{E(T(context, "Off"))}</span>")}}
                                </div>
                                <h3>{{E(server.Name)}}</h3>
                                <p class="target">{{E(ServerTargetValue(server))}}</p>
                            </div>
                            <div class="connection-choice-corner">
                                <form method="get" action="/admin/servers/{{server.Id}}" class="favorite-toggle-form connection-choice-settings-form"><button type="submit" class="favorite-toggle connection-choice-settings-corner" title="{{A(editLabel)}}" aria-label="{{A(editLabel)}}">{{Icon("settings")}}</button></form>
                            </div>
                        </div>
                    </div>
                    <div class="connection-choice-actions">
                        <a class="button primary" href="/connect/{{server.Id}}" data-shell-open-tab="1" data-shell-title="{{A(server.Name)}}" data-shell-description="{{A(T(context, "Connection"))}}">{{Icon("play")}}{{T(context, server.Protocol == ServerProtocol.Website ? "Open" : "Connect")}}</a>
                        <form method="post" action="/admin/servers/{{server.Id}}/delete" data-confirm="{{A(confirmDelete)}}">{{Csrf(context)}}<button type="submit" class="danger icon-only" title="{{A(deleteLabel)}}" aria-label="{{A(deleteLabel)}}">{{Icon("trash")}}</button></form>
                    </div>
                </article>
                """));

        // Plain (non-interpolated) raw string: keeps all JS braces literal.
        var serverViewScript = """
            <script>
                (() => {
                    const root = document.querySelector('[data-server-view-switch]');
                    if (!root) { return; }
                    const KEY = 'matgate-server-view';
                    const panels = {
                        gallery: document.querySelector('[data-server-view-panel="gallery"]'),
                        list: document.querySelector('[data-server-view-panel="list"]')
                    };
                    const buttons = root.querySelectorAll('[data-server-view]');
                    const apply = (view) => {
                        if (view !== 'list') { view = 'gallery'; }
                        Object.keys(panels).forEach((key) => {
                            if (panels[key]) { panels[key].hidden = key !== view; }
                        });
                        buttons.forEach((b) => {
                            const on = b.getAttribute('data-server-view') === view;
                            b.classList.toggle('active', on);
                            b.setAttribute('aria-pressed', on ? 'true' : 'false');
                        });
                    };
                    buttons.forEach((b) => b.addEventListener('click', () => {
                        const view = b.getAttribute('data-server-view');
                        try { localStorage.setItem(KEY, view); } catch (e) { /* ignore */ }
                        apply(view);
                    }));
                    let stored = 'gallery';
                    try { stored = localStorage.getItem(KEY) || 'gallery'; } catch (e) { /* ignore */ }
                    apply(stored);

                    // Live search over the gallery cards (same data-search matching as the start page).
                    const gallerySearch = document.querySelector('[data-admin-gallery-search]');
                    const galleryEmpty = document.querySelector('[data-admin-gallery-empty]');
                    if (gallerySearch) {
                        gallerySearch.addEventListener('input', () => {
                            const term = gallerySearch.value.trim().toLowerCase();
                            let visible = 0;
                            document.querySelectorAll('[data-admin-card]').forEach((card) => {
                                const match = !term || (card.getAttribute('data-search') || '').includes(term);
                                card.hidden = !match;
                                if (match) { visible++; }
                            });
                            if (galleryEmpty) { galleryEmpty.hidden = visible > 0; }
                        });
                    }
                })();
            </script>
            """;

        var serversPanel = $$"""
            <section class="panel">
                <div class="server-view-bar">
                    <div class="view-switch" data-server-view-switch role="group" aria-label="{{A(de ? "Ansicht" : "View")}}">
                        <button type="button" class="view-switch-btn" data-server-view="gallery">{{Icon("grid")}}<span>{{(de ? "Galerie" : "Gallery")}}</span></button>
                        <button type="button" class="view-switch-btn" data-server-view="list">{{Icon("list")}}<span>{{(de ? "Liste" : "List")}}</span></button>
                    </div>
                    <a class="button primary" href="/admin/servers/new">{{Icon("plus")}}{{(de ? "Neuer Server" : "New server")}}</a>
                </div>
                <div class="server-view-panel" data-server-view-panel="gallery">
                    <label class="home2-search server-gallery-search">
                        <span class="home2-search-icon">{{Icon("search")}}</span>
                        <input type="search" class="home2-search-input" data-admin-gallery-search placeholder="{{A(de ? "Server suchen..." : "Search servers...")}}" aria-label="{{A(de ? "Server suchen..." : "Search servers...")}}">
                    </label>
                    <div class="home2-card-grid server-gallery">{{serverCards}}</div>
                    <p class="muted server-gallery-empty" data-admin-gallery-empty hidden>{{(de ? "Keine Treffer." : "No matches.")}}</p>
                </div>
                <div class="server-view-panel" data-server-view-panel="list" hidden>{{serverTable}}</div>
                {{serverViewScript}}
            </section>
            """;

        var userRows = string.Join("", users.OrderBy(u => u.UserName).Select(u => $$"""
            <tr>
                <td><a href="/admin/users/{{u.Id}}">{{E(u.UserName)}}</a></td>
                <td>{{(string.IsNullOrWhiteSpace(u.Email) ? "<span class=\"muted\">-</span>" : E(u.Email))}}</td>
                <td>{{E(u.DisplayName)}}</td>
                <td>{{RoleLabels(context, u)}}</td>
                <td>{{(u.IsEnabled ? T(context, "Active") : T(context, "Locked"))}}</td>
                <td class="table-actions"><div class="row-actions">{{EditLink($"/admin/users/{u.Id}")}}{{(u.Id == currentUser.Id ? "" : DeleteForm($"/admin/users/{u.Id}/delete"))}}</div></td>
            </tr>
            """));
        var userHeaders = $$"""<th data-sortable>{{T(context, "Name")}}</th><th data-sortable>{{T(context, "Email")}}</th><th data-sortable>{{T(context, "Display")}}</th><th data-sortable>{{T(context, "Roles")}}</th><th data-sortable>{{T(context, "Status")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";
        var userTable = DataTable(de ? "Benutzer suchen..." : "Search users...", userHeaders, userRows, T(context, "No users created yet."), 6, 15, "",
            $$"""<a class="button primary" href="/admin/users/new">{{Icon("plus")}}{{T(context, "Create user")}}</a>""");

        var workspaceRows = string.Join("", workspaces
            .OrderByDescending(WorkspaceIsPublicAccessActive)
            .ThenBy(w => w.Name)
            .Select(w => $$"""
            <tr>
                <td><span class="server-name-cell">{{Icon("briefcase")}}<a href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}">{{E(w.Name)}}</a></span></td>
                <td><span class="badge">{{(w.IsPrivate ? T(context, "Personal") : T(context, "Shared"))}}</span></td>
                <td data-sort-value="{{A(WorkspaceValidityLabel(context, w))}}"><span class="badge" title="{{A(WorkspacePublicAccessExpiresText(context, w))}}">{{E(WorkspaceValidityLabel(context, w))}}</span></td>
                <td>{{(WorkspaceIsPublicAccessActive(w) ? T(context, "Active") : T(context, "Expired"))}}</td>
                <td class="table-actions"><div class="row-actions"><a class="icon-button" href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}" title="{{A(openLabel)}}" aria-label="{{A(openLabel)}}">{{Icon("external-link")}}</a>{{EditLink($"/workspaces/{w.Id}?tab=settings")}}{{DeleteForm($"/workspaces/{w.Id}/delete")}}</div></td>
            </tr>
            """));
        var workspaceHeaders = $$"""<th data-sortable>{{T(context, "Name")}}</th><th data-sortable>{{T(context, "Scope")}}</th><th data-sortable>{{T(context, "Validity")}}</th><th data-sortable>{{T(context, "Status")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";
        var workspaceTable = DataTable(de ? "Workspaces suchen..." : "Search workspaces...", workspaceHeaders, workspaceRows, T(context, "No workspaces yet."), 5, 15, "",
            $$"""<a class="button primary" href="/workspaces/new">{{Icon("plus")}}{{(de ? "Neuer Workspace" : "New workspace")}}</a>""");

        var tabs = new List<TabItem>
        {
            new("connections", de ? "Verbindungen" : "Connections", Icon("server"), ConnectionsAdminPanel(context, currentUser, servers, folderObjects, connectionsAccess, serverTable)),
        };
        if (currentUser.IsAdmin)
        {
            tabs.Add(new("users", T(context, "Users"), Icon("user"), UsersAdminPanel(context, currentUser, users, groups ?? [], servers, folderObjects ?? [], userTable)));
            tabs.Add(new("groups", de ? "Gruppen" : "Groups", Icon("users"), GroupsAdminPanel(context, groups ?? [], users, grants ?? [], servers, folderObjects ?? [])));
            tabs.Add(new("sso", de ? "Anmeldung" : "Sign-in", Icon("key"), SsoPanel(context, users, groups ?? [])));
        }
        tabs.Add(new("workspaces", T(context, "Workspaces"), Icon("briefcase"), WorkspacesAdminPanel(context, workspaces, users, workspaceTable)));

        if (browser is not null)
        {
            tabs.Add(new("browser", de ? "Browser" : "Browser", Icon("globe"), BrowserAdminPanel(context, browser, de)));
        }

        var tabParam = context.Request.Query["tab"].ToString().ToLowerInvariant();
        // Servers and folders were tabs of their own before 0.46.0: both are the tree now.
        tabParam = tabParam is "servers" or "folders" ? "connections" : tabParam;
        var activeKey = tabs.Any(t => t.Key == tabParam) ? tabParam : tabs[0].Key;

        var body = $$"""
            <section class="page-head">
                <div>
                    <h1>{{T(context, "Administration")}}</h1>
                </div>
            </section>
            {{Tabs(activeKey, tabs.ToArray())}}
            """;

        return Layout(context, currentUser, T(context, "Administration"), body);
    }

    private static string BrowserAdminPanel(HttpContext context, BrowserAdminData browser, bool de)
    {
        static string Duration(DateTimeOffset from, DateTimeOffset to)
        {
            var seconds = Math.Max(0, (to - from).TotalSeconds);
            return seconds < 90 ? $"{(int)seconds}s" : $"{(int)(seconds / 60)}m";
        }

        var status = browser.Status;
        var statusBadge = status is null
            ? $"""<span class="badge badge--danger">{E(de ? "Farm nicht erreichbar" : "Browser farm unreachable")}</span>"""
            : $"""<span class="badge">{E((de ? "Pool" : "Pool") + $": {status.Busy}/{status.PoolSize} " + (de ? "belegt" : "in use"))}</span>""";

        var activeRows = browser.Active.Count == 0
            ? $"""<tr><td colspan="5" class="muted">{E(de ? "Keine aktiven Sitzungen." : "No active sessions.")}</td></tr>"""
            : string.Join("", browser.Active.Select(s => $$"""
                <tr>
                    <td>{{E(s.UserName)}}</td>
                    <td><strong>{{E(s.ServerName)}}</strong><br><span class="muted">{{E(s.Url)}}</span></td>
                    <td><span class="badge">{{E(s.Browser)}}</span></td>
                    <td title="{{A(s.StartedAt.ToString("u"))}}">{{E(Duration(s.StartedAt, DateTimeOffset.UtcNow))}}</td>
                    <td class="table-actions"><form method="post" action="/admin/browser/{{s.Id}}/release" data-confirm="{{A(de ? "Sitzung shareTrigger?" : "Release this session?")}}">{{Csrf(context)}}<button type="submit" class="icon-button danger-action" title="{{A(de ? "Freigeben" : "Release")}}" aria-label="{{A(de ? "Freigeben" : "Release")}}">{{Icon("trash")}}</button></form></td>
                </tr>
                """));

        var historyRows = browser.History.Count == 0
            ? $"""<tr><td colspan="6" class="muted">{E(de ? "Noch kein Verlauf." : "No history yet.")}</td></tr>"""
            : string.Join("", browser.History.Take(50).Select(h => $$"""
                <tr>
                    <td>{{E(h.UserName)}}</td>
                    <td><strong>{{E(h.ServerName)}}</strong><br><span class="muted">{{E(h.Url)}}</span></td>
                    <td><span class="badge">{{E(h.Browser)}}</span></td>
                    <td title="{{A(h.StartedAt.ToString("u"))}}">{{E(h.StartedAt.ToString("yyyy-MM-dd HH:mm"))}}</td>
                    <td>{{E(Duration(h.StartedAt, h.EndedAt))}}</td>
                    <td><span class="muted">{{E(h.Reason)}}</span></td>
                </tr>
                """));

        var poolValue = browser.Settings.PoolSize > 0
            ? browser.Settings.PoolSize
            : (status?.PoolSize ?? 10);
        var geometryValue = string.IsNullOrWhiteSpace(browser.Settings.Geometry)
            ? (status?.Geometry ?? "1280x800x24")
            : browser.Settings.Geometry;

        return $$"""
            <section class="panel">
                <div class="server-view-bar">
                    <h2 style="margin:0">{{E(de ? "Browser-Dienst" : "Browser service")}}</h2>
                    {{statusBadge}}
                </div>
                <p class="muted">{{E(de
                    ? "Sitzungen für \"via Chromium/Firefox VNC\"-Websites. Jede belegt einen Slot im Pool und wird beim Schließen (oder nach Timeout) automatisch freigegeben."
                    : "Sessions for \"via Chromium/Firefox VNC\" websites. Each uses one pool slot and is released automatically on close (or after a timeout).")}}</p>
                <form method="post" action="/admin/browser/settings" class="form-grid" style="margin-bottom:8px">
                    {{Csrf(context)}}
                    <label>{{E(de ? "Pool-Größe (parallele Sitzungen)" : "Pool size (parallel sessions)")}}
                        <input name="poolSize" type="number" min="1" max="50" value="{{A(poolValue.ToString())}}">
                    </label>
                    <label>{{E(de ? "Auflösung (BreitexHoehexTiefe)" : "Resolution (widthxheightxdepth)")}}
                        <input name="geometry" value="{{A(geometryValue)}}" placeholder="1280x800x24">
                    </label>
                    <div class="actions"><button type="submit" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button></div>
                    <p class="muted" style="grid-column:1/-1">{{E(de
                        ? "Wird live an den Browser-Dienst übergeben. Eine kleinere Pool-Größe betrifft nur neue Sitzungen; eine neue Auflösung gilt für neu geöffnete Sitzungen."
                        : "Applied to the browser service live. A smaller pool only affects new sessions; a new resolution applies to newly opened sessions.")}}</p>
                </form>
                <h3>{{E(de ? "Aktive Sitzungen" : "Active sessions")}}</h3>
                <div class="table-wrap">
                    <table>
                        <thead><tr>
                            <th>{{T(context, "User")}}</th>
                            <th>{{E(de ? "Website" : "Website")}}</th>
                            <th>{{E(de ? "Browser" : "Browser")}}</th>
                            <th>{{E(de ? "Laeuft seit" : "Running")}}</th>
                            <th class="table-actions">{{T(context, "Actions")}}</th>
                        </tr></thead>
                        <tbody>{{activeRows}}</tbody>
                    </table>
                </div>
                <h3 style="margin-top:22px">{{E(de ? "Verlauf" : "History")}}</h3>
                <div class="table-wrap">
                    <table>
                        <thead><tr>
                            <th>{{T(context, "User")}}</th>
                            <th>{{E(de ? "Website" : "Website")}}</th>
                            <th>{{E(de ? "Browser" : "Browser")}}</th>
                            <th>{{E(de ? "Start" : "Started")}}</th>
                            <th>{{E(de ? "Dauer" : "Duration")}}</th>
                            <th>{{E(de ? "Ende" : "Reason")}}</th>
                        </tr></thead>
                        <tbody>{{historyRows}}</tbody>
                    </table>
                </div>
            </section>
            """;
    }

    public string Servers(HttpContext context, MatgateUser currentUser, IReadOnlyList<ServerEndpoint> servers, IReadOnlyList<MatgateUser> users)
    {
        var visibleServers = servers
            .OrderBy(server => server.OwnerUserId is null ? 0 : 1)
            .ThenBy(server => server.Name)
            .ToList();

        var emptyMessage = currentUser.IsAdmin || (currentUser.CanManageServers && currentUser.CanCreateServers)
            ? T(context, "No servers created yet.")
            : currentUser.CanManageServers
                ? T(context, "No global servers created yet.")
                : T(context, "No own servers created yet.");

        var createButton = currentUser.IsAdmin || currentUser.CanManageServers || currentUser.CanCreateServers
            ? $$"""
                <a class="button primary" href="/admin/servers/new">{{Icon("plus")}}{{T(context, "Create server")}}</a>
                """
            : "";

        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Administration")}}</p>
                    <h1>{{T(context, "Servers")}}</h1>
                </div>
                {{createButton}}
            </section>
            {{ManagedServersSection(context, T(context, "Servers"), visibleServers, emptyMessage, users)}}
            """;

        return Layout(context, currentUser, T(context, "Servers"), body);
    }

    // Where "Back" and a finished save lead: a connection opened from the home page was opened in a tab of
    // its own, and that tab closes again (the page behind /admin/servers/done does it); from the
    // administration it is the list there.
    private static string ServerFormBackUrl(string returnTo) => returnTo == "home" ? "/admin/servers/done" : "/admin?tab=connections";

    public string ServerDetail(
        HttpContext context,
        MatgateUser currentUser,
        ServerEndpoint server,
        IReadOnlyList<MatgateUser> users,
        IReadOnlyList<string>? folders = null,
        string returnTo = "")
    {
        var de = Language(context) == "de";
        var body = $$"""
            <div class="conn-page">
                <section class="page-head conn-head">
                    <span class="conn-head-icon" style="--proto: {{ProtocolAccent(server.Protocol)}}" aria-hidden="true">{{Icon(server.SignKey())}}</span>
                    <div>
                        <p class="eyebrow">{{(de ? "Verbindung" : "Connection")}}</p>
                        <h1>{{E(server.Name)}}</h1>
                        <p class="muted">{{E(ServerProtocolLabel(server.Protocol))}} &middot; {{E(ServerTargetValue(server))}} &middot; {{ServerScopeText(context, server, users)}}</p>
                    </div>
                </section>
                <form id="server-edit-form" method="post" action="/admin/servers/{{server.Id}}" class="stack server-form" data-server-form>
                    {{Csrf(context)}}
                    {{ServerFields(context, currentUser, server, null, folders, returnTo)}}
                </form>
                {{ServerFormScript()}}
                <section class="panel conn-actions">
                    <div class="form-actions">
                        <button type="submit" form="server-edit-form" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button>
                        <a class="button" href="{{ServerFormBackUrl(returnTo)}}">{{Icon("arrow-left")}}{{T(context, "Back")}}</a>
                        {{(server.OwnerUserId is null && Services.AccessResolver.Level(currentUser, server) >= AccessLevel.Manage ? $"""<a class="button" href="{A(EndpointMapping.AccessUrlForServer(server.Id))}" data-server-access>{Icon("shield")}{E(de ? "Zugriff" : "Access")}</a>""" : "")}}
                        <span class="spacer"></span>
                        <form method="post" action="/admin/servers/{{server.Id}}/delete" data-confirm="{{A(de ? $"Verbindung „{server.Name}“ wirklich löschen?" : $"Delete the connection \"{server.Name}\"?")}}">
                            {{Csrf(context)}}
                            <input type="hidden" name="return" value="{{A(returnTo)}}">
                            <button type="submit" class="danger">{{Icon("trash")}}{{(de ? "Löschen" : "Delete")}}</button>
                        </form>
                    </div>
                </section>
            </div>
            """;

        return Layout(context, currentUser, de ? "Verbindung bearbeiten" : "Edit connection", body);
    }

    public string ServerCreate(
        HttpContext context,
        MatgateUser currentUser,
        ServerProtocol? preferredProtocol = null,
        IReadOnlyList<string>? folders = null,
        string returnTo = "")
    {
        var de = Language(context) == "de";
        var body = $$"""
            <div class="conn-page">
                <section class="page-head conn-head">
                    <span class="conn-head-icon" aria-hidden="true">{{Icon("plus")}}</span>
                    <div>
                        <p class="eyebrow">{{(de ? "Verbindung" : "Connection")}}</p>
                        <h1>{{(de ? "Neue Verbindung" : "New connection")}}</h1>
                    </div>
                </section>
                <form id="server-create-form" method="post" action="/admin/servers" class="stack server-form" data-server-form>
                    {{Csrf(context)}}
                    {{ServerFields(context, currentUser, null, preferredProtocol, folders, returnTo)}}
                </form>
                {{ServerFormScript()}}
                <section class="panel conn-actions">
                    <div class="form-actions">
                        <button type="submit" form="server-create-form" class="primary">{{Icon("plus")}}{{(de ? "Anlegen" : "Create")}}</button>
                        <a class="button" href="{{ServerFormBackUrl(returnTo)}}">{{Icon("arrow-left")}}{{T(context, "Back")}}</a>
                    </div>
                </section>
            </div>
            """;

        return Layout(context, currentUser, de ? "Neue Verbindung" : "New connection", body);
    }

    // The last page of a connection that was opened from the home page: it has nothing to show. Inside the
    // shell it asks for its own tab to be closed, which brings the home page back with the list read anew;
    // on its own it goes there.
    public string ServerFormDone(HttpContext context, MatgateUser currentUser)
    {
        var de = Language(context) == "de";
        var body = $$"""
            <section class="panel">
                <p class="muted">{{(de ? "Gespeichert." : "Saved.")}} <a href="/">{{(de ? "Zu den Verbindungen" : "To the connections")}}</a></p>
            </section>
            <script>
                (() => {
                    try {
                        if (window.parent !== window && typeof window.parent.MatgateCloseShellTabOf === 'function' && window.parent.MatgateCloseShellTabOf(window)) {
                            return;
                        }
                    }
                    catch {
                        // Not inside the shell: the link above is the way on.
                    }
                    if (window.parent === window) {
                        window.location.replace('/');
                    }
                })();
            </script>
            """;

        return Layout(context, currentUser, de ? "Verbindungen" : "Connections", body);
    }

    // The settings (/account): six sections in two groups, built in HtmlViews.Settings.cs. Also the answer to
    // switching the second factor on, then with the recovery codes, which are shown this once.
    public string Account(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<string>? recoveryCodes = null)
    {
        return Layout(context, user, T(context, "Settings"), SettingsPage(context, user, servers, recoveryCodes));
    }

    private static string FolderIcon(string iconKey) => Icon(string.IsNullOrWhiteSpace(iconKey) ? "folder" : iconKey);

    private static string FolderEditUrl(string name) => "/admin/folders/edit?name=" + Uri.EscapeDataString(name);

    // The folders in the administration: the list. A folder is created and edited on a page of its own.
    private static string FoldersPanel(HttpContext context, MatgateUser currentUser, IReadOnlyList<ServerEndpoint> servers, IReadOnlyList<FolderDefinition>? folderObjects = null)
    {
        var accessLabel = Language(context) == "de" ? "Zugriff" : "Access";
        // A shared folder (not someone's own) whose access this user may decide: a shield beside the pencil.
        string AccessLink(ServerFolder folder) =>
            (folder.Servers.Any(server => server.OwnerUserId is null) || (folderObjects ?? []).Any(own => own.OwnerUserId is null && ServerFolders.Same(own.Name, folder.Name)))
            && Services.AccessResolver.CanManageFolder(currentUser, folder.Name)
                ? $"""<a class="icon-button" href="{A(EndpointMapping.AccessUrlForFolder(folder.Name))}" title="{A(accessLabel)}" aria-label="{A(accessLabel)}" data-folder-access>{Icon("shield")}</a>"""
                : "";
        var allAccess = Services.AccessResolver.CanManageAll(currentUser)
            ? $"""<a class="button" href="{A(EndpointMapping.AccessUrlForAll)}" data-access-all-link>{Icon("shield")}{E(Language(context) == "de" ? "Zugriff auf alle Verbindungen" : "Access to all connections")}</a>"""
            : "";
        var de = Language(context) == "de";
        // The folders of the connections, and those that exist on their own - also while empty.
        var folders = ServerFolders.List(servers);
        foreach (var own in folderObjects ?? [])
        {
            if (!folders.Any(folder => ServerFolders.Same(folder.Name, own.Name)))
            {
                folders.Add(new ServerFolder(own.Name, own.IconKey, []));
            }
        }

        folders = [.. folders.OrderBy(folder => folder.Name, StringComparer.OrdinalIgnoreCase)];
        var editLabel = de ? "Bearbeiten" : "Edit";
        var dissolveLabel = de ? "Ordner auflösen" : "Dissolve folder";
        var rows = string.Join("", folders.Select(folder => $$"""
            <tr data-folder-row="{{A(folder.Name)}}">
                <td><span class="server-name-cell"><span class="server-icon small">{{FolderIcon(folder.IconKey)}}</span><a href="{{A(FolderEditUrl(folder.Name))}}">{{E(folder.Name)}}</a></span></td>
                <td data-sort-value="{{folder.Servers.Count}}">{{folder.Servers.Count}}</td>
                <td class="muted">{{E(string.Join(", ", folder.Servers.Take(6).Select(server => server.Name)) + (folder.Servers.Count > 6 ? ", ..." : ""))}}</td>
                <td class="table-actions"><div class="row-actions"><a class="icon-button" href="{{A(FolderEditUrl(folder.Name))}}" title="{{A(editLabel)}}" aria-label="{{A(editLabel)}}">{{Icon("edit")}}</a>{{AccessLink(folder)}}<form method="post" action="/admin/folders/delete" data-confirm="{{A(de ? $"Ordner „{folder.Name}“ auflösen? Seine {folder.Servers.Count} Verbindung(en) bleiben erhalten, nur ohne Ordner." : $"Dissolve the folder \"{folder.Name}\"? Its {folder.Servers.Count} connection(s) stay, only without a folder.")}}">{{Csrf(context)}}<input type="hidden" name="name" value="{{A(folder.Name)}}"><button type="submit" class="icon-button danger-action" title="{{A(dissolveLabel)}}" aria-label="{{A(dissolveLabel)}}">{{Icon("trash")}}</button></form></div></td>
            </tr>
            """));
        var headers = $$"""<th data-sortable>{{(de ? "Ordner" : "Folder")}}</th><th data-sortable>{{(de ? "Verbindungen" : "Connections")}}</th><th>{{(de ? "Darin" : "In it")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";
        var create = $$"""<a class="button primary" href="/admin/folders/new" data-folder-new-link>{{Icon("plus")}}{{(de ? "Neuer Ordner" : "New folder")}}</a>{{allAccess}}""";
        var table = DataTable(
            de ? "Ordner suchen..." : "Search folders...",
            headers,
            rows,
            de ? "Noch kein Ordner." : "No folder yet.",
            4,
            15,
            create);

        return $$"""
            <section class="panel" data-folders>
                <p class="muted settings-lead">{{(de
                    ? "Ordner fassen Verbindungen zusammen; ein Unterordner ist ein Name mit „/“ (Labor/Linux). Ein Ordner, den ein Admin oder Server-Verwalter anlegt, sehen alle - auch solange er leer ist. Über das Schild gibt man einen Ordner frei: was dort gilt, gilt für alles darin und darunter, bis ein Unterordner nicht mehr erbt."
                    : "Folders group connections; a subfolder is a name with \"/\" (Lab/Linux). A folder an administrator or server manager makes is seen by everyone - also while it is empty. The shield gives a folder to people: what holds there holds for everything in it and below, until a subfolder stops inheriting.")}}</p>
                {{table}}
            </section>
            """;
    }

    // One folder: its name, its icon, and which connections lie in it.
    public string FolderPage(
        HttpContext context,
        MatgateUser user,
        string original,
        string name,
        string iconKey,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlySet<Guid> chosen,
        string? error = null)
    {
        var de = Language(context) == "de";
        var isNew = string.IsNullOrEmpty(original);
        var checks = string.Join("", servers.Select(server =>
        {
            // Where the connection lies now, when that is somewhere else: ticking it moves it.
            var elsewhere = !string.IsNullOrWhiteSpace(server.FolderName) && !ServerFolders.Same(server.FolderName, original)
                ? $"""<small class="muted">{E(server.FolderName)}</small>"""
                : "";
            return $$"""
                <label class="check" data-search="{{A($"{server.Name} {ServerTargetValue(server)} {server.FolderName}".ToLowerInvariant())}}"><input type="checkbox" name="server" value="{{server.Id}}"{{Checked(chosen.Contains(server.Id))}}> {{ServerIcon(server, "small")}}<span>{{E(server.Name)}}</span>{{elsewhere}}</label>
                """;
        }));

        // Plain (non-interpolated) raw string: keeps all JS braces literal.
        var script = """
            <script>
                (() => {
                    const form = document.getElementById('folder-form');
                    if (!form) { return; }
                    form.querySelectorAll('[data-icon-picker]').forEach((iconPicker) => {
                        const iconInput = iconPicker.querySelector('[data-icon-input]');
                        iconPicker.querySelectorAll('[data-icon-option]').forEach((option) => {
                            option.addEventListener('click', () => {
                                iconInput.value = option.dataset.iconOption;
                                iconPicker.querySelectorAll('[data-icon-option]').forEach((other) => {
                                    other.classList.toggle('active', other === option);
                                });
                            });
                        });
                    });
                    // Many connections: the list narrows to what is typed.
                    const search = form.querySelector('[data-folder-search]');
                    if (search) {
                        search.addEventListener('input', () => {
                            const term = search.value.trim().toLowerCase();
                            form.querySelectorAll('.conn-check-list .check').forEach((row) => {
                                row.hidden = !!term && !(row.getAttribute('data-search') || '').includes(term);
                            });
                        });
                    }
                })();
            </script>
            """;

        var dissolve = isNew
            ? ""
            : $$"""
                <span class="spacer"></span>
                <form method="post" action="/admin/folders/delete" data-confirm="{{A(de ? $"Ordner „{original}“ auflösen? Seine Verbindungen bleiben erhalten, nur ohne Ordner." : $"Dissolve the folder \"{original}\"? Its connections stay, only without a folder.")}}">
                    {{Csrf(context)}}
                    <input type="hidden" name="name" value="{{A(original)}}">
                    <button type="submit" class="danger" data-folder-dissolve>{{Icon("trash")}}{{(de ? "Ordner auflösen" : "Dissolve folder")}}</button>
                </form>
                """;
        var body = $$"""
            <div class="conn-page">
                <section class="page-head">
                    <div>
                        <p class="eyebrow">{{(de ? "Ordner" : "Folder")}}</p>
                        <h1>{{E(isNew ? (de ? "Neuer Ordner" : "New folder") : original)}}</h1>
                    </div>
                </section>
                <form id="folder-form" method="post" action="/admin/folders/save" class="stack server-form">
                    {{Csrf(context)}}
                    <input type="hidden" name="original" value="{{A(original)}}">
                    <section class="panel server-form-section">
                        {{(string.IsNullOrWhiteSpace(error) ? "" : $"<p class=\"error\" data-folder-error>{E(error)}</p>")}}
                        <h2>{{(de ? "Ordner" : "Folder")}}</h2>
                        <div class="conn-grid">
                            <label class="conn-wide"><span>{{T(context, "Name")}}<span class="req" aria-hidden="true">*</span></span>
                                <input name="name" value="{{A(name)}}" required aria-required="true" maxlength="{{ServerFolders.MaxNameLength}}" placeholder="NAS, Work, Lab">
                            </label>
                        </div>
                        <div class="conn-icon">
                            <span class="conn-field-label">{{(de ? "Symbol" : "Icon")}}</span>
                            <div class="conn-icon-body">{{ServerIconPicker("iconKey", iconKey, T(context, "Default folder icon"), "Auto")}}</div>
                        </div>
                    </section>
                    <section class="panel server-form-section">
                        <h2>{{(de ? "Verbindungen in diesem Ordner" : "Connections in this folder")}}</h2>
                        <p class="muted conn-lead">{{(de
                            ? "Angekreuzt liegt die Verbindung in diesem Ordner. Steht hinter ihr ein anderer Ordner, zieht sie von dort hierher um."
                            : "Ticked, the connection lies in this folder. With another folder named behind it, it moves here from there.")}}</p>
                        {{(servers.Count > 8 ? $$"""<label class="data-table-search"><input type="search" data-folder-search placeholder="{{A(de ? "Verbindung suchen..." : "Search connections...")}}" aria-label="{{A(de ? "Verbindung suchen..." : "Search connections...")}}"></label>""" : "")}}
                        <div class="conn-check-list">{{checks}}</div>
                    </section>
                </form>
                {{script}}
                <section class="panel conn-actions">
                    <div class="form-actions">
                        <button type="submit" form="folder-form" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button>
                        <a class="button" href="/admin?tab=folders">{{Icon("arrow-left")}}{{T(context, "Back")}}</a>
                        {{(!isNew && Services.AccessResolver.CanManageFolder(user, original) ? $"""<a class="button" href="{A(EndpointMapping.AccessUrlForFolder(original))}" data-folder-access>{Icon("shield")}{E(de ? "Zugriff" : "Access")}</a>""" : "")}}
                        {{dissolve}}
                    </div>
                </section>
            </div>
            """;

        return Layout(context, user, de ? "Ordner" : "Folder", body);
    }

    private static string KeepSessionLabel(int minutes, bool de) => minutes switch
    {
        0 => de ? "Aus - eine Sitzung endet mit ihrem Browser" : "Off - a session ends with its browser",
        < 60 => de ? $"{minutes} Minuten" : $"{minutes} minutes",
        60 => de ? "1 Stunde" : "1 hour",
        _ => de ? $"{minutes / 60} Stunden" : $"{minutes / 60} hours",
    };

    private static string KeyBarScopeLabel(string scope, bool de) => scope switch
    {
        KeyBar.ScopeScreen => de ? "Desktop (RDP, VNC, Bildschirm)" : "Desktops (RDP, VNC, screen)",
        KeyBar.ScopeTerminal => de ? "Terminal (SSH, Programme)" : "Terminals (SSH, programs)",
        _ => de ? "Überall" : "Everywhere",
    };

    // The key bar in the account: the list of buttons. Creating and editing happen on a page of their own
    // (KeyBarButtonPage); the order is changed here, one place at a time.
    private static string KeyBarPanel(HttpContext context, MatgateUser user)
    {
        var de = Language(context) == "de";
        var buttons = KeyBar.For(user);
        var editLabel = de ? "Bearbeiten" : "Edit";
        var deleteLabel = de ? "Löschen" : "Delete";
        var upLabel = de ? "Weiter nach vorn" : "Move forward";
        var downLabel = de ? "Weiter nach hinten" : "Move back";

        string Move(KeyBarButton button, string direction, string label, bool possible) => $$"""
            <form method="post" action="/account/keys/{{A(button.Id)}}/move">{{Csrf(context)}}<input type="hidden" name="direction" value="{{direction}}"><button type="submit" class="icon-button" data-key-move="{{direction}}" title="{{A(label)}}" aria-label="{{A(label)}}"{{(possible ? "" : " disabled")}}>{{Icon(direction == "up" ? "arrow-up" : "arrow-down")}}</button></form>
            """;

        var rows = string.Join("", buttons.Select((button, index) => $$"""
            <tr data-key-button="{{A(button.Id)}}">
                <td><a class="key-cap" href="/account/keys/{{A(button.Id)}}">{{E(KeyBar.Label(button, de))}}</a><span class="key-row-note muted">{{E(KeyBar.Describe(button, de))}}{{(button.Sticky ? (de ? " · bleibt gedrückt" : " · stays down") : "")}}{{(button.Scope == KeyBar.ScopeAll ? "" : " · " + E(button.Scope == KeyBar.ScopeScreen ? "Desktop" : "Terminal"))}}</span></td>
                <td>{{E(KeyBar.Describe(button, de))}}</td>
                <td>{{E(button.Sticky ? (de ? "bleibt für die nächste Taste gedrückt" : "stays down for the next key") : (de ? "drückt einmal" : "presses once"))}}</td>
                <td>{{E(KeyBarScopeLabel(button.Scope, de))}}</td>
                <td class="table-actions"><div class="row-actions">{{Move(button, "up", upLabel, index > 0)}}{{Move(button, "down", downLabel, index < buttons.Count - 1)}}<a class="icon-button" href="/account/keys/{{A(button.Id)}}" title="{{A(editLabel)}}" aria-label="{{A(editLabel)}}">{{Icon("edit")}}</a><form method="post" action="/account/keys/{{A(button.Id)}}/delete" data-confirm="{{A(de ? $"Knopf „{KeyBar.Label(button, de)}“ entfernen?" : $"Remove the button \"{KeyBar.Label(button, de)}\"?")}}">{{Csrf(context)}}<button type="submit" class="icon-button danger-action" title="{{A(deleteLabel)}}" aria-label="{{A(deleteLabel)}}">{{Icon("trash")}}</button></form></div></td>
            </tr>
            """));
        var headers = $$"""<th>{{(de ? "Knopf" : "Button")}}</th><th>{{(de ? "Tasten" : "Keys")}}</th><th>{{(de ? "Verhalten" : "Behaviour")}}</th><th>{{(de ? "Zeigen in" : "Shown in")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";
        var create = buttons.Count >= KeyBar.MaxButtons
            ? ""
            : $$"""<a class="button primary" href="/account/keys/new" data-key-new>{{Icon("plus")}}{{(de ? "Neuer Knopf" : "New button")}}</a>""";
        // Only someone who has a list of their own has something to reset. It stands below the list on the left,
        // outlined: it deletes, but it is not the main thing of this page.
        var reset = user.KeyBar is null
            ? ""
            : $$"""
                <form method="post" action="/account/keys/reset" data-confirm="{{A(de ? "Die Tastenleiste auf die Vorgabe zurücksetzen? Eigene Knöpfe und die eigene Reihenfolge gehen dabei verloren." : "Reset the key bar to the default? Your own buttons and your own order are lost.")}}">{{Csrf(context)}}<button type="submit" class="button set-danger-outline" data-key-reset>{{Icon("refresh")}}<span>{{(de ? "Auf Vorgabe zurücksetzen" : "Reset to default")}}</span></button></form>
                """;
        var table = DataTable(
            de ? "Knopf suchen..." : "Search buttons...",
            headers,
            rows,
            de ? "Die Leiste hat keinen Knopf." : "The bar has no button.",
            5,
            0,
            create,
            reset);

        return SettingsCard(
            de ? "Knöpfe" : "Buttons",
            table,
            de
                ? "In Guacamole-Sitzungen sind sie die oberste Reihe der Bildschirmtastatur. Eine Änderung gilt für Sitzungen, die danach geöffnet werden."
                : "In Guacamole sessions they are the top row of the on-screen keyboard. A change applies to sessions opened afterwards.",
            pillHtml: user.KeyBar is null ? SetPill(de ? "Vorgabe" : "Default", "neutral") : "",
            attributes: "data-key-bar");
    }

    // One button of the key bar: its keys, what is written on it, where it shows.
    public string KeyBarButtonPage(HttpContext context, MatgateUser user, KeyBarButton button, bool isNew, string? error = null)
    {
        var de = Language(context) == "de";
        var main = button.Keys.FirstOrDefault(key => !KeyBar.IsModifier(key));
        var named = main is not null && KeyBar.IsNamed(main)
            ? KeyBar.Named.First(key => string.Equals(key.Name, main, StringComparison.OrdinalIgnoreCase)).Name
            : "";
        var isCharacter = main is not null && named.Length == 0;
        var character = isCharacter && KeyBar.IsCharacter(main!) ? main! : "";
        var clean = KeyBar.Clean(button);
        var title = isNew ? (de ? "Neuer Knopf" : "New button") : (clean is null ? (de ? "Knopf" : "Button") : KeyBar.Label(clean, de));

        var modifierChecks = string.Join("", KeyBar.Modifiers.Select(modifier => $$"""
            <label class="check"><input type="checkbox" name="mod{{modifier.Name}}"{{Checked(button.Keys.Contains(modifier.Name, StringComparer.OrdinalIgnoreCase))}}> <span>{{E(de ? modifier.LongDe : modifier.LongEn)}}</span></label>
            """));
        var keyOptions = string.Join("", KeyBar.Named.Select(key =>
        {
            var name = de ? key.LongDe : key.LongEn;
            var cap = de ? key.De : key.En;
            return $"""<option value="{A(key.Name)}"{(key.Name == named ? " selected" : "")}>{E(cap == name ? name : $"{name}  {cap}")}</option>""";
        }));
        var scopeOptions = string.Join("", new[] { KeyBar.ScopeAll, KeyBar.ScopeScreen, KeyBar.ScopeTerminal }.Select(scope =>
            $"""<option value="{scope}"{((KeyBar.IsScope(button.Scope) ? button.Scope : KeyBar.ScopeAll) == scope ? " selected" : "")}>{E(KeyBarScopeLabel(scope, de))}</option>"""));

        // Plain (non-interpolated) raw string: keeps all JS braces literal.
        var script = """
            <script>
                (() => {
                    const form = document.getElementById('key-button-form');
                    if (!form) { return; }
                    const key = form.querySelector('[name="key"]');
                    const characterRow = form.querySelector('[data-key-character]');
                    const character = form.querySelector('[name="character"]');
                    const stickyRow = form.querySelector('[data-key-sticky]');
                    const sticky = form.querySelector('[name="sticky"]');
                    const apply = () => {
                        const isCharacter = key.value === 'char';
                        characterRow.hidden = !isCharacter;
                        character.required = isCharacter;
                        // Only modifiers can wait for the next key.
                        const alone = key.value === '';
                        stickyRow.hidden = !alone;
                        if (!alone) { sticky.checked = false; }
                    };
                    key.addEventListener('change', () => {
                        apply();
                        if (key.value === 'char') { character.focus(); }
                    });
                    apply();
                })();
            </script>
            """;

        var deleteForm = isNew
            ? ""
            : $$"""
                <form method="post" action="/account/keys/{{A(button.Id)}}/delete" data-confirm="{{A(de ? "Diesen Knopf entfernen?" : "Remove this button?")}}">
                    {{Csrf(context)}}
                    <button type="submit" class="button set-danger-outline" data-key-delete>{{Icon("trash")}}<span>{{(de ? "Knopf entfernen" : "Remove button")}}</span></button>
                </form>
                """;
        // The form's content as before, in two cards of the settings; the buttons below it in the usual order.
        var keysCard = SettingsCard(de ? "Tasten" : "Keys", $$"""
            <div class="quick-protocol-grid">{{modifierChecks}}</div>
            <div class="form-grid">
                <label>{{(de ? "Taste" : "Key")}}
                    <select name="key">
                        <option value=""{{(main is null ? " selected" : "")}}>{{(de ? "Keine - nur die Zusatztasten" : "None - the modifiers alone")}}</option>
                        <option value="char"{{(isCharacter ? " selected" : "")}}>{{(de ? "Buchstabe, Ziffer oder Zeichen ..." : "Letter, digit or character ...")}}</option>
                        {{keyOptions}}
                    </select>
                </label>
                <label data-key-character{{(isCharacter ? "" : " hidden")}}>{{(de ? "Zeichen" : "Character")}}
                    <input name="character" maxlength="2" size="3" autocomplete="off" autocapitalize="off" spellcheck="false" value="{{A(character)}}">
                </label>
            </div>
            <label class="toggle-row" data-key-sticky{{(main is null ? "" : " hidden")}}>
                <input type="checkbox" name="sticky"{{Checked(button.Sticky)}}>
                <span class="toggle-switch" aria-hidden="true"></span>
                <span class="toggle-copy"><strong>{{(de ? "Bleibt für die nächste Taste gedrückt" : "Stays down for the next key")}}</strong><small>{{(de ? "Erst der Knopf, dann eine Taste der Tastatur oder ein anderer Knopf - wie Strg und Alt in der Vorgabe. Ausgeschaltet wird die Zusatztaste nur einmal angetippt." : "First the button, then a key of the keyboard or another button - like Ctrl and Alt in the default. Switched off, the modifier is only tapped once.")}}</small></span>
            </label>
            """,
            de
                ? "Die Zusatztasten werden gehalten, während die Taste gedrückt wird - Strg und C ergeben Strg+C. Strg+V fügt ein, was auf diesem Gerät in der Zwischenablage liegt; Strg+Alt+Entf geht an Windows selbst."
                : "The modifiers are held while the key is pressed - Ctrl and C make Ctrl+C. Ctrl+V pastes what is on this device's clipboard; Ctrl+Alt+Del goes to Windows itself.");
        var placeCard = SettingsCard(de ? "Aussehen und Ort" : "Look and place", $$"""
            <div class="form-grid">
                <label>{{(de ? "Beschriftung" : "Label")}}
                    <input name="label" maxlength="{{KeyBar.MaxLabelLength}}" autocomplete="off" value="{{A(button.Label)}}" placeholder="{{A(de ? "automatisch aus den Tasten" : "from the keys")}}">
                </label>
                <label>{{(de ? "Zeigen in" : "Show in")}}
                    <select name="scope">{{scopeOptions}}</select>
                </label>
            </div>
            <p class="set-hint">{{(de
                ? "Ein Terminal kennt keine Windows-Taste: Knöpfe mit ihr erscheinen dort nicht, was auch eingestellt ist."
                : "A terminal knows no Windows key: buttons with it do not appear there, whatever is set.")}}</p>
            """);
        var actions = FormActions(
            $"""<button type="submit" form="key-button-form" class="button primary">{Icon("save")}<span>{E(T(context, "Save"))}</span></button>""",
            $"""<a class="button" href="/account?tab=keys">{Icon("arrow-left")}<span>{E(T(context, "Back"))}</span></a>""",
            deleteForm);
        var errorNotice = string.IsNullOrWhiteSpace(error) ? "" : SetNotice("error", E(error), attributes: "data-key-error");
        var content = $$"""
            {{errorNotice}}
            <form id="key-button-form" method="post" action="{{(isNew ? "/account/keys" : $"/account/keys/{A(button.Id)}")}}" class="set-form">
                {{Csrf(context)}}
                {{keysCard}}
                {{placeCard}}
            </form>
            {{script}}
            <div class="set-actions">{{actions}}</div>
            """;
        var panel = SettingsPanel(
            context,
            "keys",
            true,
            isNew ? (de ? "Neuer Knopf" : "New button") : (de ? "Knopf bearbeiten" : "Edit button"),
            isNew
                ? (de ? "Welche Tasten er drückt, was auf ihm steht und wo er erscheint." : "Which keys it presses, what it says and where it shows.")
                : (de ? $"„{title}“ – welche Tasten er drückt, was auf ihm steht und wo er erscheint." : $"“{title}” – which keys it presses, what it says and where it shows."),
            content,
            backHref: "/account?tab=keys",
            backLabel: de ? "Tastenleiste" : "Key bar");
        // The rail as on the settings page, its links plain: this page is no tab of it.
        var favorites = user.FavoriteServerIds?.Count ?? 0;
        var body = SettingsLayout(context, user, SettingsSections(context, user, favorites), "keys", true, panel, interactive: false);

        return Layout(context, user, de ? "Tastenleiste" : "Key bar", body);
    }

    public string WorkspaceCreate(HttpContext context, MatgateUser currentUser, string defaultRootPath)
    {
        var de = Language(context) == "de";
        var body = $$"""
            <section class="ws-create">
                <div class="ws-create-head">
                    <h1>{{(de ? "Neuer Workspace" : "New workspace")}}</h1>
                    <p class="muted">{{T(context, "A workspace is a shared folder with a public link and shared text.")}}</p>
                </div>
                <form method="post" action="/workspaces" class="ws-create-form">
                    {{Csrf(context)}}
                    <label class="ws-field">
                        <span>{{T(context, "Name")}}</span>
                        <input name="name" required maxlength="120" autofocus placeholder="{{A(de ? "z. B. Projekt X" : "e.g. Project X")}}">
                    </label>
                    <label class="ws-field">
                        <span>{{T(context, "Description")}} <small class="muted">({{(de ? "optional" : "optional")}})</small></span>
                        <textarea name="description" rows="2" placeholder="{{A(de ? "Wofür ist dieser Workspace?" : "What is this workspace for?")}}"></textarea>
                    </label>
                    <div class="ws-field">
                        <span>{{(de ? "Gültigkeit des öffentlichen Zugriffs" : "Public access validity")}}</span>
                        <div class="ws-validity" data-ws-validity>
                            <input type="hidden" name="publicAccessHours" value="24" data-ws-validity-input>
                            <button type="button" class="ws-validity-option active" data-ws-hours="24">{{(de ? "1 Tag" : "1 day")}}</button>
                            <button type="button" class="ws-validity-option" data-ws-hours="168">{{(de ? "7 Tage" : "7 days")}}</button>
                            <button type="button" class="ws-validity-option" data-ws-hours="720">{{(de ? "30 Tage" : "30 days")}}</button>
                        </div>
                    </div>
                    <label class="ws-field">
                        <span>{{T(context, "Access password")}} <small class="muted">({{(de ? "optional" : "optional")}})</small></span>
                        <input name="password" type="password" autocomplete="new-password" placeholder="{{A(de ? "Leer = kein Passwort" : "Empty = no password")}}">
                    </label>
                    <div class="ws-create-actions">
                        <button type="submit" class="button primary">{{Icon("plus")}}<span>{{(de ? "Workspace anlegen" : "Create workspace")}}</span></button>
                        <a class="button" href="/workspaces">{{Icon("arrow-left")}}<span>{{T(context, "Workspaces")}}</span></a>
                    </div>
                </form>
                <script>
                    (() => {
                        const box = document.querySelector('[data-ws-validity]');
                        if (!box) {
                            return;
                        }
                        const input = box.querySelector('[data-ws-validity-input]');
                        box.querySelectorAll('[data-ws-hours]').forEach((option) => {
                            option.addEventListener('click', () => {
                                if (input) {
                                    input.value = option.dataset.wsHours;
                                }
                                box.querySelectorAll('[data-ws-hours]').forEach((other) => other.classList.toggle('active', other === option));
                            });
                        });
                    })();
                </script>
            </section>
            """;

        return Layout(context, currentUser, T(context, "Create workspace"), body);
    }

    public string Workspaces(
        HttpContext context,
        MatgateUser currentUser,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        WorkspaceDefinition? selectedWorkspace,
        FileGatewayListResult? listing,
        IReadOnlyList<WorkspacePresenceSnapshot> sessions,
        IReadOnlyList<WorkspaceActivityEntry> activityEntries,
        bool canEditSelected,
        string publicUrl,
        string defaultRootPath,
        string? pageTitleOverride = null)
    {
        var de = Language(context) == "de";
        var active = workspaces.Where(WorkspaceIsPublicAccessActive).OrderBy(w => w.Name).ToList();
        var expired = workspaces.Where(w => !WorkspaceIsPublicAccessActive(w)).OrderBy(w => w.Name).ToList();

        string wsRow(WorkspaceDefinition w) => $$"""
            <tr>
                <td><span class="server-name-cell">{{Icon("briefcase")}}<a href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}">{{E(w.Name)}}</a></span></td>
                <td><span class="badge">{{(w.IsPrivate ? T(context, "Personal") : T(context, "Shared"))}}</span></td>
                <td data-sort-value="{{A(WorkspaceValidityLabel(context, w))}}"><span class="badge" title="{{A(WorkspacePublicAccessExpiresText(context, w))}}">{{E(WorkspaceValidityLabel(context, w))}}</span></td>
                <td class="table-actions"><div class="row-actions"><a class="icon-button" href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}" title="{{A(T(context, "Open"))}}" aria-label="{{A(T(context, "Open"))}}">{{Icon("external-link")}}</a><a class="icon-button" href="/workspaces/{{w.Id}}?tab=settings" title="{{A(de ? "Bearbeiten" : "Edit")}}" aria-label="{{A(de ? "Bearbeiten" : "Edit")}}">{{Icon("edit")}}</a></div></td>
            </tr>
            """;
        var wsHeaders = $$"""<th data-sortable>{{T(context, "Name")}}</th><th data-sortable>{{T(context, "Scope")}}</th><th data-sortable>{{T(context, "Validity")}}</th><th class="table-actions">{{T(context, "Actions")}}</th>""";

        var activeTable = DataTable(de ? "Workspaces suchen..." : "Search workspaces...", wsHeaders,
            string.Join("", active.Select(wsRow)), de ? "Keine aktiven Workspaces." : "No active workspaces.", 4, 15, "",
            $$"""<a class="button primary" href="/workspaces/new">{{Icon("plus")}}{{(de ? "Neuer Workspace" : "New workspace")}}</a>""");

        // Expired workspaces: one-click re-activation (+24h / +7d), only for workspaces the user
        // may edit (owner or admin). ExtendPublicAccess re-bases from "now" when already expired.
        bool canEditWs(WorkspaceDefinition w) => currentUser.IsAdmin || w.OwnerUserId == currentUser.Id;
        string extendForm(WorkspaceDefinition w, int hours, string label) => $$"""
            <form method="post" action="/workspaces/{{w.Id}}/extend" class="ws-extend-form">
                {{Csrf(context)}}
                <input type="hidden" name="publicAccessHours" value="{{hours}}">
                <input type="hidden" name="returnUrl" value="/workspaces">
                <button type="submit" class="button ws-extend-btn" title="{{A((de ? "Verlängern um " : "Extend by ") + label)}}">{{Icon("clock")}}<span>+{{E(label)}}</span></button>
            </form>
            """;
        string wsExpiredRow(WorkspaceDefinition w) => $$"""
            <tr>
                <td><span class="server-name-cell">{{Icon("briefcase")}}<a href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}">{{E(w.Name)}}</a></span></td>
                <td><span class="badge">{{(w.IsPrivate ? T(context, "Personal") : T(context, "Shared"))}}</span></td>
                <td><span class="badge" title="{{A(WorkspacePublicAccessExpiresText(context, w))}}">{{E(WorkspaceValidityLabel(context, w))}}</span></td>
                <td class="table-actions">
                    <div class="row-actions">
                        {{(canEditWs(w) ? extendForm(w, 24, "24h") + extendForm(w, 168, "7d") : "")}}
                        <a class="icon-button" href="/workspaces/{{w.Id}}" data-shell-open-tab="1" data-shell-title="{{A(w.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}" title="{{A(T(context, "Open"))}}" aria-label="{{A(T(context, "Open"))}}">{{Icon("external-link")}}</a>
                    </div>
                </td>
            </tr>
            """;

        var expiredSection = expired.Count == 0 ? "" : $$"""
            <section class="panel workspace-expired-panel">
                <h2 class="workspace-expired-head">{{(de ? "Abgelaufen" : "Expired")}} <span class="badge">{{expired.Count}}</span></h2>
                <div class="table-wrap">
                    <table>
                        <thead><tr>{{wsHeaders}}</tr></thead>
                        <tbody>{{string.Join("", expired.Select(wsExpiredRow))}}</tbody>
                    </table>
                </div>
            </section>
            """;

        var body = $$"""
            <section class="page-head">
                <div>
                    <h1>{{T(context, "Workspaces")}}</h1>
                </div>
            </section>
            <section class="panel">{{activeTable}}</section>
            {{expiredSection}}
            """;

        return Layout(context, currentUser, string.IsNullOrWhiteSpace(pageTitleOverride) ? T(context, "Workspaces") : pageTitleOverride!, body);
    }

    public string WorkspaceDetail(
        HttpContext context,
        MatgateUser currentUser,
        WorkspaceDefinition workspace,
        FileGatewayListResult? listing,
        IReadOnlyList<WorkspacePresenceSnapshot> sessions,
        IReadOnlyList<WorkspaceActivityEntry> activityEntries,
        bool canEditSelected,
        string publicUrl,
        string defaultRootPath)
    {
        var selectedTab = WorkspaceSelectedTab(context, includeInfo: true, includeSettings: canEditSelected);
        var currentPath = listing?.Path ?? "/";
        var body = WorkspaceContentShell(
            context,
            workspace,
            listing,
            sessions,
            activityEntries,
            selectedTab,
            canEditSelected,
            includeInfo: true,
            includeSettings: canEditSelected,
            baseUrl: $"/workspaces/{workspace.Id}",
            publicUrl: publicUrl,
            defaultRootPath: defaultRootPath,
            currentPath: currentPath,
            fileManagerAreaId: FileShareService.WorkspaceAreaId(workspace.Id).ToString());

        return Layout(context, currentUser, workspace.Name, body, "workspace-detail-main");
    }

    public string WorkspaceExpired(HttpContext context, WorkspaceDefinition workspace, string publicUrl)
