    public string WorkspacePublic(
        HttpContext context,
        WorkspaceDefinition workspace,
        FileGatewayListResult? listing,
        IReadOnlyList<WorkspacePresenceSnapshot> sessions,
        string publicUrl,
        bool passwordRequired,
        IReadOnlyList<WorkspaceActivityEntry> activityEntries,
        string? passwordError = null)
    {
        if (passwordRequired)
        {
            return WorkspacePassword(context, workspace, publicUrl, passwordError);
        }

        var selectedTab = WorkspaceSelectedTab(context);
        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Workspace")}}</p>
                    <h1>{{E(workspace.Name)}}</h1>
                    <p class="muted">{{E(workspace.Description)}}</p>
                    {{WorkspacePublicUrlLine(context, publicUrl)}}
                </div>
            </section>
            {{WorkspaceContentShell(
                context,
                workspace,
                listing,
                sessions,
                activityEntries,
                selectedTab,
                // A visitor without an account must not delete. Until now that was decided
                // of all things by "allow text exchange" - a coupling nobody would suspect:
                // whoever shared the note shared deleting along with it. Uploading stays
                // tied to "allow uploads", where it belongs.
                canEditSelected: false,
                includeInfo: false,
                includeSettings: false,
                baseUrl: $"/workspace/{workspace.Id}",
                publicUrl: publicUrl,
                defaultRootPath: "",
                currentPath: listing?.Path ?? "/",
                fileManagerAreaId: "")}}
            """;

        return Layout(context, null, workspace.Name, body, "workspace-public-main");
    }

