    public string Tools(HttpContext context, MatgateUser user)
    {
        var toolText = JsonSerializer.Serialize(new
        {
            ready = T(context, "Ready"),
            running = T(context, "Running"),
            complete = T(context, "Complete"),
            failed = T(context, "Failed"),
            aborted = T(context, "Aborted")
        }, new JsonSerializerOptions(JsonSerializerDefaults.Web));

        var body = $$"""
            <section class="page-head">
                <div>
                    <p class="eyebrow">{{T(context, "Tools")}}</p>
                    <h1>{{T(context, "Network tools")}}</h1>
                </div>
            </section>
            <section class="panel tool-panel">
                <form class="tool-form" data-tools-form>
                    {{Csrf(context)}}
                    <div class="tool-select-row">
                        <label class="tool-select-label">{{T(context, "Select tool")}}
                            <select name="tool" data-tool-select>
                                <option value="ping" data-endpoint="/api/tools/ping" data-title="{{A(T(context, "Ping"))}}" data-description="{{A(T(context, "Reachability and latency check."))}}" selected>{{T(context, "Ping")}}</option>
                                <option value="lookup" data-endpoint="/api/tools/lookup" data-title="{{A(T(context, "Lookup"))}}" data-description="{{A(T(context, "Resolve hostnames and addresses."))}}">{{T(context, "Lookup")}}</option>
                                <option value="port-check" data-endpoint="/api/tools/port-check" data-title="{{A(T(context, "Port check"))}}" data-description="{{A(T(context, "Test TCP ports live."))}}">{{T(context, "Port check")}}</option>
                                <option value="download" data-endpoint="/api/tools/download" data-title="{{A(T(context, "Download"))}}" data-description="{{A(T(context, "Stream a file and watch transfer speed."))}}">{{T(context, "Download")}}</option>
                            </select>
                        </label>
                        <span class="badge tool-status" data-tool-status>{{T(context, "Ready")}}</span>
                    </div>
                    <div class="tool-summary" aria-live="polite">
                        <div class="tool-summary-icon-stack">
                            <span class="tool-summary-icon" data-tool-icon="ping">{{Icon("refresh")}}</span>
                            <span class="tool-summary-icon" data-tool-icon="lookup" hidden>{{Icon("globe")}}</span>
                            <span class="tool-summary-icon" data-tool-icon="port-check" hidden>{{Icon("server")}}</span>
                            <span class="tool-summary-icon" data-tool-icon="download" hidden>{{Icon("download")}}</span>
                        </div>
                        <div class="tool-summary-copy">
                            <p class="eyebrow">{{T(context, "Tool")}}</p>
                            <h2 data-tool-title>{{T(context, "Ping")}}</h2>
                            <p class="muted" data-tool-description>{{T(context, "Reachability and latency check.")}}</p>
                        </div>
                    </div>
                    <div class="tool-fields">
                        <section class="tool-field-group" data-tool-fields="ping">
                            <div class="form-grid tool-form-grid">
                                <label>{{T(context, "Host or IP")}}
                                    <input name="host" required placeholder="192.168.1.1">
                                </label>
                                <label>{{T(context, "Count")}}
                                    <input name="count" type="number" min="1" max="30" value="4">
                                </label>
                                <label>{{T(context, "Interval")}} (ms)
                                    <input name="intervalMs" type="number" min="0" max="60000" value="1000">
                                </label>
                                <label>{{T(context, "Timeout")}} (ms)
                                    <input name="timeoutMs" type="number" min="100" max="60000" value="1000">
                                </label>
                            </div>
                        </section>
                        <section class="tool-field-group" data-tool-fields="lookup" hidden>
                            <div class="form-grid tool-form-grid">
                                <label>{{T(context, "Host or IP")}}
                                    <input name="host" required placeholder="nas.local">
                                </label>
                            </div>
                        </section>
                        <section class="tool-field-group" data-tool-fields="port-check" hidden>
                            <div class="form-grid tool-form-grid">
                                <label>{{T(context, "Host or IP")}}
                                    <input name="host" required placeholder="192.168.1.10">
                                </label>
                                <label>{{T(context, "Ports")}}
                                    <input name="ports" required placeholder="80,443,3389">
                                </label>
                                <label>{{T(context, "Timeout")}} (ms)
                                    <input name="timeoutMs" type="number" min="100" max="60000" value="1000">
                                </label>
                            </div>
                        </section>
                        <section class="tool-field-group" data-tool-fields="download" hidden>
                            <div class="form-grid tool-form-grid">
                                <label>{{T(context, "URL")}}
                                    <input name="url" required placeholder="http://192.168.1.10/bigfile.iso">
                                </label>
                            </div>
                        </section>
                    </div>
                    <div class="actions tool-actions">
                        <button type="submit" class="primary">{{Icon("play")}}<span>{{T(context, "Start")}}</span></button>
                    </div>
                    <pre class="tool-output" data-tool-output>{{T(context, "Ready")}}</pre>
                </form>
            </section>
            <script>
                (() => {
                    const toolText = {{toolText}};
                    const form = document.querySelector('[data-tools-form]');
                    if (!form) {
                        return;
                    }

                    const select = form.querySelector('[data-tool-select]');
                    const title = form.querySelector('[data-tool-title]');
                    const description = form.querySelector('[data-tool-description]');
                    const status = form.querySelector('[data-tool-status]');
                    const output = form.querySelector('[data-tool-output]');
                    const submitButton = form.querySelector('button[type="submit"]');
                    const toolIcons = new Map(Array.from(form.querySelectorAll('[data-tool-icon]')).map(element => [element.getAttribute('data-tool-icon') || '', element]));
                    const toolGroups = Array.from(form.querySelectorAll('[data-tool-fields]'));
                    let activeController = null;
                    let activeTool = 'ping';

                    function setStatus(value) {
                        if (status) {
                            status.textContent = value;
                        }
                    }

                    function currentOption() {
                        if (!select || !select.selectedOptions || select.selectedOptions.length === 0) {
                            return null;
                        }

                        return select.selectedOptions[0];
                    }

                    function syncTool() {
                        const option = currentOption();
                        const value = option?.value || 'ping';
                        const endpoint = option?.dataset.endpoint || '/api/tools/ping';
                        activeTool = value;
                        form.dataset.toolEndpoint = endpoint;

                        if (activeController) {
                            activeController.abort();
                            activeController = null;
                        }

                        if (title) {
                            title.textContent = option?.dataset.title || option?.textContent?.trim() || '';
                        }

                        if (description) {
                            description.textContent = option?.dataset.description || '';
                        }

                        if (output) {
                            output.textContent = toolText.ready || 'Ready';
                        }

                        setStatus(toolText.ready || 'Ready');

                        toolIcons.forEach((element, key) => {
                            element.hidden = key !== value;
                        });

                        toolGroups.forEach(group => {
                            const active = (group.getAttribute('data-tool-fields') || '') === value;
                            group.hidden = !active;
                            group.querySelectorAll('input, select, textarea').forEach(control => {
                                control.disabled = !active;
                            });
                        });
                    }

                    async function streamResponse(response, outputElement) {
                        const reader = response.body?.getReader();
                        if (!reader) {
                            outputElement.textContent = await response.text();
                            return;
                        }

                        const decoder = new TextDecoder();
                        outputElement.textContent = '';

                        while (true) {
                            const { value, done } = await reader.read();
                            if (done) {
                                break;
                            }

                            outputElement.textContent += decoder.decode(value, { stream: true });
                            outputElement.scrollTop = outputElement.scrollHeight;
                        }

                        outputElement.textContent += decoder.decode();
                        outputElement.scrollTop = outputElement.scrollHeight;
                    }

                    async function runTool() {
                        const endpoint = form.dataset.toolEndpoint || '';
                        if (!endpoint || !output || !submitButton) {
                            return;
                        }

                        if (activeController) {
                            activeController.abort();
                        }

                        const runToolValue = activeTool;
                        const controller = new AbortController();
                        activeController = controller;

                        output.textContent = '';
                        setStatus(toolText.running || 'Running');
                        submitButton.disabled = true;

                        try {
                            const response = await fetch(endpoint, {
                                method: 'POST',
                                body: new FormData(form),
                                signal: controller.signal,
                                cache: 'no-store'
                            });

                            if (!response.ok) {
                                const text = await response.text().catch(() => '');
                                output.textContent = text || toolText.failed || 'Failed';
                                setStatus(toolText.failed || 'Failed');
                                return;
                            }

                            await streamResponse(response, output);
                            setStatus(toolText.complete || 'Complete');
                        }
                        catch (error) {
                            if (controller.signal.aborted) {
                                if (runToolValue !== activeTool) {
                                    return;
                                }

                                setStatus(toolText.aborted || 'Aborted');
                                return;
                            }

                            output.textContent = error instanceof Error ? error.message : (toolText.failed || 'Failed');
                            setStatus(toolText.failed || 'Failed');
                        }
                        finally {
                            submitButton.disabled = false;
                            if (activeController === controller) {
                                activeController = null;
                            }
                        }
                    }

                    if (select) {
                        select.addEventListener('change', syncTool);
                    }

                    form.addEventListener('submit', event => {
                        event.preventDefault();
                        runTool();
                    });

                    syncTool();
                })();
            </script>
            """;

        return Layout(context, user, T(context, "Tools"), body);
    }

    private static string AboutBody(HttpContext context, string version)
    {
        var buildTag = BuildTagLabel();
        var buildTime = BuildTimestampLabel();
        var buildBadge = string.IsNullOrWhiteSpace(buildTag)
            ? ""
            : $$"""<span class="badge">{{E(buildTag)}}</span>""";
        var buildTimeLine = string.IsNullOrWhiteSpace(buildTime)
            ? ""
            : $$"""<p class="about-build muted">Build: {{E(buildTime)}}</p>""";
        var copyrightYear = DateTimeOffset.Now.Year;

        return $$"""
            <section class="about-page">
                <div class="page-head about-head">
                    <div class="about-copy">
                        <p class="eyebrow">{{T(context, "About")}}</p>
                        <h1>Matgate</h1>
                    </div>
                </div>
                <section class="panel about-card">
                    <div class="about-card-brand">{{Logo()}}</div>
                    <div class="about-meta">
                        <div class="about-version">
                            <strong>MATGATE {{E(version)}}</strong>
                        </div>
                        {{buildTimeLine}}
                        <div class="about-badges">{{buildBadge}}</div>
                    </div>
                    <p class="about-copyright muted">&copy; {{copyrightYear}} Matthias Schmoldt</p>
                </section>
            </section>
            """;
    }

    private static string WorkspaceSettingsFields(
        HttpContext context,
        WorkspaceDefinition? workspace,
        string defaultRootPath,
        bool createMode)
    {
        var name = workspace?.Name ?? "";
        var description = workspace?.Description ?? "";
        var rootPath = workspace?.RootPath ?? "";
        var allowUploads = workspace?.AllowUploads ?? true;
        var isEnabled = workspace?.IsEnabled ?? true;
        var publicAccessHours = WorkspacePublicAccessHours(workspace);
        var publicAccessField = $$"""<label>{{T(context, "Public access validity (hours)")}}<input name="publicAccessHours" type="number" min="1" step="1" value="{{A(publicAccessHours.ToString())}}"><small class="muted">{{T(context, "External access is available for this duration.")}}</small></label>""";

        return $$"""
            <div class="form-grid">
                <label>{{T(context, "Name")}}
                    <input name="name" value="{{A(name)}}" required maxlength="120">
                </label>
                <label>{{T(context, "Description")}}
                    <textarea name="description" rows="3">{{E(description)}}</textarea>
                </label>
                <label>{{T(context, "Root path")}}
                    <input name="rootPath" value="{{A(rootPath)}}" placeholder="{{A(defaultRootPath)}}">
                </label>
                <label>{{T(context, "Access password")}}
                    <input name="password" type="password" autocomplete="new-password">
                    <small class="muted">{{T(context, "Leave password empty to keep it unchanged.")}}</small>
                </label>
                {{(createMode ? publicAccessField : "")}}
                {{(createMode ? "" : $"""<label class=\"check\"><input type=\"checkbox\" name=\"clearPassword\"> {T(context, "Clear password")}</label>""")}}
                <label class="check"><input type="checkbox" name="allowUploads"{{Checked(allowUploads)}}> {{T(context, "Allow uploads")}}</label>
                <label class="check"><input type="checkbox" name="isEnabled"{{Checked(isEnabled)}}> {{T(context, "Enabled")}}</label>
            </div>
            """;
    }

    // A place's settings as a dialog in the file manager - so they can be changed without leaving
    // the tab. Only what belongs to sharing is in here: the link, the password, the expiry, whether
    // uploads are allowed. The root path and the shared note are deliberately NOT in it; what is not
    // sent stays unchanged (see UpdateWorkspaceAsync).
    // Sharing an existing place. For your own, one press is enough; for someone else's - the shared
    // folder, a connection's - a password is mandatory, because what other people have put there
    // is in it too.
    public string ShareCreateDialog(HttpContext context, ServerEndpoint area, bool passwordRequired)
    {
        var de = Language(context) == "de";
        return $$"""
            <form method="post" action="/api/files/{{area.Id}}/share" class="settings-form" data-share-create-form>
                <fieldset class="settings-group">
                    <legend>{{(de ? "Freigeben" : "Share")}}</legend>
                    <p class="muted settings-hint">{{(de
                        ? $"Aus „{E(area.Name)}“ wird ein Link, den auch jemand ohne Konto öffnen kann. Die Dateien bleiben, wo sie sind - es entsteht keine Kopie."
                        : $"“{E(area.Name)}” becomes a link that someone without an account can open too. The files stay where they are - no copy is made.")}}</p>
                    {{(passwordRequired ? $"""<p class="notice">{E(de
                        ? "Diese Ablage gehört nicht dir allein - dort liegt auch, was andere abgelegt haben. Deshalb ist ein Passwort Pflicht."
                        : "This place is not yours alone - what others put there lies in it too. A password is therefore required.")}</p>""" : "")}}
                    <div class="form-grid">
                        <label>{{T(context, "Name")}}
                            <input name="name" value="{{A(area.Name)}}" required maxlength="120">
                        </label>
                        <label>{{(de ? "Gültigkeit (Stunden)" : "Validity (hours)")}}
                            <input name="publicAccessHours" type="number" min="1" step="1" value="24">
                        </label>
                        <label>{{(de ? "Passwort für den Link" : "Password for the link")}}
                            <input name="password" type="password" autocomplete="new-password" minlength="8"{{(passwordRequired ? " required" : "")}} placeholder="{{A(passwordRequired ? (de ? "mindestens 8 Zeichen" : "at least 8 characters") : (de ? "optional" : "optional"))}}">
                        </label>
                    </div>
                    {{(area.IsReadOnly ? $"""<p class="muted settings-hint">{E(de ? "Diese Ablage ist nur lesbar - über den Link kann niemand hochladen." : "This place is read-only - nobody can upload through the link.")}</p>""" : $$"""<label class="check"><input type="checkbox" name="allowUploads" checked> <span>{{(de ? "Hochladen über den Link erlauben" : "Allow uploads through the link")}}</span></label>""")}}
                </fieldset>
                <div class="actions">
                    <button type="submit" class="primary">{{Icon("globe")}}{{(de ? "Freigeben" : "Share")}}</button>
                    <button type="button" class="button" data-workspace-dialog-close>{{T(context, "Close")}}</button>
                </div>
            </form>
            """;
    }

    public string WorkspaceSettingsDialog(
        HttpContext context,
        WorkspaceDefinition workspace,
        string publicUrl,
        IReadOnlyList<WorkspaceActivityEntry> activityEntries)
    {
        var de = Language(context) == "de";
        var service = context.RequestServices.GetService<WorkspaceService>();
        var hasPassword = service?.HasAccessPassword(workspace) ?? false;
        var remaining = service?.GetPublicAccessRemaining(workspace);
        var expiryText = remaining is null
            ? (de ? "läuft nicht ab" : "does not expire")
            : remaining.Value <= TimeSpan.Zero
                ? (de ? "abgelaufen" : "expired")
                : (de ? $"noch {WorkspaceRemainingLabel(remaining.Value)}" : $"{WorkspaceRemainingLabel(remaining.Value)} left");

        // Filling the host instead of floating in it: the dialog element is transparent by design,
        // the content brings its own surface - and these settings did not, so they stood naked over
        // the file table. As a full sheet with a bar on top the same markup fits both places it is
        // opened from: a file-manager tab and the places dialog of a running session.
        return $$"""
            <section class="share-settings-page">
                <header class="share-settings-head">
                    <button type="button" class="icon-button share-settings-back" data-workspace-dialog-close title="{{A(T(context, "Back"))}}" aria-label="{{A(T(context, "Back"))}}">{{Icon("arrow-left")}}</button>
                    <span class="share-settings-title">
                        <strong>{{E(workspace.Name)}}</strong>
                        <small>{{(de ? "Freigabe-Einstellungen" : "Share settings")}}</small>
                    </span>
                </header>
            <form method="post" action="/workspaces/{{workspace.Id}}/update" class="settings-form share-settings-body" data-workspace-settings-form>
                {{Csrf(context)}}
                <fieldset class="settings-group">
                    <legend>{{(de ? "Ablage" : "Place")}}</legend>
                    <div class="form-grid">
                        <label>{{T(context, "Name")}}
                            <input name="name" value="{{A(workspace.Name)}}" required maxlength="120">
                        </label>
                        <label>{{T(context, "Description")}}
                            <input name="description" value="{{A(workspace.Description)}}">
                        </label>
                    </div>
                    <label class="check"><input type="checkbox" name="allowUploads"{{Checked(workspace.AllowUploads)}}> <span>{{(de ? "Hochladen erlauben" : "Allow uploads")}}</span></label>
                    <label class="check"><input type="checkbox" name="isEnabled"{{Checked(workspace.IsEnabled)}}> <span>{{T(context, "Enabled")}}</span></label>
                </fieldset>
                <fieldset class="settings-group">
                    <legend>{{(de ? "Freigabe" : "Sharing")}}</legend>
                    <p class="muted settings-hint">{{(de
                        ? "Mit diesem Link kommt auch jemand hinein, der kein Konto hat. Ohne Passwort genügt der Link allein - wer ihn hat, ist drin."
                        : "This link lets in someone without an account. With no password the link alone is enough - whoever has it, is in.")}}</p>
                    <div class="workspace-share-line">
                        <code data-workspace-link>{{E(publicUrl)}}</code>
                        <button type="button" class="button" data-workspace-copy="{{A(publicUrl)}}">{{Icon("copy")}}{{T(context, "Copy to clipboard")}}</button>
                    </div>
                    <p class="muted settings-hint">{{(de ? "Gültigkeit: " : "Validity: ")}}{{E(expiryText)}}</p>
                    <div class="form-grid">
                        <label>{{(de ? "Passwort für den Link" : "Password for the link")}}
                            <input name="password" type="password" autocomplete="new-password" placeholder="{{A(hasPassword ? (de ? "gesetzt - leer lassen, um es zu behalten" : "set - leave empty to keep it") : (de ? "keines" : "none"))}}">
                        </label>
                    </div>
                    {{(hasPassword ? $"""<label class="check"><input type="checkbox" name="clearPassword"> <span>{E(de ? "Passwort entfernen" : "Remove password")}</span></label>""" : "")}}
                </fieldset>
                <fieldset class="settings-group">
                    <legend>{{T(context, "Log")}}</legend>
                    <p class="muted settings-hint">{{(de
                        ? "Wer über den Link was getan hat. Das steht nirgends sonst - der Dateimanager führt kein Protokoll, weil dort nur zu sehen ist, was man selbst tut."
                        : "Who did what through the link. This is recorded nowhere else - the file manager keeps no log, because there you only see what you do yourself.")}}</p>
                    {{WorkspaceActivityList(context, activityEntries)}}
                </fieldset>
                <div class="actions">
                    <button type="submit" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button>
                    <button type="button" class="button" data-workspace-dialog-close>{{T(context, "Close")}}</button>
                </div>
            </form>
            </section>
            """;
    }

    // The log in the dialog: brief, with the most recent entries first. The long table of the old
    // page does not fit here - what matters is what happened last, not a complete file.
    private static string WorkspaceActivityList(HttpContext context, IReadOnlyList<WorkspaceActivityEntry> entries)
    {
        var de = Language(context) == "de";
        if (entries.Count == 0)
        {
            return $"""<p class="muted">{E(T(context, "No activity yet."))}</p>""";
        }

        var rows = string.Join("", entries.Take(50).Select(entry => $$"""
            <li class="share-log-entry">
                <span class="share-log-time">{{E(entry.Timestamp.ToLocalTime().ToString("dd.MM. HH:mm"))}}</span>
                <span class="badge">{{E(entry.Mode)}}</span>
                <span class="share-log-actor">{{E(entry.Actor)}}</span>
                <span class="share-log-action">{{E(entry.Action)}}</span>
                <code class="share-log-path">{{E(entry.Path)}}</code>
            </li>
            """));

        var more = entries.Count > 50
            ? $"""<p class="muted settings-hint">{E(de ? $"… und {entries.Count - 50} weitere" : $"… and {entries.Count - 50} more")}</p>"""
            : "";

        return $"""<ul class="share-log">{rows}</ul>{more}""";
    }

    private static string WorkspaceRemainingLabel(TimeSpan remaining)
    {
        return remaining.TotalHours >= 1
            ? $"{(int)Math.Ceiling(remaining.TotalHours)} h"
            : $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalMinutes))} min";
    }

    private static string WorkspaceSettingsPanel(HttpContext context, WorkspaceDefinition workspace, string defaultRootPath)
    {
        return $$"""
            <section class="panel">
                <h2>{{T(context, "Settings")}}</h2>
                <form method="post" action="/workspaces/{{workspace.Id}}/update" class="stack">
                    {{Csrf(context)}}
                    <input type="hidden" name="tab" value="settings">
                    {{WorkspaceSettingsFields(context, workspace, defaultRootPath, false)}}
                    <div class="actions">
                        <button type="submit" class="primary">{{Icon("save")}}{{T(context, "Save")}}</button>
                    </div>
                </form>
            </section>
            """;
    }

    private static string WorkspaceFilesPanel(
        HttpContext context,
        WorkspaceDefinition workspace,
        FileGatewayListResult? listing,
        bool canDelete,
        bool canUpload,
        string baseUrl)
    {
        var currentPath = listing?.Path ?? "/";
        var parentPath = listing?.ParentPath ?? "/";
        var refreshUrl = WorkspaceTabUrl(baseUrl, "files", currentPath);
        var hasEntries = listing is not null && listing.Entries.Count > 0;
        var parentDisabled = string.Equals(currentPath, parentPath, StringComparison.Ordinal);
        var parentRow = parentDisabled
            ? $$"""
                <tr class="parent-directory is-root-directory">
                    <td class="file-select-cell"></td>
                    <td>
                        <button type="button" class="file-name-button" disabled title="{{A(currentPath)}}">
                            {{Icon("folder-up")}}<span>..</span>
                        </button>
                    </td>
                    <td>-</td>
                    <td>-</td>
                    <td class="file-actions-cell"></td>
                </tr>
                """
            : $$"""
                <tr class="parent-directory">
                    <td class="file-select-cell"></td>
                    <td>
                        <a class="file-name-button" href="{{A(WorkspaceFileUrl(baseUrl, parentPath))}}" title="{{A(parentPath)}}">
                            {{Icon("folder-up")}}<span>..</span>
                        </a>
                    </td>
                    <td>-</td>
                    <td>-</td>
                    <td class="file-actions-cell">
                        <a class="file-action-button" href="{{A(WorkspaceFileUrl(baseUrl, parentPath))}}">
                            {{Icon("folder-up")}}<span>{{T(context, "Open")}}</span>
                        </a>
                    </td>
                </tr>
                """;
        var rows = !hasEntries
            ? $"""<tr><td colspan="5" class="file-empty">{T(context, "This folder is empty.")}</td></tr>"""
            : string.Join("", listing!.Entries.Select(entry =>
            {
                var entryPath = WorkspaceFileUrl(baseUrl, entry.Path);
                var downloadUrl = $"{baseUrl}/download?path={Uri.EscapeDataString(entry.Path)}";
                var nameCell = entry.IsDirectory
                    ? $$"""<a class="file-name-button" href="{{A(entryPath)}}">{{Icon("folder")}}<span>{{E(entry.Name)}}</span></a>"""
                    : $$"""<a class="file-name-button" href="{{A(downloadUrl)}}">{{Icon("file")}}<span>{{E(entry.Name)}}</span></a>""";
                var actionCell = entry.IsDirectory
                    ? $$"""<a class="file-action-button" href="{{A(entryPath)}}">{{Icon("folder")}}<span>{{T(context, "Open")}}</span></a>"""
                    : $$"""<a class="file-action-button" href="{{A(downloadUrl)}}">{{Icon("download")}}<span>{{T(context, "Download")}}</span></a>""";
                var deleteCell = canDelete
                    ? $$"""
                        <form method="post" action="{{A($"{baseUrl}/delete-entry")}}" class="inline">
                            {{Csrf(context)}}
                            <input type="hidden" name="path" value="{{A(entry.Path)}}">
                            <input type="hidden" name="returnPath" value="{{A(currentPath)}}">
                            <button type="submit" class="file-action-button danger">{{Icon("trash")}}<span>{{T(context, "Delete")}}</span></button>
                        </form>
                        """
                    : "";

                return $$"""
                    <tr class="{{(entry.IsDirectory ? "is-directory" : "is-file")}}">
                        <td class="file-select-cell"></td>
                        <td>{{nameCell}}</td>
                        <td>{{(entry.Size is null ? "-" : $"{entry.Size:N0}")}}</td>
                        <td>{{(entry.ModifiedAt is null ? "-" : entry.ModifiedAt.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm"))}}</td>
                        <td class="file-actions-cell"><div class="file-row-actions">{{actionCell}}{{deleteCell}}</div></td>
                    </tr>
                    """;
            }));

        var createMenu = ToolbarMenu(
            "file-menu file-create-menu",
            "file-tool-button file-menu-trigger",
            T(context, "Create"),
            Icon("plus"),
            Attr("title", T(context, "Create")),
            $$"""
                <form method="post" action="{{A($"{baseUrl}/mkdir")}}" class="workspace-menu-form">
                    {{Csrf(context)}}
                    <input type="hidden" name="path" value="{{A(currentPath)}}">
                    <input type="hidden" name="tab" value="files">
                    <label class="workspace-menu-field">
                        <span>{{T(context, "Directory")}}</span>
                        <input type="text" class="toolbar-input workspace-menu-input" name="name" placeholder="{{A(T(context, "Name"))}}" required>
                    </label>
                    <button type="submit" class="toolbar-button toolbar-button--primary">{{Icon("folder-plus")}}<span>{{T(context, "Create folder")}}</span></button>
                </form>
                """,
            $$"""
                <form method="post" action="{{A($"{baseUrl}/create-file")}}" class="workspace-menu-form">
                    {{Csrf(context)}}
                    <input type="hidden" name="path" value="{{A(currentPath)}}">
                    <input type="hidden" name="tab" value="files">
                    <label class="workspace-menu-field">
                        <span>{{T(context, "File")}}</span>
                        <input type="text" class="toolbar-input workspace-menu-input" name="name" placeholder="{{A(T(context, "Name"))}}" required>
                    </label>
                    <button type="submit" class="toolbar-button toolbar-button--primary">{{Icon("file")}}<span>{{T(context, "Create file")}}</span></button>
                </form>
                """
        );

        var uploadForm = canUpload
            ? $$"""
                <form method="post" action="{{A($"{baseUrl}/upload")}}" enctype="multipart/form-data" class="workspace-upload-form">
                    {{Csrf(context)}}
                    <input type="hidden" name="path" value="{{A(currentPath)}}">
                    <input type="hidden" name="tab" value="files">
                    {{ToolbarUploadButton(T(context, "Upload"), Icon("upload"), "file-upload-button", "", "onchange=\"this.form.submit()\"")}}
                </form>
                """
            : "";

        return $$"""
            <section class="file-manager workspace-file-manager">
                <div class="file-toolbar">
                    <div class="toolbar-group file-toolbar-group file-toolbar-main">
                        <a class="toolbar-button toolbar-icon-button" href="{{A(refreshUrl)}}" title="{{A(T(context, "Refresh"))}}" aria-label="{{A(T(context, "Refresh"))}}">
                            {{Icon("refresh")}}
                        </a>
                        <form method="get" action="{{A(WorkspaceTabUrl(baseUrl, "files", null))}}" class="workspace-path-form">
                            {{ToolbarInput("file-path-input", currentPath, T(context, "Path"))}}
                            <button type="submit" class="toolbar-button">{{Icon("folder")}}<span>{{T(context, "Open")}}</span></button>
                        </form>
                        {{createMenu}}
                    </div>
                    <div class="toolbar-group file-toolbar-group file-toolbar-transfer">
                        {{uploadForm}}
                    </div>
                </div>
                <div class="file-message hidden"></div>
                <div class="file-table-wrap" data-file-drop-target>
                    <div class="file-drop-overlay hidden" data-file-drop-overlay>
                        <strong>{{T(context, "Drop files here")}}</strong>
                        <span class="muted">{{T(context, "Current folder")}}: <span data-file-drop-overlay-path>{{E(currentPath)}}</span></span>
                    </div>
                    <table class="file-table">
                        <thead>
                            <tr>
                                <th class="file-select-heading"></th>
                                <th>{{T(context, "Name")}}</th>
                                <th>{{T(context, "Size")}}</th>
                                <th>{{T(context, "Modified")}}</th>
                                <th class="file-actions-heading">{{T(context, "Actions")}}</th>
                            </tr>
                        </thead>
                        <tbody>{{parentRow}}{{rows}}</tbody>
                    </table>
                </div>
            </section>
            """;
    }

    // A workspace's files live in the file manager - as the place "Workspaces/<name>", with the
    // same tool as everywhere else. A second, smaller file view used to sit next to it; two UIs for
    // the same thing are one too many. What the page keeps is what only it can do: the link, the
    // password, the expiry and the shared note.
    private static string WorkspaceFilesPointer(HttpContext context, WorkspaceDefinition workspace, string areaId)
    {
        var de = Language(context) == "de";
        return $$"""
            <section class="panel workspace-files-pointer">
                <h3>{{(de ? "Die Dateien liegen im Dateimanager" : "The files live in the file manager")}}</h3>
                <p class="muted">{{(de
                    ? "Dieser Workspace erscheint dort als Ablage „Workspaces/" + E(workspace.Name) + "“ - mit Suche, Mehrfachauswahl, Ziehen und Ablegen und allem anderen, was der Dateimanager kann."
                    : "This workspace shows up there as the place “Workspaces/" + E(workspace.Name) + "” - with search, multiple selection, drag and drop and everything else the file manager can do.")}}</p>
                {{(workspace.AllowUploads ? "" : $"""<p class="muted">{E(de ? "Uploads sind für diesen Workspace abgeschaltet - die Ablage ist dort nur lesbar." : "Uploads are off for this workspace - the place is read-only there.")}</p>""")}}
                <div class="actions">
                    <button type="button" class="button primary" data-shell-open-server="{{A(areaId)}}">{{Icon("folder")}}{{(de ? "Im Dateimanager öffnen" : "Open in the file manager")}}</button>
                </div>
            </section>
            """;
    }
    private static string WorkspaceContentShell(
        HttpContext context,
        WorkspaceDefinition workspace,
        FileGatewayListResult? listing,
        IReadOnlyList<WorkspacePresenceSnapshot> sessions,
        IReadOnlyList<WorkspaceActivityEntry> activityEntries,
        string selectedTab,
        bool canEditSelected,
        bool includeInfo,
        bool includeSettings,
        string baseUrl,
        string publicUrl,
        string defaultRootPath,
        string currentPath,
        // The place in the file manager - set only for the signed-in view. The public page does not
        // have it: nobody is signed in there, and the file manager sits behind the sign-in. So the
        // public page still shows the files itself.
        string fileManagerAreaId)
    {
        var filesTabActive = selectedTab == "files";
        var infoTabActive = selectedTab == "info";
        var settingsTabActive = selectedTab == "settings";
        var logTabActive = selectedTab == "log";

        return $$"""
            <section class="workspace-tab-shell panel" data-workspace-tab-root="1" data-workspace-tab-key="{{A(workspace.Id.ToString("N"))}}" data-workspace-default-tab="files">
                <div class="workspace-tab-strip" role="tablist" aria-label="{{A(T(context, "Workspace content"))}}">
                    <a class="workspace-tab-button{{(filesTabActive ? " active" : "")}}" href="{{A(WorkspaceTabUrl(baseUrl, "files", currentPath))}}" data-workspace-tab="files" role="tab" aria-selected="{{A(filesTabActive ? "true" : "false")}}">{{Icon("folder")}}{{T(context, "Files")}}</a>
                    {{(includeInfo ? $"""<a class="workspace-tab-button{(infoTabActive ? " active" : "")}" href="{A(WorkspaceTabUrl(baseUrl, "info", currentPath))}" data-workspace-tab="info" role="tab" aria-selected="{A(infoTabActive ? "true" : "false")}">{Icon("info")}{T(context, "Info")}</a>""" : "")}}
                    {{(includeSettings ? $"""<a class="workspace-tab-button{(settingsTabActive ? " active" : "")}" href="{A(WorkspaceTabUrl(baseUrl, "settings", currentPath))}" data-workspace-tab="settings" role="tab" aria-selected="{A(settingsTabActive ? "true" : "false")}">{Icon("settings")}{T(context, "Settings")}</a>""" : "")}}
                    <a class="workspace-tab-button{{(logTabActive ? " active" : "")}}" href="{{A(WorkspaceTabUrl(baseUrl, "log", currentPath))}}" data-workspace-tab="log" role="tab" aria-selected="{{A(logTabActive ? "true" : "false")}}">{{Icon("list")}}{{T(context, "Log")}}</a>
                </div>
                <div class="workspace-tab-panels">
                    <div class="workspace-tab-panel{{(filesTabActive ? "" : " hidden")}}" data-workspace-panel="files">
                        {{(string.IsNullOrEmpty(fileManagerAreaId)
                            ? WorkspaceFilesPanel(context, workspace, listing, canEditSelected, workspace.AllowUploads, baseUrl)
                            : WorkspaceFilesPointer(context, workspace, fileManagerAreaId))}}
                    </div>
                    {{(includeInfo ? $$"""
                    <div class="workspace-tab-panel{{(infoTabActive ? "" : " hidden")}}" data-workspace-panel="info">
                        <div class="stack">
                            <section class="panel stack workspace-info-panel">
                                <div class="row split workspace-summary">
                                    <div>
                                        <p class="eyebrow">{{T(context, "Info")}}</p>
                                        <h2>{{E(workspace.Name)}}</h2>
                                        <p class="muted">{{E(workspace.Description)}}</p>
                                        {{WorkspacePublicUrlLine(context, publicUrl)}}
                                        <p class="muted"><strong>{{T(context, "Valid until")}}:</strong> {{E(WorkspacePublicAccessExpiresText(context, workspace))}}</p>
                                        <p class="muted"><strong>{{T(context, "Root path")}}:</strong> <code>{{E(string.IsNullOrWhiteSpace(workspace.RootPath) ? defaultRootPath : workspace.RootPath)}}</code></p>
                                    </div>
                                    <div class="stack workspace-summary-badges">
                                        <span class="badge">{{(WorkspaceIsPublicAccessActive(workspace) ? T(context, "Active") : T(context, "Expired"))}}</span>
                                        <span class="badge">{{(workspace.AllowUploads ? T(context, "Allow uploads") : T(context, "Uploads disabled"))}}</span>
                                    </div>
                                </div>
                                <div class="actions workspace-info-actions">
                                    <form method="post" action="/workspaces/{{workspace.Id}}/extend" class="inline">
                                        {{Csrf(context)}}
                                        <button type="submit" name="hours" value="24" class="button">{{Icon("clock")}}{{T(context, "+24h")}}</button>
                                        <button type="submit" name="hours" value="168" class="button">{{Icon("calendar")}}{{T(context, "+7d")}}</button>
                                    </form>
                                </div>
                            </section>
                        </div>
                    </div>
                    """ : "")}}
                    {{(includeSettings ? $$"""
                    <div class="workspace-tab-panel{{(settingsTabActive ? "" : " hidden")}}" data-workspace-panel="settings">
                        <div class="stack">
                            {{WorkspaceSettingsPanel(context, workspace, defaultRootPath)}}
                            {{WorkspaceSessionsPanel(context, sessions)}}
                            {{WorkspaceDangerPanel(context, workspace, "/workspaces")}}
                        </div>
                    </div>
                    """ : "")}}
                    <div class="workspace-tab-panel{{(logTabActive ? "" : " hidden")}}" data-workspace-panel="log">
                        {{WorkspaceActivityPanel(context, activityEntries)}}
                    </div>
                </div>
            </section>
            """;
    }

    private static string WorkspaceActivityPanel(HttpContext context, IReadOnlyList<WorkspaceActivityEntry> activityEntries)
    {
        var rows = activityEntries.Count == 0
            ? $"""<tr><td colspan="5" class="muted">{T(context, "No activity yet.")}</td></tr>"""
            : string.Join("", activityEntries.Select(entry => $$"""
                <tr>
                    <td>{{E(entry.Timestamp.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"))}}</td>
                    <td><span class="badge">{{E(entry.Mode)}}</span> {{E(entry.Actor)}}</td>
                    <td>{{E(entry.Action)}}</td>
                    <td><code>{{E(entry.Path)}}</code></td>
                    <td>{{E(entry.Details)}}</td>
                </tr>
                """));

        return $$"""
            <section class="panel">
                <div class="row split">
                    <div>
                        <h2>{{T(context, "Log")}}</h2>
                    </div>
                </div>
                <div class="table-wrap workspace-activity-table-wrap">
                    <table class="workspace-activity-table">
                        <thead>
                            <tr>
                                <th>{{T(context, "Time")}}</th>
                                <th>{{T(context, "Actor")}}</th>
                                <th>{{T(context, "Action")}}</th>
                                <th>{{T(context, "Path")}}</th>
                                <th>{{T(context, "Details")}}</th>
                            </tr>
                        </thead>
                        <tbody>{{rows}}</tbody>
                    </table>
                </div>
            </section>
            """;
    }

    private static string WorkspacePublicUrlLine(HttpContext context, string publicUrl)
    {
        var copyLabel = T(context, "Copy to clipboard");
        return $$"""
            <div class="workspace-url-line muted" data-workspace-public-url="{{A(publicUrl)}}">
                <strong>{{T(context, "Public URL")}}:</strong>
                <code>{{E(publicUrl)}}</code>
                <button
                    type="button"
                    class="toolbar-button toolbar-icon-button workspace-url-copy"
                    title="{{A(copyLabel)}}"
                    aria-label="{{A(copyLabel)}}"
                    onclick='window.MatgateCopyText({{JsonSerializer.Serialize(publicUrl)}}); return false;'>
                    {{Icon("clipboard")}}
                </button>
            </div>
            """;
    }

    private static string WorkspaceTabUrl(string baseUrl, string tabName, string? path)
    {
        var url = $"{baseUrl}?tab={Uri.EscapeDataString(tabName)}";
        if (!string.IsNullOrWhiteSpace(path))
        {
            url += $"&path={Uri.EscapeDataString(path)}";
        }

        return url;
    }

    private static string WorkspaceSelectedTab(HttpContext context, bool includeInfo = false, bool includeSettings = false)
    {
        var requested = Clean(context.Request.Query["tab"].ToString(), "").ToLowerInvariant();
        return requested switch
        {
            "files" => "files",
            "info" when includeInfo => "info",
            "settings" when includeSettings => "settings",
            "log" => "log",
            _ => "files"
        };
    }

    private static bool WorkspaceIsPublicAccessActive(WorkspaceDefinition workspace)
    {
        return workspace.PublicAccessExpiresAt is null || workspace.PublicAccessExpiresAt > DateTimeOffset.UtcNow;
    }

    private static string WorkspacePublicAccessExpiresText(HttpContext context, WorkspaceDefinition workspace)
    {
        if (workspace.PublicAccessExpiresAt is null)
        {
            return T(context, "No expiry set");
        }

        return workspace.PublicAccessExpiresAt.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm");
    }

    private static string WorkspaceValidityLabel(HttpContext context, WorkspaceDefinition workspace)
    {
        var remaining = workspace.PublicAccessExpiresAt.HasValue
            ? workspace.PublicAccessExpiresAt.Value - DateTimeOffset.UtcNow
            : TimeSpan.FromHours(24);

        if (remaining <= TimeSpan.Zero)
        {
            return T(context, "Expired");
        }

        if (remaining.TotalDays >= 1)
        {
            return $"{(int)Math.Ceiling(remaining.TotalDays)}d";
        }

        if (remaining.TotalHours >= 1)
        {
            return $"{(int)Math.Ceiling(remaining.TotalHours)}h";
        }

        return $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalMinutes))}m";
    }

    private static int WorkspacePublicAccessHours(WorkspaceDefinition? workspace)
    {
        if (workspace?.PublicAccessExpiresAt is { } expiresAt)
        {
            var remaining = expiresAt - DateTimeOffset.UtcNow;
            if (remaining > TimeSpan.Zero)
            {
                return Math.Clamp((int)Math.Ceiling(remaining.TotalHours), 1, 24 * 365 * 10);
            }
        }

        return 24;
    }

    private static string WorkspaceSessionsPanel(HttpContext context, IReadOnlyList<WorkspacePresenceSnapshot> sessions)
    {
        var rows = sessions.Count == 0
            ? $"""<tr><td colspan="3" class="muted">{T(context, "No sessions yet.")}</td></tr>"""
            : string.Join("", sessions.Select(session => $$"""
                <tr>
                    <td>{{E(session.DisplayName)}}</td>
                    <td><span class="badge">{{E(session.Mode)}}</span></td>
                    <td>{{E(session.LastSeenAt.ToLocalTime().ToString("yyyy-MM-dd HH:mm"))}}</td>
                </tr>
                """));

        return $$"""
            <section class="panel">
                <h2>{{T(context, "Open sessions")}}</h2>
                <div class="table-wrap">
                    <table>
                        <thead>
                            <tr>
                                <th>{{T(context, "Name")}}</th>
                                <th>{{T(context, "Type")}}</th>
                                <th>{{T(context, "Modified")}}</th>
                            </tr>
                        </thead>
                        <tbody>{{rows}}</tbody>
                    </table>
                </div>
            </section>
            """;
    }

    private static string WorkspaceDangerPanel(HttpContext context, WorkspaceDefinition workspace, string baseRoute)
    {
        return $$"""
            <section class="panel danger-zone">
                <h2>{{T(context, "Remove")}}</h2>
                <form method="post" action="{{A($"{baseRoute}/{workspace.Id}/delete")}}">
                    {{Csrf(context)}}
                    <button type="submit" class="danger">{{Icon("trash")}}{{T(context, "Delete workspace")}}</button>
                </form>
            </section>
            """;
    }

    private static string WorkspaceFileUrl(string baseUrl, string path)
    {
        var url = WorkspaceTabUrl(baseUrl, "files", path);
        return url;
    }

    private static string ManagedServersSection(
        HttpContext context,
        string title,
        IReadOnlyList<ServerEndpoint> servers,
        string emptyMessage,
        IReadOnlyList<MatgateUser> users)
    {
        var rows = servers.Count == 0
            ? $"""<tr><td colspan="7" class="muted">{E(emptyMessage)}</td></tr>"""
            : string.Join("", servers.Select(server => $$"""
                <tr>
                    <td><span class="server-name-cell">{{ServerIcon(server, "small")}}<a href="/admin/servers/{{server.Id}}">{{E(server.Name)}}</a></span></td>
                    <td>{{ServerScopeBadge(context, server, users)}}</td>
                    <td>{{(string.IsNullOrWhiteSpace(server.FolderName) ? "<span class=\"muted\">-</span>" : ServerFolderBadge(context, server))}}</td>
                    <td><span class="badge">{{E(ServerProtocolLabel(server.Protocol))}}</span></td>
                    <td>{{E(ServerTargetValue(server))}}</td>
                    <td>{{(server.IsEnabled ? T(context, "Active") : T(context, "Off"))}}</td>
                    <td class="table-actions">
                        <a class="button toolbar-button toolbar-icon-button" href="/connect/{{server.Id}}" data-shell-open-tab="1" data-shell-title="{{A(server.Name)}}" data-shell-description="{{A(T(context, "Connection"))}}" title="{{A(T(context, "Open"))}}" aria-label="{{A(T(context, "Open"))}}">
                            {{Icon("play")}}
                        </a>
                    </td>
                </tr>
                """));

        return $$"""
            <section class="home-management">
                <section class="panel">
                    <h2>{{E(title)}}</h2>
                    <div class="table-wrap">
                        <table>
                            <thead><tr><th>{{T(context, "Name")}}</th><th>{{T(context, "Scope")}}</th><th>{{T(context, "Folder")}}</th><th>{{T(context, "Type")}}</th><th>{{T(context, "Target")}}</th><th>{{T(context, "Status")}}</th><th class="table-actions">{{T(context, "Actions")}}</th></tr></thead>
                            <tbody>{{rows}}</tbody>
                        </table>
                    </div>
                </section>
                </section>
            """;
    }

    private static string WorkspaceListSection(HttpContext context, IReadOnlyList<WorkspaceDefinition> workspaces)
    {
        var rows = workspaces.Count == 0
            ? $"""<tr><td colspan="5" class="muted">{T(context, "No workspaces yet.")}</td></tr>"""
            : string.Join("", workspaces
                .OrderByDescending(WorkspaceIsPublicAccessActive)
                .ThenBy(workspace => workspace.Name)
                .Select(workspace => $$"""
                    <tr>
                        <td><span class="server-name-cell">{{Icon("briefcase")}}<a href="/workspaces/{{workspace.Id}}" data-shell-open-tab="1" data-shell-title="{{A(workspace.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}">{{E(workspace.Name)}}</a></span></td>
                        <td><span class="badge">{{(workspace.IsPrivate ? T(context, "Personal") : T(context, "Shared"))}}</span></td>
                        <td><span class="badge" title="{{A(WorkspacePublicAccessExpiresText(context, workspace))}}">{{E(WorkspaceValidityLabel(context, workspace))}}</span></td>
                        <td><span class="badge">{{(WorkspaceIsPublicAccessActive(workspace) ? T(context, "Active") : T(context, "Expired"))}}</span></td>
                        <td class="table-actions">
                            <a class="button toolbar-button toolbar-icon-button" href="/workspaces/{{workspace.Id}}" data-shell-open-tab="1" data-shell-title="{{A(workspace.Name)}}" data-shell-description="{{A(T(context, "Workspace"))}}" title="{{A(T(context, "Open"))}}" aria-label="{{A(T(context, "Open"))}}">
                                {{Icon("external-link")}}
                            </a>
                        </td>
                    </tr>
                    """));

        return $$"""
            <section class="panel">
                <div class="table-wrap">
                    <table>
                        <thead><tr><th>{{T(context, "Name")}}</th><th>{{T(context, "Scope")}}</th><th>{{T(context, "Validity")}}</th><th>{{T(context, "Status")}}</th><th class="table-actions">{{T(context, "Actions")}}</th></tr></thead>
                        <tbody>{{rows}}</tbody>
                    </table>
                </div>
            </section>
            """;
    }

    // The client-side "availableServers" entry for one server (used by openServer / quick-connect
    // and to rebuild the New-connection panel live after a server is added/changed).
    // What kind of place this is, so the file manager can group them without guessing from the
    // name. Empty for everything that is not a place.
    private static object ServerChoicePayload(ServerEndpoint server) => new
    {
        areaKind = server.AreaKind,
        // Read-only: the file manager hides the buttons that would achieve nothing here. A write
        // attempt is rejected in FileGatewayService anyway.
        readOnly = server.IsReadOnly,
        areaSourceId = server.AreaSourceId?.ToString() ?? "",
        id = server.Id.ToString(),
        name = server.Name,
        // Shared (no owner) - only those have an access page.
        shared = server.OwnerUserId is null,
        // The folder it is filed in, for the server manager's tree.
        folder = (server.FolderName ?? "").Trim(),
        protocol = server.Protocol.ToString().ToUpperInvariant(),
        iconKey = server.SignKey(),
        iconHtml = Icon(server.SignKey()),
        // PG / My / MS on a database's sign in the side panel.
        signTag = server.SignKey() == "database" ? server.SignTag() : "",
        // The protocol's colour dot - so a button in the bar carries the same shade as the card it
        // came from.
        protoColor = ProtocolAccent(server.Protocol),
        // "matgate" | "guacamole" | "": what opens a remote desktop or terminal here.
        engine = server.EffectiveEngine(Matgate.Services.DisplayBridge.Available, Matgate.Services.GuacamoleLauncher.Available),
        target = ServerTargetValue(server),
        // "native" | "chromiumvnc" | "firefoxvnc" - farm modes open a VNC session instead of a proxy tab.
        renderMode = server.Protocol == ServerProtocol.Website
            ? server.WebsiteRenderMode.ToString().ToLowerInvariant()
            : "native",
        // The connection's own file area, so a session can open it straight from its toolbar. Only
        // meaningful for real connections - an area does not have an area of its own.
        fileAreaId = server.Protocol == ServerProtocol.Local
            ? ""
            : FileShareService.ConnectionAreaId(server.Id).ToString()
    };

    // JSON payload for the live refresh of the New-connection panel: the rendered HTML plus the
    // updated availableServers list, so the shell can swap it in without a full page reload.
    public string ConnectionsPanelPayload(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<WorkspaceDefinition> workspaces)
    {
        return JsonSerializer.Serialize(new
        {
            html = ConnectionChoiceSections(context, user, servers, workspaces, true),
            servers = servers.Select(ServerChoicePayload),
            side = SidebarPayload(user, servers, workspaces, context)
        }, new JsonSerializerOptions(JsonSerializerDefaults.Web));
    }

    // What the side panel groups the connections by, beyond their folders: the user's favourites, what they
    // used last (the newest first), and the shares - each with the place its "Open" leads to, as on the
    // start page.
    public const string FolderObjectsKey = "matgate.folders";

    private static object SidebarPayload(
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        HttpContext context)
    {
        var known = servers.Select(server => server.Id).ToHashSet();
        var workspaceAreas = servers
            .Where(server => server.Protocol == ServerProtocol.Local && server.AreaKind == "workspace")
            .ToList();
        return new
        {
            // Folders that exist on their own, shown also while nothing lies in them.
            folders = context.Items[FolderObjectsKey] as List<string> ?? [],
            favorites = (user.FavoriteServerIds ?? [])
                .Where(known.Contains)
                .Select(id => id.ToString()),
            // The user's own order of the connections (dragged), and those they may put into another folder.
            order = (user.ConnectionOrder ?? []).Where(known.Contains).Select(id => id.ToString()),
            movable = servers.Where(server => server.Protocol != ServerProtocol.Local && Services.AccessResolver.Level(user, server) >= AccessLevel.Edit).Select(server => server.Id.ToString()),
            recent = (user.RecentConnections ?? [])
                .Select(entry => entry.ServerId)
                .Where(known.Contains)
                .Distinct()
                .Take(5)
                .Select(id => id.ToString()),
            shares = workspaces
                .Where(workspace => workspace.IsEnabled)
                .OrderBy(workspace => workspace.Name, StringComparer.OrdinalIgnoreCase)
                .Select(workspace => new
                {
                    id = workspace.Id.ToString(),
                    name = workspace.Name,
                    note = workspace.Description ?? "",
                    targetId = (workspaceAreas.FirstOrDefault(area => area.AreaSourceId == workspace.Id)?.Id ?? workspace.AreaId)?.ToString() ?? ""
                })
        };
    }

    // The logged-in home / "New Tab" page: a single, scrollable column of sections
    // (header, search, quick-connect, folders, recently used, favorites, all connections).
    private static string ConnectionChoiceSections(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        bool includeEditButtons)
    {
        var de = Language(context) == "de";
        var canCreate = user.IsAdmin || user.CanManageServers || user.CanCreateServers;
        var canQuick = user.IsAdmin || user.CanQuickConnect;
        var returnUrl = $"{context.Request.Path}{context.Request.QueryString}";

        // No question mark after user: at this point it exists. The earlier "user?." was a leftover
        // that told the compiler it could be missing - whereupon it flagged every hand-off to the
        // sections below as a possible null. Two lines further down it is used without one anyway;
        // one of the two readings had to go.
        var hiddenQuick = (user.Session?.HiddenQuickProtocols ?? []).ToHashSet(StringComparer.Ordinal);
        var quickOrder = user.Session?.QuickProtocolOrder ?? [];
        var protocolDialog = canQuick ? ProtocolDialog(de, hiddenQuick, quickOrder) : "";
        var hidden = (user.HiddenHomeSections ?? []).ToHashSet(StringComparer.Ordinal);
        var quickConnect = canQuick && !hidden.Contains("quick") ? QuickConnectSection(de, hiddenQuick, quickOrder) : "";

        // "Add connection" = create a SAVED connection (needs create rights); the ad-hoc quick connect lives
        // in its tiles and their dialog and needs the quick-connect permission. The head has a button of its
        // own for that dialog only where the tiles are not on the page (switched off as a section, or every
        // protocol hidden): otherwise the tiles' "More" is the way in, and a second button for the same
        // dialog was one too many.
        var quickButton = canQuick && quickConnect.Length == 0
            ? $$"""<button type="button" class="button primary home2-new-connection" data-home2-more>{{Icon("play")}}<span>{{(de ? "Schnell verbinden" : "Quick connect")}}</span></button>"""
            : "";
        var createLabel = de ? "Verbindung anlegen" : "Add connection";
        // A phone has room for "New" beside the title, not for the whole sentence.
        var createButton = canCreate
            ? $$"""<a class="button{{(canQuick ? "" : " primary")}} home2-new-folder" href="/admin/servers/new?return=home" data-shell-open-tab="1" data-shell-title="{{A(de ? "Neue Verbindung" : "New connection")}}" aria-label="{{A(createLabel)}}" title="{{A(createLabel)}}">{{Icon("plus")}}<span class="home2-label-long">{{createLabel}}</span><span class="home2-label-short">{{(de ? "Neu" : "New")}}</span></a>"""
            : "";
        var actionCount = (quickButton.Length > 0 ? 1 : 0) + (createButton.Length > 0 ? 1 : 0);
        var headerActions = actionCount > 0
            ? $$"""<div class="home2-head-actions">{{quickButton}}{{createButton}}</div>"""
            : "";

        // Beside the side panel the page is not the list of connections any more - the panel is. What is
        // left on it is a new connection, and the line under the title says what that is for this user.
        var lead = canQuick && canCreate
            ? (de ? "Schnell verbinden, ohne zu speichern – oder eine Verbindung anlegen, die bleibt." : "Connect quickly without saving – or add a connection that stays.")
            : canQuick
                ? (de ? "Schnell verbinden, ohne etwas zu speichern." : "Connect quickly, without saving anything.")
                : (de ? "Deine gespeicherten Verbindungen stehen links in der Seitenleiste." : "Your saved connections are in the side panel on the left.");
        var head = $$"""
            <section class="home2-head{{(actionCount > 1 ? " home2-head--two" : "")}}">
                <div class="home2-head-copy">
                    <h1><span class="home2-title-list">{{(de ? "Verbindungen" : "Connections")}}</span><span class="home2-title-side">{{(de ? "Neue Verbindung" : "New connection")}}</span></h1>
                    <p class="muted home2-side-hint">{{lead}}</p>
                </div>
                {{headerActions}}
            </section>
            """;

        // Nothing saved yet: what can be done about it, by what this user may do. The same words whether the
        // gateway's places (folders, not connections) are there or not.
        var emptyLine = canCreate && canQuick
            ? (de ? "Lege eine an, die bleibt – oder verbinde dich schnell, ohne zu speichern." : "Add one that stays – or connect quickly without saving.")
            : canCreate
                ? (de ? "Lege deine erste Verbindung an, um loszulegen." : "Add your first connection to get started.")
                : canQuick
                    ? (de ? "Verbinde dich schnell, ohne etwas zu speichern." : "Connect quickly, without saving anything.")
                    : (de ? "Sobald eine Verbindung für dich eingerichtet ist, steht sie hier." : "Once a connection is set up for you, it shows up here.");
        var emptyCreate = canCreate
            ? $$"""<a class="button primary" href="/admin/servers/new?return=home" data-shell-open-tab="1" data-shell-title="{{A(de ? "Neue Verbindung" : "New connection")}}">{{Icon("plus")}}<span>{{createLabel}}</span></a>"""
            : "";
        string NothingSavedYet(string headingTag) => $$"""
            <div>
                <{{headingTag}}>{{(de ? "Noch keine gespeicherten Verbindungen" : "No saved connections yet")}}</{{headingTag}}>
                <p class="muted">{{emptyLine}}</p>
            </div>
            {{emptyCreate}}
            """;

        // Global empty state: no accessible connections at all, not even a place.
        if (servers.Count == 0)
        {
            // Quick connect needs nothing saved: its tiles are there from the first visit on.
            return $$"""
                <section class="home2" data-home2="1">
                    {{head}}
                    {{quickConnect}}
                    <section class="home2-empty">
                        {{NothingSavedYet("h2")}}
                    </section>
                    {{protocolDialog}}
                </section>
                """;
        }

        var searchBox = $$"""
            <section class="home2-search">
                <span class="home2-search-icon">{{Icon("search")}}</span>
                <input type="search" class="home2-search-input" data-home2-search autocomplete="off" spellcheck="false" placeholder="{{A(de ? "Verbindungen, Ordner oder Host suchen…" : "Search connections, folders or hosts…")}}" aria-label="{{A(de ? "Suchen" : "Search")}}">
            </section>
            """;

        // The browser-farm hint: only there when one is configured. A website "via Chromium VNC"
        // fails when all slots are taken - which used to show only on opening. The numbers are
        // fetched by the script, so a slow farm does not hold the page up.
        var farmHint = $$"""
            <section class="home2-section home2-farm-section">
                <p class="home2-farm" data-home2-farm hidden
                   data-label-free="{{A(de ? "Browser-Farm: {free} von {pool} frei" : "Browser farm: {free} of {pool} free")}}"
                   data-label-full="{{A(de ? "Browser-Farm: alle {pool} Plätze belegt" : "Browser farm: all {pool} slots busy")}}"
                   data-label-down="{{A(de ? "Browser-Farm nicht erreichbar" : "Browser farm unreachable")}}">
                    <span class="home2-farm-dot" data-home2-farm-dot></span>
                    <span data-home2-farm-text></span>
                </p>
            </section>
            """;

        var recentSection = RecentConnectionsSection(context, user, servers, includeEditButtons, returnUrl, de);
        // A place is a folder on the gateway, not a connection to a machine. As a card among the
        // connections it read like one - with the same filled button, and sorted alphabetically
        // in between them.
        // The folder of a running session does not belong on the home page: it is there as long as
        // the session is and is reached through it, not through a tile.
        // A workspace's folder is not listed twice: it has a section of its own, and opens the same
        // place from there.
        var areas = servers
            .Where(server => server.Protocol == ServerProtocol.Local
                && server.AreaKind != "session"
                && server.AreaKind != "workspace")
            .ToList();
        var workspaceAreas = servers
            .Where(server => server.Protocol == ServerProtocol.Local && server.AreaKind == "workspace")
            .ToList();
        // A WireGuard tunnel is a way in, not something to open.
        var connections = servers.Where(server => server.Protocol is not (ServerProtocol.Local or ServerProtocol.WireGuard)).ToList();
        // The folder tiles filter the connections, so they count the connections: with the places and the
        // tunnels counted as well, "Unsorted" said 11 where 4 were to be found.
        var filterRow = FilterTilesSection(context, user, connections, de);
        var placesSection = PlacesSection(context, user, areas, returnUrl, de);
        // Places but no connection: the section says so and what to do, instead of standing there empty
        // (the script used to hide it, and the page then said nothing about connections at all).
        var connectionsSection = connections.Count > 0
            ? ConnectionsSection(context, user, connections, includeEditButtons, returnUrl, de)
            : $$"""
                <section class="home2-section home2-all-section" data-home2-all data-home2-nothing-saved>
                    <div class="home2-section-head">
                        <h2>{{Icon("monitor")}}<span>{{(de ? "Verbindungen" : "Connections")}}</span></h2>
                    </div>
                    <div class="home2-empty">
                        {{NothingSavedYet("h3")}}
                    </div>
                </section>
                """;

        // Which sections, in what order: configured under Account -> Home page. What is not ticked
        // is not even built.
        var parts = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["search"] = searchBox,
            ["quick"] = quickConnect,
            ["folders"] = filterRow,
            ["recent"] = recentSection,
            ["connections"] = connectionsSection,
            ["places"] = placesSection,
            ["workspaces"] = WorkspacesSection(context, workspaces, workspaceAreas, de),
            ["farm"] = farmHint,
        };
        var column = string.Join("", HomeLayout.Order(user.HomeSections)
            .Where(key => !hidden.Contains(key))
            .Select(key => parts.GetValueOrDefault(key, "")));

        return $$"""
            <section class="home2" data-home2="1">
                {{head}}
                {{column}}
                <section class="home2-noresults hidden" data-home2-noresults>
                    <p class="muted">{{(de ? "Keine Treffer." : "No matches.")}}</p>
                </section>
                {{protocolDialog}}
            </section>
            """;
    }

    // All protocols offered for a new connection, as tiles on the start page and in the "More" dialog.
    // Only the protocols this user kept, in the order this user gave them; what is hidden simply falls out.
    private static (string Protocol, string Name, string Desc, string IconKey, string Color)[] QuickProtocols(bool de, IReadOnlyCollection<string>? hidden = null, IReadOnlyList<string>? order = null)
    {
        var known = All(de).ToDictionary(entry => entry.Protocol, StringComparer.Ordinal);
        return SessionPreferences.OrderedQuickProtocols(order)
            .Where(known.ContainsKey)
            .Select(key => known[key])
            .Where(entry => hidden is null || !hidden.Contains(entry.Protocol))
            .ToArray();

        // The colours are the theme's protocol colours, as on the cards: one shade per protocol, readable on its
        // tint in light and dark alike. They were the dark theme's shades in both, too pale in the light. The
        // databases have no colour of their own in the themes yet.
        static (string Protocol, string Name, string Desc, string IconKey, string Color)[] All(bool de) => new (string Protocol, string Name, string Desc, string IconKey, string Color)[]
        {
            ("rdp", "RDP", de ? "Remote-Desktop" : "Remote Desktop", "rdp", "var(--proto-rdp)"),
            ("ssh", "SSH", "Linux / Unix", "ssh", "var(--proto-ssh)"),
            ("vnc", "VNC", de ? "Remote-Desktop" : "Remote Desktop", "vnc", "var(--proto-vnc)"),
            ("sftp", "SFTP", de ? "Sichere Dateien" : "Secure files", "sftp", "var(--proto-sftp)"),
            ("smb", "SMB", de ? "Netzwerkfreigabe" : "Network share", "smb", "var(--proto-smb)"),
            // The browser: a website or a device's page, fetched by Matgate and shown in the tab.
            ("website", "Browser", de ? "Webseite oder Gerät über Matgate öffnen (HTTP / HTTPS)" : "Open a website or a device through Matgate (HTTP / HTTPS)", "globe", "var(--proto-website)"),
            ("ftp", "FTP", de ? "Dateiübertragung" : "File transfer", "ftp", "var(--proto-ftp)"),
            ("webdav", "WebDAV", de ? "Dateien über HTTP" : "Files over HTTP", "cloud", "var(--proto-webdav)"),
            // Short names: on a phone the home page's tiles are about 70 pixels wide, and a name is never cut.
            ("mssql", "MSSQL", "Microsoft SQL Server", "database", "#d9534f"),
            ("mysql", "MySQL", "MySQL / MariaDB", "database", "#00758f"),
            ("postgres", "Postgres", "PostgreSQL", "database", "#336791"),
        };
    }

    // The protocol tiles + a "More" tile that opens the full protocol dialog.
    private static string QuickConnectSection(bool de, IReadOnlyCollection<string>? hiddenQuick, IReadOnlyList<string>? order)
    {
        var protocols = QuickProtocols(de, hiddenQuick, order);
        if (protocols.Length == 0)
        {
            // Everything hidden means the user does not want quick connect at all - then the heading
            // and a lone "More" button are not a leftover worth showing.
            return "";
        }

        // All the ones the user kept - before it was the first six, which meant WebDAV as the
        // eighth protocol never showed up on the home page even though it was ticked. Which ones
        // appear is decided by the setting, not by the order.
        var chips = string.Join("", protocols.Select(protocol => $$"""
            <button type="button" class="home2-proto-chip" data-home2-qc="{{A(protocol.Protocol)}}" style="--proto: {{protocol.Color}}" title="{{A(protocol.Desc)}}">
                <span class="home2-proto-chip-icon">{{Icon(protocol.IconKey)}}</span>
                <span class="home2-proto-chip-name">{{E(protocol.Name)}}</span>
            </button>
            """));

        // An even grid of tiles: all of them in one row where there is room, otherwise two rows of the same
        // length (6 and 6 for twelve) instead of a full row and a ragged rest. "More" counts as a tile. On a
        // phone the CSS makes it one row to swipe through, with "More" pinned at its end.
        var tiles = protocols.Length + 1;
        var columns = tiles <= 6 ? tiles : (tiles + 1) / 2;
        // The order and the selection are changed in the settings. A right click on a tile leads there too,
        // but an iPhone has no long press for it: this link is its only way.
        var customise = de ? "Reihenfolge und Auswahl in den Einstellungen" : "Order and selection in the settings";
        return $$"""
            <section class="home2-section home2-quick-section">
                <div class="home2-section-head">
                    <h2>{{Icon("play")}}<span>{{(de ? "Schnell verbinden" : "Quick connect")}}</span></h2>
                    <a class="home2-section-link" href="/account?tab=home#quick-order-list" data-shell-open-tab="1" data-shell-title="{{A(de ? "Einstellungen" : "Settings")}}" title="{{A(customise)}}">{{Icon("sliders")}}<span>{{(de ? "Anpassen" : "Customise")}}</span></a>
                </div>
                <div class="home2-quick-row" style="--qc-n: {{tiles}}; --qc-cols: {{columns}}">
                    {{chips}}
                    <button type="button" class="home2-proto-chip home2-proto-more" data-home2-more>
                        <span class="home2-proto-chip-icon">{{Icon("grid")}}</span>
                        <span class="home2-proto-chip-name">{{(de ? "Mehr" : "More")}}</span>
                    </button>
                </div>
            </section>
            """;
    }

    // Ad-hoc Quick-Connect dialog: pick a protocol, enter host + credentials, connect immediately
    // (nothing is saved). Opened by the "Quick connect" chips/button. Fullscreen on phones (see CSS).
    private static string ProtocolDialog(bool de, IReadOnlyCollection<string>? hiddenQuick, IReadOnlyList<string>? order)
    {
        var protocols = QuickProtocols(de, hiddenQuick, order);
        // The browser may start without an address: its tab has an address bar to type into, with host names
        // for websites and under a path of Matgate's alike.
        const bool blankBrowser = true;
        var browserPlaceholder = de
            ? "z. B. nas.local oder 10.0.0.1:8443  (leer: leerer Browser)"
            : "e.g. nas.local or 10.0.0.1:8443  (empty: a blank browser)";

        // The dialog starts on the first chip, so the hidden field has to name that one. A fixed
        // "rdp" here would be the wrong protocol the moment RDP is the one the user hid.
        var firstProtocol = protocols.Length > 0 ? protocols[0].Protocol : "rdp";

        // What opens it: RDP, VNC and SSH with Matgate's own engine or with Guacamole, a website in Matgate's own
        // browser or on the browser farm. Only the choices this installation has are offered (the farm's is
        // shown by the script once the farm answers); with one choice left there is nothing to choose.
        var guacamole = Matgate.Services.GuacamoleLauncher.Available;
        var engineChoice = $$"""
            <div class="home2-qc-engine hidden" data-home2-qc-field="engine" hidden>
                <span class="home2-qc-engine-label">{{(de ? "Öffnen mit" : "Open with")}}</span>
                <div class="home2-qc-engine-options" role="radiogroup" aria-label="{{A(de ? "Öffnen mit" : "Open with")}}">
                    <button type="button" class="home2-qc-engine-option" role="radio" data-home2-qc-engine="" data-for="remote">{{Icon("monitor")}}<span>Matgate</span></button>
                    {{(guacamole ? $"""<button type="button" class="home2-qc-engine-option" role="radio" data-home2-qc-engine="guacamole" data-for="remote">{Icon("server")}<span>Guacamole</span></button>""" : "")}}
                    <button type="button" class="home2-qc-engine-option" role="radio" data-home2-qc-engine="" data-for="web">{{Icon("globe")}}<span>{{(de ? "Integriert" : "Built-in")}}</span></button>
                    <button type="button" class="home2-qc-engine-option" role="radio" data-home2-qc-engine="farm" data-for="web" data-needs-farm hidden>{{Icon("monitor")}}<span>{{(de ? "Browser-Farm" : "Browser farm")}}</span></button>
                </div>
                <input type="hidden" name="engine" value="" data-home2-qc-engine-input>
            </div>
            """;
        // The kinds in the user's order, grouped in the list; the dialog starts on the first of that order.
        var protoButtons = KindSelect(
            protocols.Select(protocol => new KindOption(protocol.Protocol, protocol.Name, protocol.Desc, protocol.IconKey, protocol.Color, KindGroup(protocol.Protocol, de))).ToList(),
            firstProtocol,
            "data-home2-qc-proto",
            de);

        return $$"""
            <dialog class="home2-proto-dialog" data-home2-proto-dialog>
                <div class="home2-proto-dialog-head">
                    <div>
                        <h2>{{(de ? "Quick-Connect" : "Quick connect")}}</h2>
                        <p class="muted">{{(de ? "Direkt verbinden, ohne zu speichern" : "Connect directly, without saving")}}</p>
                    </div>
                    <button type="button" class="button icon-only home2-proto-dialog-close" data-home2-proto-close aria-label="{{A(de ? "Schließen" : "Close")}}">{{Icon("x")}}</button>
                </div>
                <form class="home2-qc-form" data-home2-qc-form>
                    {{protoButtons}}
                    <input type="hidden" name="protocol" value="{{A(firstProtocol)}}" data-home2-qc-proto-input>
                    {{engineChoice}}
                    <label class="home2-qc-label">
                        <span data-home2-qc-hostlabel>{{(de ? "Host" : "Host")}}</span>
                        <input name="host" required autocomplete="off" spellcheck="false" data-home2-qc-host data-web-label="{{A(de ? "Start-URL" : "Start URL")}}" data-web-blank="{{(blankBrowser ? "1" : "0")}}" data-web-placeholder="{{A(browserPlaceholder)}}" placeholder="{{A(de ? "z. B. 192.168.1.10" : "e.g. 192.168.1.10")}}">
                    </label>
                    <div class="home2-qc-grid2">
                        <label class="home2-qc-label" data-home2-qc-field="port">
                            <span>{{(de ? "Port" : "Port")}}</span>
                            <input name="port" type="number" inputmode="numeric" autocomplete="off" data-home2-qc-port>
                        </label>
                        <label class="home2-qc-label" data-home2-qc-field="domain">
                            <span>{{(de ? "Domäne" : "Domain")}}</span>
                            <input name="domain" autocomplete="off" spellcheck="false">
                        </label>
                    </div>
                    <div class="home2-qc-grid2">
                        <label class="home2-qc-label">
                            <span>{{(de ? "Benutzer" : "Username")}}</span>
                            <input name="username" autocomplete="off" spellcheck="false">
                        </label>
                        <label class="home2-qc-label">
                            <span>{{(de ? "Passwort" : "Password")}}</span>
                            <input name="password" type="password" autocomplete="off">
                        </label>
                    </div>
                    <label class="home2-qc-label" data-home2-qc-field="database" hidden>
                        <span>{{(de ? "Datenbank (optional)" : "Database (optional)")}}</span>
                        <input name="database" autocomplete="off" spellcheck="false" placeholder="{{A(de ? "leer: alle zeigen" : "empty: show all")}}">
                    </label>
                    <label class="home2-qc-label" data-home2-qc-field="fileRoot">
                        <span>{{(de ? "Startverzeichnis (optional)" : "Start folder (optional)")}}</span>
                        <input name="fileRoot" autocomplete="off" spellcheck="false" placeholder="/">
                    </label>
                    <p class="home2-qc-error hidden" data-home2-qc-error></p>
                    <div class="home2-qc-actions">
                        <button type="submit" class="button primary">{{Icon("play")}}<span data-home2-qc-submit data-connect="{{A(de ? "Verbinden" : "Connect")}}" data-browser="{{A(de ? "Browser öffnen" : "Open browser")}}">{{(de ? "Verbinden" : "Connect")}}</span></button>
                    </div>
                </form>
            </dialog>
            """;
    }

    // Filter row: a "Favorites" toggle first, then one toggle per folder. Selecting one filters the
    // single Connections list below (mutually exclusive; click the active one again to clear).
    private static string FilterTilesSection(HttpContext context, MatgateUser user, IReadOnlyList<ServerEndpoint> servers, bool de)
    {
        var favoriteIds = user.FavoriteServerIds?.ToHashSet() ?? new HashSet<Guid>();
        var favoriteCount = servers.Count(server => favoriteIds.Contains(server.Id));

        var groups = servers
            .GroupBy(server => string.IsNullOrWhiteSpace(server.FolderName) ? "" : server.FolderName.Trim(), StringComparer.OrdinalIgnoreCase)
            .Select(group => new { group.Key, First = group.First(), Count = group.Count() })
            .OrderBy(group => string.IsNullOrWhiteSpace(group.Key) ? 1 : 0)
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var hasNamedFolder = groups.Any(group => !string.IsNullOrWhiteSpace(group.Key));
        // Nothing to filter by.
        if (favoriteCount == 0 && !hasNamedFolder)
        {
            return "";
        }

        string CountLabel(int count) => count == 1
            ? (de ? "1 Verbindung" : "1 connection")
            : $"{count} {(de ? "Verbindungen" : "connections")}";

        var tiles = new List<string>();
        if (favoriteCount > 0)
        {
            tiles.Add($$"""
                <button type="button" class="home2-folder-tile home2-filter-fav" data-home2-filter="__favorites__" style="--proto: #f5b301">
                    <span class="home2-folder-icon">{{Icon("star")}}</span>
                    <span class="home2-folder-copy">
                        <span class="home2-folder-name">{{(de ? "Favoriten" : "Favorites")}}</span>
                        <small>{{E(CountLabel(favoriteCount))}}</small>
                    </span>
                </button>
                """);
        }

        var palette = new[] { "#4c8dff", "#35c07f", "#b06cff", "#f0a92b", "#3aa0ff", "#e0863a", "#5bc2a8" };
        var paletteIndex = 0;
        foreach (var group in groups)
        {
            var isUnsorted = string.IsNullOrWhiteSpace(group.Key);
            var name = isUnsorted ? (de ? "Unsortiert" : "Unsorted") : group.Key;
            var color = palette[paletteIndex++ % palette.Length];
            var icon = isUnsorted ? Icon("folder") : ServerFolderIcon(group.First);
            tiles.Add($$"""
                <button type="button" class="home2-folder-tile" data-home2-filter="{{A(FolderFilterKey(group.Key))}}" data-folder-path="{{A((group.Key ?? "").Trim())}}" style="--proto: {{color}}">
                    <span class="home2-folder-icon">{{icon}}</span>
                    <span class="home2-folder-copy">
                        <span class="home2-folder-name">{{E(name)}}</span>
                        <small>{{E(CountLabel(group.Count))}}</small>
                    </span>
                </button>
                """);
        }

        // Whoever may create connections may sort them into folders: the way there, where the folders are.
        var manageFolders = hasNamedFolder && (user.IsAdmin || user.CanManageServers || user.CanCreateServers)
            ? $$"""<a class="home2-manage-link" href="/admin?tab=connections" data-shell-open-tab="1" data-shell-title="{{A(de ? "Ordner" : "Folders")}}">{{Icon("settings")}}<span>{{(de ? "Ordner verwalten" : "Manage folders")}}</span></a>"""
            : "";
        return $$"""
            <section class="home2-section home2-folders-section">
                <div class="home2-section-head">
                    <h2>{{Icon("folder")}}<span>{{(de ? "Ordner" : "Folders")}}</span></h2>
                    {{manageFolders}}
                </div>
                <div class="home2-folder-grid">
                    {{string.Join("", tiles)}}
                </div>
            </section>
            """;
    }

    // Recently-used connections (from MatgateUser.RecentConnections), most recent first.
    private static string RecentConnectionsSection(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        bool includeEditButtons,
        string returnUrl,
        bool de)
    {
        if (user.RecentConnections is null || user.RecentConnections.Count == 0)
        {
            return "";
        }

        var byId = servers.ToDictionary(server => server.Id);
        var cards = new List<string>();
        foreach (var entry in user.RecentConnections)
        {
            if (!byId.TryGetValue(entry.ServerId, out var server))
            {
                continue;
            }

            var meta = $"""<span class="connection-choice-time">{Icon("clock")}<span>{E(RelativeTime(entry.UsedAt, de))}</span></span>""";
            cards.Add(ConnectionChoiceCard(context, user, server, includeEditButtons, returnUrl, meta));
            if (cards.Count >= 8)
            {
                break;
            }
        }

        if (cards.Count == 0)
        {
            return "";
        }

        return $$"""
            <section class="home2-section" data-home2-recent>
                <div class="home2-section-head">
                    <h2>{{Icon("clock")}}<span>{{(de ? "Zuletzt verwendet" : "Recently used")}}</span></h2>
                    <span class="badge">{{cards.Count}}</span>
                </div>
                <div class="home2-card-grid">
                    {{string.Join("", cards)}}
                </div>
            </section>
            """;
    }

    // Single connections list: favorites first, then folder/name order. The filter row above
    // (Favorites / folder toggles) and the search box narrow this list client-side.
    // The gateway's places: their own section, their own shade. No filled button - opening one
    // is browsing, not connecting.
    private static string PlacesSection(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> areas,
        string returnUrl,
        bool de)
    {
        if (areas.Count == 0)
        {
            return "";
        }

        var cards = string.Join("", areas.Select(area => ConnectionChoiceCard(context, user, area, false, returnUrl)));
        return $$"""
            <section class="home2-section home2-places-section" data-home2-places>
                <div class="home2-section-head">
                    <h2>{{Icon("server")}}<span>{{(de ? "Ablagen" : "Places")}}</span></h2>
                    <span class="badge">{{areas.Count}}</span>
                </div>
                <div class="home2-card-grid">
                    {{cards}}
                </div>
            </section>
            """;
    }

    // The workspaces on the home page: you used to get there only through the menu. As cards next
    // to the connections they are where you look anyway - switchable off like every section.
    private static string WorkspacesSection(
        HttpContext context,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        IReadOnlyList<ServerEndpoint> areas,
        bool de)
    {
        var visible = workspaces.Where(workspace => workspace.IsEnabled).OrderBy(workspace => workspace.Name).ToList();
        if (visible.Count == 0)
        {
            return "";
        }

        var cards = string.Join("", visible.Select(workspace =>
        {
            // "Open" leads into the file manager, not to the old workspace page: there the files are
            // shown with the same tool as everywhere else. The page next to it stays for what only it
            // can do - password, expiry, permissions and the link.
            // A share with a folder of its own has a place of its own; a share on an existing
            // place points straight at that place's id. In both cases "Open" leads into the
            // file manager - and only when none of that can be found does the old way through
            // the page remain.
            var place = areas.FirstOrDefault(area => area.AreaSourceId == workspace.Id);
            var targetId = place?.Id ?? workspace.AreaId;
            var openButton = targetId is null
                ? $$"""<a class="button primary" href="/workspaces/{{workspace.Id}}" data-shell-open-tab="1" data-shell-title="{{A(workspace.Name)}}">{{Icon("folder")}}{{(de ? "Öffnen" : "Open")}}</a>"""
                : $$"""<button type="button" class="button primary workspace-open-button connection-choice-open" data-server-id="{{targetId}}">{{Icon("folder")}}{{(de ? "Öffnen" : "Open")}}</button>""";
            var settingsButton = $$"""<button type="button" class="button favorite-toggle connection-choice-settings-corner" data-workspace-settings="{{workspace.Id}}" title="{{A(de ? "Einstellungen und Link" : "Settings and link")}}" aria-label="{{A(de ? "Einstellungen und Link" : "Settings and link")}}">{{Icon("settings")}}</button>""";
            return WorkspaceCard(workspace, openButton, settingsButton, de);
        }));

        return $$"""
            <section class="home2-section home2-workspaces-section" data-home2-workspaces>
                <div class="home2-section-head">
                    <h2>{{Icon("globe")}}<span>{{(de ? "Freigaben" : "Shares")}}</span></h2>
                    <span class="badge">{{visible.Count}}</span>
                </div>
                <div class="home2-card-grid">
                    {{cards}}
                </div>
            </section>
            """;
    }

    // A workspace card next to the connections: the same shape, so the home page does not fall
    // apart into two designs. What the button does is decided by the caller.
    private static string WorkspaceCard(WorkspaceDefinition workspace, string openButton, string settingsButton, bool de)
    {
        return $$"""
            <article class="connection-choice" data-home2-card="1" data-search="{{A((workspace.Name + " " + workspace.Description).ToLowerInvariant())}}" style="--proto: var(--accent-2)">
                <div class="connection-choice-body">
                    <div class="server-title connection-choice-title">
                        <span class="server-icon" title="SHARE">{{Icon("globe")}}</span>
                        <div class="connection-choice-copy">
                            <div class="connection-choice-badges">
                                <span class="badge">{{(de ? "Freigabe" : "Share")}}</span>
                                {{(workspace.IsPrivate ? $"""<span class="badge">{E(de ? "privat" : "private")}</span>""" : "")}}
                                {{(workspace.AllowUploads ? "" : $"""<span class="badge">{E(de ? "nur lesen" : "read-only")}</span>""")}}
                            </div>
                            <h3>{{E(workspace.Name)}}</h3>
                            {{(string.IsNullOrWhiteSpace(workspace.Description) ? "" : $"""<p class="target">{E(workspace.Description)}</p>""")}}
                        </div>
                        <div class="connection-choice-corner">{{settingsButton}}</div>
                    </div>
                </div>
                <div class="connection-choice-actions">{{openButton}}</div>
            </article>
            """;
    }

    private static string ConnectionsSection(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        bool includeEditButtons,
        string returnUrl,
        bool de)
    {
        var favoriteIds = user.FavoriteServerIds?.ToHashSet() ?? new HashSet<Guid>();
        // Within a folder the user's own order (dragged), then by name.
        var position = (user.ConnectionOrder ?? []).Select((id, index) => (id, index)).GroupBy(entry => entry.id).ToDictionary(group => group.Key, group => group.First().index);
        var ordered = servers
            .OrderByDescending(server => favoriteIds.Contains(server.Id))
            .ThenBy(server => string.IsNullOrWhiteSpace(server.FolderName) ? 1 : 0)
            .ThenBy(server => (server.FolderName ?? "").Trim().ToLowerInvariant())
            .ThenBy(server => position.TryGetValue(server.Id, out var index) ? index : int.MaxValue)
            .ThenBy(server => server.Name)
            .ToList();
        var cards = string.Join("", ordered.Select(server => ConnectionChoiceCard(context, user, server, includeEditButtons, returnUrl)));
        return $$"""
            <section class="home2-section home2-all-section" data-home2-all>
                <div class="home2-section-head">
                    <h2>{{Icon("monitor")}}<span>{{(de ? "Verbindungen" : "Connections")}}</span></h2>
                    <span class="badge">{{ordered.Count}}</span>
                </div>
                <div class="home2-card-grid">
                    {{cards}}
                </div>
            </section>
            """;
    }

    // Stable token used to match a folder tile against a card's data-folder attribute.
    private static string FolderFilterKey(string? folderName)
    {
        return string.IsNullOrWhiteSpace(folderName) ? "__unsorted__" : folderName.Trim().ToLowerInvariant();
    }

    // A per-protocol accent colour (mockup-style coloured icon chips). Colours are not final.
    // No longer the hex value itself but a reference to a token: that way a theme can set the
    // protocol colours, separately for light and dark. The old values were unreadable in light
    // mode on their own 16% tint (1.7 to 2.8 instead of 4.5).
    private static string ProtocolAccent(ServerProtocol protocol)
    {
        var token = protocol switch
        {
            ServerProtocol.Rdp => "rdp",
            ServerProtocol.Vnc => "vnc",
            ServerProtocol.Ssh => "ssh",
            ServerProtocol.Sftp => "sftp",
            ServerProtocol.Ftp => "ftp",
            ServerProtocol.Smb => "smb",
            ServerProtocol.Website => "website",
            ServerProtocol.WebDav => "webdav",
            ServerProtocol.MsSql or ServerProtocol.MySql or ServerProtocol.Postgres => "sftp",
            _ => "local"
        };

        return $"var(--proto-{token})";
    }

    private static string RelativeTime(DateTimeOffset when, bool de)
    {
        var delta = DateTimeOffset.UtcNow - when;
        if (delta < TimeSpan.Zero)
        {
            delta = TimeSpan.Zero;
        }

        if (delta.TotalMinutes < 1)
        {
            return de ? "gerade eben" : "just now";
        }

        if (delta.TotalMinutes < 60)
        {
            var minutes = (int)delta.TotalMinutes;
            return de ? $"vor {minutes} Min." : $"{minutes} min ago";
        }

        if (delta.TotalHours < 24)
        {
            var hours = (int)delta.TotalHours;
            return de ? $"vor {hours} Std." : $"{hours} h ago";
        }

        if (delta.TotalDays < 7)
        {
            var days = (int)delta.TotalDays;
            return de ? $"vor {days} T." : $"{days} d ago";
        }

        var weeks = (int)(delta.TotalDays / 7);
        return de ? $"vor {weeks} Wo." : $"{weeks} w ago";
    }

    private enum ConnectionBrowseMode
    {
        Folder,
        Host
    }

    private sealed record ConnectionBrowserGroup(
        string Key,
        string Title,
        string Eyebrow,
        string IconHtml,
        IReadOnlyList<ServerEndpoint> Servers,
        string EmptyMessage,
        bool ShowCreateAction);

    private static string ConnectionChoiceBrowserMode(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        bool includeEditButtons,
        string returnUrl,
        ConnectionBrowseMode mode)
    {
        var favoriteIds = user.FavoriteServerIds?.ToHashSet() ?? new HashSet<Guid>();
        var favorites = servers
            .Where(server => favoriteIds.Contains(server.Id))
            .OrderBy(ConnectionChoiceSortGroup)
            .ThenBy(server => server.Name)
            .ToList();
        var sharedServers = servers
            .Where(server => server.OwnerUserId is null)
            .OrderBy(ConnectionChoiceSortGroup)
            .ThenBy(server => server.Name)
            .ToList();
        var ownServers = servers
            .Where(server => server.OwnerUserId == user.Id)
            .OrderBy(ConnectionChoiceSortGroup)
            .ThenBy(server => server.Name)
            .ToList();

        var groups = new List<ConnectionBrowserGroup>();
        if (favorites.Count > 0)
        {
            groups.Add(new ConnectionBrowserGroup(
                "favorites",
                T(context, "Favorites"),
                T(context, "Favorites"),
                Icon("star"),
                favorites,
                T(context, "No favorite servers yet."),
                false));
        }

        var primaryGroups = mode == ConnectionBrowseMode.Host
            ? BuildConnectionBrowserGroups(
                context,
                servers,
                mode,
                "host",
                T(context, "No servers in this group."),
                false)
            : BuildConnectionBrowserGroups(
                context,
                sharedServers,
                mode,
                "shared",
                T(context, "No servers in this group."),
                false);

        var ownGroups = mode == ConnectionBrowseMode.Folder
            ? BuildConnectionBrowserGroups(
                context,
                ownServers,
                mode,
                "own",
                T(context, "No own servers created yet."),
                user.CanCreateServers)
            : new List<ConnectionBrowserGroup>();

        groups.AddRange(primaryGroups);
        groups.AddRange(ownGroups);

        if (groups.Count == 0)
        {
            return "";
        }

        var defaultGroupKey = groups[0].Key;
        var navSections = new List<string>();
        if (favorites.Count > 0)
        {
            navSections.Add(ConnectionBrowserNavSection(T(context, "Favorites"), groups.Where(group => group.Key == "favorites").ToList(), defaultGroupKey));
        }

        if (primaryGroups.Count > 0)
        {
            navSections.Add(ConnectionBrowserNavSection(mode == ConnectionBrowseMode.Folder ? T(context, "Folders") : T(context, "Servers"), primaryGroups, defaultGroupKey));
        }

        if (ownGroups.Count > 0)
        {
            navSections.Add(ConnectionBrowserNavSection(T(context, "Own servers"), ownGroups, defaultGroupKey));
        }

        var panels = string.Join("", groups.Select((group, index) => ConnectionBrowserGroupSection(context, user, group, includeEditButtons, returnUrl, index == 0)));

        return $$"""
            <section class="home-browser-mode{{(mode == ConnectionBrowseMode.Folder ? " active" : " hidden")}}" data-home-mode-panel="{{A(mode.ToString().ToLowerInvariant())}}" data-home-default-group="{{A(defaultGroupKey)}}">
                <div class="home-browser-layout">
                    <aside class="home-browser-sidebar">
                        {{string.Join("", navSections)}}
                    </aside>
                    <div class="home-browser-content">
                        {{panels}}
                    </div>
                </div>
            </section>
            """;
    }

    private static List<ConnectionBrowserGroup> BuildConnectionBrowserGroups(
        HttpContext context,
        IReadOnlyList<ServerEndpoint> servers,
        ConnectionBrowseMode mode,
        string sectionKey,
        string emptyMessage,
        bool allowCreateAction)
    {
        var groups = new List<ConnectionBrowserGroup>();
        if (servers.Count == 0)
        {
            if (allowCreateAction)
            {
                groups.Add(new ConnectionBrowserGroup(
                    $"{sectionKey}:{mode.ToString().ToLowerInvariant()}:empty",
                    T(context, "Unsorted"),
                    mode == ConnectionBrowseMode.Folder ? T(context, "Folder") : T(context, "Server"),
                    mode == ConnectionBrowseMode.Folder ? Icon("folder") : Icon("server"),
                    Array.Empty<ServerEndpoint>(),
                    emptyMessage,
                    true));
            }

            return groups;
        }

        var groupedServers = mode == ConnectionBrowseMode.Folder
            ? servers.GroupBy(server => string.IsNullOrWhiteSpace(server.FolderName) ? "" : server.FolderName.Trim(), StringComparer.OrdinalIgnoreCase)
            : servers.GroupBy(ConnectionBrowserHostGroupKey, StringComparer.OrdinalIgnoreCase);

        foreach (var group in groupedServers
                     .OrderBy(group => string.IsNullOrWhiteSpace(group.Key) ? 1 : 0)
                     .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase))
        {
            var keyPart = string.IsNullOrWhiteSpace(group.Key) ? "unsorted" : group.Key.Trim();
            var title = string.IsNullOrWhiteSpace(group.Key) ? T(context, "Unsorted") : group.Key.Trim();
            groups.Add(new ConnectionBrowserGroup(
                $"{sectionKey}:{mode.ToString().ToLowerInvariant()}:{keyPart}",
                title,
                mode == ConnectionBrowseMode.Folder ? T(context, "Folder") : T(context, "Server"),
                mode == ConnectionBrowseMode.Folder ? ServerFolderIcon(group.FirstOrDefault()) : Icon("server"),
                group.ToList(),
                emptyMessage,
                false));
        }

        return groups;
    }

    private static string ConnectionBrowserNavSection(
        string heading,
        IReadOnlyList<ConnectionBrowserGroup> groups,
        string defaultGroupKey)
    {
        if (groups.Count == 0)
        {
            return "";
        }

        return $$"""
            <section class="home-browser-nav-section">
                <p class="home-browser-nav-heading">{{E(heading)}}</p>
                <div class="home-browser-nav-list">
                    {{string.Join("", groups.Select(group => ConnectionBrowserNavItem(group, group.Key == defaultGroupKey)))}}
                </div>
            </section>
            """;
    }

    private static string ConnectionBrowserNavItem(ConnectionBrowserGroup group, bool active)
    {
        return $$"""
            <button type="button" class="home-browser-nav-item{{(active ? " active" : "")}}" data-home-group="{{A(group.Key)}}">
                <span class="home-browser-nav-icon">{{group.IconHtml}}</span>
                <span class="home-browser-nav-copy">
                    <span class="home-browser-nav-title">{{E(group.Title)}}</span>
                </span>
                <span class="badge">{{group.Servers.Count}}</span>
            </button>
            """;
    }

    private static string WorkspaceBrowserNavSection(HttpContext context, IReadOnlyList<WorkspaceDefinition> workspaces)
    {
        var ordered = workspaces
            .OrderByDescending(WorkspaceIsPublicAccessActive)
            .ThenBy(workspace => workspace.Name)
            .ToList();
        var activeWorkspaces = ordered
            .Where(WorkspaceIsPublicAccessActive)
            .ToList();

        var workspaceItems = string.Join("", activeWorkspaces.Select(workspace =>
        {
            var subtitle = T(context, "Workspace");
            var validity = WorkspaceValidityLabel(context, workspace);

            return $$"""
                <a class="home-browser-nav-item workspace-home-nav-item" href="/workspaces/{{workspace.Id}}" data-shell-open-tab="1" data-shell-title="{{A(workspace.Name)}}" data-shell-description="" data-home-workspace-item="1" data-home-workspace-active="{{A(WorkspaceIsPublicAccessActive(workspace) ? "1" : "0")}}">
                    <span class="home-browser-nav-icon">{{Icon("briefcase")}}</span>
                    <span class="home-browser-nav-copy">
                        <span class="home-browser-nav-title">{{E(workspace.Name)}}</span>
                        <small>{{E(subtitle)}}{{(string.IsNullOrWhiteSpace(workspace.Description) ? "" : $" - {E(workspace.Description)}")}}</small>
                    </span>
                    <span class="badge" title="{{A(WorkspacePublicAccessExpiresText(context, workspace))}}">{{E(validity)}}</span>
                </a>
                """;
        }));

        return $$"""
            <section class="home-browser-nav-section" data-home-workspaces="1" data-home-workspace-empty-active="{{A(T(context, "No active workspaces."))}}" data-home-workspace-empty-all="{{A(T(context, "No workspaces yet."))}}">
                <div class="row split home-browser-nav-section-head">
                    <p class="home-browser-nav-heading">{{T(context, "Workspaces")}}</p>
                </div>
                <div class="home-browser-nav-list">
                    {{workspaceItems}}
                </div>
                <div class="home-browser-nav-footer">
                    <a class="home-browser-nav-item workspace-home-nav-item workspace-home-action-item" href="/workspaces" data-shell-open-tab="1" data-shell-title="{{A(T(context, "Workspaces"))}}" data-shell-description="{{A(T(context, "Show all"))}}">
                        <span class="home-browser-nav-icon">{{Icon("list")}}</span>
                        <span class="home-browser-nav-copy">
                            <span class="home-browser-nav-title">{{T(context, "Workspaces")}}</span>
                            <small>{{T(context, "Show all")}}</small>
                        </span>
                    </a>
                    <a class="home-browser-nav-item workspace-home-nav-item workspace-home-action-item workspace-home-create-item" href="/workspaces/new" data-shell-open-tab="1" data-shell-title="{{A(T(context, "Create workspace"))}}" data-shell-description="{{A(T(context, "New workspace"))}}">
                        <span class="home-browser-nav-icon">{{Icon("plus")}}</span>
                        <span class="home-browser-nav-copy">
                            <span class="home-browser-nav-title">{{T(context, "Create workspace")}}</span>
                            <small>{{T(context, "New workspace")}}</small>
                        </span>
                    </a>
                </div>
                <div class="empty hidden" data-home-workspace-empty></div>
            </section>
            """;
    }

    private static string ConnectionBrowserGroupSection(
        HttpContext context,
        MatgateUser user,
        ConnectionBrowserGroup group,
        bool includeEditButtons,
        string returnUrl,
        bool active)
    {
        var cards = group.Servers.Count == 0
            ? ""
            : string.Join("", group.Servers.Select(server => ConnectionChoiceCard(context, user, server, includeEditButtons, returnUrl)));
        var emptyState = group.Servers.Count == 0
            ? $$"""
                <div class="empty connection-browser-empty-state">
                    <div>
                        <p class="eyebrow">{{E(group.Eyebrow)}}</p>
                        <h3>{{E(group.Title)}}</h3>
                        <p class="muted">{{E(group.EmptyMessage)}}</p>
                    </div>
                    {{(group.ShowCreateAction ? $"""<a class="button primary" href="/admin/servers/new" data-shell-open-tab="1" data-shell-title="{A(T(context, "Create server"))}">{Icon("plus")}{T(context, "Create own server")}</a>""" : "")}}
                </div>
                """
            : $"""<section class="connection-picker-grid home-browser-grid">{cards}</section>""";

        return $$"""
            <section class="home-browser-section{{(active ? " active" : "")}}" data-home-group-panel="{{A(group.Key)}}">
                <div class="connection-choice-section-head home-browser-section-head">
                    <div>
                        <p class="eyebrow">{{E(group.Eyebrow)}}</p>
                        <h2>{{group.IconHtml}}<span>{{E(group.Title)}}</span></h2>
                    </div>
                    <span class="badge">{{group.Servers.Count}}</span>
                </div>
                {{emptyState}}
            </section>
            """;
    }

    private static string ConnectionChoiceSortGroup(ServerEndpoint server)
    {
        var folder = string.IsNullOrWhiteSpace(server.FolderName) ? "" : server.FolderName.Trim().ToLowerInvariant();
        return $"{(string.IsNullOrWhiteSpace(folder) ? "1" : "0")}|{folder}|{server.Name.ToLowerInvariant()}";
    }

    private static string ConnectionBrowserHostGroupKey(ServerEndpoint server)
    {
        if (ServerEndpoint.IsWebsiteProtocol(server.Protocol))
        {
            var normalized = ServerEndpoint.NormalizeWebsiteUrl(server.WebsiteUrl, server.Host);
            if (Uri.TryCreate(normalized, UriKind.Absolute, out var uri))
            {
                return uri.Host.Trim();
            }

            if (!string.IsNullOrWhiteSpace(server.Host))
            {
                return server.Host.Trim();
            }

            return "";
        }

        if (string.IsNullOrWhiteSpace(server.Host))
        {
            return "";
        }

        return server.Host.Trim();
    }

    private static string ConnectionChoiceSection(
        HttpContext context,
        MatgateUser user,
        string eyebrow,
        string iconHtml,
        IReadOnlyList<ServerEndpoint> servers,
        bool includeEditButtons,
        string returnUrl,
        string title)
    {
        var cards = string.Join("", servers.Select(server => ConnectionChoiceCard(context, user, server, includeEditButtons, returnUrl)));
        return $$"""
            <section class="connection-choice-section">
                <div class="row split connection-choice-section-head">
                    <div>
                        <p class="eyebrow">{{E(eyebrow)}}</p>
                        <h2>{{iconHtml}}<span>{{E(title)}}</span></h2>
                    </div>
                    <span class="badge">{{servers.Count}}</span>
                </div>
                <section class="connection-picker-grid">
                    {{cards}}
                </section>
            </section>
            """;
    }

    private static string ConnectionChoiceCard(
        HttpContext context,
        MatgateUser user,
        ServerEndpoint server,
        bool includeEditButtons,
        string returnUrl,
        string extraHtml = "")
    {
        var searchIndex = $"{server.Name} {ServerTargetValue(server)} {server.FolderName} {ServerProtocolLabel(server.Protocol)}".ToLowerInvariant();

        // A place is not a saved connection: it is built from a permission and has no
        // record. The gear still pointed at /admin/servers/<id> - and therefore at a
        // page that does not exist (404).
        var isArea = server.Protocol == ServerProtocol.Local;
        var de = Language(context) == "de";
        var canEdit = includeEditButtons
            && !isArea
            && Services.AccessResolver.Level(user, server) >= AccessLevel.Edit;
        var actions = new List<string>
        {
            $"""<button type="button" class="{(isArea ? "" : "primary ")}workspace-open-button connection-choice-open" data-server-id="{server.Id}">{Icon(isArea ? "folder" : "play")}{T(context, isArea || server.Protocol == ServerProtocol.Website ? "Open" : "Connect")}</button>"""
        };

        // Gear -> the connection's settings page (own server, or any for admins/managers). It sits in
        // the top-right corner just LEFT of the favourite star, in the exact same size/look (same
        // favorite-toggle class). data-shell-open-tab makes it open inside the shell as its own tab
        // instead of a full-page navigation away from the home screen.
        var settingsCorner = canEdit
            ? $$"""<a class="button favorite-toggle connection-choice-settings-corner" href="/admin/servers/{{server.Id}}?return=home" data-shell-open-tab="1" data-shell-title="{{A(server.Name)}}" data-shell-description="{{A(T(context, "Settings"))}}" title="{{A(T(context, "Settings"))}}" aria-label="{{A(T(context, "Settings"))}}">{{Icon("settings")}}</a>"""
            : "";

        return $$"""
            <article class="connection-choice" data-home2-card="1" data-card-server="{{(isArea ? "" : server.Id.ToString())}}" data-card-access="{{(canEdit && server.OwnerUserId is null ? "1" : "0")}}" data-folder-path="{{A((server.FolderName ?? "").Trim())}}" data-fav="{{(IsFavoriteServer(user, server.Id) ? "1" : "0")}}" data-folder="{{A(FolderFilterKey(server.FolderName))}}" data-search="{{A(searchIndex)}}" style="--proto: {{ProtocolAccent(server.Protocol)}}">
                <span class="connection-choice-mark" aria-hidden="true">{{ConnectionMark(server)}}</span>
                {{(isArea ? "" : """<span class="connection-grip" aria-hidden="true"><svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg></span>""")}}
                <div class="connection-choice-body">
                    <div class="server-title connection-choice-title">
                        {{ServerIcon(server)}}
                        <div class="connection-choice-copy">
                            <div class="connection-choice-badges">
                                {{(isArea ? "" : $"""<span class="badge">{E(ServerProtocolLabel(server.Protocol))}</span>""")}}
                                {{ServerFolderBadge(context, server)}}
                                {{(server.OwnerUserId is null || isArea ? "" : ServerScopeBadge(context, server, currentUser: user))}}
                            </div>
                            <h3>{{E(server.Name)}}</h3>
                            {{(isArea ? "" : $"""<p class="target">{E(ServerTargetValue(server))}</p>""")}}
                            {{extraHtml}}
                        </div>
                        <div class="connection-choice-corner">{{settingsCorner}}{{FavoriteToggleForm(context, user, server, returnUrl)}}</div>
                        <button type="button" class="connection-choice-more" data-card-more title="{{A(de ? "Mehr" : "More")}}" aria-label="{{A((de ? "Mehr zu " : "More for ") + server.Name)}}">{{Icon("more")}}</button>
                    </div>
                    {{(string.IsNullOrWhiteSpace(server.Notes) ? "" : $"""<p class="muted connection-choice-notes">{E(server.Notes)}</p>""")}}
                </div>
                <div class="connection-choice-actions">
                    {{string.Join("", actions)}}
                </div>
            </article>
            """;
    }

    // The big sign in the background of a connection's card, cut off at its corner: what the connection is,
    // at a glance - a window of four panes for a Windows desktop, a prompt for a terminal, the connection's
    // own icon for everything else.
    private static string ConnectionMark(ServerEndpoint server) => server.Protocol switch
    {
        ServerProtocol.Rdp => """<svg viewBox="0 0 24 24" fill="currentColor" stroke="none"><path d="M3 5.6 10.4 4.6v6.8H3z"/><path d="M11.6 4.4 21 3v8.4h-9.4z"/><path d="M3 12.6h7.4v6.8L3 18.4z"/><path d="M11.6 12.6H21V21l-9.4-1.4z"/></svg>""",
        ServerProtocol.Ssh => """<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m4 7 5 5-5 5"/><path d="M12 18h8"/></svg>""",
        _ => Icon(server.SignKey()),
    };

    private static string FavoriteToggleForm(
        HttpContext context,
        MatgateUser user,
        ServerEndpoint server,
        string returnUrl)
    {
        var isFavorite = IsFavoriteServer(user, server.Id);
        var label = isFavorite ? T(context, "Remove from favorites") : T(context, "Add to favorites");
        return $$"""
            <form method="post" action="/account/favorites/{{server.Id}}/toggle" class="favorite-toggle-form" data-shell-inline>
                {{Csrf(context)}}
                <input type="hidden" name="returnUrl" value="{{A(returnUrl)}}">
                <button type="submit" class="favorite-toggle{{(isFavorite ? " active" : "")}}" title="{{A(label)}}" aria-label="{{A(label)}}">{{Icon("star")}}</button>
            </form>
            """;
    }

    private static string ServerFolderBadge(HttpContext context, ServerEndpoint server)
    {
        var folderName = Clean(server.FolderName, "");
        if (string.IsNullOrWhiteSpace(folderName))
        {
            return "";
        }

        return $"""<span class="badge server-folder-badge">{ServerFolderIcon(server)}<span>{E(folderName)}</span></span>""";
    }

    private static string ServerFolderIcon(ServerEndpoint? server)
    {
        var iconKey = server is null ? "" : ServerEndpoint.NormalizeIconKey(server.FolderIconKey);
        if (string.IsNullOrWhiteSpace(iconKey))
        {
            iconKey = "folder";
        }

        return Icon(iconKey);
    }

    private static bool IsFavoriteServer(MatgateUser user, Guid serverId)
    {
        return user.FavoriteServerIds?.Contains(serverId) == true;
    }

    public string Message(HttpContext context, MatgateUser? user, string title, string message)
    {
        // This page almost always appears because a form was not accepted - and until now only one way
        // led away from it: to the home page, with everything typed lost. "Back" brings the form back,
        // inputs and all.
        var de = Language(context) == "de";
        var body = $$"""
            <section class="panel message-panel">
                <h1>{{E(title)}}</h1>
                <p role="alert">{{E(message)}}</p>
                <div class="form-actions">
                    <button type="button" class="primary" onclick="history.back()">{{Icon("arrow-left")}}{{(de ? "Zurück" : "Back")}}</button>
                    <a class="button" href="/">{{Icon("home")}}{{T(context, "To Home")}}</a>
                </div>
            </section>
            """;

        return Layout(context, user, title, body);
    }

    public string FileViewer(
        HttpContext context,
        MatgateUser user,
        ServerEndpoint server,
        FileGatewayFileInfo file,
        string path,
        bool embedded = false)
    {
        var encodedPath = Uri.EscapeDataString(path);
        var streamUrl = $"/api/files/{server.Id}/view?path={encodedPath}";
        var downloadUrl = $"/api/files/{server.Id}/download?path={encodedPath}";
        var isAudio = file.ContentType.StartsWith("audio/", StringComparison.OrdinalIgnoreCase);
        var isVideo = file.ContentType.StartsWith("video/", StringComparison.OrdinalIgnoreCase);
        var isImage = file.ContentType.StartsWith("image/", StringComparison.OrdinalIgnoreCase);
        var isPdf = string.Equals(file.ContentType, "application/pdf", StringComparison.OrdinalIgnoreCase);
        var isText = file.ContentType.StartsWith("text/", StringComparison.OrdinalIgnoreCase)
            || string.Equals(file.ContentType, "application/json", StringComparison.OrdinalIgnoreCase)
            || string.Equals(file.ContentType, "application/xml", StringComparison.OrdinalIgnoreCase);
        // #view=FitH tells the browser's own PDF viewer to fit the page to the width. Without it a
        // phone opens the document at a zoom where most of the page is off screen, and the first thing
        // to do is pinch.
        var documentUrl = isPdf ? streamUrl + "#view=FitH" : streamUrl;

        var preview = isAudio
            ? $$"""
                <section class="viewer-stage audio-stage">
                    <div class="viewer-audio-mark">{{Icon("music")}}</div>
                    <audio controls preload="metadata" src="{{A(streamUrl)}}"></audio>
                </section>
                """
            : isVideo
                ? $$"""
                    <section class="viewer-stage video-stage">
                        <video controls preload="metadata" playsinline src="{{A(streamUrl)}}"></video>
                    </section>
                    """
                : isImage
                    ? $$"""
                        <section class="viewer-stage image-stage">
                            <img src="{{A(streamUrl)}}" alt="{{A(file.FileName)}}">
                        </section>
                        """
                    : isPdf || isText
                        ? $$"""
                            <section class="viewer-stage document-stage">
                                <iframe src="{{A(documentUrl)}}" title="{{A(file.FileName)}}"></iframe>
                            </section>
                        """
                        : $$"""
                            <section class="viewer-stage empty-viewer">
                                <h2>{{T(context, "No preview available")}}</h2>
                                <a class="button primary" href="{{A(downloadUrl)}}">{{Icon("download")}}{{T(context, "Download")}}</a>
                            </section>
                            """;

        // The labels sit in spans so a phone can drop them and keep the icons: three labelled
        // buttons wrapped onto two rows there and ate a quarter of the screen before the document
        // even began. The title stays, so the icon is never a guess.
        var actions = $$"""
            <a class="button viewer-action" href="/sessions" data-file-viewer-close title="{{A(T(context, "Close"))}}" onclick="return window.MatgateCloseFileViewer(event, this)">{{Icon("x")}}<span>{{T(context, "Close")}}</span></a>
            <a class="button viewer-action" href="{{A(streamUrl)}}" target="_blank" rel="noopener" title="{{A(T(context, "Open raw"))}}">{{Icon("eye")}}<span>{{T(context, "Open raw")}}</span></a>
            <a class="button primary viewer-action" href="{{A(downloadUrl)}}" title="{{A(T(context, "Download"))}}">{{Icon("download")}}<span>{{T(context, "Download")}}</span></a>
            """;

        var body = $$"""
            <section class="file-viewer-page{{(embedded ? " embedded-viewer" : "")}}">
                <div class="session-tab-row viewer-tab-row">
                    <div class="session-tabs viewer-tabs">
                        <div class="session-tab active viewer-tab">
                            <div class="session-tab-main viewer-tab-main" aria-current="page">
                                <span class="session-tab-title">{{Icon(server.SignKey())}}<span>{{E(file.FileName)}}</span></span>
                                <small>{{E(path)}} &middot; {{E(file.ContentType)}} &middot; {{FormatFileSize(file.Length)}}</small>
                            </div>
                        </div>
                    </div>
                    <div class="tab-actions viewer-actions">{{actions}}</div>
                </div>
                <div class="viewer-body">
                    {{preview}}
                </div>
            </section>
            """;

        return embedded ? body : Layout(context, user, file.FileName, body, "viewer-main");
    }

    public string FileViewerError(
        HttpContext context,
        ServerEndpoint server,
        string path,
        string title,
        string message)
    {
        return $$"""
            <section class="file-viewer-page embedded-viewer">
                <div class="session-tab-row viewer-tab-row">
                    <div class="session-tabs viewer-tabs">
                        <div class="session-tab active viewer-tab">
                            <div class="session-tab-main viewer-tab-main" aria-current="page">
                                <span class="session-tab-title">{{Icon(server.SignKey())}}<span>{{E(title)}}</span></span>
                                <small>{{E(path)}}</small>
                            </div>
                        </div>
                    </div>
                    <div class="tab-actions viewer-actions">
                        <a class="button" href="/sessions" data-file-viewer-close onclick="return window.MatgateCloseFileViewer(event, this)">{{Icon("x")}}{{T(context, "Close")}}</a>
                    </div>
                </div>
                <div class="viewer-body">
                    <section class="viewer-stage empty-viewer">
                        <h2>{{E(title)}}</h2>
                        <p>{{E(message)}}</p>
                    </section>
                </div>
            </section>
            """;
    }

    public string SessionsWorkspace(
        HttpContext context,
        MatgateUser user,
        IReadOnlyList<ServerEndpoint> servers,
        IReadOnlyList<WorkspaceDefinition> workspaces,
        Guid? openServerId,
        Matgate.Services.ShellStateStore.ShellState? storedTabs = null)
    {
        // For a user whose sessions outlive the browser: the tabs as the server has them (null: none yet).
        var keepSessions = SessionPreferences.KeptMinutes(user.Session) > 0;
        var serverTabs = keepSessions && storedTabs is not null
            ? JsonSerializer.Serialize(storedTabs, new JsonSerializerOptions(JsonSerializerDefaults.Web))
            : "null";
        var availableServers = JsonSerializer.Serialize(
            servers.Select(ServerChoicePayload),
            new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var actionBarServers = JsonSerializer.Serialize(
            (user.ActionBarServerIds ?? []).Select(id => id.ToString()),
            new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var sidebarData = JsonSerializer.Serialize(
            SidebarPayload(user, servers, workspaces, context),
            new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var initialOpenServerId = JsonSerializer.Serialize(openServerId?.ToString() ?? "");
        var csrfToken = JsonSerializer.Serialize(context.User.FindFirstValue("csrf") ?? "");
        var sessionPrefs = JsonSerializer.Serialize(user.Session, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var keyBar = KeyBar.GuacamoleJson(user, Language(context) == "de");
        var version = ApplicationVersion();
        var fileIcons = JsonSerializer.Serialize(new
        {
            folder = Icon("folder"),
            file = Icon("file"),
            parent = Icon("folder-up"),
            plus = Icon("plus"),
            star = Icon("star"),
            clock = Icon("clock"),
            play = Icon("play"),
            mkdir = Icon("folder-plus"),
            refresh = Icon("refresh"),
            menu = Icon("more"),
            more = Icon("more"),
            edit = Icon("edit"),
            globe = Icon("globe"),
            settings = Icon("settings"),
            copyTo = Icon("external-link"),
            queue = Icon("list"),
            clear = Icon("x"),
            chevronDown = Icon("chevron-down"),
            upload = Icon("upload"),
            download = Icon("download"),
            view = Icon("eye"),
            copy = Icon("copy"),
            move = Icon("move"),
            sort = Icon("list"),
            shield = Icon("shield"),
            archive = Icon("archive"),
            check = Icon("check"),
            delete = Icon("trash")
        }, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var actionIcons = JsonSerializer.Serialize(new
        {
            fullscreen = Icon("maximize"),
            terminal = Icon("terminal"),
            sound = Icon("volume"),
            soundOff = Icon("volume-off"),
            mic = Icon("mic"),
            micOff = Icon("mic-off"),
            gamepad = Icon("gamepad"),
            home = Icon("home"),
            copy = Icon("copy"),
            clipboard = Icon("clipboard"),
            upload = Icon("upload"),
            pointer = Icon("pointer"),
            rightClick = Icon("menu"),
            keyboard = Icon("keyboard"),
            onScreenKeyboard = Icon("grid"),
            more = Icon("more"),
            resolution = Icon("monitor"),
            zoomIn = Icon("zoom-in"),
            zoomOut = Icon("zoom-out"),
            autoResize = Icon("refresh"),
            systemKeys = Icon("command"),
            popOut = Icon("external-link"),
            windows = Icon("copy"),
            reattach = Icon("arrow-left"),
            folder = Icon("folder"),
            disconnect = Icon("logout"),
            // The display dialog: the fastest response's flash, and the settings its note leads to.
            zap = Icon("zap"),
            settings = Icon("settings")
        }, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var websiteIcons = JsonSerializer.Serialize(new
        {
            back = Icon("arrow-left"),
            forward = Icon("arrow-right"),
            refresh = Icon("refresh"),
            open = Icon("external-link"),
            secure = Icon("lock"),
            globe = Icon("globe")
        }, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var archiveExtensions = JsonSerializer.Serialize(FileArchiveFormats.SupportedExtensions, new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var bootSignature = JsonSerializer.Serialize(BuildBootSignature());
        var uiText = JsonSerializer.Serialize(new
        {
            about = T(context, "About"),
            dashboard = T(context, "Home"),
            connections = T(context, "Connections"),
            workspace = T(context, "Workspace"),
            page = T(context, "Page"),
