        var body = $$"""
            <div id="matgate-shell" class="matgate-shell">
            <div class="shell-page-row">
                <!-- No button of its own for the side panel: it is chosen in the view menu ("Normal with side panel"). -->
                <div id="session-tabs" class="session-tabs shell-page-tabs" role="tablist">
                    <div id="new-connection-tab" class="session-tab session-tab--add" role="tab" data-tab-kind="add" aria-label="{{A(T(context, "New connection"))}}">
                        <button type="button" class="session-tab-main">
                            <small class="session-tab-description" aria-hidden="true"></small>
                            <span class="session-tab-title">{{Icon("plus")}}</span>
                            <small class="session-tab-description" aria-hidden="true"></small>
                        </button>
                    </div>
                </div>
            <!-- The sessions that are out in windows of their own: a click brings one to the front, its arrow fetches it back. -->
            <div id="popped-windows" class="popped-windows" hidden aria-label="{{A(Language(context) == "de" ? "Sitzungen in eigenen Fenstern" : "Sessions in windows of their own")}}"></div>
            <div id="connection-tab-actions" class="tab-actions" aria-label="{{A(T(context, "Actions for the active tab"))}}"></div>
            </div>
            <button id="immersive-handle" type="button" class="immersive-handle" data-hint="{{A(Language(context) == "de" ? "Leiste zurückholen: oben antippen - oder mit drei Fingern ins Bild tippen" : "Bring the bar back: tap the top edge - or tap the picture with three fingers")}}" aria-label="{{A(Language(context) == "de" ? "Steuerung ein-/ausblenden" : "Show/hide controls")}}" title="{{A(Language(context) == "de" ? "Steuerung ein-/ausblenden" : "Show/hide controls")}}">{{Icon("chevron-down")}}</button>
            <div class="shell-body">
            <!-- The side panel: what there is to open - the favourites, what was used last, the connections by
                 folder, the places and the shares. On a wide screen it stands beside the sessions and takes
                 the start page's place as the list of connections; on a narrow one it is a sheet over the
                 page, brought by the menu. -->
            <aside id="server-manager" class="server-manager" hidden data-can-edit="{{(user.IsAdmin || user.CanManageServers || user.CanCreateServers ? "1" : "0")}}" aria-label="{{A(Language(context) == "de" ? "Seitenleiste" : "Side panel")}}">
                <!-- No head beside the page: the panel is switched in the view menu, and a new connection or folder
                     is made with a right click (or a finger held) on the panel. Only the sheet on a narrow
                     screen has one - its way back. -->
                <div class="server-manager-head">
                    <span class="server-manager-head-actions">
                        <button type="button" class="tab-action-button icon-only server-manager-close" data-server-manager-close title="{{A(T(context, "Close"))}}" aria-label="{{A(T(context, "Close"))}}">{{Icon("x")}}</button>
                    </span>
                </div>
                <label class="server-manager-search">{{Icon("search")}}<input id="server-manager-filter" type="search" autocomplete="off" spellcheck="false" placeholder="{{A(Language(context) == "de" ? "Suchen ..." : "Search ...")}}" aria-label="{{A(Language(context) == "de" ? "Verbindungen durchsuchen" : "Search the connections")}}"></label>
                <div id="server-manager-tree" class="server-manager-tree" role="tree"></div>
            </aside>
            <div id="shell-page-panels" class="shell-page-panels">
            <section id="home-view" class="app-view session-page multi-session-page active">
                <div id="session-deck" class="session-deck">
                    <div id="new-connection-panel" class="connection-picker-panel">
                        <div class="connection-picker-inner">
                            {{connectionChoices}}
                        </div>
                    </div>
                </div>
                <form id="credential-dialog" class="credential-dialog hidden">
                    <div class="dialog-head"><h2>{{T(context, "Credentials")}}</h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                        <div id="credential-fields" class="stack"></div>
                    </div>
                    <div class="actions dialog-foot">
                        <button type="submit" class="primary">{{Icon("save")}}{{T(context, "Send")}}</button>
                        <button id="credential-cancel" type="button" data-dialog-close>{{T(context, "Cancel")}}</button>
                    </div>
                </form>
                <form id="clipboard-dialog" class="credential-dialog clipboard-dialog hidden">
                    <div class="dialog-head"><h2>{{T(context, "Send clipboard")}}</h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                        <label>{{T(context, "Text")}}
                            <textarea id="clipboard-text" required></textarea>
                        </label>
                    </div>
                    <div class="actions dialog-foot">
                        <button type="submit" class="primary">{{Icon("save")}}{{T(context, "Send to active tab")}}</button>
                        <button id="clipboard-type" type="button">{{Icon("keyboard")}}{{(Language(context) == "de" ? "Als Tasten tippen" : "Type as keystrokes")}}</button>
                        <button id="clipboard-close" type="button" data-dialog-close>{{T(context, "Close")}}</button>
                    </div>
                </form>
                <!-- The clipboard of this device, for the session in front: what is in it (a picture, text), and what
                     to do with it - paste it as text, as a file, as a picture; or paste something else (typed here, or
                     a file of this device). The status bar's clipboard button and the session toolbar open it. -->
                <div id="clip-panel" class="credential-dialog clip-panel hidden" role="dialog" aria-modal="true" aria-labelledby="clip-panel-title">
                    <div class="dialog-head"><h2 id="clip-panel-title">{{(Language(context) == "de" ? "Zwischenablage" : "Clipboard")}}</h2><button type="button" class="dialog-x" data-clip-close aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                        <div class="clip-panel-what" data-clip-what></div>
                        <div class="clip-panel-preview" data-clip-preview></div>
                        <div class="clip-panel-actions" data-clip-actions></div>
                        <label class="clip-panel-other">{{(Language(context) == "de" ? "Etwas anderes einfügen" : "Paste something else")}}
                            <textarea data-clip-text rows="4" spellcheck="false" placeholder="{{A(Language(context) == "de" ? "Text hier eingeben oder bearbeiten ..." : "Type or edit text here ...")}}"></textarea>
                        </label>
                        <div class="clip-panel-actions" data-clip-other-actions></div>
                        <input type="file" data-clip-file multiple hidden>
                    </div>
                </div>
                <!-- This sheet has exactly one job: handing files from this device to the open session. It once
                     had two switches - source and target, two buttons each - and with them four combinations, of
                     which "from a place into a place" had nothing to do with a session at all. Copying now
                     happens where one browses anyway: in the file manager. -->
                <form id="sftp-target-dialog" class="credential-dialog send-files-dialog hidden">
                    <div class="dialog-head"><h2>{{(Language(context) == "de" ? "Dateien in die Sitzung" : "Send files into the session")}}</h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                    <button id="send-files-drop" type="button" class="send-files-drop">
                        {{Icon("upload")}}
                        <strong>{{(Language(context) == "de" ? "Dateien hierher ziehen" : "Drop files here")}}</strong>
                        <small>{{(Language(context) == "de" ? "oder klicken, um sie auszuwählen" : "or click to pick them")}}</small>
                    </button>
                    <input id="send-files-input" type="file" multiple class="hidden">
                    <p id="sftp-target-files" class="muted send-files-list"></p>
                    <label id="send-target-session">
                        <span id="send-target-label">{{(Language(context) == "de" ? "Wohin in der Sitzung" : "Where in the session")}}</span>
                        <input id="sftp-target-path" type="text" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="/home/user">
                        <select id="sftp-target-area" class="hidden"></select>
                        <small id="send-target-hint" class="muted"></small>
                    </label>
                    </div>
                    <div class="actions dialog-foot">
                        <button type="submit" class="primary">{{Icon("upload")}}{{(Language(context) == "de" ? "Senden" : "Send")}}</button>
                        <button id="sftp-target-close" type="button" data-dialog-close>{{T(context, "Close")}}</button>
                    </div>
                </form>
                <!-- Copying from one place to another. This used to be possible only as a detour through the
                     send dialog of a running session - now it is where one browses anyway. -->
                <form id="copy-to-dialog" class="credential-dialog copy-to-dialog hidden">
                    <div class="dialog-head"><h2>{{(Language(context) == "de" ? "Kopieren nach" : "Copy to")}}</h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                    <p id="copy-to-files" class="muted"></p>
                    <label>{{(Language(context) == "de" ? "Zielort" : "Target place")}}
                        <select id="copy-to-target"></select>
                    </label>
                    <label>{{(Language(context) == "de" ? "Ordner dort" : "Folder there")}}
                        <input id="copy-to-path" type="text" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="/" value="/">
                    </label>
                    <p id="copy-to-error" class="muted hidden"></p>
                    </div>
                    <div class="actions dialog-foot">
                        <button type="submit" class="primary">{{Icon("copy")}}{{(Language(context) == "de" ? "Kopieren" : "Copy")}}</button>
                        <button id="copy-to-close" type="button" data-dialog-close>{{T(context, "Close")}}</button>
                    </div>
                </form>
                <!-- Asks for the name of a new place. A dialog of the app's own rather than the
                     browser's prompt: a prompt can be switched off by the browser, and it cannot
                     say what went wrong when the gateway refuses. -->
                <!-- One sheet for every "what should it be called?": a new place, a folder, a file,
                     an archive, a new name for something that exists. The browser's own prompt did
                     this before - it can be switched off, it looks nothing like the application,
                     and it cannot say why the gateway refused a name. -->
                <form id="name-dialog" class="credential-dialog name-dialog hidden">
                    <div class="dialog-head"><h2 data-name-title></h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                        <p class="muted" data-name-hint></p>
                        <label><span data-name-label>{{T(context, "Name")}}</span>
                            <input id="name-dialog-input" type="text" maxlength="120" autocomplete="off" spellcheck="false" required>
                        </label>
                        <p class="muted hidden" data-name-error></p>
                    </div>
                    <div class="actions dialog-foot">
                        <button type="submit" class="primary" data-name-confirm>{{T(context, "Save")}}</button>
                        <button type="button" data-name-close data-dialog-close>{{T(context, "Close")}}</button>
                    </div>
                </form>
                <!-- Catches files dropped anywhere in the window. Without it the browser opens the file itself
                     and the session behind it is gone. -->
                <div id="drop-catcher" class="drop-catcher hidden" aria-hidden="true">
                    <div class="drop-catcher-box">
                        {{Icon("upload")}}
                        <strong>{{(Language(context) == "de" ? "Dateien hier ablegen" : "Drop files here")}}</strong>
                        <span class="muted" data-drop-catcher-text></span>
                    </div>
                </div>
                <div id="file-area-dialog" class="credential-dialog file-area-dialog hidden">
                    <div class="file-area-dialog-head">
                        <select id="file-area-dialog-select" class="file-area-dialog-select" aria-label="{{A(Language(context) == "de" ? "Ablage" : "Place")}}"></select>
                        <span id="file-area-dialog-status" class="muted file-area-dialog-status"></span>
                        <span class="file-area-dialog-actions">
                            <button id="file-area-dialog-send" type="button" class="button primary">{{Icon("upload")}}{{(Language(context) == "de" ? "In die Sitzung" : "Into the session")}}</button>
                            <button id="file-area-dialog-close" type="button" class="tab-action-button icon-only" aria-label="{{A(T(context, "Close"))}}">&times;</button>
                        </span>
                    </div>
                    <div id="file-area-dialog-body" class="file-area-dialog-body"></div>
                </div>
                <div id="resolution-dialog" class="credential-dialog resolution-dialog hidden" role="dialog" aria-labelledby="resolution-dialog-title">
                    <div class="dialog-head"><h2 id="resolution-dialog-title">{{(Language(context) == "de" ? "Anzeige" : "Display")}}</h2><button type="button" class="dialog-x" data-dialog-x aria-label="{{A(T(context, "Close"))}}" title="{{A(T(context, "Close"))}}">&times;</button></div>
                    <div class="dialog-body">
                        <div id="resolution-options" class="resolution-options"></div>
                        <div id="resolution-extra" class="resolution-extra"></div>
                    </div>
                    <div class="actions dialog-foot">
                        <button id="resolution-close" type="button" class="primary" data-dialog-close>{{(Language(context) == "de" ? "Fertig" : "Done")}}</button>
                    </div>
                </div>
                <dialog id="file-viewer-dialog" class="matgate-dialog file-viewer-dialog"></dialog>
                <dialog id="workspace-settings-dialog" class="matgate-dialog workspace-settings-dialog"></dialog>
            </section>
            </div>
            </div>
            <div id="session-statusbar" class="session-statusbar">
                <div class="status-primary">
                    <strong id="status-title">{{T(context, "No active tab")}}</strong>
                    <span id="status-target">-</span>
                </div>
                <div class="status-secondary">
                    <div class="status-metrics">
                        <span id="status-state">{{T(context, "Ready")}}</span>
                        <span id="status-resolution" class="status-resolution"></span>
                        <span id="status-latency">{{T(context, "Gateway: -")}}</span>
                        <span id="status-tunnel">{{T(context, "Tunnel: -")}}</span>
                        <span id="status-sync">{{T(context, "Sync: -")}}</span>
                        <span id="status-message">-</span>
                    </div>
                    <div class="status-actions">
                        <button id="status-clip" type="button" class="status-clip" hidden data-has="unknown">{{Icon("clipboard")}}<span class="status-clip-label"></span></button>
                        <button id="status-system" type="button" class="status-system" hidden aria-haspopup="dialog" aria-expanded="false"><span class="status-system-cpu"></span><span class="status-system-ram"></span></button>
                        <div id="status-system-panel" class="status-system-panel" role="dialog" hidden></div>
                        <span id="status-info-icon" hidden>{{Icon("info")}}</span>
                    </div>
                </div>
            </div>
            </div>
            <script src="/guacamole/guacamole-common-js/all.min.js"></script>
            <script>
            (() => {
                const availableServers = {{availableServers}};
                // What the side panel shows beyond the connections themselves: which of them are favourites,
                // which were used last, and the shares.
                let sidebarData = {{sidebarData}};
                // Connections that should sit on the home page as a button in the bar.
                const actionBarServers = {{actionBarServers}};
                // The built-in order of the session bar's actions, for whoever has not sorted them.
                const defaultActionOrder = {{JsonSerializer.Serialize(SessionPreferences.SortableActions)}};
                const sessionPrefs = Object.assign({ edgePanning: true, dragPanning: true, stretchToWindow: false, systemCombos: true, functionKeys: false, ctrlAltDelHotkey: true, pasteAsKeystrokes: false, actionOrder: [], hiddenActions: [] }, {{sessionPrefs}});
                // The user's key bar (Account -> Key bar), as Guacamole sessions take it: keysyms.
                const keyBarButtons = {{keyBar}};
                const initialOpenServerId = {{initialOpenServerId}};
                // This window was popped out of another (a tab opened in its own window). It shows a
                // "re-attach" control instead of "pop out", and re-attach hands the session back.
                const isPoppedWindow = (() => { try { return new URL(location.href).searchParams.get('popped') === '1'; } catch (e) { return false; } })();
                const poppedKey = (() => { try { return new URL(location.href).searchParams.get('key') || ''; } catch (e) { return ''; } })();
                // The window of one session: the layout hides everything around that session.
                document.documentElement.toggleAttribute('data-popped', isPoppedWindow);
                const csrfToken = {{csrfToken}};
                const uiText = {{uiText}};
                const fileIcons = {{fileIcons}};
                const actionIcons = {{actionIcons}};
                const websiteIcons = {{websiteIcons}};
                const archiveExtensions = {{archiveExtensions}};
                const homeView = document.getElementById('home-view');
                const tabsRoot = document.getElementById('session-tabs');
                const newConnectionTab = document.getElementById('new-connection-tab');
                const newConnectionPanel = document.getElementById('new-connection-panel');
                const deck = document.getElementById('session-deck');
                const connectionTabActions = document.getElementById('connection-tab-actions');
                const statusTitle = document.getElementById('status-title');
                const statusTarget = document.getElementById('status-target');
                const statusState = document.getElementById('status-state');
                const statusLatency = document.getElementById('status-latency');
                const statusTunnel = document.getElementById('status-tunnel');
                const statusSync = document.getElementById('status-sync');
                const statusMessage = document.getElementById('status-message');
                // The "About" page is reached through the account menu; its icon for the tab.
                const aboutInfoButton = document.getElementById('status-info-icon');
                const fileViewerDialog = document.getElementById('file-viewer-dialog');
                const credentialDialog = document.getElementById('credential-dialog');
                const credentialFields = document.getElementById('credential-fields');
                const credentialCancel = document.getElementById('credential-cancel');
                const clipboardDialog = document.getElementById('clipboard-dialog');
                const clipboardText = document.getElementById('clipboard-text');
                const clipboardTypeButton = document.getElementById('clipboard-type');
                const clipboardClose = document.getElementById('clipboard-close');
                const fileAreaDialog = document.getElementById('file-area-dialog');
                const fileAreaDialogBody = document.getElementById('file-area-dialog-body');
                const fileAreaDialogSelect = document.getElementById('file-area-dialog-select');
                const fileAreaDialogClose = document.getElementById('file-area-dialog-close');
                const fileAreaDialogSend = document.getElementById('file-area-dialog-send');
                const sftpTargetDialog = document.getElementById('sftp-target-dialog');
                const sftpTargetPath = document.getElementById('sftp-target-path');
                const sftpTargetArea = document.getElementById('sftp-target-area');
                const sendFilesDrop = document.getElementById('send-files-drop');
                const sendFilesInput = document.getElementById('send-files-input');
                const copyToDialog = document.getElementById('copy-to-dialog');
                const copyToFiles = document.getElementById('copy-to-files');
                const copyToTarget = document.getElementById('copy-to-target');
                const copyToPath = document.getElementById('copy-to-path');
                const copyToError = document.getElementById('copy-to-error');
                const copyToClose = document.getElementById('copy-to-close');
                const dropCatcher = document.getElementById('drop-catcher');
                const sendTargetLabel = document.getElementById('send-target-label');
                const sendTargetHint = document.getElementById('send-target-hint');
                const sftpTargetFiles = document.getElementById('sftp-target-files');
                const sftpTargetClose = document.getElementById('sftp-target-close');
                const statusResolution = document.getElementById('status-resolution');
                const resolutionDialog = document.getElementById('resolution-dialog');
                const resolutionOptions = document.getElementById('resolution-options');
                const resolutionExtra = document.getElementById('resolution-extra');
                const resolutionClose = document.getElementById('resolution-close');
                const shellPagePanels = document.getElementById('shell-page-panels');
                const tabs = new Map();
                const workspaceStorageKey = 'matgate.workspace.tabs.v2';
                const shellTabStorageKey = 'matgate.shell.tabs.v1';
                const tabOrderStorageKey = 'matgate.tab.order.v1';
                const shellTabs = new Map();
                const homeBrowser = document.querySelector('[data-home-browser]');
                const homeBrowserStateKey = 'matgate.home.browser.v1';
                const appBootSignatureKey = 'matgate.app.boot.signature.v1';
                const appBootSignature = {{bootSignature}};

                let activeTabId = null;
                let activeShellTabId = '';
                // While the tabs come back at start: bringing one forward then must not write down the others as
                // gone - those of the other kind are not back yet.
                let restoringTabs = true;
                let draggedTabId = null;
                let suppressTabClicks = false;
                let transparentDragImage = null;
                const wiredWorkspaceTabRoots = new WeakSet();
                const wiredWorkspaceTextForms = new WeakSet();
                let credentialTab = null;
                let resizeTimer = null;
                let gatewayLatencyMs = null;
                let fileViewerLoadToken = 0;
                let homeBrowserState = {
                    mode: 'folder',
                    workspaceFilter: 'active',
                    groups: {
                        folder: '',
                        host: ''
                    }
                };

                function clearMatgatePersistentState() {
                    const keysToClear = new Set([
                        workspaceStorageKey,
                        shellTabStorageKey,
                        tabOrderStorageKey,
                        homeBrowserStateKey,
                        appBootSignatureKey
                    ]);

                    try {
                        for (let index = localStorage.length - 1; index >= 0; index -= 1) {
                            const key = localStorage.key(index);
                            if (!key) {
                                continue;
                            }

                            if (keysToClear.has(key) || key.startsWith('matgate.workspace.panel.')) {
                                localStorage.removeItem(key);
                            }
                        }
                    }
                    catch {
                        // Ignore storage failures.
                    }

                    try {
                        sessionStorage.clear();
                    }
                    catch {
                        // Ignore storage failures.
                    }
                }

                function ensureFreshBootState() {
                    try {
                        const storedSignature = localStorage.getItem(appBootSignatureKey);
                        if (storedSignature === appBootSignature) {
                            return;
                        }

                        clearMatgatePersistentState();
                        localStorage.setItem(appBootSignatureKey, appBootSignature);

                        if ('serviceWorker' in navigator) {
                            navigator.serviceWorker.getRegistrations()
                                .then(registrations => Promise.all(registrations.map(registration => registration.unregister())))
                                .catch(() => {});
                        }
                    }
                    catch {
                        // Ignore storage failures.
                    }
                }

                ensureFreshBootState();

                // Sessions that outlive the browser (Account -> Session): the open tabs are the user's, not
                // this browser's. What the server has replaces what this browser remembers - before anything
                // is restored from it - and every change goes back to the server.
                const keepSessions = {{(keepSessions ? "true" : "false")}};
                const serverTabs = {{serverTabs}};
                if (keepSessions && serverTabs) {
                    try {
                        [[workspaceStorageKey, serverTabs.workspace], [shellTabStorageKey, serverTabs.shell], [tabOrderStorageKey, serverTabs.order]].forEach(([key, value]) => {
                            if (typeof value === 'string') {
                                localStorage.setItem(key, value);
                            }
                            else {
                                localStorage.removeItem(key);
                            }
                        });
                    }
                    catch {
                        // Without storage the tabs start empty, as they would anyway.
                    }
                }
                let tabStateTimer = null;
                function pushTabState() {
                    tabStateTimer = null;
                    try {
                        fetch('/api/shell-state', {
                            method: 'PUT',
                            keepalive: true,
                            credentials: 'same-origin',
                            headers: { 'Content-Type': 'application/json', 'X-Matgate-Csrf': csrfToken },
                            body: JSON.stringify({
                                workspace: localStorage.getItem(workspaceStorageKey),
                                shell: localStorage.getItem(shellTabStorageKey),
                                order: localStorage.getItem(tabOrderStorageKey)
                            })
                        }).catch(() => {});
                    }
                    catch {
                        // The next change tries again.
                    }
                }
                function scheduleTabStatePush() {
                    if (!keepSessions || isPoppedWindow) {
                        return;
                    }
                    window.clearTimeout(tabStateTimer);
                    tabStateTimer = window.setTimeout(pushTabState, 500);
                }
                // A tab that is closed ends its session for good; one that merely lost its browser would stay
                // until its time runs out. The session's id is part of the tab's address.
                function endKeptSession(url) {
                    try {
                        const session = new URL(url, window.location.href).searchParams.get('session');
                        if (!session || !/^\/(display|ssh)\//.test(new URL(url, window.location.href).pathname)) {
                            return;
                        }
                        fetch('/api/kept-sessions/end?session=' + encodeURIComponent(session), {
                            method: 'POST',
                            keepalive: true,
                            credentials: 'same-origin',
                            headers: { 'X-Matgate-Csrf': csrfToken }
                        }).catch(() => {});
                    }
                    catch {
                        // An address without a session has none to end.
                    }
                }

                const shellLayout = document.body.dataset.shellLayout === '1';
                // Android/Chrome: let the on-screen keyboard OVERLAY the page instead of resizing the
                // viewport, so an active remote session is never resized when the keyboard opens.
                try {
                    if (navigator.virtualKeyboard) {
                        navigator.virtualKeyboard.overlaysContent = true;
                        // Android can dismiss the soft keyboard WITHOUT blurring the focused input
                        // (back gesture, the keyboard's own hide key) - focus/blur tracking alone then
                        // reports "open" forever and the toolbar toggle needs a dead tap. When the
                        // keyboard geometry collapses to zero, blur the hidden session input so the
                        // open/closed state (tab.deviceKbOpen) and the button highlight resync.
                        if (typeof navigator.virtualKeyboard.addEventListener === 'function') {
                            navigator.virtualKeyboard.addEventListener('geometrychange', () => {
                                const kbRect = navigator.virtualKeyboard.boundingRect;
                                const active = document.activeElement;
                                if (kbRect && kbRect.height === 0 && active && active.classList && active.classList.contains('osk-input')) {
                                    active.blur();
                                }
                                // Also moves the bottom edge of the dialogs (updateViewportHeight shifts the session too).
                                updateViewportHeight();
                            });
                        }
                    }
                }
                catch (e) {
                    // Unsupported (iOS/Firefox) - handled below via visualViewport.
                }
                // "See what you type": when a soft keyboard (the device keyboard OR the in-app
                // on-screen keyboard) covers the lower part of the session, slide the remote view UP so
                // the spot the user last tapped (where the text cursor lands) stays visible just above
                // the keyboard. Pure visual translate - it never resizes the remote (no RDP/VNC
                // resolution change), matching the "keyboard overlays, not resizes" behaviour.
                // What could hold the device's keyboard: a field with the cursor in it - in the shell, or inside
                // the frame of a page tab. A frame of another origin cannot be looked into, so it may.
                function keyboardHolder() {
                    let element = document.activeElement;
                    for (let depth = 0; element && depth < 6; depth++) {
                        if (element.tagName === 'IFRAME') {
                            let inner = null;
                            try {
                                inner = element.contentDocument;
                            }
                            catch {
                                inner = null;
                            }

                            if (!inner) {
                                return element;
                            }

                            element = inner.activeElement;
                        }
                        else if (element.shadowRoot && element.shadowRoot.activeElement) {
                            element = element.shadowRoot.activeElement;
                        }
                        else {
                            break;
                        }
                    }

                    return element && (element.isContentEditable || /^(INPUT|TEXTAREA|SELECT|IFRAME)$/.test(element.tagName)) ? element : null;
                }

                // Takes the cursor out of whatever field holds the keyboard, unless that field is inside `keep`.
                function dropKeyboardHolder(keep) {
                    const holder = keyboardHolder();
                    if (!holder || holder.tagName === 'IFRAME' || !(window.matchMedia && window.matchMedia('(pointer: coarse)').matches)) {
                        return;
                    }

                    const outer = document.activeElement;
                    if (keep && outer && keep.contains(outer)) {
                        return;
                    }

                    try {
                        holder.blur();
                    }
                    catch {
                        // Nothing to let go of.
                    }
                }

                function keyboardCoverTopY(tab) {
                    // In-app on-screen keyboard (a DOM panel pinned to the bottom of the session).
                    if (tab && tab.osk && tab.osk.classList.contains('open')) {
                        return tab.osk.getBoundingClientRect().top;
                    }
                    // Android: the system keyboard reports its own rectangle (overlaysContent = true, so
                    // visualViewport does NOT shrink and cannot be used here).
                    const vk = navigator.virtualKeyboard;
                    if (vk && vk.boundingRect && vk.boundingRect.height > 0) {
                        return vk.boundingRect.top;
                    }
                    // iOS / others: the visual viewport shrinks from the bottom by the keyboard height.
                    // Only while a field holds the keyboard. An iPhone does not always say when the keyboard
                    // went (switching tabs or apps, most of all as an installed app): the viewport stayed
                    // "shrunk", and the key bar hung above an empty space where the keyboard had been.
                    const vv = window.visualViewport;
                    if (vv && keyboardHolder()) {
                        const visibleBottom = vv.offsetTop + vv.height;
                        if (window.innerHeight - visibleBottom > 120) {
                            return visibleBottom;
                        }
                    }
                    return null;
                }
                function updateSessionKeyboardShift() {
                    if (!shellLayout) {
                        return;
                    }
                    const tab = tabs.get(activeTabId);
                    if (!tab || !tab.displayRoot || !tab.client || tab.terminal) {
                        return;
                    }
                    const kbTop = keyboardCoverTopY(tab);
                    if (kbTop === null) {
                        if (tab.keyboardShift) {
                            tab.displayRoot.style.transform = '';
                            tab.keyboardShift = 0;
                        }
                        return;
                    }
                    const shift = tab.keyboardShift || 0;
                    const rect = tab.displayRoot.getBoundingClientRect();
                    // rect.top already reflects the current shift; the anchor is stored un-shifted.
                    const unshiftedTop = rect.top + shift;
                    const margin = 28;
                    const anchor = (typeof tab.lastTouchUnshiftedY === 'number')
                        ? tab.lastTouchUnshiftedY
                        : unshiftedTop + rect.height * 0.62;
                    const maxShift = Math.max(0, Math.round(rect.height - 120));
                    const delta = Math.max(0, Math.min(Math.round(anchor - (kbTop - margin)), maxShift));
                    if (delta !== shift) {
                        tab.keyboardShift = delta;
                        tab.displayRoot.style.transform = delta > 0 ? `translateY(${-delta}px)` : '';
                    }
                }

                // Android lets the keyboard overlay the page: it reports its own rectangle and leaves the
                // visual viewport alone. Nothing anywhere else.
                function overlaidKeyboardHeight() {
                    const vk = navigator.virtualKeyboard;
                    if (vk && vk.overlaysContent && vk.boundingRect && vk.boundingRect.height > 0) {
                        return vk.boundingRect.height;
                    }
                    return 0;
                }

                const updateViewportHeight = () => {
                    const vv = window.visualViewport;
                    const visualHeight = vv ? vv.height : window.innerHeight;
                    const keyboardOpen = (window.innerHeight - visualHeight) > 120;
                    // This height is for the dialogs: the session is laid out with dvh, and the keyboard must
                    // OVERLAY that - shrinking it would resize the RDP/VNC session (Android) and leave a
                    // scroll/gap (iOS). A dialog has fields of its own, though. Taken at the full height it ran
                    // under the keyboard: half of it hidden, and the buttons at its bottom with it. So it gets
                    // the part of the screen the keyboard leaves. iOS shrinks the visual viewport and may pan
                    // it (the top edge follows); Android reports the keyboard on its own.
                    const height = Math.max(0, visualHeight - overlaidKeyboardHeight());
                    document.documentElement.style.setProperty('--matgate-viewport-height', `${Math.round(height)}px`);
                    document.documentElement.style.setProperty('--matgate-viewport-top', `${Math.round(vv ? vv.offsetTop : 0)}px`);
                    // iOS standalone-PWA bug: opening the keyboard pans the whole app upward and often
                    // NEVER pans it back after dismissal - the app then sits shifted up with a dead black
                    // strip at the physical bottom. Once the keyboard is closed, force the pan back.
                    if (shellLayout && !keyboardOpen && (!vv || vv.scale <= 1.01)) {
                        const panOffset = (vv ? vv.offsetTop : 0) || window.scrollY || document.documentElement.scrollTop || 0;
                        if (panOffset > 0) {
                            window.scrollTo(0, 0);
                            document.documentElement.scrollTop = 0;
                            document.body.scrollTop = 0;
                        }
                    }
                    if (shellLayout) {
                        document.documentElement.style.overscrollBehavior = 'none';
                        document.documentElement.style.overflow = 'hidden';
                        document.body.style.overscrollBehavior = 'none';
                        document.body.style.overflow = 'hidden';
                    }
                    else {
                        document.documentElement.style.overscrollBehavior = '';
                        document.documentElement.style.overflow = '';
                        document.body.style.overscrollBehavior = '';
                        document.body.style.overflow = '';
                    }
                    updateSessionKeyboardShift();
                    updatePageKeyboardInset();
                };
                // A page tab (a session of Matgate's own engine, a terminal) is a document of its own: it cannot
                // see the device's keyboard, which lay over its bottom - the key bar and the lower part of the
                // picture with it. The page is told how much the keyboard covers, and ends above it.
                // Every page tab is told - the one in front what the keyboard covers, the others that it covers
                // nothing. Only the one in front used to hear: a tab left with the keyboard up kept its room
                // for it, and came back with the key bar above a gap.
                let keyboardWatch = 0;
                function updatePageKeyboardInset() {
                    let active = null;
                    let pages = [];
                    try {
                        active = activeTabId ? null : shellTabs.get(activeShellTabId);
                        pages = Array.from(shellTabs.values());
                    }
                    catch {
                        // The tabs are not set up yet.
                        return;
                    }
                    const top = keyboardCoverTopY(null);
                    let covered = false;
                    pages.forEach(entry => {
                        const frame = entry.panel ? entry.panel.querySelector('iframe') : null;
                        if (!frame) {
                            return;
                        }
                        const inset = entry === active && top !== null ? Math.max(0, Math.round(frame.getBoundingClientRect().bottom - top)) : 0;
                        covered = covered || inset > 0;
                        try {
                            const inner = frame.contentWindow;
                            if (inner && typeof inner.MatgateKeyboardInset === 'function') {
                                inner.MatgateKeyboardInset(inset);
                            }
                        }
                        catch {
                            // A page that is not Matgate's own.
                        }
                    });
                    // While room is kept for the keyboard it is looked at again and again: the moment the field
                    // lets go, the room goes - whether or not the phone reported anything.
                    if (covered && !keyboardWatch) {
                        keyboardWatch = setInterval(updateViewportHeight, 500);
                    }
                    else if (!covered && keyboardWatch) {
                        clearInterval(keyboardWatch);
                        keyboardWatch = 0;
                    }
                }
                // Looked at again now and a few moments later: after a switch of tabs or apps the phone's numbers
                // settle late, and sometimes without an event.
                let keyboardRechecks = [];
                function recheckKeyboardSoon() {
                    keyboardRechecks.forEach(clearTimeout);
                    keyboardRechecks = [0, 250, 700, 1500].map(delay => setTimeout(updateViewportHeight, delay));
                }
                document.addEventListener('visibilitychange', () => {
                    if (document.visibilityState !== 'visible') {
                        // Leaving the app takes the keyboard away without telling the field. Let go of it, so
                        // that coming back finds both agreeing: no keyboard, no cursor.
                        dropKeyboardHolder(null);
                    }
                    recheckKeyboardSoon();
                });
                window.addEventListener('pageshow', recheckKeyboardSoon);
                window.addEventListener('focus', recheckKeyboardSoon);
                window.MatgateRecheckKeyboard = recheckKeyboardSoon;
                updateViewportHeight();
                window.addEventListener('resize', updateViewportHeight, { passive: true });
                window.addEventListener('orientationchange', updateViewportHeight);
                // Release any held browser-farm slots if the whole app is closed/backgrounded.
                window.addEventListener('pagehide', () => {
                    tabs.forEach(tab => { releaseBrowserFarm(tab); releaseSessionFiles(tab); });
                });
                if (window.visualViewport) {
                    window.visualViewport.addEventListener('resize', updateViewportHeight, { passive: true });
                    window.visualViewport.addEventListener('scroll', updateViewportHeight, { passive: true });
                }

                window.MatgateOpenAboutTab = (event) => {
                    if (event) {
                        event.preventDefault();
                    }

                    openShellTab('/about', ui('About'), aboutInfoButton?.innerHTML || '');
                    return false;
                };
                if (aboutInfoButton) {
                    aboutInfoButton.addEventListener('click', window.MatgateOpenAboutTab);
                }
                if (fileViewerDialog) {
                    fileViewerDialog.addEventListener('click', (event) => {
                        if (event.target === fileViewerDialog) {
                            closeFileViewerDialog();
                        }
                    });
                    fileViewerDialog.addEventListener('close', () => {
                        fileViewerLoadToken += 1;
                        fileViewerDialog.replaceChildren();
                    });
                }

                function closeFileViewerDialog() {
                    fileViewerLoadToken += 1;
                    if (fileViewerDialog && typeof fileViewerDialog.close === 'function' && fileViewerDialog.open) {
                        fileViewerDialog.close();
                        return;
                    }

                    if (fileViewerDialog) {
                        fileViewerDialog.replaceChildren();
                    }
                }

                async function openFileViewerDialog(tab, path) {
                    const pageUrl = `/files/${tab.serverId}/view?path=${encodeURIComponent(path)}&embedded=1`;
                    if (!fileViewerDialog || typeof fileViewerDialog.showModal !== 'function') {
                        // No <dialog> in the browser? Then as a tab, not as a page change. A page
                        // change on the shell takes every running session with it - looking at a
                        // file must not cost that.
                        const name = path.split('/').filter(Boolean).pop() || path;
                        openShellTab(`/files/${tab.serverId}/view?path=${encodeURIComponent(path)}`, name);
                        return;
                    }

                    const loadToken = ++fileViewerLoadToken;
                    fileViewerDialog.replaceChildren();
                    const loading = document.createElement('div');
                    loading.className = 'file-viewer-dialog-loading';
                    loading.textContent = `${ui('loading')}...`;
                    fileViewerDialog.appendChild(loading);
                    if (!fileViewerDialog.open) {
                        fileViewerDialog.showModal();
                    }

                    try {
                        const response = await fetch(pageUrl, { cache: 'no-store' });
                        if (loadToken !== fileViewerLoadToken) {
                            return;
                        }

                        if (!response.ok) {
                            const errorText = await response.text().catch(() => '');
                            fileViewerDialog.innerHTML = `
                                <div class="file-viewer-dialog-loading error">
                                    <div>
                                        <h2>${escapeHtml(ui('fileAccessFailed'))}</h2>
                                        <p>${escapeHtml(errorText || ui('fileAccessFailed'))}</p>
                                    </div>
                                </div>`;
                            return;
                        }

                        const html = await response.text();
                        if (loadToken !== fileViewerLoadToken) {
                            return;
                        }

                        fileViewerDialog.innerHTML = normalizeFileViewerMarkup(html);
                    }
                    catch (error) {
                        if (loadToken !== fileViewerLoadToken) {
                            return;
                        }

                        const message = error instanceof Error ? error.message : ui('fileAccessFailed');
                        fileViewerDialog.innerHTML = `
                            <div class="file-viewer-dialog-loading error">
                                <div>
                                    <h2>${escapeHtml(ui('error') || 'Error')}</h2>
                                    <p>${escapeHtml(message)}</p>
                                </div>
                            </div>`;
                    }
                }

                function normalizeFileViewerMarkup(html) {
                    try {
                        const doc = new DOMParser().parseFromString(html, 'text/html');
                        const embeddedViewer = doc.querySelector('section.file-viewer-page');
                        if (embeddedViewer) {
                            return embeddedViewer.outerHTML;
                        }

                        const main = doc.querySelector('main');
                        if (main) {
                            return main.innerHTML.trim() || html;
                        }
                    }
                    catch {
                        // Fall back to the raw response below.
                    }

                    return html;
                }

                function showView(view, updateHistory) {
                    activateNewConnectionTab();
                    document.body.dataset.view = 'home';
                    document.title = `${ui('dashboard')} - Matgate`;

                    if (updateHistory && location.pathname !== '/') {
                        history.pushState({ view: 'home' }, '', '/');
                    }
                }

                function setWorkspaceVisible(active) {
                    if (homeView) {
                        homeView.classList.toggle('hidden', !active);
                    }

                    if (shellPagePanels) {
                        shellPagePanels.classList.toggle('hidden', false);
                    }
                }

                function homeBrowserDefaultState() {
                    return {
                        mode: 'folder',
                        workspaceFilter: 'active',
                        groups: {
                            folder: '',
                            host: ''
                        }
                    };
                }

                function loadHomeBrowserState() {
                    try {
                        const raw = localStorage.getItem(homeBrowserStateKey);
                        if (!raw) {
                            return homeBrowserDefaultState();
                        }

                        const parsed = JSON.parse(raw);
                        return {
                            mode: parsed?.mode === 'host' ? 'host' : 'folder',
                            workspaceFilter: parsed?.workspaceFilter === 'all' ? 'all' : 'active',
                            groups: {
                                folder: typeof parsed?.groups?.folder === 'string' ? parsed.groups.folder : '',
                                host: typeof parsed?.groups?.host === 'string' ? parsed.groups.host : ''
                            }
                        };
                    }
                    catch {
                        return homeBrowserDefaultState();
                    }
                }

                function saveHomeBrowserState() {
                    try {
                        localStorage.setItem(homeBrowserStateKey, JSON.stringify(homeBrowserState));
                    }
                    catch {
                        // Ignore storage failures.
                    }
                }

                function getHomeBrowserModePanels() {
                    return homeBrowser ? Array.from(homeBrowser.querySelectorAll('[data-home-mode-panel]')) : [];
                }

                function getHomeBrowserModeButtons() {
                    return homeBrowser ? Array.from(homeBrowser.querySelectorAll('[data-home-mode-switch]')) : [];
                }

                function findHomeBrowserModePanel(mode) {
                    return getHomeBrowserModePanels().find(panel => panel.dataset.homeModePanel === mode) || null;
                }

                function getHomeBrowserGroupButtons(panel) {
                    return panel ? Array.from(panel.querySelectorAll('[data-home-group]')) : [];
                }

                function getHomeBrowserGroupPanels(panel) {
                    return panel ? Array.from(panel.querySelectorAll('[data-home-group-panel]')) : [];
                }

                function getHomeBrowserWorkspaceRoot() {
                    return homeBrowser ? homeBrowser.querySelector('[data-home-workspaces="1"]') : null;
                }

                function getHomeBrowserWorkspaceButtons() {
                    const root = getHomeBrowserWorkspaceRoot();
                    return root ? Array.from(root.querySelectorAll('[data-home-workspace-filter]')) : [];
                }

                function setHomeBrowserWorkspaceFilter(filter, persist = true) {
                    if (!homeBrowser) {
                        return;
                    }

                    const resolvedFilter = filter === 'all' ? 'all' : 'active';
                    homeBrowserState.workspaceFilter = resolvedFilter;

                    getHomeBrowserWorkspaceButtons().forEach(button => {
                        button.classList.toggle('active', button.dataset.homeWorkspaceFilter === resolvedFilter);
                    });

                    const root = getHomeBrowserWorkspaceRoot();
                    if (root) {
                        const items = Array.from(root.querySelectorAll('[data-home-workspace-item="1"]'));
                        const showAll = resolvedFilter === 'all';
                        let visibleCount = 0;
                        items.forEach(item => {
                            const isActive = item.dataset.homeWorkspaceActive === '1';
                            const visible = showAll || isActive;
                            item.classList.toggle('hidden', !visible);
                            if (visible) {
                                visibleCount += 1;
                            }
                        });

                        const empty = root.querySelector('[data-home-workspace-empty]');
                        if (empty) {
                            const label = showAll
                                ? root.getAttribute('data-home-workspace-empty-all') || uiText.noWorkspacesYet || 'No workspaces yet.'
                                : root.getAttribute('data-home-workspace-empty-active') || uiText.noActiveWorkspaces || 'No active workspaces.';
                            empty.textContent = label;
                            empty.classList.toggle('hidden', visibleCount > 0);
                        }
                    }

                    if (persist) {
                        saveHomeBrowserState();
                    }
                }

                function setHomeBrowserGroup(mode, groupKey, persist = true) {
                    if (!homeBrowser) {
                        return;
                    }

                    const resolvedMode = mode === 'host' ? 'host' : 'folder';
                    const panel = findHomeBrowserModePanel(resolvedMode);
                    if (!panel) {
                        return;
                    }

                    const buttons = getHomeBrowserGroupButtons(panel);
                    const panels = getHomeBrowserGroupPanels(panel);
                    const resolvedKey = buttons.some(button => button.dataset.homeGroup === groupKey)
                        ? groupKey
                        : (panel.dataset.homeDefaultGroup || buttons[0]?.dataset.homeGroup || '');

                    buttons.forEach(button => button.classList.toggle('active', button.dataset.homeGroup === resolvedKey));
                    panels.forEach(section => section.classList.toggle('hidden', section.dataset.homeGroupPanel !== resolvedKey));

                    if (!homeBrowserState.groups) {
                        homeBrowserState.groups = {
                            folder: '',
                            host: ''
                        };
                    }

                    homeBrowserState.groups[resolvedMode] = resolvedKey;
                    if (persist) {
                        saveHomeBrowserState();
                    }
                }

                function setHomeBrowserMode(mode, persist = true) {
                    if (!homeBrowser) {
                        return;
                    }

                    const resolvedMode = mode === 'host' ? 'host' : 'folder';
                    homeBrowserState.mode = resolvedMode;

                    getHomeBrowserModeButtons().forEach(button => button.classList.toggle('active', button.dataset.homeModeSwitch === resolvedMode));
                    getHomeBrowserModePanels().forEach(panel => panel.classList.toggle('hidden', panel.dataset.homeModePanel !== resolvedMode));
                    setHomeBrowserGroup(resolvedMode, homeBrowserState.groups?.[resolvedMode] || '', false);

                    if (persist) {
                        saveHomeBrowserState();
                    }
                }

                function wireHomeBrowser() {
                    if (!homeBrowser) {
                        return;
                    }

                    getHomeBrowserModeButtons().forEach(button => {
                        button.addEventListener('click', () => {
                            setHomeBrowserMode(button.dataset.homeModeSwitch || 'folder');
                        });
                    });

                    getHomeBrowserWorkspaceButtons().forEach(button => {
                        button.addEventListener('click', () => {
                            setHomeBrowserWorkspaceFilter(button.dataset.homeWorkspaceFilter || 'active');
                        });
                    });

                    getHomeBrowserModePanels().forEach(panel => {
                        getHomeBrowserGroupButtons(panel).forEach(button => {
                            button.addEventListener('click', () => {
                                setHomeBrowserGroup(panel.dataset.homeModePanel || 'folder', button.dataset.homeGroup || '');
                            });
                        });
                    });

                    // Mobile off-canvas drawer for the folder/server sidebar.
                    const navToggle = homeBrowser.querySelector('[data-home-nav-toggle]');
                    const setNavOpen = open => {
                        homeBrowser.classList.toggle('home-nav-open', open);
                        if (navToggle) {
                            navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
                        }
                    };
                    if (navToggle) {
                        navToggle.addEventListener('click', () => {
                            setNavOpen(!homeBrowser.classList.contains('home-nav-open'));
                        });
                    }
                    homeBrowser.addEventListener('click', event => {
                        if (!homeBrowser.classList.contains('home-nav-open')) {
                            return;
                        }
                        const target = event.target instanceof Element ? event.target : null;
                        if (!target || target.closest('[data-home-nav-toggle]')) {
                            return;
                        }
                        // Picking a folder/server (or workspace), or tapping the scrim/content, closes it.
                        if (target.closest('.home-browser-nav-item') || !target.closest('.home-browser-sidebar')) {
                            setNavOpen(false);
                        }
                    });
                }

                function restoreHomeBrowser() {
                    if (!homeBrowser) {
                        return;
                    }

                    homeBrowserState = loadHomeBrowserState();
                    setHomeBrowserMode(homeBrowserState.mode, false);
                    setHomeBrowserWorkspaceFilter(homeBrowserState.workspaceFilter, false);
                }

                // Home / New Tab page: live search + folder filtering over the connection cards.
                // Re-fetch the New-connection panel (HTML + availableServers) and swap it in, so a
                // server created/edited/deleted in an embedded admin tab shows up without a full reload.
                async function refreshConnectionsPanel() {
                    try {
                        const res = await fetch('/api/connections/panel', { headers: { 'X-Matgate-Csrf': csrfToken }, cache: 'no-store' });
                        if (!res.ok) { return; }
                        const data = await res.json();
                        const inner = document.querySelector('#new-connection-panel .connection-picker-inner');
                        if (inner && typeof data.html === 'string') {
                            inner.innerHTML = data.html;
                        }
                        if (data.side) {
                            sidebarData = data.side;
                        }
                        if (Array.isArray(data.servers)) {
                            availableServers.length = 0;
                            availableServers.push(...data.servers);
                        }
                        renderServerManager();
                        wireHome2();
                        wireOpenControls(inner || document);
                    }
                    catch (e) { /* ignore refresh failures */ }
                }

                let home2KeydownWired = false;
                // Where the sideways rows of the start page were left. The page is built anew after every
                // favourite, edit or change of the settings - a row that jumped back to its start each time
                // would be a row nobody scrolls twice.
                const home2RowScroll = {};
                // A row that scrolls sideways: it takes back where it was left when it is built anew or comes
                // back into sight (a hidden row has no position of its own), and says whether it is scrolled -
                // the fade at its start - and whether there is more after its end. Once per element.
                function wireHome2Row(row, key) {
                    if (!row || row.dataset.hscroll) {
                        return;
                    }
                    row.dataset.hscroll = '1';
                    const mark = () => {
                        row.classList.toggle('is-scrolled', row.scrollLeft > 4);
                        row.classList.toggle('has-more', row.scrollLeft + row.clientWidth < row.scrollWidth - 4);
                    };
                    const restore = () => {
                        const wanted = home2RowScroll[key] || 0;
                        if (row.clientWidth > 0 && Math.abs(row.scrollLeft - wanted) > 1) {
                            row.scrollLeft = wanted;
                        }
                        mark();
                    };
                    row.addEventListener('scroll', () => {
                        if (row.clientWidth > 0) {
                            home2RowScroll[key] = row.scrollLeft;
                        }
                        mark();
                    }, { passive: true });
                    if (typeof ResizeObserver === 'function') {
                        new ResizeObserver(restore).observe(row);
                    }
                    restore();
                }

                function wireHome2() {
                    const root = document.querySelector('[data-home2]');
                    if (!root) {
                        return;
                    }

                    wireHome2Row(root.querySelector('.home2-quick-row'), 'quick');
                    wireHome2Row(root.querySelector('.home2-folder-grid'), 'folders');

                    // The state of the browser farm, if there is one. A failure stays silent:
                    // the line is an extra, not part of the page.
                    const farmLine = root.querySelector('[data-home2-farm]');
                    if (farmLine) {
                        fetch('/api/browser-farm/status')
                            .then(response => (response.ok ? response.json() : null))
                            .then(data => {
                                if (!data || !data.configured) {
                                    return;
                                }

                                const text = farmLine.querySelector('[data-home2-farm-text]');
                                const dot = farmLine.querySelector('[data-home2-farm-dot]');
                                const fill = (template, values) => (template || '')
                                    .replace('{free}', values.free)
                                    .replace('{pool}', values.pool);
                                if (!data.reachable) {
                                    text.textContent = farmLine.dataset.labelDown || '';
                                    dot.dataset.state = 'down';
                                }
                                else if (!data.free) {
                                    text.textContent = fill(farmLine.dataset.labelFull, { free: data.free, pool: data.poolSize });
                                    dot.dataset.state = 'busy';
                                }
                                else {
                                    text.textContent = fill(farmLine.dataset.labelFree, { free: data.free, pool: data.poolSize });
                                    dot.dataset.state = 'free';
                                }

                                farmLine.hidden = false;
                            })
                            .catch(() => { /* keine Farm, keine Zeile */ });
                    }

                    const searchInput = root.querySelector('[data-home2-search]');
                    const cards = Array.from(root.querySelectorAll('[data-home2-card]'));
                    const quickSection = root.querySelector('.home2-quick-section');
                    const allSection = root.querySelector('[data-home2-all]');
                    const noResults = root.querySelector('[data-home2-noresults]');
                    const filterTiles = Array.from(root.querySelectorAll('[data-home2-filter]'));
                    const resultSections = Array.from(root.querySelectorAll('[data-home2-recent],[data-home2-all],[data-home2-places]'));
                    // null = no filter; '__favorites__' = only favorites; otherwise a folder key.
                    let activeFilter = null;

                    const apply = () => {
                        const term = (searchInput ? searchInput.value : '').trim().toLowerCase();
                        const searching = term.length > 0;
                        let visibleCount = 0;
                        cards.forEach(card => {
                            const inAll = allSection ? allSection.contains(card) : false;
                            const matchesSearch = !searching || (card.dataset.search || '').includes(term);
                            let matchesFilter = true;
                            if (activeFilter !== null && inAll) {
                                matchesFilter = activeFilter === '__favorites__'
                                    ? card.dataset.fav === '1'
                                    : card.dataset.folder === activeFilter;
                            }
                            const visible = matchesSearch && matchesFilter;
                            card.hidden = !visible;
                            if (visible) {
                                visibleCount += 1;
                            }
                        });
                        resultSections.forEach(section => {
                            // Nothing saved yet: that, and what to do about it, stands there until a search
                            // or a filter asks for cards.
                            if (section.hasAttribute('data-home2-nothing-saved')) {
                                section.hidden = searching || activeFilter !== null;
                                return;
                            }
                            // "Recently used" and the places only make sense with no folder/favourites
                            // filter active - when the user filters by a folder, hide them entirely
                            // (their cards aren't part of the filtered set, so they would be left
                            // standing under an empty list).
                            const outsideFilter = section.hasAttribute('data-home2-recent')
                                || section.hasAttribute('data-home2-places');
                            if (outsideFilter && activeFilter !== null) {
                                section.hidden = true;
                                return;
                            }

                            section.hidden = section.querySelector('[data-home2-card]:not([hidden])') === null;
                        });
                        if (quickSection) {
                            quickSection.hidden = searching;
                        }
                        if (noResults) {
                            // "No matches" answers a search or a filter - not a page that has no cards yet.
                            const empty = visibleCount === 0 && (searching || activeFilter !== null);
                            noResults.hidden = !empty;
                            noResults.classList.toggle('hidden', !empty);
                        }
                    };

                    if (searchInput) {
                        searchInput.addEventListener('input', apply);
                    }

                    filterTiles.forEach(tile => {
                        tile.addEventListener('click', () => {
                            const key = tile.dataset.home2Filter || '';
                            activeFilter = activeFilter === key ? null : key;
                            filterTiles.forEach(other => other.classList.toggle('active', other.dataset.home2Filter === activeFilter));
                            apply();
                            if (activeFilter !== null && allSection) {
                                allSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
                            }
                        });
                    });

                    const protoDialog = root.querySelector('[data-home2-proto-dialog]');
                    if (protoDialog) {
                        const qcForm = protoDialog.querySelector('[data-home2-qc-form]');
                        const qcProtoInput = protoDialog.querySelector('[data-home2-qc-proto-input]');
                        const qcProtoButtons = Array.from(protoDialog.querySelectorAll('[data-home2-qc-proto]'));
                        const qcHostLabel = protoDialog.querySelector('[data-home2-qc-hostlabel]');
                        const qcHostInput = protoDialog.querySelector('[data-home2-qc-host]');
                        const qcPortInput = protoDialog.querySelector('[data-home2-qc-port]');
                        const qcError = protoDialog.querySelector('[data-home2-qc-error]');
                        const qcSubmitLabel = protoDialog.querySelector('[data-home2-qc-submit]');
                        const originalHostPlaceholder = qcHostInput ? (qcHostInput.getAttribute('placeholder') || '') : '';
                        const originalHostLabel = qcHostLabel ? qcHostLabel.textContent : 'Host';
                        const defaultPorts = { rdp: '3389', ssh: '22', vnc: '5900', sftp: '22', ftp: '21', smb: '445', website: '', webdav: '', mssql: '1433', mysql: '3306', postgres: '5432' };
                        // Which chip the dialog starts on. Not a fixed protocol: the user decides
                        // which ones exist here, and the first surviving one is the only safe pick.
                        // (The first in the user's order - the server put it into the field; the list itself
                        // is grouped and may start with another.)
                        const qcDefaultProto = (qcProtoInput && qcProtoInput.value) || (qcProtoButtons.length
                            ? qcProtoButtons[0].dataset.home2QcProto
                            : 'rdp');

                        const setField = (name, on) => {
                            const el = protoDialog.querySelector('[data-home2-qc-field="' + name + '"]');
                            if (el) {
                                el.hidden = !on;
                                el.classList.toggle('hidden', !on);
                            }
                        };

                        const setQcProtocol = proto => {
                            const value = Object.prototype.hasOwnProperty.call(defaultPorts, proto) ? proto : qcDefaultProto;
                            if (qcProtoInput) {
                                qcProtoInput.value = value;
                            }
                            qcProtoButtons.forEach(button => button.classList.toggle('active', button.dataset.home2QcProto === value));
                            if (typeof window.MatgateKindSync === 'function') {
                                window.MatgateKindSync(protoDialog.querySelector('[data-kind-select]'));
                            }
                            const isWeb = value === 'website';
                            setField('database', value === 'mssql' || value === 'mysql' || value === 'postgres');
                            const isDav = value === 'webdav';
                            if (qcSubmitLabel) {
                                qcSubmitLabel.textContent = isWeb ? qcSubmitLabel.dataset.browser : qcSubmitLabel.dataset.connect;
                            }
                            setField('port', !isWeb);
                            setField('domain', value === 'rdp' || value === 'smb');
                            setField('fileRoot', isDav || value === 'sftp' || value === 'ftp' || value === 'smb');
                            if (typeof showEngines === 'function') {
                                showEngines(value);
                            }
                            if (qcHostLabel) {
                                qcHostLabel.textContent = isWeb ? ((qcHostInput && qcHostInput.dataset.webLabel) || 'URL') : originalHostLabel;
                            }
                            if (qcHostInput) {
                                // The browser without an address is a tab to type addresses into - where a tab
                                // can go anywhere (host names for websites); otherwise it starts with this one.
                                qcHostInput.required = !(isWeb && qcHostInput.dataset.webBlank === '1');
                                qcHostInput.placeholder = isWeb ? (qcHostInput.dataset.webPlaceholder || 'https://…') : (isDav ? 'nas.local  /  https://nas.local/dav' : originalHostPlaceholder);
                            }
                            if (qcPortInput) {
                                qcPortInput.value = isWeb ? '' : (defaultPorts[value] || '');
                            }
                        };

                        qcProtoButtons.forEach(button => {
                            button.addEventListener('click', () => setQcProtocol(button.dataset.home2QcProto));
                        });

                        // What opens it. Asked for anew with every protocol: Matgate's own engine or Guacamole
                        // for RDP, VNC and SSH, the built-in browser or the browser farm for a website. The
                        // farm's choice is only there once the farm says it is set up.
                        const qcEngineInput = protoDialog.querySelector('[data-home2-qc-engine-input]');
                        const qcEngineOptions = Array.from(protoDialog.querySelectorAll('[data-home2-qc-engine]'));
                        const pickEngine = option => {
                            qcEngineOptions.forEach(other => {
                                const on = other === option;
                                other.classList.toggle('active', on);
                                other.setAttribute('aria-checked', on ? 'true' : 'false');
                            });
                            if (qcEngineInput) {
                                qcEngineInput.value = option ? option.dataset.home2QcEngine : '';
                            }
                        };
                        function showEngines(proto) {
                            const kind = proto === 'website' ? 'web' : (proto === 'rdp' || proto === 'vnc' || proto === 'ssh') ? 'remote' : '';
                            const offered = qcEngineOptions.filter(option => {
                                const on = option.dataset.for === kind && !(option.hasAttribute('data-needs-farm') && protoDialog.dataset.farm !== '1');
                                option.hidden = !on;
                                return on;
                            });
                            setField('engine', offered.length > 1);
                            pickEngine(offered[0] || null);
                        };
                        qcEngineOptions.forEach(option => option.addEventListener('click', () => pickEngine(option)));
                        if (qcEngineOptions.some(option => option.hasAttribute('data-needs-farm'))) {
                            fetch('/api/browser-farm/status')
                                .then(response => (response.ok ? response.json() : null))
                                .then(data => {
                                    if (data && data.configured) {
                                        protoDialog.dataset.farm = '1';
                                        showEngines(qcProtoInput ? qcProtoInput.value : '');
                                    }
                                })
                                .catch(() => { /* no farm: no choice */ });
                        }

                        const openDialog = proto => {
                            setQcProtocol(proto || qcDefaultProto);
                            if (qcError) {
                                qcError.hidden = true;
                                qcError.classList.add('hidden');
                            }
                            if (typeof protoDialog.showModal === 'function') {
                                protoDialog.showModal();
                            }
                            else {
                                protoDialog.setAttribute('open', '');
                            }
                            // With a mouse the cursor stands in the first field. On a touch screen it does not:
                            // focusing brings the keyboard up before anything is read, and the phone shoves and
                            // zooms the page to make room for it.
                            if (qcHostInput && !(window.matchMedia && window.matchMedia('(pointer: coarse)').matches)) {
                                qcHostInput.focus();
                            }
                        };

                        const showQcError = error => {
                            if (qcError) {
                                qcError.textContent = (error && error.message) || ui('connectionStartFailed');
                                qcError.hidden = false;
                                qcError.classList.remove('hidden');
                            }
                        };

                        // Registers what the form describes and answers with its id; throws with the
                        // server's own words when it cannot.
                        const startQuick = async body => {
                            const response = await fetch('/api/quick-connect', {
                                method: 'POST',
                                headers: { 'X-Matgate-Csrf': csrfToken },
                                body
                            });
                            if (!response.ok) {
                                let message = ui('connectionStartFailed');
                                try {
                                    const payload = await response.json();
                                    message = payload.error || message;
                                }
                                catch {
                                    // Keep the generic error.
                                }
                                throw new Error(message);
                            }
                            const data = await response.json();
                            if (!data || !data.server || !data.server.id) {
                                throw new Error(ui('connectionStartFailed'));
                            }
                            // Made for this once: it has no place among the saved connections of the server manager.
                            data.server.ephemeral = true;
                            availableServers.push(data.server);
                            return data.server.id;
                        };

                        Array.from(root.querySelectorAll('[data-home2-more]')).forEach(button => {
                            button.addEventListener('click', () => openDialog(qcDefaultProto));
                        });
                        Array.from(root.querySelectorAll('[data-home2-qc]')).forEach(button => {
                            button.addEventListener('click', async () => {
                                if (button.dataset.home2Qc !== 'website') {
                                    openDialog(button.dataset.home2Qc);
                                    return;
                                }

                                // The browser needs no dialog: its tab has an address bar, and that is where
                                // an address is typed. (With a start address or a sign-in: the dialog, under "More".)
                                const body = new FormData();
                                body.append('protocol', 'website');
                                try {
                                    openServer(await startQuick(body));
                                }
                                catch (error) {
                                    openDialog('website');
                                    showQcError(error);
                                }
                            });
                        });

                        const protoClose = protoDialog.querySelector('[data-home2-proto-close]');
                        if (protoClose) {
                            protoClose.addEventListener('click', () => protoDialog.close());
                        }
                        protoDialog.addEventListener('click', event => {
                            if (event.target === protoDialog) {
                                protoDialog.close();
                            }
                        });

                        if (qcForm) {
                            qcForm.addEventListener('submit', async event => {
                                event.preventDefault();
                                if (qcError) {
                                    qcError.hidden = true;
                                    qcError.classList.add('hidden');
                                }
                                const submitButton = qcForm.querySelector('button[type="submit"]');
                                if (submitButton) {
                                    submitButton.disabled = true;
                                }
                                try {
                                    const id = await startQuick(new FormData(qcForm));
                                    protoDialog.close();
                                    qcForm.reset();
                                    openServer(id);
                                }
                                catch (error) {
                                    showQcError(error);
                                }
                                finally {
                                    if (submitButton) {
                                        submitButton.disabled = false;
                                    }
                                }
                            });
                        }

                        setQcProtocol(qcDefaultProto);
                    }

                    // Bind the global search shortcut only once, and query the (possibly re-rendered)
                    // search field live so it keeps working after the panel is refreshed.
                    if (!home2KeydownWired) {
                        home2KeydownWired = true;
                        document.addEventListener('keydown', event => {
                            const si = document.querySelector('[data-home2-search]');
                            if ((event.ctrlKey || event.metaKey) && (event.key === 'k' || event.key === 'K')) {
                                if (si && si.offsetParent !== null) {
                                    event.preventDefault();
                                    si.focus();
                                    si.select();
                                    return;
                                }
                                // Beside the side panel the page has no search of its own: the panel's is the
                                // one meant. Only while the start page is in front - in a session the keys
                                // are the session's, and anywhere else the key stays the browser's.
                                const filter = document.getElementById('server-manager-filter');
                                const home = document.getElementById('new-connection-panel');
                                if (filter && filter.offsetParent !== null && home && home.offsetParent !== null && !home.classList.contains('hidden')) {
                                    event.preventDefault();
                                    filter.focus();
                                    filter.select();
                                }
                            }
                            else if (event.key === 'Escape' && si && document.activeElement === si && si.value) {
                                si.value = '';
                                si.dispatchEvent(new Event('input', { bubbles: true }));
                            }
                        });
                    }

                    apply();
                }

                function shellEmbeddedUrl(url) {
                    try {
                        const parsed = new URL(url, window.location.origin);
                        parsed.searchParams.set('embed', '1');
                        return `${parsed.pathname}${parsed.search}${parsed.hash}`;
                    }
                    catch {
                        return `${url}${url.includes('?') ? '&' : '?'}embed=1`;
                    }
                }

                // The address a page tab is at NOW: a session page writes its session into its own address,
                // and it may do so after the tab's load was seen (a session that ended and was started again).
                function syncShellTabUrl(tab) {
                    try {
                        const frame = tab.panel ? tab.panel.querySelector('iframe') : null;
                        const loc = frame && frame.contentWindow ? frame.contentWindow.location : null;
                        if (loc && loc.origin === window.location.origin) {
                            const u = new URL(loc.href);
                            u.searchParams.delete('embed');
                            tab.url = `${u.pathname}${u.search}${u.hash}`;
                        }
                    }
                    catch {
                        // A page that cannot be read keeps the address the tab was opened with.
                    }
                    return tab;
                }
                window.MatgateTabAddressChanged = () => saveShellTabs();
                // The sessions the other tabs of this browser show - a screen page asks before it opens a second
                // session to the same machine, and these it need not ask about. `self` is the asking page's window.
                window.MatgateShellSessions = self => Array.from(shellTabs.values())
                    .filter(tab => {
                        const frame = tab.panel ? tab.panel.querySelector('iframe') : null;
                        return !(frame && frame.contentWindow === self);
                    })
                    .map(tab => {
                        try {
                            return new URL(syncShellTabUrl(tab).url, location.origin).searchParams.get('session') || '';
                        }
                        catch {
                            return '';
                        }
                    })
                    .filter(Boolean);

                function saveShellTabs() {
                    if (isPoppedWindow) { return; }
                    try {
                        localStorage.setItem(shellTabStorageKey, JSON.stringify({
                            tabs: Array.from(shellTabs.values()).map(syncShellTabUrl).map(tab => ({
                                id: tab.id,
                                title: tab.title,
                                url: tab.url,
                                iconHtml: tab.iconHtml || '',
                                description: shellTabDescription(tab)
                            })),
                            activeTabId: activeShellTabId
                        }));
                        scheduleTabStatePush();
                    }
                    catch {
                        // Ignore storage failures.
                    }
                }

                function createShellTab(tab) {
                    if (!tabsRoot || !shellPagePanels || shellTabs.has(tab.id)) {
                        return shellTabs.get(tab.id) || null;
                    }

                    const resolvedTitle = tab.url === '/about'
                        ? (uiText.about || ui('About'))
                        : tab.title;
                    const resolvedTab = { ...tab, title: resolvedTitle };

                    const button = document.createElement('div');
                    button.className = 'session-tab session-tab--page';
                    button.setAttribute('data-shell-tab-id', resolvedTab.id);
                    button.setAttribute('data-tab-id', resolvedTab.id);
                    button.setAttribute('data-tab-kind', 'page');

                    const main = document.createElement('button');
                    main.type = 'button';
                    main.className = 'session-tab-main';
                    main.draggable = true;

                    const title = document.createElement('span');
                    title.className = 'session-tab-title';
                    title.innerHTML = `${resolvedTab.iconHtml || ''}<span>${escapeHtml(resolvedTab.title)}</span>`;

                    const subtitle = document.createElement('small');
                    subtitle.className = 'session-tab-description';
                    const resolvedDescription = shellTabDescription(resolvedTab);
                    subtitle.textContent = resolvedDescription;
                    subtitle.hidden = !resolvedDescription;
                    button.classList.toggle('session-tab--compact', !resolvedDescription);
                    main.append(title, subtitle);

                    const close = document.createElement('button');
                    close.type = 'button';
                    close.className = 'session-tab-close';
                    close.setAttribute('aria-label', ui('close'));
                    close.innerHTML = '&times;';
                    close.addEventListener('click', (event) => {
                        event.stopPropagation();
                        closeShellTab(resolvedTab.id);
                    });
                    close.addEventListener('mousedown', event => {
                        event.stopPropagation();
                    });
                    close.addEventListener('dragstart', event => {
                        event.preventDefault();
                        event.stopPropagation();
                    });

                    const panel = document.createElement('section');
                    panel.className = 'shell-page-panel hidden';
                    panel.setAttribute('data-shell-panel-id', resolvedTab.id);
                    const iframe = document.createElement('iframe');
                    iframe.title = resolvedTab.title;
                    // A page in a tab may use the clipboard, full screen and sound like a page of its own (the agent's screen does).
                    iframe.allow = 'clipboard-read; clipboard-write; fullscreen; autoplay; keyboard-map';
                    iframe.allowFullscreen = true;
                    iframe.src = shellEmbeddedUrl(resolvedTab.url);
                    panel.appendChild(iframe);

                    button.append(main, close);
                    const entry = { ...resolvedTab, button, panel, iframe, publicUrl: '' };
                    iframe.addEventListener('load', () => {
                        try {
                            const marker = iframe.contentDocument?.querySelector('[data-workspace-public-url]');
                            const publicUrl = marker?.getAttribute('data-workspace-public-url') || '';
                            if (publicUrl) {
                                entry.publicUrl = publicUrl;
                                if (activeShellTabId === entry.id) {
                                    updateTabActions();
                                }
                            }
                        }
                        catch {
                            // Ignore cross-document lookup failures.
                        }

                        try {
                            const doc = iframe.contentDocument;
                            if (doc) {
                                wireWorkspaceTabs(doc);
                                wireWorkspaceTextForms(doc);
                            }
                        }
                        catch {
                            // Ignore wiring failures in embedded documents.
                        }

                        // A page that loaded while the keyboard is up learns of it now.
                        try {
                            updatePageKeyboardInset();
                        }
                        catch {
                            // Ignore wiring failures in embedded documents.
                        }

                        // Keep the tab header + stored URL in sync when the user navigates INSIDE the
                        // embedded page (back links, in-page links) - otherwise the tab title goes stale.
                        try {
                            const doc = iframe.contentDocument;
                            const newTitle = (doc && doc.title ? doc.title : '').replace(/\s*[-–]\s*Matgate\s*$/i, '').trim();
                            if (newTitle && newTitle !== entry.title) {
                                entry.title = newTitle;
                                const titleSpan = button.querySelector('.session-tab-title > span:last-child');
                                if (titleSpan) {
                                    titleSpan.textContent = newTitle;
                                }
                                iframe.title = newTitle;
                                if (activeShellTabId === entry.id) {
                                    document.title = `${newTitle} - Matgate`;
                                }
                            }

                            const loc = iframe.contentWindow ? iframe.contentWindow.location : null;
                            if (loc && loc.pathname) {
                                const u = new URL(loc.href);
                                u.searchParams.delete('embed');
                                entry.url = `${u.pathname}${u.search}${u.hash}`;
                                // A server or workspace may have changed in this admin/workspaces tab
                                // (create/edit/delete redirect to /admin?tab=servers or /admin/servers,
                                // and workspaces to /workspaces*) - refresh the New-connection panel so a
                                // newly created connection shows up immediately, without a full reload.
                                if (/^\/admin(\/|$)|^\/workspaces(\/|$)/.test(u.pathname)) {
                                    refreshConnectionsPanel();
                                }
                            }
                            saveShellTabs();
                        }
                        catch {
                            // Cross-document / navigation timing edge cases - ignore.
                        }
                    });
                    main.addEventListener('click', event => {
                        if (suppressTabClicks) {
                            event.preventDefault();
                            return;
                        }

                        activateShellTab(resolvedTab.id);
                    });
                    insertTabButton(button);
                    shellPagePanels.appendChild(panel);
                    wireTabDrag(button, resolvedTab.id, main);

                    shellTabs.set(resolvedTab.id, entry);
                    return entry;
                }

                function shellTabDescription(tab) {
                    const fallback = uiText.page || 'Page';
                    if (tab.url.startsWith('/workspaces') || tab.url.startsWith('/workspace/') || tab.url.startsWith('/w/')) {
                        return uiText.workspace || 'Workspace';
                    }
                    if (tab.url === '/tools') {
                        return fallback;
                    }

                    const description = typeof tab.description === 'string' ? tab.description.trim() : '';
                    if (!description) {
                        return fallback;
                    }

                    if (description.startsWith('/') || description.includes('://') || /^[a-zA-Z]:[\\/]/.test(description)) {
                        return fallback;
                    }

                    return description;
                }

                function activateShellTab(tabId) {
                    activeShellTabId = tabId;
                    activeTabId = null;
                    if (!restoringTabs) {
                        // What is in front is written down with the other kind of tabs (saveWorkspaceTabs: front).
                        saveWorkspaceTabs();
                    }
                    newConnectionTab.classList.remove('active');
                    newConnectionPanel.classList.add('hidden');
                    for (const tab of tabs.values()) {
                        tab.tabButton.classList.remove('active');
                        tab.panel.classList.add('hidden');
                    }
                    releaseInactiveHeldKeys();
                    setWorkspaceVisible(false);
                    document.title = `${(shellTabs.get(tabId)?.title || ui('dashboard'))} - Matgate`;

                    shellTabs.forEach(tab => {
                        tab.button.classList.toggle('active', tab.id === tabId);
                        tab.panel.classList.toggle('hidden', tab.id !== tabId);
                    });

                    shellTabs.get(tabId)?.button.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                    dropKeyboardHolder(shellTabs.get(tabId)?.panel || null);
                    recheckKeyboardSoon();

                    updateTabActions();
                    updateStatusBar();
                    saveTabOrder();
                    saveShellTabs();
                }

                function closeShellTab(tabId) {
                    const tab = shellTabs.get(tabId);
                    if (!tab) {
                        return;
                    }

                    // An agent terminal keeps running when its tab closes - picking the work up again later, from
                    // another device even, is the point. It ends with "Beenden" (its page or the agent overview).
                    // A session of Matgate's own engine (RDP, VNC, SSH) ends with its tab.
                    endKeptSession(syncShellTabUrl(tab).url);

                    tab.button.remove();
                    tab.panel.remove();
                    shellTabs.delete(tabId);

                    if (activeShellTabId === tabId) {
                        activeShellTabId = '';
                        activateNewConnectionTab();
                    }

                    saveTabOrder();
                    saveShellTabs();
                }

                function openShellTab(url, title, iconHtml = '', description = '') {
                    if (!url) {
                        activateNewConnectionTab();
                        return;
                    }

                    if ((!tabsRoot || !shellPagePanels) && window.top && window.top !== window && typeof window.top.MatgateOpenShellTab === 'function') {
                        window.top.MatgateOpenShellTab(url, title, iconHtml, description);
                        return;
                    }

                    const existing = Array.from(shellTabs.values()).find(tab => tab.url === url);
                    if (existing) {
                        activateShellTab(existing.id);
                        return;
                    }

                    // The settings are one tab, whichever section is asked for: the open one comes to the front and
                    // goes to that section - unless something in it is not saved yet, which a new address would lose.
                    const pathOf = value => { try { return new URL(value, location.href).pathname; } catch (e) { return ''; } };
                    if (pathOf(url) === '/account') {
                        const settingsTab = Array.from(shellTabs.values()).find(tab => pathOf(tab.url) === '/account');
                        if (settingsTab) {
                            activateShellTab(settingsTab.id);
                            let unsaved = false;
                            try {
                                unsaved = !!settingsTab.iframe.contentDocument?.querySelector('form[data-settings-form][data-dirty]');
                            }
                            catch (e) {
                                unsaved = true;
                            }
                            if (!unsaved) {
                                settingsTab.url = url;
                                settingsTab.iframe.src = shellEmbeddedUrl(url);
                                saveShellTabs();
                            }
                            return;
                        }
                    }

                    const id = `shell-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
                    createShellTab({ id, url, title, iconHtml, description });
                    activateShellTab(id);
                }

                window.MatgateOpenShellTab = openShellTab;
                // A save in a settings tab reaches the shell at once, without a reload (the page calls this with what it
                // saved): the theme and its colours (here and in every page tab), the session settings and the key bar
                // for sessions opened from now on, the action bar and the start page. The lists are filled in place -
                // everything else holds on to them.
                window.MatgateSettingsSaved = data => {
                    if (!data || typeof data !== 'object') {
                        return;
                    }

                    if (data.theme && typeof window.MatgateApplyTheme === 'function') {
                        window.MatgateApplyTheme(data.theme);
                    }
                    if (data.sessionPrefs && typeof data.sessionPrefs === 'object') {
                        Object.assign(sessionPrefs, data.sessionPrefs);
                        updateTabActions();
                    }
                    if (Array.isArray(data.keyBar)) {
                        keyBarButtons.length = 0;
                        keyBarButtons.push(...data.keyBar);
                    }
                    if (Array.isArray(data.actionBar)) {
                        actionBarServers.length = 0;
                        actionBarServers.push(...data.actionBar);
                        updateTabActions();
                    }
                    if (data.refreshPanel) {
                        refreshConnectionsPanel();
                    }
                };
                // From a page that is done (a connection saved from the home page): its own tab closes, and the
                // home page behind it reads the connections anew. False when the page is in no tab of this shell.
                window.MatgateCloseShellTabOf = child => {
                    const entry = Array.from(shellTabs.values()).find(tab => {
                        const frame = tab.panel ? tab.panel.querySelector('iframe') : null;
                        return !!frame && frame.contentWindow === child;
                    });
                    if (!entry) {
                        return false;
                    }
                    refreshConnectionsPanel();
                    closeShellTab(entry.id);
                    return true;
                };
                // From an agent's terminal page: back to that agent's start screen (its tab, or a new one).
                window.MatgateShowAgent = serverId => {
                    const existing = [...tabs.values()].find(candidate => candidate.serverId === serverId && isAgentTab(candidate));
                    if (!existing) {
                        openServer(serverId);
                        return;
                    }

                    activateTab(existing.id);
                    startAgentHome(existing);
                };
                // An embedded page could so far only open a PAGE as a tab. For the workspace
                // page to be able to point at its own place in the file manager, it needs the
                // way to a connection too.
                window.MatgateOpenServerTab = (serverId) => openServer(serverId);

                function restoreShellTabs() {
                    if (!tabsRoot || !shellPagePanels) {
                        return;
                    }

                    try {
                        const raw = localStorage.getItem(shellTabStorageKey);
                        if (!raw) {
                            activateNewConnectionTab();
                            return;
                        }

                        const state = JSON.parse(raw);
                        const storedTabs = Array.isArray(state.tabs) ? state.tabs : [];
                        storedTabs.forEach(tab => {
                            if (tab && tab.id && tab.url && tab.title) {
                                createShellTab(tab);
                            }
                        });

                        const preferred = state.activeTabId && shellTabs.has(state.activeTabId)
                            ? state.activeTabId
                            : '';
                        if (preferred) {
                            activateShellTab(preferred);
                        }
                        else {
                            activateNewConnectionTab();
                        }
                    }
                    catch {
                        activateNewConnectionTab();
                    }
                }

                // Idempotent per-element wiring for the open buttons + shell-tab links. Safe to call
                // again after part of the DOM is re-rendered (guards already-wired elements), so the
                // live-refreshed New-connection panel gets working buttons without double-binding.
                function wireOpenControls(root) {
                    const scope = (root && root.querySelectorAll) ? root : document;
                    scope.querySelectorAll('.workspace-open-button').forEach(button => {
                        if (button.dataset.openWired) { return; }
                        button.dataset.openWired = '1';
                        button.addEventListener('click', () => {
                            openServer(button.getAttribute('data-server-id') || '');
                        });
                    });

                    // A link that points at a place: in the shell it becomes the place, not a
                    // page change. Its href only carries where there is no shell - for instance
                    // when somebody opens the page on its own.
                    scope.querySelectorAll('a[data-server-id]').forEach(anchor => {
                        if (anchor.dataset.openWired) { return; }
                        anchor.dataset.openWired = '1';
                        anchor.addEventListener('click', event => {
                            if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || event.button !== 0) {
                                return;
                            }

                            event.preventDefault();
                            openServer(anchor.getAttribute('data-server-id') || '');
                        });
                    });

                    scope.querySelectorAll('[data-shell-open-tab="1"]').forEach(anchor => {
                        if (anchor.dataset.openWired) { return; }
                        anchor.dataset.openWired = '1';
                        anchor.addEventListener('click', event => {
                            if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || event.button !== 0) {
                                return;
                            }

                            const url = anchor.getAttribute('href') || '';
                            const title = anchor.getAttribute('data-shell-title') || anchor.textContent.trim() || '';
                            const description = anchor.getAttribute('data-shell-description') || '';
                            const iconHtml = anchor.querySelector('.icon')?.outerHTML || anchor.getAttribute('data-shell-icon-html') || '';
                            if (!url) {
                                return;
                            }

                            event.preventDefault();
                            openShellTab(url, title, iconHtml, description);
                        });
                    });
                }

                // A place's settings as a dialog - the way through a page of its own threw you
                // out of the tab you were working in. Saving happens in the background, and
                // afterwards everything stays where it was.
                const workspaceSettingsDialog = document.getElementById('workspace-settings-dialog');

                // Sharing runs through the same dialog in two steps: first the form, then - if
                // it worked - the settings of the fresh share, because that is where the link
                // you want to pass on is.
                async function openSharePlace(areaId) {
                    if (!workspaceSettingsDialog || !areaId) {
                        return;
                    }

                    workspaceSettingsDialog.replaceChildren();
                    const loadingEl = document.createElement('div');
                    loadingEl.className = 'file-viewer-dialog-loading';
                    loadingEl.textContent = `${ui('loading')}...`;
                    workspaceSettingsDialog.appendChild(loadingEl);
                    if (typeof workspaceSettingsDialog.showModal === 'function' && !workspaceSettingsDialog.open) {
                        workspaceSettingsDialog.showModal();
                    }

                    let response;
                    try {
                        response = await fetch(`/api/files/${encodeURIComponent(areaId)}/share-form`, {
                            headers: { 'X-Matgate-Csrf': csrfToken },
                            cache: 'no-store',
                        });
                    }
                    catch {
                        loadingEl.textContent = uiText.actionFailed || 'Failed';
                        return;
                    }

                    if (!response.ok) {
                        // The server says why - for instance that only an administrator may do this.
                        let reason = uiText.actionFailed || 'Failed';
                        try { reason = (await response.json()).error || reason; } catch { }
                        loadingEl.textContent = reason;
                        return;
                    }

                    workspaceSettingsDialog.innerHTML = await response.text();
                    workspaceSettingsDialog.querySelectorAll('[data-workspace-dialog-close]').forEach(button => {
                        button.addEventListener('click', () => workspaceSettingsDialog.close());
                    });

                    const shareForm = workspaceSettingsDialog.querySelector('[data-share-create-form]');
                    if (!shareForm) {
                        return;
                    }

                    shareForm.addEventListener('submit', async event => {
                        event.preventDefault();
                        let result;
                        try {
                            const r = await fetch(shareForm.getAttribute('action') || '', {
                                method: 'POST',
                                body: new FormData(shareForm),
                                credentials: 'same-origin',
                                headers: { 'X-Matgate-Csrf': csrfToken },
                            });
                            result = await r.json();
                            if (!r.ok) {
                                throw new Error(result && result.error ? result.error : String(r.status));
                            }
                        }
                        catch (failure) {
                            // The dialog stays open so that nothing typed is lost.
                            let notice = shareForm.querySelector('.notice.error');
                            if (!notice) {
                                notice = document.createElement('div');
                                notice.className = 'notice error';
                                shareForm.prepend(notice);
                            }

                            notice.textContent = failure && failure.message ? failure.message : String(failure);
                            return;
                        }

                        await refreshConnectionsPanel();
                        await openWorkspaceSettings(result && result.id);
                    });
                }

                async function openWorkspaceSettings(workspaceId) {
                    if (!workspaceSettingsDialog || !workspaceId) {
                        return;
                    }

                    workspaceSettingsDialog.replaceChildren();
                    const loadingEl = document.createElement('div');
                    loadingEl.className = 'file-viewer-dialog-loading';
                    loadingEl.textContent = `${ui('loading')}...`;
                    workspaceSettingsDialog.appendChild(loadingEl);
                    if (typeof workspaceSettingsDialog.showModal === 'function' && !workspaceSettingsDialog.open) {
                        workspaceSettingsDialog.showModal();
                    }

                    let html = '';
                    try {
                        const response = await fetch(`/api/workspaces/${encodeURIComponent(workspaceId)}/settings`, {
                            headers: { 'X-Matgate-Csrf': csrfToken },
                            cache: 'no-store',
                        });
                        if (!response.ok) {
                            throw new Error(String(response.status));
                        }

                        html = await response.text();
                    }
                    catch {
                        loadingEl.textContent = uiText.actionFailed || 'Failed';
                        return;
                    }

                    workspaceSettingsDialog.innerHTML = html;
                    workspaceSettingsDialog.querySelectorAll('[data-workspace-dialog-close]').forEach(button => {
                        button.addEventListener('click', () => workspaceSettingsDialog.close());
                    });
                    workspaceSettingsDialog.querySelectorAll('[data-workspace-copy]').forEach(button => {
                        button.addEventListener('click', async () => {
                            await window.MatgateCopyText?.(button.getAttribute('data-workspace-copy') || '');
                        });
                    });

                    const shareForm = workspaceSettingsDialog.querySelector('[data-workspace-settings-form]');
                    if (shareForm) {
                        shareForm.addEventListener('submit', async event => {
                            event.preventDefault();
                            try {
                                await fetch(shareForm.getAttribute('action') || '', {
                                    method: 'POST',
                                    body: new FormData(shareForm),
                                    credentials: 'same-origin',
                                    headers: { 'X-Matgate-Csrf': csrfToken },
                                });
                            }
                            catch {
                                // No connection - then the dialog stays open and nothing is lost.
                                return;
                            }

                            workspaceSettingsDialog.close();
                            // The name may have changed: fetch the list of places again, relabel the tab,
                            // reload the content.
                            await refreshConnectionsPanel();
                            const tab = tabs.get(activeTabId);
                            if (tab) {
                                const fresh = findServer(tab.serverId);
                                if (fresh) {
                                    tab.name = fresh.name;
                                    const titleEl = tab.tabMain ? tab.tabMain.querySelector('.session-tab-title') : null;
                                    if (titleEl) {
                                        titleEl.innerHTML = tabTitleHtml(fresh);
                                    }
                                }

                                startFileTab(tab);
                            }
                        });
                    }
                }

                document.addEventListener('click', event => {
                    const shareTrigger = event.target instanceof Element
                        ? event.target.closest('[data-share-place]')
                        : null;
                    if (shareTrigger) {
                        event.preventDefault();
                        openSharePlace(shareTrigger.getAttribute('data-share-place'));
                        return;
                    }

                    const button = event.target instanceof Element
                        ? event.target.closest('[data-workspace-settings]')
                        : null;
                    if (button) {
                        event.preventDefault();
                        openWorkspaceSettings(button.getAttribute('data-workspace-settings'));
                    }
                });
                function wireShellNavigation() {
                    wireOpenControls(document);

                    newConnectionTab.addEventListener('click', event => {
                        if (suppressTabClicks) {
                            event.preventDefault();
                            return;
                        }

                        activateNewConnectionTab();
                    });

                    // A middle click on a tab closes it, as in a browser: the same as the cross on the tab, without
                    // having to hit the cross. The plus ("new connection") is no tab to close. The button press is
                    // cancelled as well, or Windows starts its autoscroll over a strip that scrolls sideways - and in
                    // the capture phase, because the cross keeps its own presses from bubbling.
                    if (tabsRoot) {
                        const closableTabOf = event => {
                            const element = event.button === 1 && event.target instanceof Element ? event.target.closest('.session-tab') : null;
                            const kind = element ? element.getAttribute('data-tab-kind') : '';
                            return kind === 'connection' || kind === 'page' ? element : null;
                        };
                        tabsRoot.addEventListener('mousedown', event => {
                            if (closableTabOf(event)) {
                                event.preventDefault();
                            }
                        }, true);
                        tabsRoot.addEventListener('auxclick', event => {
                            const element = closableTabOf(event);
                            if (!element) {
                                return;
                            }

                            event.preventDefault();
                            if (element.getAttribute('data-tab-kind') === 'page') {
                                closeShellTab(element.getAttribute('data-shell-tab-id'));
                            }
                            else {
                                closeTab(element.getAttribute('data-tab-id'));
                            }
                        });
                    }

                    // ---- Right click ----------------------------------------------------------------------
                    // A menu at the pointer for the things one works with here: a connection's card, a tab, a
                    // quick-connect chip, a row in the file list. Whatever a card or a row offers is read off
                    // the buttons it already has, so there is one place that says what each of them does.
                    // Not where text is typed or marked (the browser's menu is the right one there), not
                    // inside a session (the click belongs to the machine), and never with Shift held: that
                    // is the way to the browser's own menu.
                    const contextIcon = source => {
                        const svg = source ? source.querySelector('svg') : null;
                        return svg ? svg.outerHTML : '';
                    };
                    const contextMenuOfCard = card => {
                        const items = [];
                        const open = card.querySelector('.connection-choice-actions button, .connection-choice-actions a');
                        if (open) {
                            items.push({ label: (open.textContent || '').trim(), iconHtml: contextIcon(open), onSelect: () => open.click() });
                            const serverId = open.getAttribute('data-server-id');
                            if (serverId) {
                                items.push({
                                    label: ui('ctxBrowserTab'),
                                    iconHtml: actionIcons.popOut || '',
                                    onSelect: () => window.open('/?open=' + encodeURIComponent(serverId), '_blank', 'noopener')
                                });
                            }
                        }

                        const corner = Array.from(card.querySelectorAll('.connection-choice-corner .favorite-toggle'));
                        if (items.length && corner.length) {
                            items.push({ separator: true });
                        }
                        // The star first, then the gear - the order of use, not of the corner.
                        corner.sort((a, b) => (a.closest('form') ? 0 : 1) - (b.closest('form') ? 0 : 1)).forEach(control => {
                            items.push({
                                label: control.getAttribute('title') || control.getAttribute('aria-label') || '',
                                iconHtml: contextIcon(control),
                                onSelect: () => control.click()
                            });
                        });

                        // Who may use it - as in the side panel's menu; the phone's "..." leads here too.
                        const accessId = card.dataset.cardServer;
                        if (accessId && card.dataset.cardAccess === '1') {
                            const name = ((card.querySelector('h3') || {}).textContent || '').trim();
                            items.push({ label: uiText.managerAccess || 'Access ...', iconHtml: fileIcon('shield'), onSelect: () => openShellTab('/admin/access?server=' + encodeURIComponent(accessId), (uiText.managerAccessTitle || 'Access') + ': ' + name, fileIcon('shield'), '') });
                        }

                        const address = ((card.querySelector('.target') || {}).textContent || '').trim();
                        if (address) {
                            items.push({ separator: true });
                            items.push({ label: ui('ctxCopyAddress'), iconHtml: fileIcon('copy'), onSelect: () => window.MatgateCopyText?.(address) });
                        }

                        return { trigger: card, title: ((card.querySelector('h3') || {}).textContent || '').trim(), items };
                    };
                    // A row of the server manager offers what the connection's card on the start page does (the
                    // card is where its buttons are), and one thing of its own: a further session.
                    const cardOfServer = serverId => Array.from(document.querySelectorAll('[data-home2-card]'))
                        .find(card => card.querySelector('.connection-choice-actions [data-server-id="' + serverId + '"]')) || null;
                    const contextMenuOfManaged = (row, card) => {
                        const serverId = row.dataset.managerServer;
                        const fromCard = card ? contextMenuOfCard(card).items : [];
                        const items = fromCard.length ? fromCard : [{ label: uiText.managerConnect || 'Connect', iconHtml: contextIcon(row), onSelect: () => openServer(serverId) }];
                        if (sessionsOfServer(serverId).length) {
                            items.splice(1, 0, { label: uiText.managerNewSession || 'Open another session', iconHtml: fileIcon('plus'), onSelect: () => openServer(serverId) });
                        }

                        // Filing: into a folder by name (a subfolder with "/"), or out of the one it is in.
                        const side = window.MatgateSidePanel;
                        const server = availableServers.find(candidate => candidate.id === serverId);
                        if (side && server && side.canMove(serverId) && row.dataset.sortable === '1') {
                            items.push({ separator: true });
                            items.push({
                                label: uiText.managerMoveTo || 'Move to folder ...',
                                iconHtml: fileIcon('move'),
                                onSelect: async () => {
                                    const folder = await side.askFolderName(uiText.managerMoveTo || 'Move to folder', server.folder || '', uiText.managerMove || 'Move', uiText.managerMoveHint || '');
                                    if (folder !== null && folder !== (server.folder || '')) {
                                        side.move(serverId, folder);
                                    }
                                }
                            });
                            if (server.folder) {
                                items.push({ label: uiText.managerMoveOut || 'Take out of the folder', iconHtml: fileIcon('folder'), onSelect: () => side.move(serverId, '') });
                            }
                            // Who may use it: its access page (for a shared connection; the page says when one may not).
                            if (server.shared !== false) {
                                items.push({ label: uiText.managerAccess || 'Access ...', iconHtml: fileIcon('shield'), onSelect: () => openShellTab('/admin/access?server=' + encodeURIComponent(serverId), (uiText.managerAccessTitle || 'Access') + ': ' + server.name, fileIcon('shield'), '') });
                            }
                        }

                        return { trigger: row, title: ((row.querySelector('strong') || {}).textContent || '').trim(), items };
                    };
                    // A folder of the side panel: a new connection in it, a subfolder, its page; and for every
                    // group, all of them shut or open.
                    const contextMenuOfFolder = head => {
                        const side = window.MatgateSidePanel;
                        const path = head.dataset.folder || '';
                        const items = [];
                        if (head.dataset.kind === 'folder' && side && side.canEdit()) {
                            items.push({ label: uiText.managerNewHere || 'New connection here', iconHtml: fileIcon('plus'), onSelect: () => side.newIn(path) });
                            items.push({
                                label: path ? (uiText.managerNewSubfolder || 'New subfolder ...') : (uiText.managerNewFolder || 'New folder ...'),
                                iconHtml: fileIcon('mkdir'),
                                onSelect: async () => {
                                    const name = await side.askFolderName(path ? uiText.managerNewSubfolder : uiText.managerNewFolder, '', uiText.managerCreate || 'Continue', uiText.managerFolderHint || '');
                                    if (name) {
                                        side.createFolder(path ? path + '/' + name : name);
                                    }
                                }
                            });
                            if (path) {
                                items.push({
                                    label: uiText.managerEditFolder || 'Edit folder',
                                    iconHtml: fileIcon('edit'),
                                    onSelect: () => openShellTab('/admin/folders/edit?name=' + encodeURIComponent(path), path, fileIcon('folder'), uiText.managerFolder || '')
                                });
                                // Who may use what lies in it: the folder's access page.
                                items.push({
                                    label: uiText.managerAccess || 'Access ...',
                                    iconHtml: fileIcon('shield'),
                                    onSelect: () => openShellTab('/admin/access?folder=' + encodeURIComponent(path), (uiText.managerAccessTitle || 'Access') + ': ' + path, fileIcon('shield'), '')
                                });
                            }
                        }

                        // The user's own order of this folder (dragged) given up: by name again.
                        const ordered = side && (head.dataset.kind === 'folder' || head.dataset.kind === 'favorites') ? side.orderedIn(head) : [];
                        if (ordered.length) {
                            if (items.length) {
                                items.push({ separator: true });
                            }
                            items.push({ label: uiText.managerSortByName || 'Sort by name', iconHtml: fileIcon('sort'), onSelect: () => side.resetOrder(ordered) });
                        }

                        if (side) {
                            if (items.length) {
                                items.push({ separator: true });
                            }
                            items.push({ label: uiText.managerCollapseAll || 'Collapse all folders', iconHtml: fileIcon('chevronDown'), onSelect: () => side.setAllClosed(true) });
                            items.push({ label: uiText.managerExpandAll || 'Expand all folders', iconHtml: fileIcon('folder'), onSelect: () => side.setAllClosed(false) });
                        }

                        return { trigger: head, title: ((head.querySelector('.server-manager-folder-name') || {}).textContent || '').trim(), items };
                    };
                    // The free room of the side panel: what can be made from there.
                    const contextMenuOfSidePanel = panel => {
                        const side = window.MatgateSidePanel;
                        const items = [];
                        const quick = document.querySelector('[data-home2-more]');
                        if (quick) {
                            items.push({ label: uiText.managerQuick || 'Quick connect', iconHtml: fileIcon('play') || contextIcon(quick), onSelect: () => quick.click() });
                        }
                        if (side && side.canEdit()) {
                            items.push({ label: uiText.managerNew || 'New connection', iconHtml: fileIcon('plus'), onSelect: () => side.newIn('') });
                            items.push({
                                label: uiText.managerNewFolder || 'New folder ...',
                                iconHtml: fileIcon('mkdir'),
                                onSelect: async () => {
                                    const name = await side.askFolderName(uiText.managerNewFolder, '', uiText.managerCreate || 'Continue', uiText.managerFolderHint || '');
                                    if (name) {
                                        side.createFolder(name);
                                    }
                                }
                            });
                        }
                        if (side) {
                            items.push({ separator: true });
                            items.push({ label: uiText.managerCollapseAll || 'Collapse all folders', iconHtml: fileIcon('chevronDown'), onSelect: () => side.setAllClosed(true) });
                            items.push({ label: uiText.managerExpandAll || 'Expand all folders', iconHtml: fileIcon('folder'), onSelect: () => side.setAllClosed(false) });
                        }

                        return { trigger: panel, title: uiText.managerTitle || '', items };
                    };
                    const contextMenuOfTab = element => {
                        const kind = element.getAttribute('data-tab-kind');
                        if (kind !== 'connection' && kind !== 'page') {
                            return null;
                        }

                        const id = element.getAttribute('data-tab-id');
                        const close = which => which.getAttribute('data-tab-kind') === 'page'
                            ? closeShellTab(which.getAttribute('data-shell-tab-id'))
                            : closeTab(which.getAttribute('data-tab-id'));
                        const others = Array.from(tabsRoot.querySelectorAll('.session-tab[data-tab-kind="connection"], .session-tab[data-tab-kind="page"]'))
                            .filter(other => other !== element);
                        const items = [];
                        if (kind === 'page') {
                            const page = shellTabs.get(id);
                            items.push({
                                label: ui('ctxReload'),
                                iconHtml: fileIcon('refresh'),
                                onSelect: () => { try { page.iframe.contentWindow.location.reload(); } catch { page.iframe.src = page.iframe.src; } }
                            });
                            if (page && !isPoppedWindow && serverIdOfShellTab(page)) {
                                items.push({ label: ui('ctxOwnWindow'), iconHtml: actionIcons.popOut || '', onSelect: () => popOutShellTab(page) });
                            }
                        }
                        else if (tabs.get(id) && tabs.get(id).serverId) {
                            items.push({ label: ui('ctxOwnWindow'), iconHtml: actionIcons.popOut || '', onSelect: () => popOutTab(tabs.get(id)) });
                        }

                        if (items.length) {
                            items.push({ separator: true });
                        }
                        items.push({ label: ui('ctxCloseTab'), iconHtml: fileIcon('clear'), onSelect: () => close(element) });
                        items.push({
                            label: ui('ctxCloseOthers'),
                            iconHtml: fileIcon('clear'),
                            disabled: others.length === 0,
                            onSelect: async () => {
                                if (await askToConfirm({ title: ui('ctxCloseOthersTitle'), text: ui('ctxCloseOthersText'), confirm: ui('ctxCloseOthers') })) {
                                    others.forEach(close);
                                }
                            }
                        });
                        return { trigger: element, title: ((element.querySelector('.session-tab-title') || {}).textContent || '').trim(), items };
                    };
                    const contextMenuOfChip = chip => ({
                        trigger: chip,
                        title: (chip.textContent || '').trim(),
                        items: [
                            { label: (chip.textContent || '').trim(), iconHtml: contextIcon(chip), onSelect: () => chip.click() },
                            { separator: true },
                            {
                                label: ui('ctxCustomize'),
                                iconHtml: fileIcon('settings'),
                                onSelect: () => openShellTab('/account?tab=home#quick-order-list', ui('ctxCustomize'), fileIcon('settings'), '')
                            }
                        ]
                    });
                    const contextMenuOfFileRow = row => {
                        const sources = Array.from(row.querySelectorAll('.file-row-actions .file-action-button'));
                        return sources.length === 0 ? null : {
                            trigger: row,
                            title: ((row.querySelector('.file-name-button') || {}).textContent || '').trim(),
                            items: sources.map(source => ({
                                label: source.title,
                                iconHtml: contextIcon(source),
                                danger: source.classList.contains('danger'),
                                onSelect: () => source.click()
                            }))
                        };
                    };
                    document.addEventListener('contextmenu', event => {
                        const target = event.target instanceof Element ? event.target : null;
                        if (!target || event.shiftKey || event.defaultPrevented
                            || target.closest('input, textarea, select, [contenteditable], .toolbar-menu-panel')) {
                            return;
                        }

                        const tab = target.closest('.session-tab');
                        const managed = target.closest('[data-manager-server]');
                        const card = target.closest('[data-home2-card]') || (managed ? cardOfServer(managed.dataset.managerServer) : null);
                        const chip = target.closest('.home2-proto-chip[data-home2-qc]');
                        const row = target.closest('.file-table tbody tr');
                        // A finger held on a tab is the start of dragging it, not a wish for a menu.
                        const folderHead = target.closest('#server-manager-tree .server-manager-folder');
                        const sidePanel = target.closest('#server-manager');
                        const menu = tab ? (event.pointerType === 'touch' ? null : contextMenuOfTab(tab))
                            : managed ? contextMenuOfManaged(managed, card)
                            : folderHead ? contextMenuOfFolder(folderHead)
                            : sidePanel ? contextMenuOfSidePanel(sidePanel)
                            : card ? contextMenuOfCard(card)
                            : chip ? contextMenuOfChip(chip)
                            : row ? contextMenuOfFileRow(row)
                            : null;
                        if (!menu || menu.items.length === 0 || typeof window.MatgateOpenMenu !== 'function') {
                            return;
                        }

                        event.preventDefault();
                        window.MatgateOpenMenu({
                            trigger: menu.trigger,
                            at: { x: event.clientX, y: event.clientY },
                            title: menu.title,
                            closeLabel: ui('close'),
                            items: menu.items
                        });
                    });

                    // The "..." of a connection on a phone: the card's menu, as a right click opens it (star,
                    // settings, access, copy the address). The card itself connects when tapped.
                    document.addEventListener('click', event => {
                        const more = event.target instanceof Element ? event.target.closest('[data-card-more]') : null;
                        const card = more ? more.closest('[data-home2-card]') : null;
                        if (!card || typeof window.MatgateOpenMenu !== 'function') {
                            return;
                        }

                        event.preventDefault();
                        event.stopPropagation();
                        const menu = contextMenuOfCard(card);
                        const box = more.getBoundingClientRect();
                        window.MatgateOpenMenu({
                            trigger: more,
                            at: { x: box.right, y: box.bottom },
                            title: menu.title,
                            closeLabel: ui('close'),
                            items: menu.items
                        });
                    }, true);

                    // A finger held still on the side panel is its right click: that is where a new connection
                    // or folder is made now that the panel has no head. iOS sends no contextmenu for it, so it is
                    // made here; where the browser sends one itself (Android), that one is taken and ours dropped.
                    let holdTimer = 0;
                    let holdStart = null;
                    let holdFiredAt = 0;
                    const cancelHold = () => {
                        window.clearTimeout(holdTimer);
                        holdTimer = 0;
                        holdStart = null;
                    };
                    document.addEventListener('pointerdown', event => {
                        cancelHold();
                        // A new touch: whatever the last hold kept from being a tap is over.
                        holdFiredAt = 0;
                        const target = event.target instanceof Element ? event.target : null;
                        if (event.pointerType !== 'touch' || !target || !target.closest('#server-manager') || target.closest('input, textarea, select, button.server-manager-close')) {
                            return;
                        }
                        holdStart = { x: event.clientX, y: event.clientY, target };
                        holdTimer = window.setTimeout(() => {
                            const start = holdStart;
                            cancelHold();
                            if (!start || !start.target.isConnected) {
                                return;
                            }
                            holdFiredAt = Date.now();
                            start.target.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: start.x, clientY: start.y }));
                        }, 550);
                    }, true);
                    document.addEventListener('pointermove', event => {
                        if (holdStart && Math.hypot(event.clientX - holdStart.x, event.clientY - holdStart.y) > 10) {
                            cancelHold();
                        }
                    }, true);
                    ['pointerup', 'pointercancel', 'scroll'].forEach(name => document.addEventListener(name, cancelHold, true));
                    window.addEventListener('contextmenu', event => {
                        if (!event.isTrusted) {
                            return;
                        }
                        if (holdTimer) {
                            // The browser's own came first: it is the one.
                            cancelHold();
                        }
                        else if (Date.now() - holdFiredAt < 1500 && event.target instanceof Element && event.target.closest('#server-manager')) {
                            // Ours is open already - the browser's would be a second menu, or its own callout.
                            event.preventDefault();
                            event.stopImmediatePropagation();
                        }
                    }, true);
                    // Lifting the finger after the menu came is no tap: it must not open what was held.
                    document.addEventListener('click', event => {
                        if (Date.now() - holdFiredAt < 800 && event.target instanceof Element && event.target.closest('#server-manager')) {
                            event.preventDefault();
                            event.stopImmediatePropagation();
                        }
                    }, true);

                    // Safety net: on the shell, NO internal navigation may replace the page - that would
                    // tear down every live session. Any internal <a> that isn't already a shell-tab link,
                    // a download, or an external/_blank link is intercepted and opened as a shell tab
                    // instead; links back to the shell itself just focus the New-connection tab. Runs
                    // after the per-link data-shell-open-tab handlers (which set defaultPrevented).
                    document.addEventListener('click', event => {
                        if (event.defaultPrevented || event.button !== 0
                            || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) {
                            return;
                        }

                        const anchor = event.target.closest ? event.target.closest('a[href]') : null;
                        if (!anchor || anchor.hasAttribute('data-shell-open-tab') || anchor.hasAttribute('download')) {
                            return;
                        }

                        const target = anchor.getAttribute('target');
                        if (target && target !== '_self') {
                            return;
                        }

                        const href = anchor.getAttribute('href') || '';
                        if (!href.startsWith('/') || href.startsWith('//')) {
                            return; // external, protocol-relative or in-page anchor - leave it alone
                        }

                        event.preventDefault();
                        if (href === '/' || href === '/sessions' || href.startsWith('/sessions?') || href.startsWith('/sessions#')) {
                            activateNewConnectionTab();
                            return;
                        }

                        const title = anchor.getAttribute('data-shell-title') || (anchor.textContent || '').trim() || href;
                        openShellTab(href, title);
                    });

                    // The same safety net for forms. A submitted form is a navigation, and a
                    // navigation on the shell takes every running session with it - without a
                    // word, the tabs are simply gone. That is exactly what the favourite star on
                    // the home page did. Forms with [data-shell-inline] are therefore submitted
                    // in the background, after which the connection list is fetched again.
                    document.addEventListener('submit', async (event) => {
                        const form = event.target;
                        if (!(form instanceof HTMLFormElement) || !form.hasAttribute('data-shell-inline')) {
                            return;
                        }

                        event.preventDefault();
                        try {
                            await fetch(form.getAttribute('action') || '', {
                                method: 'POST',
                                body: new FormData(form),
                                credentials: 'same-origin',
                                headers: { 'X-Matgate-Csrf': csrfToken },
                            });
                        }
                        catch {
                            // No connection to the gateway - then the list stays as it was.
                        }

                        await refreshConnectionsPanel();
                    });

                    window.addEventListener('popstate', () => {
                        showView('home', false);
                    });
                }

                function wireWorkspaceTabs(root = document) {
                    const scope = root && typeof root.querySelectorAll === 'function' ? root : document;
                    scope.querySelectorAll('[data-workspace-tab-root="1"]').forEach(root => {
                        if (wiredWorkspaceTabRoots.has(root)) {
                            return;
                        }
                        wiredWorkspaceTabRoots.add(root);

                        const buttons = Array.from(root.querySelectorAll('[data-workspace-tab]'));
                        const panels = Array.from(root.querySelectorAll('[data-workspace-panel]'));
                        if (!buttons.length || !panels.length) {
                            return;
                        }

                        const workspaceKey = root.getAttribute('data-workspace-tab-key') || window.location.pathname;
                        const storageKey = `matgate.workspace.panel.${workspaceKey}`;
                        const defaultTab = root.getAttribute('data-workspace-default-tab')
                            || buttons[0].getAttribute('data-workspace-tab')
                            || 'files';

                        const activate = (tabName, persist = true) => {
                            const selected = buttons.some(button => button.getAttribute('data-workspace-tab') === tabName)
                                ? tabName
                                : defaultTab;

                            buttons.forEach(button => {
                                button.classList.toggle('active', button.getAttribute('data-workspace-tab') === selected);
                                button.setAttribute('aria-selected', button.getAttribute('data-workspace-tab') === selected ? 'true' : 'false');
                            });

                            panels.forEach(panel => {
                                panel.classList.toggle('hidden', panel.getAttribute('data-workspace-panel') !== selected);
                            });

                            if (persist) {
                                try {
                                    localStorage.setItem(storageKey, selected);
                                }
                                catch {
                                    // Ignore storage errors.
                                }
                            }
                        };

                        buttons.forEach(button => {
                            button.addEventListener('click', () => {
                                activate(button.getAttribute('data-workspace-tab') || defaultTab);
                            });
                        });

                        let initialTab = defaultTab;
                        try {
                            const requested = new URL(window.location.href).searchParams.get('tab');
                            if (requested) {
                                initialTab = requested;
                            }
                            else {
                                const stored = localStorage.getItem(storageKey);
                                if (stored) {
                                    initialTab = stored;
                                }
                            }
                        }
                        catch {
                            // Ignore storage errors.
                        }

                        activate(initialTab, false);
                    });
                }

                function wireWorkspaceTextForms(root = document) {
                    const scope = root && typeof root.querySelectorAll === 'function' ? root : document;
                    scope.querySelectorAll('form[data-workspace-text-form="1"]').forEach(form => {
                        if (wiredWorkspaceTextForms.has(form)) {
                            return;
                        }
                        wiredWorkspaceTextForms.add(form);

                        const textarea = form.querySelector('textarea[name="text"]');
                        const saveButton = form.querySelector('[data-workspace-text-save]');
                        const autoSaveInput = form.querySelector('[data-workspace-text-auto-save]');
                        const status = form.querySelector('[data-workspace-text-status]');
                        const lastSaved = form.querySelector('[data-workspace-text-last-saved]');
                        const currentPath = form.dataset.workspaceCurrentPath || '';
                        const tabRoot = form.closest('[data-workspace-tab-root="1"]');
                        const logPanel = tabRoot?.querySelector('[data-workspace-panel="log"]') || null;
                        const savingLabel = form.dataset.workspaceSavingLabel || 'Saving...';
                        const savedLabel = form.dataset.workspaceSavedLabel || 'Saved';
                        const readyLabel = form.dataset.workspaceReadyLabel || 'Ready';
                        const dirtyLabel = form.dataset.workspaceDirtyLabel || 'Unsaved changes';
                        const failedLabel = form.dataset.workspaceFailedLabel || 'Save failed.';
                        const neverSavedLabel = form.dataset.workspaceNeverSavedLabel || 'Never saved';
                        const initialLastSavedAt = form.dataset.workspaceLastSavedAt || '';
                        const autoSaveDelay = 1200;
                        let autoSaveTimer = null;
                        let saveInFlight = false;
                        let lastSavedValue = textarea?.value || '';
                        let pendingSave = false;

                        if (!textarea) {
                            return;
                        }

                        const pad = value => String(value).padStart(2, '0');
                        const formatDateTime = (date) => {
                            if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
                                return neverSavedLabel;
                            }

                            return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
                        };

                        const updateLastSaved = (date) => {
                            if (!lastSaved) {
                                return;
                            }

                            lastSaved.textContent = date ? formatDateTime(date) : neverSavedLabel;
                        };

                        const setStatus = (message) => {
                            if (status) {
                                status.textContent = message;
                            }
                        };

                        const clearAutoSaveTimer = () => {
                            if (autoSaveTimer) {
                                window.clearTimeout(autoSaveTimer);
                                autoSaveTimer = null;
                            }
                        };

                        const refreshLogPanel = async () => {
                            if (!logPanel) {
                                return;
                            }

                            try {
                                const url = new URL(window.location.href);
                                url.searchParams.set('tab', 'log');
                                url.searchParams.set('path', currentPath || '/');
                                url.searchParams.set('embed', '1');
                                const response = await fetch(url.toString(), { cache: 'no-store' });
                                if (!response.ok) {
                                    return;
                                }

                                const html = await response.text();
                                const doc = new DOMParser().parseFromString(html, 'text/html');
                                const nextPanel = doc.querySelector('[data-workspace-panel="log"]');
                                if (nextPanel) {
                                    logPanel.innerHTML = nextPanel.innerHTML;
                                }
                            }
                            catch {
                                // Ignore refresh failures.
                            }
                        };

                        const saveWorkspaceText = async () => {
                            if (saveInFlight) {
                                pendingSave = true;
                                return;
                            }

                            const snapshot = textarea.value;
                            if (snapshot === lastSavedValue) {
                                setStatus(readyLabel);
                                clearAutoSaveTimer();
                                return;
                            }

                            clearAutoSaveTimer();
                            saveInFlight = true;
                            form.dataset.workspaceSaving = '1';
                            if (saveButton instanceof HTMLButtonElement) {
                                saveButton.disabled = true;
                            }
                            setStatus(savingLabel);

                            try {
                                const response = await fetch(form.action, {
                                    method: 'POST',
                                    body: new FormData(form),
                                    cache: 'no-store',
                                    credentials: 'same-origin',
                                    headers: {
                                        'X-Requested-With': 'XMLHttpRequest',
                                        'Accept': 'application/json'
                                    }
                                });

                                if (!response.ok) {
                                    const errorText = await response.text().catch(() => '');
                                    throw new Error(errorText || failedLabel);
                                }

                                const finalUrl = new URL(response.url, window.location.href);
                                if (finalUrl.pathname === '/login') {
                                    throw new Error(failedLabel);
                                }

                                const contentType = response.headers.get('content-type') || '';
                                if (!contentType.includes('application/json')) {
                                    throw new Error(failedLabel);
                                }

                                const payload = await response.json();
                                if (!payload || payload.ok !== true) {
                                    throw new Error((payload && payload.error) || failedLabel);
                                }

                                const savedAt = payload.savedAt ? new Date(payload.savedAt) : new Date();
                                lastSavedValue = snapshot;
                                updateLastSaved(savedAt);
                                if (textarea.value === snapshot) {
                                    setStatus(`${savedLabel} ${formatDateTime(savedAt)}`);
                                }
                                else {
                                    setStatus(dirtyLabel);
                                    scheduleAutoSave();
                                }
                                await refreshLogPanel();
                            }
                            catch (error) {
                                setStatus(error instanceof Error && error.message ? error.message : failedLabel);
                            }
                            finally {
                                saveInFlight = false;
                                form.dataset.workspaceSaving = '0';
                                if (saveButton instanceof HTMLButtonElement) {
                                    saveButton.disabled = false;
                                }
                                if (pendingSave && textarea.value !== lastSavedValue) {
                                    pendingSave = false;
                                    setStatus(dirtyLabel);
                                    scheduleAutoSave();
                                }
                                else {
                                    pendingSave = false;
                                }
                            }
                        };

                        const scheduleAutoSave = () => {
                            clearAutoSaveTimer();
                            if (!autoSaveInput || !autoSaveInput.checked || textarea.value === lastSavedValue) {
                                return;
                            }

                            autoSaveTimer = window.setTimeout(() => {
                                autoSaveTimer = null;
                                saveWorkspaceText();
                            }, autoSaveDelay);
                        };

                        textarea.addEventListener('input', () => {
                            if (saveInFlight) {
                                pendingSave = true;
                                return;
                            }

                            if (textarea.value === lastSavedValue) {
                                clearAutoSaveTimer();
                                setStatus(readyLabel);
                                return;
                            }

                            setStatus(dirtyLabel);
                            scheduleAutoSave();
                        });

                        saveButton?.addEventListener('click', event => {
                            event.preventDefault();
                            clearAutoSaveTimer();
                            saveWorkspaceText();
                        });

                        form.addEventListener('submit', event => {
                            event.preventDefault();
                            clearAutoSaveTimer();
                            saveWorkspaceText();
                        });

                        autoSaveInput?.addEventListener('change', () => {
                            if (textarea.value === lastSavedValue) {
                                clearAutoSaveTimer();
                                setStatus(readyLabel);
                                return;
                            }

                            if (autoSaveInput.checked) {
                                setStatus(dirtyLabel);
                                scheduleAutoSave();
                            }
                            else {
                                clearAutoSaveTimer();
                                setStatus(dirtyLabel);
                            }
                        });

                        updateLastSaved(initialLastSavedAt ? new Date(initialLastSavedAt) : null);
                        setStatus(readyLabel);
                    });
                }

                function newTabId() {
                    if (crypto && crypto.randomUUID) {
                        return crypto.randomUUID();
                    }

                    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, ch => {
                        const random = Math.floor(Math.random() * 16);
                        const value = ch === 'x' ? random : (random & 0x3) | 0x8;
                        return value.toString(16);
                    });
                }

                function findServer(serverId) {
                    return availableServers.find(server => server.id === serverId);
                }

                function orderedSessionTabs() {
                    return Array.from(tabsRoot.querySelectorAll('.session-tab[data-tab-id][data-tab-kind="connection"]'))
                        .map(tabButton => tabs.get(tabButton.getAttribute('data-tab-id') || ''))
                        .filter(Boolean);
                }

                function ui(key) {
                    return uiText[key] || key;
                }

                function isFileProtocol(protocol) {
                    // LOCAL is a file area on the gateway itself - same manager, same operations.
                    return ['SFTP', 'FTP', 'SMB', 'LOCAL', 'WEBDAV', 'AGENT'].includes((protocol || '').toUpperCase());
                }

                function isWebsiteProtocol(protocol) {
                    return (protocol || '').toUpperCase() === 'WEBSITE';
                }

                // A website whose render mode routes it through the browser-farm (opened as a VNC
                // session) instead of the native reverse-proxy tab.
                function isFarmWebsiteServer(server) {
                    return !!server
                        && isWebsiteProtocol(server.protocol)
                        && !!server.renderMode
                        && server.renderMode !== 'native';
                }

                function protocolLabel(protocol) {
                    switch ((protocol || '').toUpperCase()) {
                        case 'WEBSITE': return uiText.websiteBeta || 'Website (Beta)';
                        default: return protocol || '-';
                    }
                }

                function buildWebsiteTabUrl(serverId, tabId, sourceUrl = '') {
                    const fallbackUrl = `/website/${serverId}/${tabId}/proxy/`;
                    if (!sourceUrl) {
                        return fallbackUrl;
                    }

                    try {
                        const url = new URL(sourceUrl, window.location.origin);
                        if (url.origin !== window.location.origin) {
                            return fallbackUrl;
                        }

                        const tabSpecificMatch = url.pathname.match(/^\/website\/[^/]+\/[^/]+\/proxy\/?/i);
                        if (tabSpecificMatch) {
                            return `${url.origin}${url.pathname.replace(/^\/website\/[^/]+\/[^/]+\/proxy\/?/i, `/website/${serverId}/${tabId}/proxy/`)}${url.search}${url.hash}`;
                        }

                        const legacyMatch = url.pathname.match(/^\/website\/[^/]+\/proxy\/?/i);
                        if (legacyMatch) {
                            return `${url.origin}${url.pathname.replace(/^\/website\/[^/]+\/proxy\/?/i, `/website/${serverId}/${tabId}/proxy/`)}${url.search}${url.hash}`;
                        }
                    }
                    catch {
                        // Fall back to a clean proxy URL.
                    }

                    return fallbackUrl;
                }

                function buildWebsiteDisplayUrl(tab, sourceUrl = '') {
                    const fallbackUrl = tab.target || '';
                    if (!sourceUrl) {
                        return fallbackUrl;
                    }

                    try {
                        const url = new URL(sourceUrl, window.location.origin);
                        const proxyMatch = url.pathname.match(/^\/website\/[^/]+\/(?:([^/]+)\/)?proxy\/?(.*)$/i);
                        if (!proxyMatch) {
                            // On its way to another website: where it is going.
                            const wanted = /^\/website\/[^/]+\/[^/]+\/go$/i.test(url.pathname) ? url.searchParams.get('u') : '';
                            return wanted || (url.origin === window.location.origin ? fallbackUrl : sourceUrl);
                        }

                        // A browser tab has a frame per website; the page told which website this one shows.
                        const frameBase = tab.pathBrowse && tab.frameBases ? tab.frameBases[(proxyMatch[1] || '').toLowerCase()] : '';
                        const targetBase = new URL(frameBase || tab.target || fallbackUrl || window.location.origin, window.location.origin);
                        const relativePath = `${proxyMatch[2] || ''}${url.search}${url.hash}`;
                        return new URL(relativePath, targetBase).href;
                    }
                    catch {
                        // Fall back to the configured target URL.
                    }

                    return fallbackUrl || sourceUrl;
                }

                // Where a website tab's frame is, under Matgate's address. A page may pretend to lie at the root of
                // its website (the proxy's script gives it that path, see WebsiteProxyService): it knows better.
                function websiteFrameUrl(tab) {
                    const inner = tab.websiteUi.frame.contentWindow;
                    return typeof inner.__matgateRealUrl === 'function' ? inner.__matgateRealUrl() : inner.location.href;
                }

                // A page under a path that left for a root path - "/login", meant as its own - has landed on one
                // of Matgate's pages, inside the frame. Where the browser lets the page's script catch that jump
                // it never gets here; where it does not (Safari before 26.2), the shell does: the website is
                // shown as if it lay at the root from now on, and the frame goes where the page wanted to go.
                function rescueWebsiteFrame(tab) {
                    let inner = null;
                    let where = null;
                    try {
                        inner = tab.websiteUi.frame.contentWindow;
                        where = new URL(inner.location.href);
                    }
                    catch {
                        return false;
                    }

                    if (where.origin !== window.location.origin || /^\/website\//i.test(where.pathname) || typeof inner.__matgateRealUrl === 'function') {
                        return false;
                    }

                    const last = /^(?:https?:\/\/[^/]+)?(\/website\/[^/]+\/[^/]+)\/proxy\//i.exec(tab.currentUrl || '');
                    const now = Date.now();
                    tab.rootRescues = (tab.rootRescues || []).filter(at => now - at < 15000);
                    if (!last || tab.rootRescues.length >= 3) {
                        return false;
                    }

                    tab.rootRescues.push(now);
                    const target = `${last[1]}/proxy/${where.pathname.replace(/^\/+/, '')}${where.search}${where.hash}`;
                    fetch(`${last[1]}/state?root=1`, { method: 'POST', credentials: 'same-origin' })
                        .catch(() => { })
                        .then(() => {
                            if (tabs.has(tab.id)) {
                                tab.websiteUi.frame.src = target;
                            }
                        });
                    return true;
                }

                function updateWebsiteLocation(tabId, url, base = '') {
                    const tab = tabs.get(tabId);
                    if (!tab || !isWebsiteProtocol(tab.protocol)) {
                        return;
                    }

                    if (tab.pathBrowse) {
                        if (url === 'about:blank') {
                            return;
                        }

                        const frame = typeof url === 'string' ? url.match(/\/website\/[^/]+\/([^/]+)\/proxy(?:\/|$)/i) : null;
                        if (base && frame) {
                            tab.frameBases[frame[1].toLowerCase()] = base;
                        }
                    }

                    const nextProxyUrl = typeof url === 'string' && url.trim()
                        ? url.trim()
                        : tab.target || '';
                    const nextDisplayUrl = buildWebsiteDisplayUrl(tab, nextProxyUrl);

                    tab.currentUrl = nextProxyUrl;
                    tab.displayUrl = nextDisplayUrl;
                    // Not while someone is typing the next address into it.
                    if (tab.websiteUi?.address && !(tab.pathBrowse && document.activeElement === tab.websiteUi.address)) {
                        tab.websiteUi.address.value = nextDisplayUrl;
                    }

                    tab.lastSyncAt = Date.now();
                    tab.lastMessage = uiText.websiteLoaded || 'Website loaded';
                    markWebsiteAddress(tab);
                    updateStatusBar();
                }

                // The mark in a browser tab's address bar: a lock where the website is reached encrypted.
                function markWebsiteAddress(tab) {
                    const bar = tab && tab.websiteUi && tab.websiteUi.address ? tab.websiteUi.address.closest('.website-toolbar-address') : null;
                    if (bar) {
                        bar.classList.toggle('is-secure', /^https:/i.test(tab.displayUrl || ''));
                    }
                }

                function setStatus(tab, status) {
                    markWebsiteAddress(tab);
                    tab.status = status;
                    tab.statusUpdatedAt = Date.now();
                    tab.statusLabel.textContent = status;
                    updateStatusBar();
                }

                function setOverlay(tab, headline, text, showActions) {
                    tab.overlayTitle.textContent = headline;
                    tab.overlayMessage.textContent = text;
                    tab.lastMessage = text;
                    tab.overlayActions.classList.toggle('hidden', !showActions);
                    tab.overlay.classList.remove('hidden');
                    // A covering message means no keyboard should stay up over the session.
                    closeSessionKeyboards(tab);
                    updateStatusBar();
                }

                function hideOverlay(tab) {
                    tab.overlay.classList.add('hidden');
                }

                function isFullscreenActive() {
                    return Boolean(document.fullscreenElement
                        || document.webkitFullscreenElement
                        || document.mozFullScreenElement
                        || document.msFullscreenElement);
                }

                function requestFullscreen(element) {
                    if (!element) {
                        return Promise.reject(new Error('Fullscreen unavailable'));
                    }

                    const method = element.requestFullscreen
                        || element.webkitRequestFullscreen
                        || element.webkitEnterFullscreen
                        || element.mozRequestFullScreen
                        || element.msRequestFullscreen;

                    if (!method) {
                        return Promise.reject(new Error('Fullscreen unavailable'));
                    }

                    try {
                        const result = method.call(element);
                        return result && typeof result.then === 'function' ? result : Promise.resolve();
                    }
                    catch (error) {
                        return Promise.reject(error);
                    }
                }

                function exitFullscreen() {
                    const method = document.exitFullscreen
                        || document.webkitExitFullscreen
                        || document.webkitCancelFullScreen
                        || document.mozCancelFullScreen
                        || document.msExitFullscreen;

                    if (!method) {
                        return Promise.resolve();
                    }

                    try {
                        const result = method.call(document);
                        return result && typeof result.then === 'function' ? result : Promise.resolve();
                    }
                    catch (error) {
                        return Promise.reject(error);
                    }
                }

                async function toggleFullscreen(element) {
                    // "Immersive" (CSS) hides the header/tab list for maximum session space and works
                    // everywhere, incl. iOS Safari where the Fullscreen API is unavailable. We also try
                    // the real Fullscreen API where supported.
                    const goImmersive = !document.documentElement.classList.contains('session-immersive');
                    document.documentElement.classList.toggle('session-immersive', goImmersive);

                    if (goImmersive) {
                        // Flash the toolbar once on entry so the pull-tab is discoverable, then auto-hide.
                        flashImmersiveBar();
                    }
                    else {
                        closeImmersiveBar();
                    }

                    try {
                        if (goImmersive) {
                            if (!isFullscreenActive()) {
                                for (const candidate of [element, document.documentElement].filter(Boolean)) {
                                    try {
                                        await requestFullscreen(candidate);
                                        break;
                                    }
                                    catch {
                                        // Try the next candidate; immersive CSS applies regardless.
                                    }
                                }
                            }
                        }
                        else if (isFullscreenActive()) {
                            await exitFullscreen();
                        }
                    }
                    catch {
                        // Fullscreen API unavailable (e.g. iOS Safari) - immersive mode still applies.
                    }

                    scheduleResize();
                }

                // In fullscreen, capture browser-reserved shortcuts (Ctrl+T/W/N, Alt+Tab where allowed,
                // Escape) via the Keyboard Lock API so they reach the remote session for real isolation.
                function applyKeyboardLock() {
                    try {
                        if (!navigator.keyboard || typeof navigator.keyboard.lock !== 'function') {
                            return;
                        }

                        // Only grab the OS shortcuts when the user wants system combos passed through
                        // (Windows, Alt+Tab, Alt+F4, Escape, Ctrl+W...). Off -> those stay with the local OS.
                        if (isFullscreenActive() && sessionPrefs.systemCombos) {
                            navigator.keyboard.lock();
                        }
                        else if (typeof navigator.keyboard.unlock === 'function') {
                            navigator.keyboard.unlock();
                        }
                    }
                    catch {
                        // Keyboard Lock API unsupported or blocked; fullscreen still works without it.
                    }
                }
                document.addEventListener('fullscreenchange', applyKeyboardLock);
                document.addEventListener('webkitfullscreenchange', applyKeyboardLock);
                document.addEventListener('fullscreenchange', () => {
                    if (!isFullscreenActive()) {
                        document.documentElement.classList.remove('session-immersive');
                        closeImmersiveBar();
                    }
                    scheduleResize();
                });


                // --- Immersive toolbar reveal -----------------------------------------------------
                // In immersive/fullscreen the toolbar slides out of the way so the session fills the
                // screen. A fixed pull-tab (#immersive-handle) toggles it back in; a swipe down from the
                // very top edge does the same. It auto-hides after a few seconds of inactivity.
                const immersiveHandle = document.getElementById('immersive-handle');
                let immersiveBarTimer = null;

                function clearImmersiveBarTimer() {
                    if (immersiveBarTimer !== null) {
                        window.clearTimeout(immersiveBarTimer);
                        immersiveBarTimer = null;
                    }
                }

                function scheduleImmersiveBarHide() {
                    clearImmersiveBarTimer();
                    immersiveBarTimer = window.setTimeout(() => {
                        document.documentElement.classList.remove('immersive-bar-open');
                        immersiveBarTimer = null;
                        showImmersiveHint();
                    }, 6000);
                }

                // The first time the bar goes away after full screen was entered, a note says how it comes
                // back - on a phone nothing else on the screen gives that away.
                let immersiveHintDue = false;
                let immersiveHintTimer = null;
                function showImmersiveHint() {
                    if (!immersiveHintDue || !immersiveHandle || !isTouchDevice || !document.documentElement.classList.contains('session-immersive')) {
                        return;
                    }
                    immersiveHintDue = false;
                    let hint = document.getElementById('immersive-hint');
                    if (!hint) {
                        hint = document.createElement('div');
                        hint.id = 'immersive-hint';
                        hint.className = 'immersive-hint';
                        hint.setAttribute('role', 'status');
                        document.body.appendChild(hint);
                    }
                    hint.textContent = immersiveHandle.dataset.hint || '';
                    hint.classList.add('show');
                    window.clearTimeout(immersiveHintTimer);
                    immersiveHintTimer = window.setTimeout(() => hint.classList.remove('show'), 4500);
                }
                // From a page tab (a session of Matgate's own engine): three fingers tapped on the picture.
                // Touches inside that page never reach this document, so the page asks.
                window.MatgateToggleControls = () => {
                    if (!document.documentElement.classList.contains('session-immersive')) {
                        return false;
                    }
                    toggleImmersiveBar();
                    return true;
                };

                function openImmersiveBar() {
                    document.documentElement.classList.add('immersive-bar-open');
                    document.getElementById('immersive-hint')?.classList.remove('show');
                    scheduleImmersiveBarHide();
                }

                function closeImmersiveBar() {
                    clearImmersiveBarTimer();
                    document.documentElement.classList.remove('immersive-bar-open');
                    document.getElementById('immersive-hint')?.classList.remove('show');
                }

                function flashImmersiveBar() {
                    // Show briefly on entry, then let the auto-hide timer tuck it away.
                    immersiveHintDue = true;
                    openImmersiveBar();
                }

                function toggleImmersiveBar() {
                    if (document.documentElement.classList.contains('immersive-bar-open')) {
                        closeImmersiveBar();
                    }
                    else {
                        openImmersiveBar();
                    }
                }

                if (immersiveHandle) {
                    // Open on the first touch/press so a single tap is enough on every device - no precise
                    // swipe or click-delay to fight on iOS. touchstart is the most reliable on iOS Safari;
                    // pointerdown/click cover mouse + other browsers. The bar auto-hides again.
                    immersiveHandle.addEventListener('touchstart', event => {
                        event.preventDefault();
                        openImmersiveBar();
                    }, { passive: false });
                    immersiveHandle.addEventListener('pointerdown', event => {
                        event.preventDefault();
                        openImmersiveBar();
                    });
                    immersiveHandle.addEventListener('click', event => {
                        event.preventDefault();
                        openImmersiveBar();
                    });
                }

                // Keep the bar visible while the user is actually touching it.
                document.addEventListener('pointerdown', event => {
                    if (document.documentElement.classList.contains('immersive-bar-open')
                        && event.target instanceof Element
                        && event.target.closest('.shell-page-row')) {
                        scheduleImmersiveBarHide();
                    }
                }, true);

                // Swipe down from the top edge to reveal the bar (best-effort; the tab is the sure path).
                let edgeSwipeStartY = null;
                document.addEventListener('touchstart', event => {
                    if (document.documentElement.classList.contains('session-immersive')
                        && event.touches.length === 1
                        && event.touches[0].clientY <= 80) {
                        edgeSwipeStartY = event.touches[0].clientY;
                    }
                    else {
                        edgeSwipeStartY = null;
                    }
                }, { passive: true, capture: true });
                document.addEventListener('touchmove', event => {
                    if (edgeSwipeStartY !== null
                        && event.touches.length === 1
                        && event.touches[0].clientY - edgeSwipeStartY > 36) {
                        edgeSwipeStartY = null;
                        openImmersiveBar();
                    }
                }, { passive: true, capture: true });
                document.addEventListener('touchend', () => { edgeSwipeStartY = null; }, true);

                // Desktop (and any mouse): move the pointer to the very top edge to reveal the toolbar,
                // like a fullscreen video player - no need to aim for the small corner handle. It tucks
                // away again on the usual inactivity timer. Also keeps the bar open while hovering it.
                document.addEventListener('mousemove', event => {
                    if (!document.documentElement.classList.contains('session-immersive')) {
                        return;
                    }
                    if (event.clientY <= 6) {
                        openImmersiveBar();
                    }
                    else if (document.documentElement.classList.contains('immersive-bar-open')
                        && event.target instanceof Element
                        && event.target.closest('.shell-page-row')) {
                        scheduleImmersiveBarHide();
                    }
                }, { passive: true });

                // A session that was just (re)connected - or got a new size, which for RDP is a reconnect -
                // starts with its pointer in a corner of its own, and nothing tells it where the pointer was.
                // The cursor then sat in the top left until the next movement, and on a touch device the
                // next swipe set out from there. So the pointer is put back where it was (kept inside the new
                // size) - or, with nothing known yet on a touch device, in the middle, where a swipe can
                // carry on from.
                function restorePointer(tab) {
                    // Only desktops have a pointer to put back; a terminal has none.
                    if (!tab || !tab.client || tab.terminal || !supportsResolution(tab.protocol)) {
                        return;
                    }

                    const display = tab.client.getDisplay();
                    const width = display.getWidth();
                    const height = display.getHeight();
                    if (!width || !height) {
                        return;
                    }

                    if (tab.syncPointer && tab.syncPointer()) {
                        return;
                    }

                    const known = tab.lastPointer || (isTouchDevice ? { x: Math.floor(width / 2), y: Math.floor(height / 2) } : null);
                    if (!known) {
                        return;
                    }

                    tab.lastPointer = { x: Math.max(0, Math.min(width - 1, known.x)), y: Math.max(0, Math.min(height - 1, known.y)) };
                    tab.client.sendMouseState({ x: tab.lastPointer.x, y: tab.lastPointer.y, left: false, middle: false, right: false, up: false, down: false }, false);
                }

                // Send a right-click at the last known cursor position (touch cursor mode has no
                // native right-click gesture, so a toolbar button drives it).
                function sendRightClick(tab) {
                    if (!tab || !tab.client) {
                        return;
                    }
                    const p = tab.lastPointer || { x: 0, y: 0 };
                    const down = { x: p.x, y: p.y, left: false, middle: false, right: true, up: false, down: false };
                    const up = { x: p.x, y: p.y, left: false, middle: false, right: false, up: false, down: false };
                    // lastPointer is in remote pixels, so no display scale on top.
                    tab.client.sendMouseState(down, false);
                    window.setTimeout(() => {
                        try { tab.client.sendMouseState(up, false); } catch {}
                    }, 60);
                }

                // In-app on-screen keyboard for touch sessions: a browser-rendered keyboard that sends
                // X11 keysyms straight to the Guacamole client - an alternative to the device keyboard
                // that never touches the viewport. Shift is one-shot; Ctrl/Alt are one-shot modifiers.
                //
                // Two full layouts are offered (QWERTZ/German + QWERTY/US) with a live toggle key. The
                // layout is purely VISUAL: every key sends the keysym of the character it is labelled with,
                // so the remote types exactly that character regardless of the remote's own keymap. That
                // is also why "?" simply lives on the key it belongs to per layout (Shift+ß on QWERTZ,
                // Shift+/ on QWERTY). Special keys (Esc, Tab, arrows, Del, Strg+Alt+Entf) sit in the top
                // function row; Enter sits at the bottom-right like a physical keyboard.
                const oskCharToKeysym = ch => {
                    const cp = ch.codePointAt(0);
                    return cp < 0x100 ? cp : 0x01000000 + cp;
                };
                const OSK_COMBO_ICON = '<svg class="icon osk-combo-icon" viewBox="0 0 46 24" aria-hidden="true"><rect x="1.5" y="6" width="12" height="12" rx="2.5"/><rect x="17" y="6" width="12" height="12" rx="2.5"/><rect x="32.5" y="6" width="12" height="12" rx="2.5"/></svg>';
                // The special keys there were before the key bar could be configured. In a layout this row
                // only marks the place of the top row: what is shown there is the user's own key bar.
                const OSK_FN_ROW = [
                    { t: 'Esc', sym: 0xFF1B }, { t: 'Tab', sym: 0xFF09 },
                    { t: '←', sym: 0xFF51 }, { t: '↑', sym: 0xFF52 }, { t: '↓', sym: 0xFF54 }, { t: '→', sym: 0xFF53 },
                    { t: 'Entf', sym: 0xFFFF },
                    { html: OSK_COMBO_ICON, title: 'Strg + Alt + Entf', combo: true, cls: 'osk-combo' }
                ];
                const OSK_SHIFT = { t: '⇧', mod: 'shift', cls: 'osk-wide' };
                const OSK_BSP = { t: '⌫', sym: 0xFF08, cls: 'osk-wide' };
                const OSK_CTRL = { t: 'Strg', mod: 'ctrl' };
                const OSK_ALT = { t: 'Alt', mod: 'alt' };
                const OSK_LAYOUT_KEY = { toggleLayout: true, cls: 'osk-layout' };
                const OSK_SPACE = { t: 'Leertaste', sym: 0x20, cls: 'osk-space' };
                const OSK_ENTER = { t: '↵', sym: 0xFF0D, cls: 'osk-enter' };
                const OSK_LAYOUTS = {
                    de: {
                        label: 'DE',
                        rows: [
                            OSK_FN_ROW,
                            [ { c: '1', s: '!' }, { c: '2', s: '"' }, { c: '3', s: '§' }, { c: '4', s: '$' }, { c: '5', s: '%' }, { c: '6', s: '&' }, { c: '7', s: '/' }, { c: '8', s: '(' }, { c: '9', s: ')' }, { c: '0', s: '=' }, { c: 'ß', s: '?' }, OSK_BSP ],
                            [ 'q', 'w', 'e', 'r', 't', 'z', 'u', 'i', 'o', 'p', 'ü' ],
                            [ 'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'ö', 'ä' ],
                            [ OSK_SHIFT, 'y', 'x', 'c', 'v', 'b', 'n', 'm', { c: ',', s: ';' }, { c: '.', s: ':' }, { c: '-', s: '_' } ],
                            [ OSK_CTRL, OSK_ALT, OSK_LAYOUT_KEY, { c: '#', s: '\'' }, OSK_SPACE, { c: '+', s: '*' }, OSK_ENTER ]
                        ]
                    },
                    us: {
                        label: 'EN',
                        rows: [
                            OSK_FN_ROW,
                            [ { c: '1', s: '!' }, { c: '2', s: '@' }, { c: '3', s: '#' }, { c: '4', s: '$' }, { c: '5', s: '%' }, { c: '6', s: '^' }, { c: '7', s: '&' }, { c: '8', s: '*' }, { c: '9', s: '(' }, { c: '0', s: ')' }, { c: '-', s: '_' }, OSK_BSP ],
                            [ 'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', { c: '[', s: '{' } ],
                            [ 'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', { c: ';', s: ':' }, { c: '\'', s: '"' } ],
                            [ OSK_SHIFT, 'z', 'x', 'c', 'v', 'b', 'n', 'm', { c: ',', s: '<' }, { c: '.', s: '>' }, { c: '/', s: '?' } ],
                            [ OSK_CTRL, OSK_ALT, OSK_LAYOUT_KEY, { c: '=', s: '+' }, OSK_SPACE, { c: '\\', s: '|' }, OSK_ENTER ]
                        ]
                    }
                };
                // Optional F1-F12 row (per-user toggle), prepended to whichever layout is active.
                const OSK_FKEY_ROW = (() => {
                    const row = [];
                    for (let i = 1; i <= 12; i++) {
                        row.push({ t: 'F' + i, sym: 0xFFBD + i, cls: 'osk-fkey' });
                    }
                    return row;
                })();
                let oskLayout = (() => {
                    try { return localStorage.getItem('matgate-osk-layout') === 'us' ? 'us' : 'de'; }
                    catch { return 'de'; }
                })();

                function buildSessionOsk(tab) {
                    const osk = document.createElement('div');
                    osk.className = 'matgate-osk';
                    const state = { shift: false, ctrl: false, alt: false, win: false };
                    const MOD_SYMS = { ctrl: 0xFFE3, alt: 0xFFE9, shift: 0xFFE1, win: 0xFFEB };
                    let modButtons = {};
                    // The sticky buttons of the user's key bar: lit while all of their modifiers are held.
                    let ownSticky = [];
                    // Which of the user's buttons this session shows: those for terminals or those for desktops.
                    const ownScope = (tab.protocol || '').toUpperCase() === 'SSH' ? 'terminal' : 'screen';
                    const ownButtons = keyBarButtons.filter(button => button.scope === 'all' || button.scope === ownScope);

                    const applyShiftLabels = () => {
                        osk.querySelectorAll('[data-osk-cap]').forEach(el => {
                            el.textContent = state.shift ? el.getAttribute('data-osk-upper') : el.getAttribute('data-osk-lower');
                        });
                    };
                    const refreshMods = () => {
                        Object.keys(modButtons).forEach(name => modButtons[name].classList.toggle('active', !!state[name]));
                        ownSticky.forEach(entry => entry.btn.classList.toggle('active', entry.mods.every(name => state[name])));
                    };
                    const sendPress = keysym => {
                        if (!tab.client) {
                            return;
                        }
                        const held = [];
                        if (state.ctrl) {
                            held.push(0xFFE3);
                        }
                        if (state.alt) {
                            held.push(0xFFE9);
                        }
                        if (state.win) {
                            held.push(0xFFEB);
                        }
                        held.forEach(m => tab.client.sendKeyEvent(1, m));
                        tab.client.sendKeyEvent(1, keysym);
                        tab.client.sendKeyEvent(0, keysym);
                        held.slice().reverse().forEach(m => tab.client.sendKeyEvent(0, m));
                        if (state.ctrl || state.alt || state.win) {
                            state.ctrl = false;
                            state.alt = false;
                            state.win = false;
                            refreshMods();
                        }
                    };
                    // A button of the user's key bar: its keys, together with whatever the keyboard holds.
                    const sendOwn = syms => {
                        if (!tab.client) {
                            return;
                        }
                        const held = Object.keys(MOD_SYMS).filter(name => state[name]).map(name => MOD_SYMS[name]).filter(sym => !syms.includes(sym));
                        const all = held.concat(syms);
                        all.forEach(sym => tab.client.sendKeyEvent(1, sym));
                        all.slice().reverse().forEach(sym => tab.client.sendKeyEvent(0, sym));
                        Object.keys(MOD_SYMS).forEach(name => {
                            state[name] = false;
                        });
                        applyShiftLabels();
                        refreshMods();
                    };
                    const pressOwn = async button => {
                        if (button.sticky) {
                            const on = !button.mods.every(name => state[name]);
                            button.mods.forEach(name => {
                                state[name] = on;
                            });
                            applyShiftLabels();
                            refreshMods();
                            return;
                        }
                        if (button.action === 'paste') {
                            // What is on this device's clipboard goes along; without access to it the keys go alone.
                            let clip = '';
                            try {
                                clip = await readBrowserClipboard();
                            }
                            catch {
                                clip = '';
                            }
                            if (clip && (ownScope === 'terminal' || sessionPrefs.pasteAsKeystrokes)) {
                                // A terminal has no clipboard it would paste from: the text is typed.
                                typeTextToRemote(tab, clip);
                                return;
                            }
                            if (clip) {
                                tab.lastSentClipboard = clip;
                                sendClipboardText(tab, clip, true);
                                // The remote clipboard first, then the keys that paste from it.
                                window.setTimeout(() => sendOwn(button.syms), 150);
                                return;
                            }
                        }
                        sendOwn(button.syms);
                    };
                    const sendCombo = syms => {
                        if (!tab.client) {
                            return;
                        }
                        syms.forEach(s => tab.client.sendKeyEvent(1, s));
                        syms.slice().reverse().forEach(s => tab.client.sendKeyEvent(0, s));
                    };

                    const renderLayout = () => {
                        osk.replaceChildren();
                        modButtons = {};
                        const layout = OSK_LAYOUTS[oskLayout] || OSK_LAYOUTS.de;
                        ownSticky = [];
                        const ownRow = ownButtons.map(button => ({ t: button.label, title: button.title, own: button, cls: 'osk-own' }));
                        // Someone who removed every button has no top row.
                        const laid = layout.rows.map(row => row === OSK_FN_ROW ? ownRow : row).filter(row => row.length);
                        const rows = sessionPrefs.functionKeys ? [OSK_FKEY_ROW, ...laid] : laid;
                        rows.forEach(row => {
                            const rowEl = document.createElement('div');
                            rowEl.className = 'matgate-osk-row' + (row === ownRow ? ' osk-own-row' : '');
                            row.forEach(def => {
                                const key = typeof def === 'string' ? { c: def } : def;
                                const btn = document.createElement('button');
                                btn.type = 'button';
                                btn.className = 'matgate-osk-key' + (key.cls ? ' ' + key.cls : '');
                                if (key.toggleLayout) {
                                    btn.textContent = layout.label;
                                    btn.title = 'Tastaturlayout wechseln (QWERTZ / QWERTY)';
                                    btn.setAttribute('aria-label', btn.title);
                                }
                                else if (key.c !== undefined) {
                                    const upper = key.s !== undefined ? key.s : key.c.toUpperCase();
                                    btn.setAttribute('data-osk-cap', '1');
                                    btn.setAttribute('data-osk-lower', key.c);
                                    btn.setAttribute('data-osk-upper', upper);
                                    btn.textContent = state.shift ? upper : key.c;
                                }
                                else if (key.html !== undefined) {
                                    btn.innerHTML = key.html;
                                    if (key.title) {
                                        btn.title = key.title;
                                        btn.setAttribute('aria-label', key.title);
                                    }
                                }
                                else {
                                    btn.textContent = key.t;
                                    if (key.title) {
                                        btn.title = key.title;
                                    }
                                }
                                if (key.mod) {
                                    modButtons[key.mod] = btn;
                                }
                                if (key.own) {
                                    btn.dataset.id = key.own.id;
                                    if (key.own.sticky) {
                                        ownSticky.push({ btn, mods: key.own.mods });
                                    }
                                }
                                // The tap's end must not move the focus either: on a phone that closes the device
                                // keyboard. The key itself is pressed on pointerdown, below.
                                btn.addEventListener('touchend', event => event.preventDefault(), { passive: false });
                                btn.addEventListener('pointerdown', event => {
                                    event.preventDefault();
                                    if (key.toggleLayout) {
                                        oskLayout = oskLayout === 'de' ? 'us' : 'de';
                                        try { localStorage.setItem('matgate-osk-layout', oskLayout); }
                                        catch { /* private mode: keep the choice for this session only */ }
                                        renderLayout();
                                        return;
                                    }
                                    if (key.own) {
                                        pressOwn(key.own);
                                        return;
                                    }
                                    if (key.mod) {
                                        state[key.mod] = !state[key.mod];
                                        if (key.mod === 'shift') {
                                            applyShiftLabels();
                                        }
                                        refreshMods();
                                        return;
                                    }
                                    if (key.combo) {
                                        sendCombo([0xFFE3, 0xFFE9, 0xFFFF]);
                                        return;
                                    }
                                    if (key.sym !== undefined) {
                                        sendPress(key.sym);
                                        return;
                                    }
                                    const ch = state.shift ? (key.s !== undefined ? key.s : key.c.toUpperCase()) : key.c;
                                    sendPress(oskCharToKeysym(ch));
                                    if (state.shift) {
                                        state.shift = false;
                                        applyShiftLabels();
                                        refreshMods();
                                    }
                                });
                                rowEl.appendChild(btn);
                            });
                            osk.appendChild(rowEl);
                        });
                        refreshMods();
                    };

                    renderLayout();
                    return osk;
                }

                function toggleSessionOsk(tab, button) {
                    if (!tab || !tab.client) {
                        return;
                    }
                    if (!tab.osk) {
                        tab.osk = buildSessionOsk(tab);
                        tab.panel.appendChild(tab.osk);
                    }
                    const open = tab.osk.classList.toggle('open');
                    if (button) {
                        button.classList.toggle('active', open);
                    }
                    // Opening the in-app keyboard must not also raise the device keyboard.
                    if (open && tab.oskInput && tab.deviceKbOpen) {
                        tab.oskInput.blur();
                    }
                    // Slide the remote view up so the last-tapped spot stays above the in-app keyboard
                    // (the panel has a slide-in transition, so re-check after it settles too).
                    updateSessionKeyboardShift();
                    window.setTimeout(updateSessionKeyboardShift, 230);
                }

                // Force both soft keyboards down. Called whenever the session gets covered by an overlay
                // (disconnect, error, "opening", credentials submitted, ...): once the tab is terminal its
                // toolbar keyboard buttons are gone, so a still-open device keyboard or in-app on-screen
                // keyboard would float over the dead session with no way to dismiss it.
                function closeSessionKeyboards(tab) {
                    if (!tab) {
                        return;
                    }
                    // Device (OS) keyboard: blurring the hidden input dismisses it and, via the input's
                    // own blur handler, resets tab.deviceKbOpen + the toolbar highlight.
                    if (tab.oskInput) {
                        try { tab.oskInput.blur(); }
                        catch { /* input already detached */ }
                    }
                    // In-app on-screen keyboard panel + its toolbar button highlight.
                    if (tab.osk) {
                        tab.osk.classList.remove('open');
                    }
                    if (tab.oskButton) {
                        tab.oskButton.classList.remove('active');
                    }
                    // Drop any keyboard-avoidance shift so the remote view isn't left translated (the
                    // normal shift updater bails out once the tab is terminal, so reset it directly).
                    if (tab.displayRoot && tab.keyboardShift) {
                        tab.displayRoot.style.transform = '';
                        tab.keyboardShift = 0;
                    }
                    updateSessionKeyboardShift();
                }

                // A button that is being pressed must still be there when the press ends. The row below is built
                // anew whenever a session says that something changed - and pressing a button IS such a change:
                // the picture loses the cursor. The button under the pointer was replaced between "down" and
                // "up", the click went to nobody, and one had to press twice. While a press on the row (or on
                // its "..." panel) lasts, the rebuild waits.
                let tabActionsHeld = false;
                let tabActionsStale = false;
                let tabActionsHeldTimer = 0;
                function releaseTabActions() {
                    window.clearTimeout(tabActionsHeldTimer);
                    if (!tabActionsHeld) {
                        return;
                    }

                    tabActionsHeld = false;
                    if (tabActionsStale) {
                        tabActionsStale = false;
                        updateTabActions();
                    }
                }
                document.addEventListener('pointerdown', event => {
                    const target = event.target instanceof Element ? event.target : null;
                    if (!target || !target.closest('#connection-tab-actions, .tab-action-overflow-panel')) {
                        return;
                    }

                    tabActionsHeld = true;
                    window.clearTimeout(tabActionsHeldTimer);
                    // A press that never ends (the pointer left the window) must not freeze the row.
                    tabActionsHeldTimer = window.setTimeout(releaseTabActions, 4000);
                }, true);
                // The click comes after "up", in the same breath: let it through first.
                ['pointerup', 'pointercancel'].forEach(name => document.addEventListener(name, () => {
                    if (tabActionsHeld) {
                        window.clearTimeout(tabActionsHeldTimer);
                        tabActionsHeldTimer = window.setTimeout(releaseTabActions, 60);
                    }
                }, true));

                // ---- The server manager -------------------------------------------------------------------
                // A panel on the left, for a wide screen: the connections by folder, a field to search them, a
                // mark at those with a session open. One click connects - or goes to the session that is
                // already open; the middle button (or Ctrl) opens another one; the right button brings the
                // menu the connection's card has on the start page. Whether it is shown, and which folders
                // are closed, is kept in this browser.
                const serverManager = document.getElementById('server-manager');
                const serverManagerToggle = document.getElementById('server-manager-toggle');
                const serverManagerTree = document.getElementById('server-manager-tree');
                const serverManagerFilter = document.getElementById('server-manager-filter');
                const serverManagerStore = {
                    read(key, fallback) {
                        try {
                            const value = window.localStorage.getItem('matgate.serverManager.' + key);
                            return value === null ? fallback : JSON.parse(value);
                        }
                        catch {
                            return fallback;
                        }
                    },
                    write(key, value) {
                        try {
                            window.localStorage.setItem('matgate.serverManager.' + key, JSON.stringify(value));
                        }
                        catch {
                            // No storage: then it is not remembered.
                        }
                    }
                };
                let serverManagerShown = '';
                // The sessions that are open for a connection: tabs of Guacamole and of the file manager, and
                // the pages of Matgate's own engine.
                function sessionsOfServer(serverId) {
                    const found = [];
                    for (const tab of tabs.values()) {
                        if (tab.serverId === serverId) {
                            found.push({ id: tab.id, kind: 'connection', active: tab.id === activeTabId });
                        }
                    }

                    shellTabs.forEach(shellTab => {
                        const screen = agentScreenOf(shellTab);
                        const url = String(shellTab.url || (shellTab.iframe && shellTab.iframe.getAttribute('src')) || '');
                        if ((screen && screen.serverId === serverId) || url.indexOf('/' + serverId + '/') >= 0) {
                            found.push({ id: shellTab.id, kind: 'page', active: !activeTabId && shellTab.id === activeShellTabId });
                        }
                    });
                    return found;
                }
                // The grip a connection is dragged by (with a finger; the mouse takes the whole row).
                function dragGrip() {
                    return '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg>';
                }
                function renderServerManager(force = false) {
                    if (!serverManager || serverManager.hidden) {
                        return;
                    }

                    const wanted = (serverManagerFilter.value || '').trim().toLowerCase();
                    const closed = serverManagerStore.read('closed', []);
                    const byName = (a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' });
                    // The user's own order (dragged) first, the rest by name.
                    const orderIndex = new Map((sidebarData.order || []).map((id, index) => [id, index]));
                    const byOrder = (a, b) => {
                        const left = orderIndex.has(a.id) ? orderIndex.get(a.id) : Number.MAX_SAFE_INTEGER;
                        const right = orderIndex.has(b.id) ? orderIndex.get(b.id) : Number.MAX_SAFE_INTEGER;
                        return left - right || byName(a, b);
                    };
                    const matches = text => !wanted || String(text).toLowerCase().indexOf(wanted) >= 0;
                    const entryOf = server => {
                        const sessions = sessionsOfServer(server.id);
                        return {
                            id: server.id,
                            share: '',
                            page: '',
                            name: server.name || '',
                            note: server.target && server.target !== '-' ? server.target : '',
                            iconHtml: (server.iconHtml || '') + (server.signTag ? '<span class="server-icon-tag">' + escapeHtml(server.signTag) + '</span>' : ''),
                            color: server.protoColor || 'var(--accent)',
                            tip: [server.name, server.protocol, server.target].filter(Boolean).join(' · '),
                            open: sessions.length,
                            active: sessions.some(session => session.active)
                        };
                    };
                    const isPlace = server => String(server.protocol || '').toUpperCase() === 'LOCAL';
                    const connections = availableServers.filter(server => !server.areaKind && !isPlace(server) && !server.ephemeral && String(server.protocol || '').toUpperCase() !== 'WIREGUARD');
                    const byId = new Map(connections.map(server => [server.id, server]));
                    // The groups, from top to bottom. A group's key is what its closed state is remembered by:
                    // a folder's is its name, the others carry their kind in front.
                    const groups = [];
                    const add = (key, kind, name, iconHtml, entries, more = {}) => {
                        if (entries.length || more.keep) {
                            groups.push({ key, kind, name, iconHtml, closed: !wanted && closed.indexOf(key) >= 0, entries, depth: more.depth || 0, count: more.count ?? entries.length, hidden: !!more.hidden });
                        }
                    };
                    // A search goes through every connection once: the favourites and what was used last are
                    // the same connections a second time.
                    if (!wanted) {
                        add('favorites:', 'favorites', uiText.managerFavorites || 'Favorites', fileIcon('star'),
                            (sidebarData.favorites || []).map(id => byId.get(id)).filter(Boolean).sort(byOrder).map(entryOf));
                        add('recent:', 'recent', uiText.managerRecent || 'Recently used', fileIcon('clock'),
                            (sidebarData.recent || []).map(id => byId.get(id)).filter(Boolean).map(entryOf));
                    }

                    // The folders as a tree: a "/" in a folder's name makes a subfolder ("Lab/Linux" lies in
                    // "Lab"). A folder shows its subfolders first, then its connections; its number counts
                    // everything under it. A shut folder hides all of that.
                    const folderNode = path => ({ path, children: new Map(), servers: [] });
                    const root = folderNode('');
                    const unfiledServers = [];
                    // The folders that exist on their own: there also while empty (not in a search).
                    const ensureFolder = path => {
                        let node = root;
                        String(path || '').split('/').map(part => part.trim()).filter(Boolean).forEach((part, index, parts) => {
                            const key = part.toLowerCase();
                            if (!node.children.has(key)) {
                                node.children.set(key, Object.assign(folderNode(parts.slice(0, index + 1).join('/')), { name: part }));
                            }
                            node = node.children.get(key);
                        });
                    };
                    if (!wanted) {
                        (sidebarData.folders || []).forEach(ensureFolder);
                    }
                    connections
                        .filter(server => matches([server.name, server.target, server.folder, server.protocol].join(' ')))
                        .forEach(server => {
                            const parts = String(server.folder || '').split('/').map(part => part.trim()).filter(Boolean);
                            if (!parts.length) {
                                unfiledServers.push(server);
                                return;
                            }

                            let node = root;
                            parts.forEach((part, index) => {
                                const key = part.toLowerCase();
                                if (!node.children.has(key)) {
                                    node.children.set(key, Object.assign(folderNode(parts.slice(0, index + 1).join('/')), { name: part }));
                                }

                                node = node.children.get(key);
                            });
                            node.servers.push(server);
                        });
                    const countOf = node => node.servers.length + Array.from(node.children.values()).reduce((sum, child) => sum + countOf(child), 0);
                    const walk = (node, depth, hidden) => {
                        Array.from(node.children.values())
                            .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }))
                            .forEach(child => {
                                const shut = !wanted && closed.indexOf(child.path) >= 0;
                                add(child.path, 'folder', child.name, fileIcon('folder'), child.servers.slice().sort(byOrder).map(entryOf), { keep: true, depth, count: countOf(child), hidden });
                                walk(child, depth + 1, hidden || shut);
                            });
                    };
                    walk(root, 0, false);
                    // Those without a folder come last, under "No folder" - or, where nobody made a folder,
                    // under what they are.
                    add('', 'folder', (root.children.size ? uiText.managerNoFolder : uiText.managerTitle) || 'No folder', fileIcon('folder'),
                        unfiledServers.slice().sort(byOrder).map(entryOf));
                    // The places of the file manager - without a session's folder, which is reached through
                    // its session, and without a share's, which stands under the shares.
                    add('places:', 'places', uiText.managerPlaces || 'Places', fileIcon('folder'),
                        availableServers
                            .filter(server => isPlace(server) && server.areaKind !== 'session' && server.areaKind !== 'workspace' && !server.ephemeral)
                            .filter(server => matches(server.name))
                            .map(entryOf));
                    // A share opens its place in the file manager; one without a place opens its page.
                    add('shares:', 'shares', uiText.managerShares || 'Shares', fileIcon('globe'),
                        (sidebarData.shares || [])
                            .filter(share => matches([share.name, share.note].join(' ')))
                            .map(share => {
                                const sessions = share.targetId ? sessionsOfServer(share.targetId) : [];
                                return {
                                    id: share.targetId || '',
                                    share: share.id,
                                    page: share.targetId ? '' : '/workspaces/' + share.id,
                                    name: share.name || '',
                                    note: share.note || uiText.managerShare || 'Share',
                                    iconHtml: fileIcon('globe'),
                                    color: 'var(--accent-2)',
                                    tip: share.name || '',
                                    open: sessions.length,
                                    active: sessions.some(session => session.active)
                                };
                            }));
                    // Built anew only when something it shows has changed: it is asked to on every change of a
                    // tab, and a row that is replaced under the pointer loses its click.
                    const signature = JSON.stringify(groups.map(group => [group.key, group.closed, group.hidden, group.count, group.entries.map(entry => [entry.id, entry.share, entry.name, entry.note, entry.open, entry.active])]));
                    if (!force && signature === serverManagerShown) {
                        return;
                    }

                    serverManagerShown = signature;
                    const nodes = [];
                    // Connections without a folder and nothing else: then the heading says nothing.
                    const lone = groups.length === 1 && groups[0].kind === 'folder' && groups[0].key === '';
                    const canEdit = serverManager.dataset.canEdit === '1';
                    groups.forEach(group => {
                        if (group.hidden) {
                            return;
                        }

                        if (!lone) {
                            const head = document.createElement('button');
                            head.type = 'button';
                            head.className = 'server-manager-folder server-manager-folder--' + group.kind + (group.closed ? ' closed' : '');
                            head.setAttribute('aria-expanded', group.closed ? 'false' : 'true');
                            head.dataset.folder = group.key;
                            head.dataset.kind = group.kind;
                            head.style.setProperty('--depth', group.depth);
                            head.innerHTML = `<span class="server-manager-caret" aria-hidden="true">${fileIcon('chevronDown')}</span><span class="server-manager-folder-icon" aria-hidden="true">${group.iconHtml}</span><span class="server-manager-folder-name">${escapeHtml(group.name)}</span><span class="server-manager-count">${group.count}</span>`;
                            nodes.push(head);
                        }

                        if (group.closed) {
                            return;
                        }

                        group.entries.forEach(entry => {
                            const row = document.createElement('button');
                            row.type = 'button';
                            row.className = 'server-manager-item' + (entry.active ? ' active' : '') + (entry.open ? ' open' : '') + (lone ? ' server-manager-item--flat' : '');
                            row.setAttribute('role', 'treeitem');
                            row.dataset.managerIn = group.kind;
                            row.style.setProperty('--depth', group.depth);
                            if (group.kind === 'folder') {
                                row.dataset.folderPath = group.key;
                            }

                            // A connection in a folder (or among the favourites) can be dragged: to another place in
                            // the user's own order, or - by someone who may change it - into another folder.
                            const sortable = !!entry.id && (group.kind === 'folder' || group.kind === 'favorites');
                            if (sortable) {
                                row.dataset.sortable = '1';
                            }

                            if (entry.id) {
                                row.dataset.managerServer = entry.id;
                            }
                            else {
                                row.dataset.managerPage = entry.page;
                            }

                            row.style.setProperty('--proto', entry.color);
                            row.title = entry.tip;
                            row.innerHTML = `<span class="server-manager-item-icon" aria-hidden="true">${entry.iconHtml}</span><span class="server-manager-item-text"><strong>${escapeHtml(entry.name)}</strong><small>${escapeHtml(entry.note)}</small></span>${entry.open ? `<span class="server-manager-dot" title="${escapeHtml(uiText.managerOpen || 'Session open')}">${entry.open > 1 ? entry.open : ''}</span>` : ''}${sortable ? `<span class="connection-grip server-manager-grip" aria-hidden="true">${dragGrip()}</span>` : ''}`;
                            nodes.push(row);
                        });
                    });
                    if (!nodes.length) {
                        const none = document.createElement('p');
                        none.className = 'muted server-manager-empty';
                        none.textContent = uiText.managerEmpty || 'No matches.';
                        nodes.push(none);
                    }

                    serverManagerTree.replaceChildren(...nodes);
                }
                // On a wide screen the panel stands beside the page, and whether it does is remembered - it is
                // there unless it was put away. On a narrow one it is a sheet over the page: it comes when
                // asked for and goes with the choice made in it, and nothing of that is remembered.
                const serverManagerNarrow = window.matchMedia('(max-width: 900px)');
                function setServerManagerOpen(open, remember = true) {
                    if (!serverManager) {
                        return;
                    }

                    serverManager.hidden = !open;
                    document.documentElement.toggleAttribute('data-server-manager', open);
                    if (serverManagerToggle) {
                        serverManagerToggle.classList.toggle('active', open);
                        serverManagerToggle.setAttribute('aria-pressed', open ? 'true' : 'false');
                    }

                    if (remember && !serverManagerNarrow.matches) {
                        serverManagerStore.write('open', open);
                    }

                    renderServerManager(true);
                    if (!serverManagerNarrow.matches) {
                        // The sessions beside it have a different width now.
                        window.dispatchEvent(new Event('resize'));
                    }
                }
                if (serverManager) {
                    const toggleServerManager = () => setServerManagerOpen(serverManager.hidden);
                    if (serverManagerToggle) {
                        serverManagerToggle.addEventListener('click', toggleServerManager);
                    }

                    // The same from the menu: in the compact view and on a phone the button is not there.
                    document.querySelectorAll('[data-server-manager-menu]').forEach(item => {
                        item.addEventListener('click', () => {
                            // The menu goes first: on a phone it is a sheet over everything, the panel's as well.
                            if (typeof window.MatgateCloseMenus === 'function') {
                                window.MatgateCloseMenus();
                            }

                            toggleServerManager();
                        });
                    });
                    serverManager.querySelectorAll('[data-server-manager-close]').forEach(button => {
                        button.addEventListener('click', () => setServerManagerOpen(false));
                    });
                    // The sheet goes when something beside it is pressed, with Escape, and when a link in it
                    // was followed.
                    const closeSheet = () => {
                        if (serverManagerNarrow.matches && !serverManager.hidden) {
                            setServerManagerOpen(false);
                        }
                    };
                    document.addEventListener('pointerdown', event => {
                        const target = event.target instanceof Element ? event.target : null;
                        if (target && !target.closest('#server-manager, [data-server-manager-menu], #server-manager-toggle')) {
                            closeSheet();
                        }
                    }, true);
                    document.addEventListener('keydown', event => {
                        if (event.key === 'Escape') {
                            closeSheet();
                        }
                    });
                    serverManager.addEventListener('click', event => {
                        if (event.target instanceof Element && event.target.closest('a[href]')) {
                            closeSheet();
                        }
                    });
                    // In the compact view as well: the panel is switched on its own, apart from the view.
                    const wantedOpen = () => !isPoppedWindow && !serverManagerNarrow.matches && serverManagerStore.read('open', true) === true;
                    // Into a folder ("" = none; "Lab/Linux" = a subfolder). The list is read anew either way: a
                    // refusal leaves the connection where it was.
                    const moveToFolder = async (serverId, folder) => {
                        const body = new FormData();
                        body.append('folder', folder || '');
                        try {
                            await fetch('/api/servers/' + encodeURIComponent(serverId) + '/folder', {
                                method: 'POST',
                                body,
                                credentials: 'same-origin',
                                headers: { 'X-Matgate-Csrf': csrfToken }
                            });
                        }
                        catch {
                            // No connection to the gateway: the list stays as it was.
                        }

                        // The folder it went into is opened, so the connection is seen where it landed.
                        const parts = String(folder || '').split('/');
                        const opened = parts.map((part, index) => parts.slice(0, index + 1).join('/'));
                        serverManagerStore.write('closed', serverManagerStore.read('closed', []).filter(name => opened.indexOf(name) < 0));
                        await refreshConnectionsPanel();
                    };
                    // A new connection, with its folder already chosen: a folder exists while a connection lies in it.
                    const newConnectionIn = folder => openShellTab(
                        '/admin/servers/new?return=home' + (folder ? '&folder=' + encodeURIComponent(folder) : ''),
                        uiText.managerNew || 'New connection', fileIcon('plus'), folder || '');
                    const askFolderName = async (title, value, confirm, hint) => {
                        const name = await askForName({ title, label: uiText.managerFolder || 'Folder', value: value || '', confirm, hint, selectAll: true, work: entered => entered });
                        return name === null || name === undefined ? null : String(name).split('/').map(part => part.trim()).filter(Boolean).join('/');
                    };
                    window.MatgateSidePanel = {
                        set: open => setServerManagerOpen(open),
                        isOpen: () => !serverManager.hidden,
                        move: moveToFolder,
                        newIn: newConnectionIn,
                        // A folder made on its own, there also while empty.
                        createFolder: async name => {
                            const body = new FormData();
                            body.append('name', name);
                            try {
                                await fetch('/api/folders', { method: 'POST', body, credentials: 'same-origin', headers: { 'X-Matgate-Csrf': csrfToken } });
                            }
                            catch {
                                // No connection to the gateway: nothing made.
                            }
                            await refreshConnectionsPanel();
                        },
                        askFolderName,
                        canEdit: () => serverManager.dataset.canEdit === '1',
                        // May this user put this connection into another folder (Edit on it)?
                        canMove: id => (sidebarData.movable || []).indexOf(id) >= 0,
                        // The connections of a folder (or the favourites) that have a place in the user's own order.
                        orderedIn: head => {
                            const order = sidebarData.order || [];
                            const kind = head.dataset.kind;
                            const path = head.dataset.folder || '';
                            return availableServers
                                .filter(server => kind === 'favorites' ? (sidebarData.favorites || []).indexOf(server.id) >= 0 : (server.folder || '') === path)
                                .map(server => server.id)
                                .filter(id => order.indexOf(id) >= 0);
                        },
                        // Out of the user's own order: by name again.
                        resetOrder: async ids => {
                            sidebarData.order = (sidebarData.order || []).filter(id => ids.indexOf(id) < 0);
                            const body = new FormData();
                            body.append('ids', ids.join(','));
                            body.append('reset', '1');
                            await fetch('/api/order/connections', { method: 'POST', body, credentials: 'same-origin', headers: { 'X-Matgate-Csrf': csrfToken } }).catch(() => null);
                            await refreshConnectionsPanel();
                        },
                        setAllClosed: shut => {
                            const all = Array.from(serverManagerTree.querySelectorAll('.server-manager-folder')).map(head => head.dataset.folder);
                            serverManagerStore.write('closed', shut ? all : []);
                            renderServerManager(true);
                            if (shut) {
                                // Folders under shut ones were not drawn: shut them as well.
                                const more = Array.from(new Set(availableServers.map(server => server.folder || '').filter(Boolean)
                                    .flatMap(path => path.split('/').map((part, index, parts) => parts.slice(0, index + 1).join('/')))));
                                serverManagerStore.write('closed', Array.from(new Set(all.concat(more))));
                                renderServerManager(true);
                            }
                        }
                    };

                    // ---- Dragging connections - in the side panel and on the start page. Dropped between two
                    // connections, it goes there in the user's OWN order (nobody else's changes); dropped into
                    // another folder (its heading, its tile on the start page, or a connection in it), it moves
                    // there - for everyone, so only for whoever may change it. Pointer events, not the browser's
                    // drag and drop: that one never starts on an iPhone or iPad. The mouse takes the whole row or
                    // card (after a few pixels, so a click stays a click); a finger takes the grip, so the rest
                    // still scrolls.
                    const saveConnectionOrder = ids => {
                        // At once here - the same merge as on the gateway (EndpointMapping.MergeOrder) - then there.
                        const members = new Set(ids);
                        const current = (sidebarData.order || []).slice();
                        const at = current.findIndex(id => members.has(id));
                        const rest = current.filter(id => !members.has(id));
                        const insertAt = at < 0 ? rest.length : current.slice(0, at).filter(id => !members.has(id)).length;
                        rest.splice(insertAt, 0, ...ids);
                        sidebarData.order = rest;
                        const body = new FormData();
                        body.append('ids', ids.join(','));
                        return fetch('/api/order/connections', { method: 'POST', body, credentials: 'same-origin', headers: { 'X-Matgate-Csrf': csrfToken } }).catch(() => null);
                    };
                    const mayMove = id => (sidebarData.movable || []).indexOf(id) >= 0;
                    let connectionDrag = null;
                    let connectionDragEnded = 0;
                    // iOS takes a finger that moves for scrolling, whatever the pointer events say: while a connection is
                    // held by its grip, the page does not move.
                    document.addEventListener('touchmove', event => {
                        if (connectionDrag) {
                            event.preventDefault();
                        }
                    }, { passive: false });
                    function makeConnectionsDraggable(spec) {
                        const indicator = document.createElement('div');
                        indicator.className = 'connection-drop-line';
                        indicator.hidden = true;
                        const clearTargets = () => document.querySelectorAll('.connection-drop-target').forEach(node => node.classList.remove('connection-drop-target'));
                        const finish = () => {
                            const drag = connectionDrag;
                            connectionDrag = null;
                            indicator.hidden = true;
                            clearTargets();
                            if (drag) {
                                drag.item.classList.remove('connection-dragging');
                                if (drag.ghost) {
                                    drag.ghost.remove();
                                }
                                document.documentElement.classList.remove('connection-drag-active');
                            }
                            return drag;
                        };
                        spec.root.addEventListener('pointerdown', event => {
                            if (event.button !== 0 || connectionDrag) {
                                return;
                            }
                            const target = event.target instanceof Element ? event.target : null;
                            const item = target ? target.closest(spec.item) : null;
                            if (!item || !spec.root.contains(item) || !spec.idOf(item)) {
                                return;
                            }
                            const grip = target.closest('.connection-grip');
                            if (!grip && (event.pointerType !== 'mouse' || (spec.ignore && target.closest(spec.ignore)))) {
                                return;
                            }
                            if (grip) {
                                // The finger is the grip's: no scrolling, no long press (its menu) underneath.
                                event.preventDefault();
                                event.stopPropagation();
                            }
                            connectionDrag = { spec, item, id: spec.idOf(item), pointerId: event.pointerId, x: event.clientX, y: event.clientY, started: false, drop: null };
                        });
                        document.addEventListener('pointermove', event => {
                            const drag = connectionDrag;
                            if (!drag || drag.spec !== spec || event.pointerId !== drag.pointerId) {
                                return;
                            }
                            if (!drag.started) {
                                if (Math.hypot(event.clientX - drag.x, event.clientY - drag.y) < 6) {
                                    return;
                                }
                                drag.started = true;
                                const box = drag.item.getBoundingClientRect();
                                drag.dx = drag.x - box.left;
                                drag.dy = drag.y - box.top;
                                drag.ghost = drag.item.cloneNode(true);
                                drag.ghost.classList.add('connection-drag-ghost');
                                // On the element itself: a card's own rules would otherwise put it back into the flow -
                                // and under the pointer it must never be what the pointer finds.
                                Object.assign(drag.ghost.style, { width: box.width + 'px', height: box.height + 'px', position: 'fixed', left: '0', top: '0', margin: '0', pointerEvents: 'none', zIndex: '60' });
                                document.body.appendChild(drag.ghost);
                                if (!indicator.isConnected) {
                                    document.body.appendChild(indicator);
                                }
                                drag.item.classList.add('connection-dragging');
                                document.documentElement.classList.add('connection-drag-active');
                            }
                            event.preventDefault();
                            drag.ghost.style.transform = `translate(${event.clientX - drag.dx}px, ${event.clientY - drag.dy}px)`;
                            clearTargets();
                            indicator.hidden = true;
                            drag.drop = null;
                            const under = document.elementFromPoint(event.clientX, event.clientY);
                            const over = under ? under.closest(spec.item) : null;
                            if (over && over !== drag.item && spec.root.contains(over) && spec.idOf(over)) {
                                const box = over.getBoundingClientRect();
                                const horizontal = !!spec.horizontal && spec.horizontal(over);
                                const before = horizontal ? event.clientX < box.left + box.width / 2 : event.clientY < box.top + box.height / 2;
                                drag.drop = { kind: 'item', over, before };
                                indicator.hidden = false;
                                indicator.classList.toggle('vertical', horizontal);
                                if (horizontal) {
                                    Object.assign(indicator.style, { left: ((before ? box.left : box.right) - 2) + 'px', top: box.top + 'px', width: '3px', height: box.height + 'px' });
                                }
                                else {
                                    Object.assign(indicator.style, { left: box.left + 'px', top: ((before ? box.top : box.bottom) - 1) + 'px', width: box.width + 'px', height: '3px' });
                                }
                                return;
                            }
                            const folder = under ? under.closest(spec.folder) : null;
                            if (folder && spec.folderPathOf(folder) !== null) {
                                drag.drop = { kind: 'folder', path: spec.folderPathOf(folder) };
                                folder.classList.add('connection-drop-target');
                            }
                        }, { passive: false });
                        const release = async event => {
                            const drag = connectionDrag;
                            if (!drag || drag.spec !== spec || event.pointerId !== drag.pointerId) {
                                return;
                            }
                            finish();
                            if (!drag.started) {
                                return;
                            }
                            connectionDragEnded = Date.now();
                            if (event.type === 'pointercancel' || !drag.drop) {
                                return;
                            }
                            const server = availableServers.find(candidate => candidate.id === drag.id);
                            const from = server ? (server.folder || '') : '';
                            let folder = null;
                            let ids = null;
                            if (drag.drop.kind === 'item') {
                                const group = spec.groupOf(drag.drop.over);
                                const fromGroup = spec.groupOf(drag.item);
                                folder = group === fromGroup ? null : spec.folderOfItem(drag.drop.over);
                                if (group !== fromGroup && folder === null) {
                                    // Into the favourites from a folder (or the other way round): nothing to do there.
                                    return;
                                }
                                ids = spec.itemsOf(group, drag.drop.over).filter(node => node !== drag.item).map(spec.idOf);
                                const at = ids.indexOf(spec.idOf(drag.drop.over));
                                ids.splice(drag.drop.before ? at : at + 1, 0, drag.id);
                            }
                            else {
                                folder = drag.drop.path;
                            }
                            if (folder !== null && folder !== from) {
                                if (!mayMove(drag.id)) {
                                    spec.say(uiText.dragNoMove || 'Only whoever may change this connection can put it into another folder.');
                                    return;
                                }
                                await moveToFolder(drag.id, folder);
                            }
                            if (ids) {
                                await saveConnectionOrder(ids);
                            }
                            await refreshConnectionsPanel();
                        };
                        document.addEventListener('pointerup', release);
                        document.addEventListener('pointercancel', release);
                        // The click that ends a drag opens nothing; nor does a long press open a menu meanwhile.
                        spec.root.addEventListener('click', event => {
                            if (Date.now() - connectionDragEnded < 400) {
                                event.preventDefault();
                                event.stopPropagation();
                            }
                        }, true);
                        spec.root.addEventListener('contextmenu', event => {
                            if (connectionDrag && connectionDrag.started) {
                                event.preventDefault();
                                event.stopPropagation();
                            }
                        }, true);
                    }
                    const sayInPanel = message => {
                        let note = serverManager.querySelector('.server-manager-note');
                        if (!note) {
                            note = document.createElement('p');
                            note.className = 'server-manager-note';
                            note.setAttribute('role', 'status');
                            serverManager.insertBefore(note, serverManagerTree);
                        }
                        note.textContent = message;
                        note.hidden = false;
                        window.clearTimeout(note.timer);
                        note.timer = window.setTimeout(() => { note.hidden = true; }, 6000);
                    };
                    makeConnectionsDraggable({
                        root: serverManagerTree,
                        item: '.server-manager-item[data-sortable="1"]',
                        folder: '.server-manager-folder[data-kind="folder"]',
                        idOf: row => row.dataset.managerServer || '',
                        groupOf: row => row.dataset.managerIn + ':' + (row.dataset.folderPath || ''),
                        folderOfItem: row => row.dataset.managerIn === 'folder' ? (row.dataset.folderPath || '') : null,
                        folderPathOf: head => head.dataset.folder,
                        itemsOf: group => Array.from(serverManagerTree.querySelectorAll('.server-manager-item[data-sortable="1"]')).filter(row => row.dataset.managerIn + ':' + (row.dataset.folderPath || '') === group),
                        say: sayInPanel
                    });
                    // The start page's connection cards (wherever the start page is shown - it is rebuilt now and
                    // then, so it is found anew on every drag).
                    const homeRoot = document.querySelector('.app-view') || document.body;
                    makeConnectionsDraggable({
                        root: homeRoot,
                        item: '[data-home2-all] .home2-card-grid .connection-choice[data-card-server]:not([data-card-server=""])',
                        folder: '.home2-folder-tile[data-folder-path]',
                        ignore: 'button, a, input, select, textarea, form, label',
                        horizontal: () => true,
                        idOf: card => card.dataset.cardServer || '',
                        groupOf: card => card.dataset.fav === '1' ? 'favorites:' : 'folder:' + (card.dataset.folderPath || ''),
                        folderOfItem: card => card.dataset.fav === '1' ? null : (card.dataset.folderPath || ''),
                        folderPathOf: tile => tile.dataset.folderPath,
                        // The cards of the grid the card was dropped in (favourites and all connections; the grip shows only there).
                        itemsOf: (group, over) => Array.from((over && over.closest('.home2-card-grid') || homeRoot).querySelectorAll('.connection-choice[data-card-server]:not([data-card-server=""])')).filter(card => (card.dataset.fav === '1' ? 'favorites:' : 'folder:' + (card.dataset.folderPath || '')) === group),
                        say: message => {
                            let note = document.querySelector('.connection-drag-note');
                            if (!note) {
                                note = document.createElement('div');
                                note.className = 'connection-drag-note';
                                note.setAttribute('role', 'status');
                                document.body.appendChild(note);
                            }
                            note.textContent = message;
                            note.hidden = false;
                            window.clearTimeout(note.timer);
                            note.timer = window.setTimeout(() => { note.hidden = true; }, 6000);
                        }
                    });
                    serverManagerNarrow.addEventListener('change', () => {
                        setServerManagerOpen(wantedOpen(), false);
                    });
                    serverManagerFilter.addEventListener('input', () => renderServerManager());
                    serverManagerFilter.addEventListener('keydown', event => {
                        if (event.key === 'Escape' && serverManagerFilter.value) {
                            serverManagerFilter.value = '';
                            renderServerManager();
                            event.stopPropagation();
                        }
                        else if (event.key === 'Enter') {
                            // Enter opens what the search leaves at the top.
                            const first = serverManagerTree.querySelector('[data-manager-server]');
                            if (first) {
                                first.click();
                            }
                        }
                    });
                    const openFromManager = (serverId, another) => {
                        const sessions = another ? [] : sessionsOfServer(serverId);
                        if (sessions.length) {
                            const session = sessions.find(item => item.active) || sessions[0];
                            if (session.kind === 'page') {
                                activateShellTab(session.id);
                            }
                            else {
                                activateTab(session.id);
                            }

                            return;
                        }

                        openServer(serverId, '', '', another);
                    };
                    serverManagerTree.addEventListener('click', event => {
                        const target = event.target instanceof Element ? event.target : null;
                        const folder = target ? target.closest('.server-manager-folder') : null;
                        if (folder) {
                            const closed = serverManagerStore.read('closed', []).filter(name => name !== folder.dataset.folder);
                            if (!folder.classList.contains('closed')) {
                                closed.push(folder.dataset.folder);
                            }

                            serverManagerStore.write('closed', closed);
                            renderServerManager();
                            return;
                        }

                        const row = target ? target.closest('.server-manager-item') : null;
                        if (!row) {
                            return;
                        }

                        if (row.dataset.managerServer) {
                            openFromManager(row.dataset.managerServer, event.ctrlKey || event.metaKey);
                        }
                        else if (row.dataset.managerPage) {
                            openShellTab(row.dataset.managerPage, ((row.querySelector('strong') || {}).textContent || '').trim(), fileIcon('globe'), '');
                        }

                        closeSheet();
                    });
                    serverManagerTree.addEventListener('auxclick', event => {
                        const row = event.button === 1 && event.target instanceof Element ? event.target.closest('[data-manager-server]') : null;
                        if (row) {
                            event.preventDefault();
                            openFromManager(row.dataset.managerServer, true);
                        }
                    });
                    setServerManagerOpen(wantedOpen(), false);
                }

                function updateTabActions() {
                    renderServerManager();
                    checkPoppedWindow();
                    if (!connectionTabActions) {
                        updateStatusBar();
                        return;
                    }

                    if (tabActionsHeld) {
                        tabActionsStale = true;
                        return;
                    }

                    connectionTabActions.replaceChildren();
                    const connectionTab = tabs.get(activeTabId);
                    const shellTab = connectionTab ? null : shellTabs.get(activeShellTabId) || null;
                    const tab = connectionTab || shellTab;
                    if (!tab) {
                        // No tab open means: the home page is at the front. There the bar carries the
                        // connections you put into it - one press connects, without the detour over
                        // the cards.
                        (Array.isArray(actionBarServers) ? actionBarServers : []).forEach(id => {
                            const server = availableServers.find(entry => entry.id === id);
                            if (!server) {
                                // Taken away or no longer shared - then the button is missing instead of
                                // pointing at nothing.
                                return;
                            }

                            const button = createTabActionButton(
                                server.iconHtml || '',
                                server.name || '',
                                () => openServer(server.id),
                                'tab-action-shortcut');
                            button.style.setProperty('--proto', server.protoColor || 'var(--accent)');
                            // Which connection is behind it - two of them may carry the same name.
                            button.dataset.serverId = server.id;
                            connectionTabActions.appendChild(button);
                        });
                        // On a narrow screen not all of them fit into the row - the rest moves into
                        // the three-dot menu, just like the actions of a session.
                        collapseConnectionActions(connectionTabActions);
                        updateStatusBar();
                        return;
                    }

                    if (connectionTab) {
                        const fullscreenButton = createTabActionButton(
                            actionIcons.fullscreen,
                            uiText.fullscreen || 'Fullscreen',
                            async () => {
                                try {
                                    await toggleFullscreen(document.documentElement);
                                    scheduleResize();
                                }
                                catch {
                                    // Ignore fullscreen failures on browsers with partial support.
                                }
                            },
                            'tab-action-keep',
                            true);

                        addTabAction('fullscreen', fullscreenButton);

                        // Pop the session out into its own window (or, in a popped window, hand it back
                        // to the main window). Moving a live session reconnects it in the target window.
                        if (isPoppedWindow) {
                            const reattachButton = createTabActionButton(
                                actionIcons.reattach,
                                uiText.reattachToMain || 'Re-attach to main window',
                                () => reattachTab(tab),
                                'tab-action-keep tab-action-reattach',
                                false);
                            addTabAction('reattach', reattachButton);
                        }
                        else {
                            const popOutButton = createTabActionButton(
                                actionIcons.popOut,
                                uiText.openInNewWindow || 'Open in a new window',
                                () => popOutTab(tab),
                                'tab-action-keep',
                                true);
                            addTabAction('popOut', popOutButton);
                        }

                        if (isTouchDevice && tab.client && !tab.terminal) {
                            const pointerButton = createTabActionButton(
                                actionIcons.pointer,
                                pointerMode === 'touchpad' ? (uiText.pointerTouchpad || 'Touchpad pointer') : (uiText.pointerDirect || 'Direct touch'),
                                () => setPointerMode(pointerMode === 'touchpad' ? 'direct' : 'touchpad'),
                                pointerMode === 'touchpad' ? 'active' : '',
                                true);
                            addTabAction('pointer', pointerButton);

                            const rightClickButton = createTabActionButton(
                                actionIcons.rightClick,
                                uiText.rightClick || 'Right click',
                                () => sendRightClick(tab),
                                '',
                                true);
                            addTabAction('rightClick', rightClickButton);

                            if (tab.oskInput) {
                                const keyboardButton = createTabActionButton(
                                    actionIcons.keyboard,
                                    uiText.showKeyboard || 'Show/hide keyboard',
                                    () => {
                                        // Use the explicit state, NOT document.activeElement: on Android
                                        // the tap focuses this button first, which flipped the old check
                                        // and re-opened the keyboard, making it impossible to close.
                                        if (tab.deviceKbOpen) {
                                            tab.oskInput.blur();
                                        }
                                        else {
                                            // preventScroll: iOS pans the whole standalone app up to
                                            // "reveal" the (hidden) input and never pans back.
                                            tab.oskInput.focus({ preventScroll: true });
                                        }
                                        // Fallback in case neither visualViewport nor virtualKeyboard
                                        // fires promptly: re-evaluate the keyboard-avoidance shift.
                                        window.setTimeout(updateSessionKeyboardShift, 300);
                                    },
                                    'tab-action-keep',
                                    true);
                                // Don't let the tap steal focus from oskInput (Android would otherwise
                                // blur it before the handler runs, desyncing the toggle).
                                keyboardButton.addEventListener('mousedown', event => event.preventDefault());
                                keyboardButton.classList.toggle('active', !!tab.deviceKbOpen);
                                // The oskInput focus/blur listeners keep this button's highlight in
                                // sync (incl. system-side keyboard dismissals via geometrychange).
                                tab.keyboardButton = keyboardButton;
                                addTabAction('keyboard', keyboardButton);
                            }

                            const oskButton = createTabActionButton(
                                actionIcons.onScreenKeyboard,
                                uiText.onScreenKeyboard || 'Show/hide on-screen keyboard',
                                () => toggleSessionOsk(tab, oskButton),
                                'tab-action-keep',
                                true);
                            oskButton.addEventListener('mousedown', event => event.preventDefault());
                            // Reflect the current panel state and keep a handle so closeSessionKeyboards()
                            // can clear the highlight when the session is covered by an overlay.
                            oskButton.classList.toggle('active', !!(tab.osk && tab.osk.classList.contains('open')));
                            tab.oskButton = oskButton;
                            addTabAction('osk', oskButton);
                        }

                        // Resolution / scale picker (+ zoom in fixed mode): on ALL devices, not just touch,
                        // so the fixed-resolution desktop mode and the per-user panning/stretch behaviours
                        // are reachable with a mouse too.
                        if (tab.client && !tab.terminal && supportsResolution(tab.protocol)) {
                            const resScaleOnly = isScaleOnlyTab(tab);
                            const resLabelWord = resScaleOnly ? (uiText.scaleLabel || 'Scale') : (uiText.resolutionLabel || 'Resolution');
                            const resolutionButton = createTabActionButton(
                                actionIcons.resolution,
                                `${resLabelWord}: ${resolutionOptionLabel(tab.displayRes, resScaleOnly)}`,
                                () => openResolutionDialog(),
                                isDesktopDisplayMode(tab) ? 'active' : '',
                                true);
                            addTabAction('resolution', resolutionButton);

                            // Auto-resize toggle, right next to the resolution button (fit modes on protocols
                            // that CAN renegotiate, i.e. RDP; not VNC/farm which have a fixed remote size).
                            // On (highlighted) = resize renegotiates the remote (sharp, RDP reconnects); off =
                            // the image stretches to fill on resize (no reconnect).
                            if (isFitMode(tab) && !tab.farmWebsite && !resScaleOnly) {
                                const autoResizeButton = createTabActionButton(
                                    actionIcons.autoResize,
                                    `${uiText.autoResize || 'Auto-resize'}: ${tab.autoResize ? (uiText.onLabel || 'On') : (uiText.offLabel || 'Off')}`,
                                    () => setAutoResize(!tab.autoResize),
                                    tab.autoResize ? 'active' : '',
                                    true);
                                addTabAction('autoResize', autoResizeButton);
                            }

                            if (isDesktopDisplayMode(tab)) {
                                const zoomOutButton = createTabActionButton(
                                    actionIcons.zoomOut,
                                    uiText.zoomOutLabel || 'Zoom out',
                                    () => adjustZoom(-0.25),
                                    '',
                                    true);
                                addTabAction('zoomOut', zoomOutButton);

                                const zoomInButton = createTabActionButton(
                                    actionIcons.zoomIn,
                                    uiText.zoomInLabel || 'Zoom in',
                                    () => adjustZoom(0.25),
                                    '',
                                    true);
                                addTabAction('zoomIn', zoomInButton);
                            }
                        }

                        if (tab.websiteUi) {
                            const copyUrl = toShareableUrl(tab.displayUrl || tab.currentUrl || tab.target || '');
                            if (copyUrl) {
                                const copyUrlButton = createTabActionButton(
                                    actionIcons.copy,
                                    uiText.copyUrlToClipboard || 'Copy URL to clipboard',
                                    async () => { await window.MatgateCopyText?.(copyUrl); },
                                    '',
                                    true);
                                addTabAction('copyUrl', copyUrlButton);
                            }
                        }

                        if (tab.client && !tab.terminal) {
                            const clipboardButton = createTabActionButton(
                                actionIcons.clipboard,
                                uiText.pasteToActiveTab || uiText.clipboard || 'Paste to active tab',
                                async () => {
                                    // The clipboard panel: what is on it, and what to do with it (as text, as a file, as a picture).
                                    if (window.MatgateOpenClipPanel) {
                                        window.MatgateOpenClipPanel();
                                        return;
                                    }
                                    try {
                                        const text = await readBrowserClipboard();
                                        if (text && pasteTextToRemote(tab, text)) {
                                            if (tab.id === activeTabId) {
                                                clipboardText.value = text;
                                            }
                                            return;
                                        }
                                    }
                                    catch {
                                        // Fall through to the manual dialog below.
                                    }

                                    openClipboardDialog(tab.remoteClipboard || '');
                                },
                                '',
                                true);
                            addTabAction('clipboard', clipboardButton);
                        }

                        // Ctrl+Alt+Del button: the Windows secure-attention sequence cannot be forwarded by
                        // any browser (the OS grabs it first), so it needs an explicit control. The other
                        // system combos (Windows, Alt+Tab, Alt+F4) are instead passed through automatically
                        // in fullscreen via the Keyboard Lock API (see applyKeyboardLock) - no button needed.
                        if (sessionPrefs.ctrlAltDelHotkey && tab.client && !tab.terminal
                            && !tab.websiteUi && (tab.protocol || '').toUpperCase() !== 'SSH') {
                            const cadButton = createTabActionButton(
                                actionIcons.systemKeys,
                                uiText.comboCtrlAltDel || 'Ctrl+Alt+Del',
                                () => sendSessionCombo(tab, [0xFFE3, 0xFFE9, 0xFFFF]),
                                '',
                                true);
                            addTabAction('cad', cadButton);
                        }

                        if (tab.filesystem && !tab.terminal) {
                            const uploadButton = createTabActionButton(
                                actionIcons.upload,
                                uiText.xferUpload || 'Send files to the session',
                                // The dialog comes first now, and the files are chosen inside it. That
                                // way picking a file and saying where it should go is one step, and on
                                // a phone the native picker no longer runs before anything is decided.
                                () => askForTargetFolder(tab, []),
                                '',
                                true);
                            addTabAction('upload', uploadButton);
                        }

                        // The connection's own file area, one tap away. Only offered when the user has
                        // that area at all - findServer only knows the areas they were given.
                        if (tab.fileAreaId && findServer(tab.fileAreaId)) {
                            const areaButton = createTabActionButton(
                                actionIcons.folder || actionIcons.upload,
                                uiText.openFileArea || 'Files for this connection',
                                () => openFileAreaDialog(tab.fileAreaId),
                                '',
                                true);
                            addTabAction('fileArea', areaButton);
                        }

                        // A Matgate agent says what it offers. Its programs (Claude Code, PowerShell, ...) open
                        // in a terminal tab of their own, started in the folder this file tab is showing.
                        if (isAgentTab(tab) && !tab.terminal) {
                            if (tab.agentStatus === undefined) {
                                tab.agentStatus = null;
                                fetch('/api/agent/' + encodeURIComponent(tab.serverId) + '/status', { credentials: 'same-origin' })
                                    .then(response => response.ok ? response.json() : null)
                                    .catch(() => null)
                                    .then(status => {
                                        tab.agentStatus = status || { online: false, plugins: [] };
                                        if (tab.id === activeTabId) {
                                            updateTabActions();
                                        }
                                    });
                            }

                            // The agent's own icon, always first: back to its start screen from the files - and in the
                            // overview a fresh look (a new version, a program that ended).
                            const overviewButton = createTabActionButton(
                                tab.iconHtml || actionIcons.home,
                                agentTexts.overview,
                                () => startAgentHome(tab),
                                'tab-action-keep tab-action-app',
                                true);
                            addTabAction('agent-overview', overviewButton);

                            // In the files the programs beside it.
                            if (tab.agentView === 'files') {
                                (tab.agentStatus && tab.agentStatus.plugins || [])
                                    .filter(plugin => plugin.kind === 'terminal')
                                    .forEach(plugin => {
                                        const programButton = createTabActionButton(
                                            actionIcons.terminal,
                                            plugin.title || plugin.id,
                                            () => openAgentTerminal(tab, plugin, tab.filePath || '/'),
                                            '');
                                        addTabAction('agent-' + plugin.id, programButton);
                                    });
                            }
                        }

                        const disconnectButton = createTabActionButton(
                            actionIcons.disconnect,
                            uiText.disconnect || 'Disconnect',
                            () => closeTab(tab.id),
                            'danger tab-action-disconnect');
                        addTabAction('disconnect', disconnectButton);
                        // Order first, then decide what still fits - so the actions the user put first
                        // are the ones that survive into the visible part of the row.
                        applyActionOrder();
                        collapseConnectionActions(connectionTabActions);
                    }
                    else if (shellTab && agentScreenOf(shellTab)) {
                        addAgentScreenActions(shellTab);
                        applyActionOrder();
                        collapseConnectionActions(connectionTabActions);
                    }
                    else if (shellTab && sshTerminalOf(shellTab)) {
                        addSshTerminalActions(shellTab);
                        applyActionOrder();
                        collapseConnectionActions(connectionTabActions);
                    }
                    else if (shellTab) {
                        const copyUrl = getShellTabCopyUrl(shellTab);
                        if (copyUrl) {
                            const copyUrlButton = createTabActionButton(
                                actionIcons.copy,
                                uiText.copyUrlToClipboard || 'Copy URL to clipboard',
                                async () => { await window.MatgateCopyText?.(copyUrl); },
                                '',
                                true);
                            addTabAction('copyUrl', copyUrlButton);
                        }
                    }
                    updateStatusBar();
                }

                // The screen of an agent's machine, in a page tab: the page brings no bar of its own there - the
                // session toolbar steers it, the same buttons as for an RDP session (fullscreen, pointer mode,
                // keyboards, resolution, clipboard, Ctrl+Alt+Del, disconnect). The page answers through
                // window.MatgateScreen and says when something changed (MatgateScreenChanged).
                function agentScreenOf(shellTab) {
                    const match = shellTab ? /^\/(agent|display)\/([0-9a-fA-F-]{36})\/screen/.exec(shellTab.url || '') : null;
                    if (!match) {
                        return null;
                    }

                    let api = null;
                    try {
                        api = (shellTab.iframe && shellTab.iframe.contentWindow && shellTab.iframe.contentWindow.MatgateScreen) || null;
                    }
                    catch {
                        api = null;
                    }

                    return { kind: match[1], serverId: match[2], api };
                }

                // An SSH terminal of Matgate's own, in a page tab.
                function sshTerminalOf(shellTab) {
                    if (!shellTab || !/^\/ssh\/[0-9a-fA-F-]{36}\/terminal/.test(shellTab.url || '')) {
                        return null;
                    }

                    try {
                        return { api: (shellTab.iframe && shellTab.iframe.contentWindow && shellTab.iframe.contentWindow.MatgateTerminal) || null };
                    }
                    catch {
                        return { api: null };
                    }
                }

                // Into a window of its own - or, in that window, back into the main one.
                function addWindowAction(shellTab) {
                    if (isPoppedWindow) {
                        addTabAction('reattach', createTabActionButton(
                            actionIcons.reattach,
                            uiText.reattachToMain || 'Re-attach to main window',
                            () => reattachShellTab(shellTab),
                            'tab-action-keep tab-action-reattach',
                            false));
                    }
                    else if (serverIdOfShellTab(shellTab)) {
                        addTabAction('popOut', createTabActionButton(
                            actionIcons.popOut,
                            uiText.openInNewWindow || 'Open in a new window',
                            () => popOutShellTab(shellTab),
                            'tab-action-keep',
                            true));
                    }
                }

                function addSshTerminalActions(shellTab) {
                    const api = () => sshTerminalOf(shellTab)?.api || null;
                    addTabAction('fullscreen', createTabActionButton(
                        actionIcons.fullscreen,
                        uiText.fullscreen || 'Fullscreen',
                        async () => {
                            try {
                                await toggleFullscreen(document.documentElement);
                            }
                            catch {
                                // Ignore fullscreen failures on browsers with partial support.
                            }
                            api()?.focus();
                        },
                        'tab-action-keep',
                        true));
                    addWindowAction(shellTab);
                    addTabAction('clipboard', createTabActionButton(
                        actionIcons.clipboard,
                        uiText.pasteToActiveTab || uiText.clipboard || 'Paste to active tab',
                        async () => {
                            // The clipboard panel: what is on it, and what to do with it (as text, as a file, as a picture).
                            if (window.MatgateOpenClipPanel) {
                                window.MatgateOpenClipPanel();
                                return;
                            }
                            try {
                                const text = await readBrowserClipboard();
                                if (text) {
                                    api()?.paste(text);
                                }
                            }
                            catch {
                                // No access to this device's clipboard: Ctrl+Shift+V in the terminal still works.
                            }
                            api()?.focus();
                        },
                        '',
                        true));
                    // Files go to the server through SFTP, into the login's home folder.
                    addTabAction('upload', createTabActionButton(
                        actionIcons.upload,
                        uiText.xferUpload || 'Send files to the session',
                        () => api()?.pickFiles(),
                        '',
                        true));
                    addTabAction('disconnect', createTabActionButton(
                        actionIcons.disconnect,
                        uiText.disconnect || 'Disconnect',
                        () => closeShellTab(shellTab.id),
                        'danger tab-action-disconnect'));
                }

                function activeAgentScreen() {
                    const shellTab = activeTabId ? null : shellTabs.get(activeShellTabId);
                    const screen = shellTab ? agentScreenOf(shellTab) : null;
                    return screen ? { shellTab, ...screen } : null;
                }

                window.MatgateScreenChanged = () => {
                    // The page's field took or let go of the cursor (among other things): the keyboard may have moved.
                    recheckKeyboardSoon();
                    if (activeAgentScreen()) {
                        updateTabActions();
                    }
                };
                window.MatgateScreenStats = () => {
                    if (activeAgentScreen()) {
                        updateStatusBar();
                    }
                };

                function addAgentScreenActions(shellTab) {
                    const screen = agentScreenOf(shellTab);
                    // Looked up at the time of the click: the page may have loaded (or reloaded) since.
                    const api = () => agentScreenOf(shellTab)?.api || null;
                    const state = screen.api ? screen.api.state() : {};
                    const agentTab = [...tabs.values()].find(candidate => candidate.serverId === screen.serverId && isAgentTab(candidate));

                    if (screen.kind === 'agent') {
                        addTabAction('agent-overview', createTabActionButton(
                            (agentTab && agentTab.iconHtml) || actionIcons.home,
                            agentTexts.overview,
                            () => window.MatgateShowAgent(screen.serverId),
                            'tab-action-keep tab-action-app',
                            true));
                    }

                    addTabAction('fullscreen', createTabActionButton(
                        actionIcons.fullscreen,
                        uiText.fullscreen || 'Fullscreen',
                        async () => {
                            try {
                                await toggleFullscreen(document.documentElement);
                            }
                            catch {
                                // Ignore fullscreen failures on browsers with partial support.
                            }
                            api()?.focus();
                        },
                        'tab-action-keep',
                        true));
                    addWindowAction(shellTab);

                    if (isTouchDevice) {
                        addTabAction('pointer', createTabActionButton(
                            actionIcons.pointer,
                            pointerMode === 'touchpad' ? (uiText.pointerTouchpad || 'Touchpad pointer') : (uiText.pointerDirect || 'Direct touch'),
                            () => setPointerMode(pointerMode === 'touchpad' ? 'direct' : 'touchpad'),
                            pointerMode === 'touchpad' ? 'active' : '',
                            true));

                        addTabAction('rightClick', createTabActionButton(
                            actionIcons.rightClick,
                            uiText.rightClick || 'Right click',
                            () => api()?.rightClick(),
                            '',
                            true));

                        const keyboardButton = createTabActionButton(
                            actionIcons.keyboard,
                            uiText.showKeyboard || 'Show/hide keyboard',
                            () => api()?.toggleKeyboard(),
                            'tab-action-keep' + (state.keyboardOpen ? ' active' : ''),
                            true);
                        // The tap must not take the focus from the page's input first.
                        keyboardButton.addEventListener('mousedown', event => event.preventDefault());
                        addTabAction('keyboard', keyboardButton);

                        const keysButton = createTabActionButton(
                            actionIcons.onScreenKeyboard,
                            uiText.onScreenKeyboard || 'Show/hide on-screen keyboard',
                            () => api()?.toggleKeyBar(),
                            'tab-action-keep' + (state.keyBarOpen ? ' active' : ''),
                            true);
                        keysButton.addEventListener('mousedown', event => event.preventDefault());
                        addTabAction('osk', keysButton);
                    }

                    addTabAction('resolution', createTabActionButton(
                        actionIcons.resolution,
                        `${uiText.resolutionLabel || 'Resolution'}: ${state.resolutionLabel || '-'}`,
                        () => openResolutionDialog(),
                        state.resolution === 'auto' ? 'active' : '',
                        true));

                    // The machine's windows (an agent that knows them): a list to switch by, and one window
                    // as the whole picture. The list itself belongs to the page.
                    if (state.canWindows) {
                        addTabAction('windows', createTabActionButton(
                            actionIcons.windows || actionIcons.popOut,
                            agentTexts.windows,
                            () => api()?.toggleWindows(),
                            'tab-action-keep' + (state.windowsOpen || state.windowOnly ? ' active' : ''),
                            true));
                    }

                    // VNC carries no sound.
                    if (state.canSound !== false) {
                        addTabAction('sound', createTabActionButton(
                            state.sound ? actionIcons.sound : actionIcons.soundOff,
                            state.sound ? agentTexts.soundOff : agentTexts.soundOn,
                            () => api()?.toggleSound(),
                            state.sound ? 'active' : '',
                            true));
                    }

                    // This device's microphone as one of the machine's (an agent's screen). Where the
                    // machine cannot take it the button stays: pressing it says what is missing there.
                    if (state.canMic) {
                        addTabAction('mic', createTabActionButton(
                            state.mic ? actionIcons.mic : actionIcons.micOff,
                            state.mic ? agentTexts.micOff : agentTexts.micOn,
                            () => api()?.toggleMic(),
                            state.mic ? 'active' : '',
                            true));
                    }

                    // A game controller of this device is one of the machine's right now.
                    if (state.pads > 0) {
                        addTabAction('gamepad', createTabActionButton(
                            actionIcons.gamepad,
                            agentTexts.gamepads.replace('{n}', String(state.pads)),
                            () => { },
                            'active',
                            true));
                    }

                    addTabAction('clipboard', createTabActionButton(
                        actionIcons.clipboard,
                        uiText.pasteToActiveTab || uiText.clipboard || 'Paste to active tab',
                        async () => {
                            // The clipboard panel: what is on it, and what to do with it (as text, as a file, as a picture).
                            if (window.MatgateOpenClipPanel) {
                                window.MatgateOpenClipPanel();
                                return;
                            }
                            try {
                                const text = await readBrowserClipboard();
                                if (text) {
                                    api()?.pasteText(text);
                                }
                            }
                            catch {
                                // No access to this device's clipboard: Ctrl+V in the picture still works.
                            }
                            api()?.focus();
                        },
                        '',
                        true));

                    if (sessionPrefs.ctrlAltDelHotkey) {
                        addTabAction('cad', createTabActionButton(
                            actionIcons.systemKeys,
                            uiText.comboCtrlAltDel || 'Ctrl+Alt+Del',
                            () => api()?.sas(),
                            '',
                            true));
                    }

                    addTabAction('disconnect', createTabActionButton(
                        actionIcons.disconnect,
                        uiText.disconnect || 'Disconnect',
                        () => closeShellTab(shellTab.id),
                        'danger tab-action-disconnect'));
                }

                // The parts the display dialog is made of - both of its kinds, this one and Guacamole's.
                function resolutionHeading(label) {
                    const heading = document.createElement('h3');
                    heading.className = 'resolution-heading';
                    heading.textContent = label;
                    return heading;
                }
                // Something that is on or off, and is so at once: the name (and what it means) on the left, a
                // switch on the right. The whole row is the button.
                function resolutionSwitch(label, hint, on, onToggle) {
                    const row = document.createElement('button');
                    row.type = 'button';
                    row.className = 'resolution-toggle' + (on ? ' active' : '');
                    row.setAttribute('role', 'switch');
                    row.setAttribute('aria-checked', on ? 'true' : 'false');
                    const words = document.createElement('span');
                    words.className = 'resolution-toggle-text';
                    const name = document.createElement('strong');
                    name.textContent = label;
                    words.appendChild(name);
                    if (hint) {
                        const more = document.createElement('small');
                        more.textContent = hint;
                        words.appendChild(more);
                    }
                    const track = document.createElement('span');
                    track.className = 'switch-track';
                    track.setAttribute('aria-hidden', 'true');
                    row.append(words, track);
                    row.addEventListener('click', onToggle);
                    return row;
                }
                // A few choices of which one applies, side by side - at most three in a row, unless the caller
                // says how many (the four picture qualities: two by two).
                function resolutionChoices(items, columns) {
                    const row = document.createElement('div');
                    row.className = 'resolution-seg';
                    row.style.setProperty('--count', String(columns || Math.min(items.length, 3)));
                    row.append(...items);
                    return row;
                }

                // The display dialog of a session of Matgate's own engine (RDP, VNC, an agent's screen), filled
                // with what the machine offers.
                function openScreenResolutionDialog(screen) {
                    const api = screen.api;
                    if (!api || !resolutionDialog || !resolutionOptions) {
                        return;
                    }

                    // The dialog lives with the connection tabs, which are hidden behind a page tab: it moves to the
                    // page itself (its rules are global, RDP sessions find it there just as well).
                    if (resolutionDialog.parentElement !== document.body) {
                        document.body.appendChild(resolutionDialog);
                    }

                    const state = api.state();
                    // A choice. With a title it is a card of two lines: the name, and under it what it means -
                    // with a flash for the fastest response.
                    const option = (label, active, onClick, detail) => {
                        const button = document.createElement('button');
                        button.type = 'button';
                        button.className = 'resolution-option' + (active ? ' active' : '');
                        if (detail && detail.title) {
                            const name = document.createElement('span');
                            name.className = 'resolution-option-title';
                            name.textContent = detail.title;
                            const hint = document.createElement('small');
                            hint.className = 'resolution-option-hint';
                            if (detail.value === 'fast' && actionIcons.zap) {
                                hint.insertAdjacentHTML('beforeend', actionIcons.zap);
                            }
                            hint.append(detail.hint || '');
                            button.append(name, hint);
                            button.setAttribute('aria-label', label);
                        }
                        else {
                            button.textContent = label;
                        }
                        button.addEventListener('click', () => {
                            onClick();
                            closeResolutionDialog();
                            api.focus();
                        });
                        return button;
                    };
                    // "Fit to window" comes first - that is what nearly everyone wants, and nobody should have to
                    // pick a resolution by its numbers. Next to it the machine's own size, and the fixed sizes
                    // behind the third choice.
                    const choices = state.resolutionOptions || [];
                    const fixed = choices.filter(item => item.value !== 'auto' && item.value !== 'native');
                    const chosenFixed = fixed.some(item => item.value === state.resolution);
                    const list = document.createElement('div');
                    list.className = 'resolution-fixed-list';
                    list.hidden = !chosenFixed;
                    fixed.forEach(item => list.appendChild(option(item.label, item.value === state.resolution, () => api.setResolution(item.value))));
                    const sizes = choices.filter(item => item.value === 'auto' || item.value === 'native')
                        .map(item => option(item.label, item.value === state.resolution, () => api.setResolution(item.value)));
                    if (fixed.length) {
                        const opener = document.createElement('button');
                        opener.type = 'button';
                        opener.className = 'resolution-seg-item' + (chosenFixed ? ' active' : '');
                        opener.dataset.fixedSizes = '1';
                        opener.setAttribute('aria-expanded', chosenFixed ? 'true' : 'false');
                        opener.textContent = state.texts?.fixedSizes || 'A fixed resolution';
                        opener.addEventListener('click', () => {
                            list.hidden = !list.hidden;
                            opener.setAttribute('aria-expanded', list.hidden ? 'false' : 'true');
                        });
                        sizes.push(opener);
                    }
                    resolutionOptions.replaceChildren(resolutionHeading(uiText.sizeHeading || 'Size'), resolutionChoices(sizes), list);
                    if (resolutionExtra) {
                        resolutionExtra.replaceChildren();
                        // The scale of "fit to window": a few steps to tap and a slider for everything between.
                        // Nobody has to know a resolution - the note says which one it comes to.
                        if (typeof api.setScale === 'function') {
                            const box = document.createElement('div');
                            box.className = 'resolution-scale';
                            const head = document.createElement('label');
                            head.className = 'resolution-scale-head';
                            const name = document.createElement('span');
                            name.textContent = state.texts?.scale || uiText.scaleLabel || 'Scale';
                            const value = document.createElement('strong');
                            const slider = document.createElement('input');
                            slider.type = 'range';
                            slider.className = 'resolution-scale-slider';
                            slider.min = '25';
                            slider.max = '300';
                            slider.step = '5';
                            slider.value = String(state.scale || 100);
                            head.append(name, value);
                            head.appendChild(slider);
                            const presets = document.createElement('div');
                            presets.className = 'resolution-scale-presets';
                            const note = document.createElement('p');
                            note.className = 'muted resolution-scale-note';
                            const show = () => {
                                const percent = Number(slider.value);
                                value.textContent = percent + ' %';
                                slider.style.setProperty('--filled', ((percent - 25) / 2.75) + '%');
                                const size = api.fitAt(percent);
                                note.textContent = (state.texts?.remoteSize || uiText.scaleNote || 'Resolution') + ': ' + size.fitWidth + ' × ' + size.fitHeight;
                                presets.querySelectorAll('button').forEach(item => item.classList.toggle('active', state.resolution === 'auto' && Number(item.dataset.scale) === percent));
                            };
                            [50, 75, 100, 125, 150, 200].forEach(percent => {
                                const item = document.createElement('button');
                                item.type = 'button';
                                item.className = 'resolution-scale-preset';
                                item.dataset.scale = String(percent);
                                item.textContent = percent + ' %';
                                item.addEventListener('click', () => {
                                    api.setScale(percent);
                                    closeResolutionDialog();
                                    api.focus();
                                });
                                presets.appendChild(item);
                            });
                            slider.addEventListener('input', show);
                            // The machine is asked once the finger lets go: every step on the way would be a
                            // resolution of its own.
                            slider.addEventListener('change', () => {
                                api.setScale(Number(slider.value));
                                state.resolution = 'auto';
                                show();
                            });
                            show();
                            box.append(head, presets, note);
                            resolutionExtra.appendChild(box);
                        }
                        // A heading and its choices; as cards of two lines, four of them two by two.
                        const group = (title, items, onPick, cards) => {
                            if (!items || items.length < 2) {
                                return false;
                            }

                            resolutionExtra.appendChild(resolutionHeading(title));
                            const row = resolutionChoices(
                                items.map(item => option(item.label, item.active, () => onPick(item.value), cards ? item : null)),
                                cards && items.length === 4 ? 2 : undefined);
                            if (cards) {
                                row.classList.add('resolution-seg--cards');
                            }
                            resolutionExtra.appendChild(row);
                            return true;
                        };
                        const qualities = state.qualities || [];
                        if (group(state.texts?.quality || 'Quality', qualities, value => api.setQuality(value), true) && state.texts?.qualityNoteDevice) {
                            // Where the choice is kept: on this device for this connection, or - fixed in the
                            // settings - for every new session. Either way the settings are one tap away.
                            const fixedQuality = state.qualityDefault || '';
                            const start = qualities.find(item => item.value === fixedQuality);
                            const note = document.createElement('p');
                            note.className = 'resolution-note';
                            note.textContent = (fixedQuality
                                ? (state.texts.qualityNoteFixed || '').replace('{title}', start ? (start.title || start.label) : fixedQuality)
                                : state.texts.qualityNoteDevice) + ' ';
                            const link = document.createElement('button');
                            link.type = 'button';
                            link.className = 'resolution-note-link';
                            link.textContent = fixedQuality ? state.texts.qualityChange : state.texts.qualityForAll;
                            link.addEventListener('click', () => {
                                closeResolutionDialog();
                                openShellTab('/account?tab=session#screen-quality', uiText.settingsTitle || 'Settings', actionIcons.settings || '');
                            });
                            note.appendChild(link);
                            resolutionExtra.appendChild(note);
                        }
                        group(state.texts?.monitor || 'Monitor', state.monitors, value => api.setMonitor(value));

                        const switches = [];
                        // A phone or tablet: what the device's keyboard does to the picture.
                        if (state.touch && typeof api.setKeyboardResize === 'function') {
                            const toggle = resolutionSwitch(
                                state.texts?.keyboardResize || 'Fit the resolution to the keyboard',
                                state.texts?.keyboardResizeHint || '',
                                !!state.keyboardResize,
                                () => {
                                    api.setKeyboardResize(!state.keyboardResize);
                                    openScreenResolutionDialog(screen);
                                });
                            toggle.dataset.keyboardResize = state.keyboardResize ? '1' : '0';
                            switches.push(toggle);
                        }
                        // The session's numbers as a mark in the picture - on a phone the only place for them.
                        if (typeof api.setPerf === 'function') {
                            const toggle = resolutionSwitch(
                                state.texts?.perf || 'Performance numbers in the picture',
                                '',
                                !!state.perf,
                                () => {
                                    api.setPerf(!state.perf);
                                    openScreenResolutionDialog(screen);
                                });
                            toggle.dataset.perf = state.perf ? '1' : '0';
                            toggle.title = state.texts?.perfHint || '';
                            switches.push(toggle);
                        }
                        if (switches.length) {
                            const rows = document.createElement('div');
                            rows.className = 'resolution-switches';
                            rows.append(...switches);
                            resolutionExtra.append(resolutionHeading(uiText.optionsHeading || 'Options'), rows);
                        }
                        // Where the numbers stand in the picture - a corner, kept on this device.
                        if (state.perf && typeof api.setPerfPosition === 'function') {
                            const labels = state.texts?.perfPlaces || ['Top left', 'Top right', 'Bottom left', 'Bottom right'];
                            group(state.texts?.perfPosition || 'Performance numbers stand',
                                ['top-left', 'top-right', 'bottom-left', 'bottom-right'].map((value, index) => ({ value, label: labels[index], active: state.perfAt === value })),
                                value => {
                                    api.setPerfPosition(value);
                                    openScreenResolutionDialog(screen);
                                });
                        }
                    }

                    resolutionDialog.classList.remove('hidden');
                }

                function createTabActionButton(iconHtml, label, onClick, className = '', iconOnly = false) {
                    const button = document.createElement('button');
                    button.type = 'button';
                    button.className = ['tab-action-button', iconOnly ? 'icon-only' : '', className].filter(Boolean).join(' ');
                    button.title = label;
                    button.setAttribute('aria-label', label);
                    button.innerHTML = iconOnly
                        ? `${iconHtml || ''}`
                        : `${iconHtml || ''}<span>${escapeHtml(label)}</span>`;
                    button.addEventListener('click', onClick);
                    return button;
                }

                // Every action carries a stable key, independent of what it says. The labels are
                // translated and two of them contain live state ("Resolution: 1920x1080"), so neither
                // can identify an action across languages or sessions - which a saved order needs.
                function addTabAction(key, button) {
                    if (!button) {
                        return;
                    }

                    // Hidden by the user - and gone, not just moved into the overflow menu. Disconnect
                    // is never hidden: ending a session has to stay reachable. Nor is the device keyboard on a
                    // touch screen: without it nothing can be typed there.
                    if (key !== 'disconnect'
                        && !(key === 'keyboard' && isTouchDevice)
                        && Array.isArray(sessionPrefs.hiddenActions)
                        && sessionPrefs.hiddenActions.indexOf(key) >= 0) {
                        return;
                    }

                    button.dataset.action = key;
                    connectionTabActions.appendChild(button);
                }

                // Puts the row in the order the user picked. Actions they never sorted - because they
                // are new, or only appear for some protocols - keep their built-in place at the end
                // rather than disappearing. Disconnect stays last whatever the order says: it is the
                // one action that must not end up buried in the overflow menu.
                function applyActionOrder() {
                    const own = Array.isArray(sessionPrefs.actionOrder) ? sessionPrefs.actionOrder : [];
                    const order = own.length ? own : defaultActionOrder;
                    // On a touch screen the device keyboard comes first, whatever the order says: without it
                    // nothing can be typed there.
                    const keyboardFirst = isTouchDevice;
                    const rank = key => {
                        if (keyboardFirst && key === 'keyboard') {
                            return -1;
                        }

                        const at = order.indexOf(key);
                        return at < 0 ? order.length : at;
                    };

                    Array.from(connectionTabActions.children)
                        .sort((a, b) => {
                            const left = a.dataset.action || '';
                            const right = b.dataset.action || '';
                            if (left === 'disconnect') { return 1; }
                            if (right === 'disconnect') { return -1; }
                            return rank(left) - rank(right);
                        })
                        .forEach(button => connectionTabActions.appendChild(button));
                }

                // On phones the session toolbar keeps only the primary buttons (fullscreen, keyboards)
                // + disconnect inline and moves the rest into a "..." dropdown, so the tab strip stays
                // visible. The panel is position:fixed to escape the toolbar's horizontal overflow.
                // Overflow panels are plain divs toggled by plain buttons - NO <details>/<summary>,
                // which is unreliable on iOS PWAs. Panels live under <body> (position:fixed), so no
                // scrollable/sticky ancestor can clip them.
                function showOverflowPanel(trigger, panel) {
                    // Single-open policy: opening one overflow panel closes every other one, so two
                    // triggers (toolbar "..." + header tab menu) can never stack overlapping panels.
                    document.querySelectorAll('body > .tab-action-overflow-panel').forEach(other => {
                        if (other !== panel) {
                            other.style.display = 'none';
                        }
                    });
                    // Remember the owning trigger so the outside-close handler can exempt exactly
                    // this panel's trigger (and not every trigger, which kept foreign panels open).
                    panel.matgateTrigger = trigger;
                    if (panel.parentElement !== document.body) {
                        document.body.appendChild(panel);
                    }
                    const rect = trigger.getBoundingClientRect();
                    panel.style.top = Math.round(rect.bottom + 6) + 'px';
                    panel.style.left = 'auto';
                    panel.style.display = 'flex';
                    // Anchor to the trigger's right edge, then clamp BOTH ways using the real panel
                    // width so it can never leave the screen regardless of where the trigger sits.
                    const width = panel.getBoundingClientRect().width;
                    let right = Math.max(8, Math.round(window.innerWidth - rect.right));
                    right = Math.min(right, Math.max(8, Math.round(window.innerWidth - width - 8)));
                    panel.style.right = right + 'px';
                }

                // Anything outside an open overflow panel (and not on ITS OWN trigger) closes it.
                // Wired to pointerdown AND click: Guacamole preventDefaults touchstart on the remote
                // display, which suppresses synthesized clicks - pointerdown still fires, so tapping
                // the session dismisses the menu on touch devices too. click stays as a fallback for
                // browsers without PointerEvent and for synthetic .click() calls.
                const closeOverflowPanelsOutside = (target) => {
                    document.querySelectorAll('body > .tab-action-overflow-panel').forEach(panel => {
                        if (panel.style.display !== 'flex') {
                            return;
                        }
                        if (target && (panel.contains(target)
                            || (panel.matgateTrigger && panel.matgateTrigger.contains(target)))) {
                            return;
                        }
                        panel.style.display = 'none';
                    });
                };
                document.addEventListener('pointerdown', event => {
                    closeOverflowPanelsOutside(event.target instanceof Element ? event.target : null);
                }, true);
                document.addEventListener('click', event => {
                    closeOverflowPanelsOutside(event.target instanceof Element ? event.target : null);
                }, true);

                // Rebuild the toolbar when the viewport crosses the phone breakpoint (rotation,
                // window resize): collapseConnectionActions samples the media query at build time
                // only, so without this a landscape-built toolbar kept ~10 loose icons after
                // rotating to portrait (and vice versa).
                try {
                    const collapseBreakpoint = window.matchMedia('(max-width: 720px)');
                    if (typeof collapseBreakpoint.addEventListener === 'function') {
                        collapseBreakpoint.addEventListener('change', () => updateTabActions());
                    }
                }
                catch {
                    // matchMedia change events unsupported: the toolbar still rebuilds on tab switches.
                }

                // Moves one action out of the row and into the overflow panel, where it needs its label
                // spelled out because it is no longer just an icon. The button NODE is moved, never
                // cloned: the keyboard buttons are held on the tab object and kept in sync by focus and
                // blur handlers, and a copy would break that silently.
                function moveActionToPanel(btn, panel) {
                    const label = btn.getAttribute('aria-label') || '';
                    if (label && !btn.querySelector('span')) {
                        const labelSpan = document.createElement('span');
                        labelSpan.textContent = label;
                        btn.appendChild(labelSpan);
                    }

                    btn.classList.remove('icon-only');
                    btn.classList.add('tab-action-menu-item');
                    panel.appendChild(btn);
                }

                // Second pass, by measurement. The rule above only knows "phone or not" and keeps a
                // fixed set of actions in the row - which is why the row could still run past the right
                // edge and put the last action out of reach. Here the row is measured and the last
                // action is moved into the panel until it genuinely fits. Disconnect and the overflow
                // trigger itself stay put.
                function fitConnectionActions(container, panel, trigger) {
                    if (!container || !panel || !container.clientWidth) {
                        return;
                    }

                    for (let guard = 0; guard < 40 && container.scrollWidth > container.clientWidth; guard++) {
                        const movable = Array.from(container.querySelectorAll('.tab-action-button'))
                            .filter(btn => btn !== trigger && !btn.classList.contains('tab-action-disconnect'));
                        const last = movable[movable.length - 1];
                        if (!last) {
                            return;
                        }

                        moveActionToPanel(last, panel);
                    }
                }

                function collapseConnectionActions(container) {
                    // Drop any stale portaled panel from a previous toolbar build (but never the
                    // header tab menu's panel, which persists across rebuilds). This must run BEFORE
                    // the media-query gate: a rebuild while >720px must also clean up a panel that was
                    // portaled while the viewport was narrow.
                    document.querySelectorAll('body > .tab-action-overflow-panel:not(.mobile-tab-menu-panel)').forEach(el => el.remove());
                    if (!container || !window.matchMedia('(max-width: 720px)').matches) {
                        return;
                    }
                    const buttons = Array.from(container.querySelectorAll('.tab-action-button'))
                        .filter(b => !b.classList.contains('tab-action-disconnect'));
                    if (buttons.length < 2) {
                        return;
                    }
                    const panel = document.createElement('div');
                    panel.className = 'tab-action-more-panel tab-action-overflow-panel';
                    // Who stays in the row: when the user sorted the actions themselves, their order
                    // decides and only the measured fit below takes any away - otherwise the built-in
                    // "keep" set would pin actions they had deliberately pushed to the back, and
                    // sorting would change nothing about what is actually within reach. Without an
                    // order of their own the primary buttons stay inline, exactly as before.
                    const sorted = Array.isArray(sessionPrefs.actionOrder) && sessionPrefs.actionOrder.length > 0;
                    if (!sorted) {
                        buttons
                            .filter(btn => !btn.classList.contains('tab-action-keep'))
                            .forEach(btn => moveActionToPanel(btn, panel));
                    }
                    panel.addEventListener('click', () => { panel.style.display = 'none'; });
                    const trigger = createTabActionButton(
                        actionIcons.more || '&#8943;',
                        uiText.moreActions || 'More actions',
                        () => {
                            if (panel.style.display === 'flex') {
                                panel.style.display = 'none';
                            }
                            else {
                                showOverflowPanel(trigger, panel);
                            }
                        },
                        'tab-action-more-trigger',
                        true);
                    const disconnect = container.querySelector('.tab-action-disconnect');
                    if (disconnect) {
                        container.insertBefore(trigger, disconnect);
                    }
                    else {
                        container.appendChild(trigger);
                    }

                    fitConnectionActions(container, panel, trigger);
                }

                function getTabEntry(tabId) {
                    return tabs.get(tabId) || shellTabs.get(tabId) || null;
                }

                function insertTabButton(tabButton) {
                    if (!tabsRoot || !tabButton) {
                        return;
                    }

                    if (newConnectionTab && newConnectionTab.parentElement === tabsRoot) {
                        tabsRoot.insertBefore(tabButton, newConnectionTab);
                        return;
                    }

                    tabsRoot.appendChild(tabButton);
                }

                function saveTabOrder() {
                    if (isPoppedWindow) { return; }
                    try {
                        localStorage.setItem(tabOrderStorageKey, JSON.stringify({
                            order: Array.from(tabsRoot.querySelectorAll('.session-tab[data-tab-id]'))
                                .map(tabButton => tabButton.getAttribute('data-tab-id'))
                                .filter(Boolean)
                        }));
                        scheduleTabStatePush();
                    }
                    catch {
                        // Ignore ordering failures.
                    }
                }

                function restoreTabOrder() {
                    if (!tabsRoot) {
                        return;
                    }

                    try {
                        const raw = localStorage.getItem(tabOrderStorageKey);
                        if (!raw) {
                            return;
                        }

                        const state = JSON.parse(raw);
                        const order = Array.isArray(state.order) ? state.order : [];
                        const anchor = newConnectionTab && newConnectionTab.parentElement === tabsRoot ? newConnectionTab : null;
                        order.forEach(tabId => {
                            const entry = getTabEntry(tabId);
                            const tabButton = entry?.tabButton || entry?.button;
                            if (tabButton && tabButton.parentElement === tabsRoot) {
                                tabsRoot.insertBefore(tabButton, anchor);
                            }
                        });
                    }
                    catch {
                        // Ignore ordering failures.
                    }
                }

                function wireTabDrag(tabButton, tabId) {
                    const dragHandle = tabButton.querySelector('.session-tab-main') || tabButton;
                    dragHandle.draggable = true;
                    dragHandle.addEventListener('dragstart', event => {
                        draggedTabId = tabId;
                        suppressTabClicks = true;
                        tabButton.classList.add('dragging');
                        try {
                            event.dataTransfer.effectAllowed = 'move';
                            event.dataTransfer.setData('text/plain', tabId);
                            event.dataTransfer.setDragImage(getTransparentDragImage(), 0, 0);
                        }
                        catch {
                            // Ignore drag data issues.
                        }
                    });
                    dragHandle.addEventListener('dragend', () => {
                        tabButton.classList.remove('dragging');
                        draggedTabId = null;
                        setTimeout(() => {
                            suppressTabClicks = false;
                        }, 0);
                        saveTabOrder();
                    });
                    tabButton.addEventListener('dragover', event => {
                        if (!draggedTabId || draggedTabId === tabId) {
                            return;
                        }

                        event.preventDefault();
                        const draggingTab = getTabEntry(draggedTabId);
                        const draggingButton = draggingTab?.tabButton || draggingTab?.button;
                        if (!draggingButton) {
                            return;
                        }

                        const rect = tabButton.getBoundingClientRect();
                        const insertBefore = event.clientX < rect.left + (rect.width / 2);
                        const referenceNode = insertBefore ? tabButton : (tabButton.nextSibling || newConnectionTab);
                        if (draggingButton !== referenceNode) {
                            tabsRoot.insertBefore(draggingButton, referenceNode);
                        }
                    });
                    tabButton.addEventListener('drop', event => {
                        if (!draggedTabId) {
                            return;
                        }

                        event.preventDefault();
                        draggedTabId = null;
                        saveTabOrder();
                    });
                }

                function getTransparentDragImage() {
                    if (transparentDragImage) {
                        return transparentDragImage;
                    }

                    transparentDragImage = document.createElement('div');
                    transparentDragImage.style.width = '1px';
                    transparentDragImage.style.height = '1px';
                    transparentDragImage.style.opacity = '0';
                    transparentDragImage.style.position = 'fixed';
                    transparentDragImage.style.pointerEvents = 'none';
                    transparentDragImage.style.top = '-100px';
                    transparentDragImage.style.left = '-100px';
                    document.body.appendChild(transparentDragImage);
                    return transparentDragImage;
                }

                function activateNewConnectionTab() {
                    activeTabId = null;
                    newConnectionTab.classList.add('active');
                    newConnectionPanel.classList.remove('hidden');
                    activeShellTabId = '';
                    setWorkspaceVisible(true);
                    document.title = `${ui('dashboard')} - Matgate`;

                    shellTabs.forEach(tab => {
                        tab.button.classList.remove('active');
                        tab.panel.classList.add('hidden');
                    });
                    for (const tab of tabs.values()) {
                        tab.tabButton.classList.remove('active');
                        tab.panel.classList.add('hidden');
                    }
                    releaseInactiveHeldKeys();

                    updateTabActions();
                    if (!restoringTabs) {
                        // At start this is the page tabs coming back - the other tabs are not, yet, and writing them
                        // down now would write them down as none.
                        saveWorkspaceTabs();
                    }
                }

                function createTab(server, options = {}) {
                    const tabId = options.tabId || newTabId();
                    // Farm-website tabs render like a VNC guac session (the browser runs remotely),
                    // so they use the guac path, not the native website iframe.
                    const farmWebsite = isFarmWebsiteServer(server);
                    const isWebsite = isWebsiteProtocol(server.protocol) && !farmWebsite;
                    const tabButton = document.createElement('div');
                    tabButton.className = 'session-tab session-tab--connection';
                    tabButton.setAttribute('role', 'tab');
                    tabButton.setAttribute('data-tab-id', tabId);
                    tabButton.setAttribute('data-tab-kind', 'connection');

                    const tabMain = document.createElement('button');
                    tabMain.type = 'button';
                    tabMain.className = 'session-tab-main';
                    tabMain.draggable = true;
                    const tabTitle = document.createElement('span');
                    tabTitle.className = 'session-tab-title';
                    tabTitle.innerHTML = tabTitleHtml(server);

                    const tabDescription = document.createElement('small');
                    tabDescription.className = 'session-tab-description';
                    tabDescription.textContent = ui('starting');

                    tabMain.append(tabTitle, tabDescription);

                    const closeButton = document.createElement('button');
                    closeButton.type = 'button';
                    closeButton.className = 'session-tab-close';
                    closeButton.setAttribute('aria-label', 'Tab schließen');
                    closeButton.innerHTML = '&times;';
                    closeButton.addEventListener('mousedown', event => {
                        event.stopPropagation();
                    });
                    closeButton.addEventListener('dragstart', event => {
                        event.preventDefault();
                        event.stopPropagation();
                    });
                    closeButton.addEventListener('click', event => {
                        event.stopPropagation();
                        closeTab(tabId);
                    });

                    tabButton.append(tabMain, closeButton);
                    tabMain.addEventListener('click', event => {
                        if (suppressTabClicks) {
                            event.preventDefault();
                            return;
                        }

                        activateTab(tabId);
                    });
                    insertTabButton(tabButton);
                    wireTabDrag(tabButton, tabId);

                    const panel = document.createElement('div');
                    panel.className = 'connection-panel hidden';
                    panel.tabIndex = 0;
                    panel.addEventListener('keydown', event => {
                        if (shouldSuppressBrowserScroll(event)) {
                            event.preventDefault();
                        }

                        // Ctrl+V / Shift+Insert: noted for Guacamole.Keyboard's handler, which runs right after
                        // this one and may hold the key back (see holdPasteKey). A key that is only repeating
                        // must not paste again, so the browser's own paste is cancelled for it.
                        const chord = isPasteChord(event);
                        if (chord && event.repeat) {
                            event.preventDefault();
                        }

                        tab.pasteChordPending = chord && !event.repeat;
                    }, true);

                    const displayRoot = document.createElement('div');
                    displayRoot.className = isWebsite ? 'website-display' : 'guac-display';

                    const overlay = document.createElement('div');
                    overlay.className = 'connection-overlay';

                    const dialog = document.createElement('div');
                    dialog.className = 'connection-dialog';

                    const overlayTitle = document.createElement('h1');
                    overlayTitle.textContent = ui('opening');

                    const overlayMessage = document.createElement('p');
                    overlayMessage.textContent = ui('preparing');

                    const overlayActions = document.createElement('div');
                    overlayActions.className = 'actions hidden';

                    const reconnectButton = document.createElement('button');
                    reconnectButton.type = 'button';
                    reconnectButton.className = 'primary';
                    reconnectButton.textContent = uiText.reconnect || 'Reconnect';

                    const closeOverlayButton = document.createElement('button');
                    closeOverlayButton.type = 'button';
                    closeOverlayButton.textContent = uiText.closeTab || 'Close tab';

                    overlayActions.append(reconnectButton, closeOverlayButton);
                    dialog.append(overlayTitle, overlayMessage, overlayActions);
                    overlay.appendChild(dialog);
                    panel.append(displayRoot, overlay);
                    deck.appendChild(panel);

                    const tab = {
                        id: tabId,
                        serverId: server.id,
                        name: server.name,
                        protocol: farmWebsite ? 'VNC' : server.protocol,
                        farmWebsite,
                        // The connection's own file area, so its toolbar can offer it directly.
                        fileAreaId: server.fileAreaId || '',
                        browserSessionId: '',
                        fileSessionId: '',
                        browserFarmTimer: null,
                        iconKey: server.iconKey,
                        iconHtml: server.iconHtml,
                        target: server.target,
                        initialFilePath: options.filePath || '',
                        tabButton,
                        tabMain,
                        closeButton,
                        statusLabel: tabDescription,
                        panel,
                        displayRoot,
                        overlay,
                        overlayTitle,
                        overlayMessage,
                        overlayActions,
                        client: null,
                        keyboard: null,
                        lastError: '',
                        lastMessage: ui('newConnection'),
                        terminal: false,
                        connectedAt: null,
                        lastSyncAt: null,
                        lastSentSize: null,
                        tunnelState: 'Initialisiert',
                        connectionName: '',
                        encryptedData: '',
                        remoteClipboard: '',
                        displayRes: resolutionForServer(server.id, server.protocol),
                        autoResize: autoResizeForServer(server.id),
                        zoom: 1,
                        websiteUi: null,
                        currentUrl: '',
                        displayUrl: '',
                        statusTimer: null,
                        statusUpdatedAt: Date.now(),
                        watchdog: null
                    };

                    if (isWebsite) {
                        const websiteShell = document.createElement('div');
                        websiteShell.className = 'website-shell';
                        websiteShell.innerHTML = `
                            ${Toolbar('website-toolbar',
                                ToolbarGroup('website-toolbar-group',
                                    ToolbarIconButton(uiText.back || 'Back', websiteIcons.back, 'website-tool-button', Attr('data-website-action', 'back') + Attr('title', uiText.back || 'Back')),
                                    ToolbarIconButton(uiText.forward || 'Forward', websiteIcons.forward, 'website-tool-button', Attr('data-website-action', 'forward') + Attr('title', uiText.forward || 'Forward')),
                                    ToolbarIconButton(uiText.refresh || 'Refresh', websiteIcons.refresh, 'website-tool-button', Attr('data-website-action', 'reload') + Attr('title', uiText.refresh || 'Refresh'))
                                ),
                                ToolbarGroup('website-toolbar-group website-toolbar-address toolbar-group--grow',
                                    `<span class="website-address-mark" aria-hidden="true"><span class="website-address-globe">${websiteIcons.globe}</span><span class="website-address-lock">${websiteIcons.secure}</span></span>`
                                    + ToolbarInput('website-address', server.target || '', uiText.website || 'Website', true)
                                ),
                                ToolbarGroup('website-toolbar-group toolbar-group--end',
                                    ToolbarButton(uiText.openInNewTab || 'Open in new tab', websiteIcons.open, 'website-tool-button', Attr('data-website-action', 'open') + Attr('title', uiText.openInNewTab || 'Open in new tab'))
                                )
                            )}
                            <iframe class="website-frame" title="${escapeHtml(server.name)}" allow="clipboard-read; clipboard-write; fullscreen"></iframe>
                            <div class="website-start" hidden>
                                <div class="website-start-box">
                                    <span class="website-start-icon" aria-hidden="true">${websiteIcons.globe}</span>
                                    <h2>${escapeHtml(uiText.websiteStartTitle || 'Browser')}</h2>
                                    <p class="muted">${escapeHtml(uiText.websiteStartHint || '')}</p>
                                    <div class="website-start-group" data-website-start="saved" hidden>
                                        <h3>${escapeHtml(uiText.websiteStartSaved || 'Saved websites')}</h3>
                                        <div class="website-start-list"></div>
                                    </div>
                                    <div class="website-start-group" data-website-start="recent" hidden>
                                        <h3>${escapeHtml(uiText.websiteStartRecent || 'Recently visited')}</h3>
                                        <div class="website-start-list"></div>
                                        <button type="button" class="website-start-clear">${escapeHtml(uiText.websiteStartClear || 'Clear the list')}</button>
                                    </div>
                                </div>
                            </div>`;
                        displayRoot.appendChild(websiteShell);
                        tab.websiteUi = {
                            shell: websiteShell,
                            frame: websiteShell.querySelector('.website-frame'),
                            start: websiteShell.querySelector('.website-start'),
                            address: websiteShell.querySelector('.website-address'),
                            backButton: websiteShell.querySelector('[data-website-action="back"]'),
                            forwardButton: websiteShell.querySelector('[data-website-action="forward"]'),
                            reloadButton: websiteShell.querySelector('[data-website-action="reload"]'),
                            openButton: websiteShell.querySelector('[data-website-action="open"]')
                        };
                        tab.websiteUi.frame.name = tab.id;
                        tab.websiteUi.frame.addEventListener('load', () => {
                            if (!tabs.has(tab.id)) {
                                return;
                            }

                            if (tab.site) {
                                // Another origin: the page says itself where it is (see the message handler).
                            }
                            else {
                                if (rescueWebsiteFrame(tab)) {
                                    return;
                                }

                                try {
                                    updateWebsiteLocation(tab.id, websiteFrameUrl(tab));
                                }
                                catch {
                                    updateWebsiteLocation(tab.id, tab.target || '');
                                }
                            }

                            hideOverlay(tab);
                            setStatus(tab, ui('ready'));
                            updateStatusBar();
                        });
                        tab.websiteUi.address.addEventListener('keydown', event => {
                            if (event.key === 'Enter' && (tab.site || tab.pathBrowse)) {
                                event.preventDefault();
                                navigateWebsiteTab(tab, tab.websiteUi.address.value.trim());
                            }
                            else if (event.key === 'Escape' && (tab.site || tab.pathBrowse)) {
                                tab.websiteUi.address.value = tab.displayUrl || '';
                                tab.websiteUi.address.blur();
                            }
                        });
                        // Left without sending it off: the bar shows where the tab is again, not what was typed.
                        tab.websiteUi.address.addEventListener('blur', () => {
                            if (tab.pathBrowse) {
                                tab.websiteUi.address.value = tab.displayUrl || '';
                            }
                        });
                        tab.websiteUi.address.addEventListener('focus', () => {
                            if (tab.site || tab.pathBrowse) {
                                tab.websiteUi.address.select();
                            }
                        });
                        tab.websiteUi.backButton.addEventListener('click', () => {
                            if (tab.site) {
                                tellWebsiteSite(tab, { go: 'back' });
                                return;
                            }

                            try {
                                tab.websiteUi.frame.contentWindow.history.back();
                            }
                            catch {
                                // Ignore navigation issues.
                            }
                        });
                        tab.websiteUi.forwardButton.addEventListener('click', () => {
                            if (tab.site) {
                                tellWebsiteSite(tab, { go: 'forward' });
                                return;
                            }

                            try {
                                tab.websiteUi.frame.contentWindow.history.forward();
                            }
                            catch {
                                // Ignore navigation issues.
                            }
                        });
                        tab.websiteUi.reloadButton.addEventListener('click', () => {
                            if (tab.site) {
                                if (tab.site.live) {
                                    tellWebsiteSite(tab, { go: 'reload' });
                                }
                                else if (tab.displayUrl) {
                                    // A page that does not answer (an error page, a download): asked for anew.
                                    requestWebsiteSite(tab, tab.displayUrl)
                                        .then(data => data.available && data.url && showWebsiteSite(tab, data))
                                        .catch(() => { });
                                }

                                return;
                            }

                            try {
                                // A page that pretends to lie at the root is loaded anew from where it really is.
                                const inner = tab.websiteUi.frame.contentWindow;
                                if (typeof inner.__matgateRealUrl === 'function' && inner.__matgateRealUrl() !== inner.location.href) {
                                    inner.location.replace(inner.__matgateRealUrl());
                                }
                                else {
                                    inner.location.reload();
                                }
                            }
                            catch {
                                tab.websiteUi.frame.src = tab.websiteUi.frame.src;
                            }
                        });
                        tab.websiteUi.openButton.addEventListener('click', () => {
                            if (tab.site) {
                                // A window first, while the click still counts; its address when it is known.
                                const opened = window.open('about:blank', '_blank');
                                requestWebsiteSite(tab, tab.displayUrl || '').then(data => {
                                    if (opened && data.available && data.url) {
                                        opened.opener = null;
                                        opened.location.href = data.url;
                                    }
                                    else if (opened) {
                                        opened.close();
                                    }
                                }).catch(() => opened && opened.close());
                                return;
                            }

                            if (tab.pathBrowse) {
                                // The frame as it is: it belongs to the website it shows, a new tab id would not.
                                let shown = '';
                                try {
                                    shown = websiteFrameUrl(tab);
                                }
                                catch {
                                    shown = '';
                                }

                                if (shown && shown !== 'about:blank') {
                                    window.open(shown, '_blank', 'noopener');
                                }

                                return;
                            }

                            const nextTabId = newTabId();
                            const current = tab.websiteUi.frame?.contentWindow?.location?.href
                                || tab.websiteUi.frame?.src
                                || tab.currentUrl
                                || tab.websiteUi.address.value
                                || tab.target
                                || '';
                            window.open(buildWebsiteTabUrl(tab.serverId, nextTabId, current), '_blank', 'noopener');
                        });
                    }

                    reconnectButton.addEventListener('click', () => restartTab(tab));
                    closeOverlayButton.addEventListener('click', () => closeTab(tab.id));
                    // A click into the tab pulls focus onto the surface so that key presses land in
                    // the remote session. A click on a CONTROL belongs to that control, though:
                    // grabbing the focus otherwise closed every select in the file manager the
                    // moment it had opened - changing folders was impossible.
                    panel.addEventListener('click', event => {
                        const control = event.target instanceof Element
                            ? event.target.closest('input, select, textarea, button, a, label, [contenteditable]')
                            : null;
                        if (control) {
                            return;
                        }

                        panel.focus();
                    });
                    // Focus leaving the surface - a click on the toolbar, the tab strip, the address bar - takes the
                    // keyboard with it, and the release of whatever is held with it. Moving to something INSIDE the
                    // panel, the hidden field of the on-screen keyboard, is not leaving.
                    panel.addEventListener('focusout', event => {
                        if (event.relatedTarget instanceof Node && panel.contains(event.relatedTarget)) {
                            return;
                        }

                        releaseHeldKeys(tab);
                    });

                    tabs.set(tab.id, tab);
                    activateTab(tab.id);
                    updateTabActions();
                    startTab(tab);
                    saveWorkspaceTabs();
                    return tab;
                }

                // A key that is down when the keyboard leaves a session never reports its release to this
                // page: Ctrl for Ctrl+Tab (which switches BROWSER tabs), Alt for Alt+Tab, the Windows key, a
                // virtual desktop. The remote desktop then keeps it pressed - every click is a Ctrl+click,
                // every letter a shortcut - until the key is pressed once more, and a held letter goes on
                // repeating, because the auto-repeat of Guacamole runs until the release it never gets.
                // Guacamole.Keyboard lets go of what it knows to be down only when told to, so it is told
                // whenever the keyboard may have gone elsewhere: the window loses focus, the page is hidden,
                // focus leaves the surface of the session, another tab comes to the front.
                function releaseHeldKeys(tab) {
                    if (tab && tab.keyboard) {
                        passHeldPasteOn(tab);
                        tab.keyboard.reset();
                        // Its own idea of which modifiers are down goes too: one that is STILL held when the
                        // keyboard comes back is then pressed again by its next key, instead of being taken for
                        // a key that was never let go.
                        tab.keyboard.modifiers = new Guacamole.Keyboard.ModifierState();
                    }
                }

                function releaseAllHeldKeys() {
                    for (const tab of tabs.values()) {
                        releaseHeldKeys(tab);
                    }
                }

                // Every session but the one that is shown now.
                function releaseInactiveHeldKeys() {
                    for (const tab of tabs.values()) {
                        if (tab.id !== activeTabId) {
                            releaseHeldKeys(tab);
                        }
                    }
                }

                function activateTab(tabId) {
                    if (!tabs.has(tabId)) {
                        return;
                    }

                    activeTabId = tabId;
                    activeShellTabId = '';
                    setWorkspaceVisible(true);
                    newConnectionTab.classList.remove('active');
                    newConnectionPanel.classList.add('hidden');
                    document.title = `${tabs.get(tabId)?.name || ui('dashboard')} - Matgate`;
                    shellTabs.forEach(tab => {
                        tab.button.classList.remove('active');
                        tab.panel.classList.add('hidden');
                    });
                    for (const tab of tabs.values()) {
                        const active = tab.id === tabId;
                        tab.tabButton.classList.toggle('active', active);
                        tab.panel.classList.toggle('hidden', !active);
                    }
                    releaseInactiveHeldKeys();

                    const activeTab = tabs.get(tabId);
                    fitDisplay(activeTab);
                    activeTab.panel.focus();
                    activeTab.tabButton.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                    updateTabActions();
                    dropKeyboardHolder(activeTab.panel);
                    recheckKeyboardSoon();
                    saveTabOrder();
                    saveWorkspaceTabs();
                    // The overview of an agent is fresh every time one comes back to it: a program started or
                    // ended in the meantime shows up.
                    if (isAgentTab(activeTab) && activeTab.agentView === 'home' && activeTab.displayRoot.querySelector('.agent-home-inner')) {
                        startAgentHome(activeTab);
                    }
                }

                // Report the session as still open, so the gateway does not sweep away the file areas
                // it prepared for it. Matgate has no other way to know: the tunnel runs between this
                // browser and Guacamole and never touches the gateway.
                function startSessionKeepalive(tab) {
                    stopSessionKeepalive(tab);
                    tab.sessionKeepaliveTimer = window.setInterval(() => {
                        if (!tab.fileSessionId) {
                            return;
                        }

                        fetch(`/api/sessions/${encodeURIComponent(tab.fileSessionId)}/keepalive`, { method: 'POST', keepalive: true })
                            .catch(() => {});
                    }, 60000);
                }

                function stopSessionKeepalive(tab) {
                    if (tab.sessionKeepaliveTimer) {
                        window.clearInterval(tab.sessionKeepaliveTimer);
                        tab.sessionKeepaliveTimer = null;
                    }
                }

                // Tell the gateway the session is over, so its file areas go now instead of waiting
                // for the sweeper. Best effort by nature - a crash or a killed browser never gets
                // here, which is why the gateway also sweeps on its own.
                function releaseSessionFiles(tab) {
                    stopSessionKeepalive(tab);
                    const sessionId = tab.fileSessionId;
                    if (!sessionId) {
                        return;
                    }

                    tab.fileSessionId = '';
                    const url = `/api/sessions/${encodeURIComponent(sessionId)}/close`;
                    try {
                        if (!navigator.sendBeacon || !navigator.sendBeacon(url)) {
                            fetch(url, { method: 'POST', keepalive: true }).catch(() => {});
                        }
                    }
                    catch {
                        fetch(url, { method: 'POST', keepalive: true }).catch(() => {});
                    }
                }

                // Keep the browser-farm slot reserved while a farm-website tab is open.
                function startBrowserFarmKeepalive(tab) {
                    stopBrowserFarmKeepalive(tab);
                    tab.browserFarmTimer = window.setInterval(() => {
                        if (!tab.browserSessionId) {
                            return;
                        }

                        fetch(`/api/browser-sessions/${tab.browserSessionId}/keepalive`, { method: 'POST', keepalive: true })
                            .catch(() => {});
                    }, 30000);
                }

                function stopBrowserFarmKeepalive(tab) {
                    if (tab.browserFarmTimer) {
                        window.clearInterval(tab.browserFarmTimer);
                        tab.browserFarmTimer = null;
                    }
                }

                // Free the pool slot when the tab closes (sendBeacon survives page unload).
                function releaseBrowserFarm(tab) {
                    stopBrowserFarmKeepalive(tab);
                    const sessionId = tab.browserSessionId;
                    if (!sessionId) {
                        return;
                    }

                    tab.browserSessionId = '';
                    const url = `/api/browser-sessions/${sessionId}/close`;
                    try {
                        if (!navigator.sendBeacon || !navigator.sendBeacon(url)) {
                            fetch(url, { method: 'POST', keepalive: true }).catch(() => {});
                        }
                    }
                    catch {
                        fetch(url, { method: 'POST', keepalive: true }).catch(() => {});
                    }
                }

                function closeTab(tabId) {
                    const tab = tabs.get(tabId);
                    if (!tab) {
                        return;
                    }

                    releaseBrowserFarm(tab);
                    releaseSessionFiles(tab);
                    tab.terminal = true;
                    window.clearInterval(tab.watchdog);
                    if (tab.client) {
                        tab.client.disconnect();
                    }
                    if (tab.websiteUi?.frame) {
                        tab.websiteUi.frame.src = 'about:blank';
                    }

                    if (credentialTab && credentialTab.id === tabId) {
                        closeCredentialDialog();
                    }

                    tab.tabButton.remove();
                    tab.panel.remove();
                    tabs.delete(tabId);

                    if (activeTabId === tabId) {
                        const next = tabs.values().next().value;
                        activeTabId = null;
                        if (next) {
                            activateTab(next.id);
                        }
                        else {
                            activateNewConnectionTab();
                        }
                    }

                    updateTabActions();
                    saveTabOrder();
                    saveWorkspaceTabs();
                }

                // --- Pop a session out into its own window, and hand it back ----------------------
                // A live session (WebSocket + picture) is bound to its window and cannot be carried over, so
                // moving it between windows opens the connection anew in the other one (a brief reconnect).
                //
                // A window of its own shows that one session and nothing else - no tab strip, no side panel,
                // no menu - with a button that hands it back. The main window lists the windows that are out
                // beside its tabs: a click brings one to the front, its arrow fetches the session back.
                // The windows find each other over a BroadcastChannel, so the way back works also when the
                // main window was loaded anew (and the popped one lost its opener); with no main window left
                // the popped one becomes the main window itself.
                const windowChannel = (() => { try { return new BroadcastChannel('matgate-windows'); } catch { return null; } })();
                const thisWindowKey = 'w' + Math.random().toString(36).slice(2) + Date.now().toString(36);
                const poppedHandles = new Map();
                const poppedWindows = new Map();
                const poppedList = document.getElementById('popped-windows');

                function serverIdOfShellTab(shellTab) {
                    const screen = agentScreenOf(shellTab);
                    if (screen && screen.serverId) {
                        return screen.serverId;
                    }

                    const match = /\/([0-9a-fA-F-]{36})(\/|$)/.exec(String((shellTab && shellTab.url) || ''));
                    return match && findServer(match[1]) ? match[1] : '';
                }

                function popOutServer(serverId, closeHere) {
                    if (!serverId) {
                        return false;
                    }

                    const key = 'matgate-pop-' + serverId + '-' + Date.now();
                    const win = window.open('/?open=' + encodeURIComponent(serverId) + '&popped=1&key=' + encodeURIComponent(key), key, 'popup,width=1280,height=860');
                    if (!win) {
                        if (statusMessage) {
                            statusMessage.textContent = uiText.popupBlocked || 'Allow pop-ups to open this in a new window.';
                        }

                        return false;
                    }

                    poppedHandles.set(key, win);
                    const server = findServer(serverId);
                    poppedWindows.set(key, { key, serverId, name: (server && server.name) || '', seen: Date.now() });
                    renderPoppedWindows();
                    closeHere();
                    return true;
                }

                function popOutTab(tab) {
                    if (tab && tab.serverId) {
                        popOutServer(tab.serverId, () => closeTab(tab.id));
                    }
                }

                function popOutShellTab(shellTab) {
                    popOutServer(serverIdOfShellTab(shellTab), () => closeShellTab(shellTab.id));
                }

                // The popped window hands its session back: to the window that opened it if that one is still
                // there, otherwise to whichever main window answers first; none answering, it becomes one.
                function reattachServer(serverId) {
                    if (!serverId) {
                        window.close();
                        return;
                    }

                    try {
                        if (window.opener && !window.opener.closed && window.opener.location.origin === location.origin
                            && typeof window.opener.MatgateTakeBack === 'function') {
                            window.opener.MatgateTakeBack(serverId);
                            try { window.opener.focus(); } catch { /* the browser decides */ }
                            window.close();
                            return;
                        }
                    }
                    catch {
                        // The opener is gone or another page now: ask around instead.
                    }

                    const ask = thisWindowKey + '-' + Date.now();
                    let answered = false;
                    const onOffer = event => {
                        const data = event.data || {};
                        if (data.type === 'reattach-offer' && data.ask === ask && !answered) {
                            answered = true;
                            windowChannel.postMessage({ type: 'reattach-to', target: data.window, serverId });
                            window.setTimeout(() => window.close(), 150);
                        }
                    };
                    if (windowChannel) {
                        windowChannel.addEventListener('message', onOffer);
                        windowChannel.postMessage({ type: 'reattach-ask', ask });
                    }

                    window.setTimeout(() => {
                        if (!answered) {
                            // No main window anywhere: this one becomes it, with the session in it.
                            location.href = '/?open=' + encodeURIComponent(serverId);
                        }
                    }, windowChannel ? 700 : 0);
                }

                function reattachTab(tab) {
                    reattachServer(tab && tab.serverId);
                }

                function reattachShellTab(shellTab) {
                    reattachServer(serverIdOfShellTab(shellTab));
                }

                // The main window takes a session back. Also callable straight from the popped window.
                window.MatgateTakeBack = serverId => {
                    if (isPoppedWindow) {
                        return;
                    }

                    openServer(serverId);
                    try { window.focus(); } catch { /* ignore */ }
                };

                // Old windows still post this message.
                window.addEventListener('message', event => {
                    if (event.origin !== location.origin) {
                        return;
                    }

                    const data = event.data;
                    if (data && data.type === 'matgate-reattach' && data.kind === 'session' && data.serverId) {
                        window.MatgateTakeBack(data.serverId);
                    }
                });

                // The list of popped windows in the main window, beside the tabs.
                function renderPoppedWindows() {
                    if (!poppedList || isPoppedWindow) {
                        return;
                    }

                    const now = Date.now();
                    for (const [key, entry] of poppedWindows) {
                        const handle = poppedHandles.get(key);
                        if ((handle && handle.closed) || (!handle && now - entry.seen > 8000)) {
                            poppedWindows.delete(key);
                            poppedHandles.delete(key);
                        }
                    }

                    const entries = Array.from(poppedWindows.values());
                    poppedList.hidden = entries.length === 0;
                    poppedList.replaceChildren(...entries.map(entry => {
                        const server = findServer(entry.serverId);
                        const item = document.createElement('div');
                        item.className = 'popped-window';
                        item.dataset.poppedKey = entry.key;
                        item.style.setProperty('--proto', (server && server.protoColor) || 'var(--accent)');
                        const focus = document.createElement('button');
                        focus.type = 'button';
                        focus.className = 'popped-window-focus';
                        focus.title = uiText.poppedFocus || 'Bring the window to the front';
                        focus.innerHTML = `<span class="popped-window-icon" aria-hidden="true">${(server && server.iconHtml) || actionIcons.popOut || ''}</span><span class="popped-window-name"></span>`;
                        focus.querySelector('.popped-window-name').textContent = entry.name || (server && server.name) || '';
                        focus.addEventListener('click', () => {
                            const handle = poppedHandles.get(entry.key);
                            if (handle && !handle.closed) {
                                handle.focus();
                            }
                            else if (windowChannel) {
                                windowChannel.postMessage({ type: 'focus', key: entry.key });
                            }
                        });
                        const back = document.createElement('button');
                        back.type = 'button';
                        back.className = 'popped-window-back';
                        back.title = uiText.reattachToMain || 'Re-attach to main window';
                        back.setAttribute('aria-label', back.title);
                        back.innerHTML = actionIcons.reattach || '';
                        back.addEventListener('click', () => {
                            poppedWindows.delete(entry.key);
                            const handle = poppedHandles.get(entry.key);
                            poppedHandles.delete(entry.key);
                            if (windowChannel) {
                                windowChannel.postMessage({ type: 'close', key: entry.key });
                            }
                            try { if (handle && !handle.closed) { handle.close(); } } catch { /* ignore */ }
                            renderPoppedWindows();
                            openServer(entry.serverId);
                        });
                        item.append(focus, back);
                        return item;
                    }));
                }

                if (windowChannel) {
                    windowChannel.addEventListener('message', event => {
                        const data = event.data || {};
                        if (!isPoppedWindow) {
                            if (data.type === 'reattach-ask') {
                                windowChannel.postMessage({ type: 'reattach-offer', ask: data.ask, window: thisWindowKey });
                            }
                            else if (data.type === 'reattach-to' && data.target === thisWindowKey) {
                                window.MatgateTakeBack(data.serverId);
                            }
                            else if (data.type === 'popped-alive') {
                                poppedWindows.set(data.key, { key: data.key, serverId: data.serverId, name: data.name || '', seen: Date.now() });
                                renderPoppedWindows();
                            }
                            else if (data.type === 'popped-gone') {
                                poppedWindows.delete(data.key);
                                poppedHandles.delete(data.key);
                                renderPoppedWindows();
                            }
                        }
                        else if (data.key && data.key === poppedKey) {
                            if (data.type === 'close') {
                                window.close();
                            }
                            else if (data.type === 'focus') {
                                try { window.focus(); } catch { /* the browser decides */ }
                            }
                        }
                    });
                }

                if (!isPoppedWindow) {
                    window.setInterval(renderPoppedWindows, 3000);
                }

                // A popped window says that it is there - so a main window loaded anew lists it again - and
                // goes when its session went.
                let poppedHadSession = false;
                function poppedSessionServer() {
                    const tab = tabs.values().next().value;
                    if (tab) {
                        return tab.serverId;
                    }

                    const shellTab = shellTabs.values().next().value;
                    return shellTab ? serverIdOfShellTab(shellTab) : '';
                }
                function checkPoppedWindow() {
                    if (!isPoppedWindow) {
                        return;
                    }

                    const serverId = poppedSessionServer();
                    if (serverId) {
                        poppedHadSession = true;
                        const server = findServer(serverId);
                        if (server && server.name && document.title !== server.name) {
                            document.title = server.name;
                        }
                    }
                    else if (poppedHadSession) {
                        window.close();
                    }
                }
                if (isPoppedWindow) {
                    window.setInterval(() => {
                        const serverId = poppedSessionServer();
                        if (windowChannel && serverId) {
                            const server = findServer(serverId);
                            windowChannel.postMessage({ type: 'popped-alive', key: poppedKey, serverId, name: (server && server.name) || '' });
                        }
                    }, 2500);
                    window.addEventListener('pagehide', () => {
                        if (windowChannel) {
                            windowChannel.postMessage({ type: 'popped-gone', key: poppedKey });
                        }
                    });
                }

                // The file areas over the running session instead of next to it: the session keeps its
                // tab either way, but this way it stays on screen behind the dialog - which is what you
                // want while moving a file from an area into the session's drive.
                //
                // The manager itself is not rebuilt for this. The area opens as an ordinary tab, its
                // panel is lifted into the dialog, and it goes back to the deck on close. The tab's
                // button is hidden while the dialog owns it, so the strip does not grow a second entry
                // for something that is already on screen.
                // The dialog is NOT a tab. It used to borrow one - create it, lift its panel out of the
                // deck and hide its button - and that is where the odd behaviour came from: the strip
                // lost its selection because the active tab was the hidden one, and closing left a tab
                // behind. It only ever needed the file manager, not the tab machinery around it, so it
                // builds the handful of elements the manager writes into and runs it on those.
                let fileAreaHost = null;

                function buildFileAreaHost(server) {
                    const panel = document.createElement('div');
                    panel.className = 'connection-panel file-area-host';

                    const overlay = document.createElement('div');
                    overlay.className = 'connection-overlay hidden';
                    const overlayTitle = document.createElement('h2');
                    const overlayMessage = document.createElement('p');
                    const overlayActions = document.createElement('div');
                    overlayActions.className = 'overlay-actions hidden';
                    overlay.append(overlayTitle, overlayMessage, overlayActions);

                    const displayRoot = document.createElement('div');
                    panel.append(overlay, displayRoot);

                    return {
                        id: 'file-area-dialog',
                        serverId: server.id,
                        name: server.name,
                        protocol: server.protocol,
                        panel,
                        displayRoot,
                        overlay,
                        overlayTitle,
                        overlayMessage,
                        overlayActions,
                        // Written to by setStatus; the dialog has no status bar of its own.
                        // A line that is really visible: setStatus used to write into a span that was
                        // never in the tree.
                        statusLabel: document.getElementById('file-area-dialog-status') || document.createElement('span'),
                        selectedFilePaths: new Set(),
                    };
                }

                // Two groups instead of one long list: at the top what belongs to the here and
                // now - this session's folder, the place you are in, your own and the shared
                // files. Below that the places of the other connections.
                // Not an id but a marker: picking it does not switch places, it makes one.
                const CREATE_PLACE = '__create-place__';

                // The confirmation sheet is the layout's, shared by every page; the shell only passes
                // its own words (the delete label comes from its ui strings).
                function askToConfirm(options) {
                    return window.MatgateAskToConfirm({ confirm: ui('delete'), ...options });
                }

                // Asks for a name and hands it to the caller's work. Resolves with whatever that
                // work returns, or with null when the sheet was closed. A refusal is said inside the
                // sheet, which stays open: that is where the person is looking, and what they typed
                // is still there.
                //
                //   await askForName({ title, hint, label, value, confirm, work: async name => ... })
                //
                // `work` throws to keep the sheet open with its message, and returns the value the
                // caller wants back.
                function askForName(options) {
                    const dialog = document.getElementById('name-dialog');
                    const nameField = document.getElementById('name-dialog-input');
                    if (!dialog || !nameField) {
                        return Promise.resolve(null);
                    }

                    const titleLine = dialog.querySelector('[data-name-title]');
                    const hintLine = dialog.querySelector('[data-name-hint]');
                    const labelLine = dialog.querySelector('[data-name-label]');
                    const errorLine = dialog.querySelector('[data-name-error]');
                    const confirmButton = dialog.querySelector('[data-name-confirm]');
                    const closeButton = dialog.querySelector('[data-name-close]');

                    return new Promise(resolve => {
                        const finish = value => {
                            dialog.classList.add('hidden');
                            dialog.removeEventListener('submit', onSubmit);
                            closeButton.removeEventListener('click', onCancel);
                            document.removeEventListener('keydown', onKey);
                            resolve(value);
                        };

                        const onCancel = () => finish(null);
                        const onKey = event => {
                            if (event.key === 'Escape') {
                                event.preventDefault();
                                finish(null);
                            }
                        };

                        async function onSubmit(event) {
                            event.preventDefault();
                            const name = nameField.value.trim();
                            if (!name) {
                                nameField.focus();
                                return;
                            }

                            confirmButton.disabled = true;
                            try {
                                finish(await options.work(name));
                            }
                            catch (error) {
                                errorLine.textContent = (error && error.message) || ui('actionFailed');
                                errorLine.classList.remove('hidden');
                            }
                            finally {
                                confirmButton.disabled = false;
                            }
                        }

                        titleLine.textContent = options.title || '';
                        hintLine.textContent = options.hint || '';
                        hintLine.classList.toggle('hidden', !options.hint);
                        labelLine.textContent = options.label || ui('name');
                        confirmButton.textContent = options.confirm || ui('save');
                        nameField.value = options.value || '';
                        errorLine.textContent = '';
                        errorLine.classList.add('hidden');
                        dialog.classList.remove('hidden');
                        dialog.addEventListener('submit', onSubmit);
                        closeButton.addEventListener('click', onCancel);
                        document.addEventListener('keydown', onKey);
                        window.setTimeout(() => {
                            nameField.focus();
                            // The extension stays out of the selection: renaming usually means
                            // changing the name, not the kind of file.
                            const dot = nameField.value.lastIndexOf('.');
                            nameField.setSelectionRange(
                                0,
                                options.selectAll || dot <= 0 ? nameField.value.length : dot);
                        }, 0);
                    });
                }

                // A place with a folder of its own. Everything else - link, password, expiry - is
                // set afterwards in its settings, because at this moment nobody knows yet what the
                // place is for. The list of places is fetched again before returning, otherwise the
                // new one would be missing from the very select that made it.
                function createPlace() {
                    return askForName({
                        title: ui('newPlace'),
                        hint: ui('newPlaceHint'),
                        confirm: ui('create'),
                        work: async name => {
                            const data = new FormData();
                            data.append('name', name);
                            const response = await fetch('/api/files/places', {
                                method: 'POST',
                                body: data,
                                credentials: 'same-origin',
                                headers: { 'X-Matgate-Csrf': csrfToken }
                            });
                            if (!response.ok) {
                                const payload = await response.json().catch(() => ({}));
                                throw new Error(payload.error || ui('newPlaceFailed'));
                            }

                            const payload = await response.json();
                            await refreshConnectionsPanel();
                            return payload.placeId || null;
                        }
                    });
                }

                function placeOptionGroups(places, currentId) {
                    // A workspace is not a connection - so it gets a group of its own and not the
                    // heading "Other connections".
                    const isWorkspace = place => (place.areaKind || '') === 'workspace';
                    const belongsHere = place => !isWorkspace(place)
                        && (place.id === currentId || ['user', 'global'].includes(place.areaKind || ''));
                    const rank = place => place.id === currentId ? 0 : (place.areaKind === 'user' ? 1 : 2);
                    const current = places.filter(belongsHere).sort((a, b) => rank(a) - rank(b));
                    const workspacePlaces = places.filter(isWorkspace);
                    const others = places.filter(place => !belongsHere(place) && !isWorkspace(place));
                    const option = place => `<option value="${escapeHtml(place.id)}"${place.id === currentId ? ' selected' : ''}>${escapeHtml(place.name)}</option>`;
                    const group = (label, items) => (items.length
                        ? `<optgroup label="${escapeHtml(label)}">${items.map(option).join('')}</optgroup>`
                        : '');

                    // The last entry under the workspaces makes a new one. A place is created where
                    // it is used - since the workspace page left the menu there was no way to make
                    // one at all, because sharing only ever turns an EXISTING place into a share.
                    const createEntry = `<option value="${CREATE_PLACE}">${escapeHtml(ui('newPlace'))}</option>`;
                    const workspaceGroup = `<optgroup label="${escapeHtml(ui('placesWorkspaces'))}">`
                        + workspacePlaces.map(option).join('') + createEntry + '</optgroup>';

                    // The groups are always named now: with the create entry there is always a
                    // second one, so a lone unnamed list cannot occur any more.
                    return group(ui('placesCurrent'), current)
                        + workspaceGroup
                        + group(ui('placesOther'), others);
                }

                // The areas this user can reach, so one dialog manages all of them instead of showing
                // whichever one it happened to be opened with. The connection's own area comes first
                // when the dialog was opened from a session - that is the one meant by "its files".
                function fileAreaChoices(preferredId) {
                    const areas = availableServers.filter(server => (server.protocol || '').toUpperCase() === 'LOCAL');
                    const preferred = areas.filter(server => server.id === preferredId);
                    return preferred.concat(areas.filter(server => server.id !== preferredId));
                }

                async function openFileAreaDialog(areaId) {
                    // The places may have changed since the page was loaded: a second session has
                    // been added, another one ended.
                    await refreshConnectionsPanel();
                    const choices = fileAreaChoices(areaId);
                    if (!choices.length) {
                        return;
                    }

                    // The same two groups as in the file manager: the here and now at the top, the
                    // places of the other connections below.
                    fileAreaDialogSelect.innerHTML = placeOptionGroups(choices, choices[0].id);

                    showFileArea(choices[0].id);

                    // "Into the session" needs a session with a file channel - a VNC session, a
                    // website or a file-manager tab has none. The button was there anyway and then
                    // did nothing but close the dialog. Set inline, because .hidden loses against
                    // the button rules here.
                    const sessionTab = tabs.get(activeTabId || '');
                    fileAreaDialogSend.style.display = (sessionTab && sessionTab.filesystem && !sessionTab.terminal)
                        ? ''
                        : 'none';
                    fileAreaDialog.classList.remove('hidden');
                }

                // When the place changes the queue does not belong there any more. It used to
                // vanish silently: whoever switched places during a batch lost the rest without
                // a word. Now it is cancelled and says so.
                function abandonUploads(tab) {
                    let dropped = 0;
                    ((tab && tab.uploadQueue) || []).forEach(item => {
                        if (item.status !== 'queued' && item.status !== 'uploading') {
                            return;
                        }

                        item.status = 'failed';
                        item.error = uiText.uploadCancelled || 'Abgebrochen';
                        dropped += 1;
                        if (item.xhr) {
                            try { item.xhr.abort(); } catch (e) { /* schon beendet */ }
                        }
                    });

                    return dropped;
                }

                // Point the same file manager at another place instead of opening a second one.
                // What is in the tab. A place says that it is one: "Files: User". Before, it
                // just said "User" - among tabs that are remote sessions, that read like a
                // machine name. In ONE place, because the title is built in two spots (new tab
                // and switching place in the same tab) and two versions would sooner or later
                // drift apart.
                function tabTitleHtml(server) {
                    const isPlace = (server.protocol || '').toUpperCase() === 'LOCAL';
                    const text = isPlace ? `${ui('filesPrefix')}: ${server.name}` : server.name;
                    return `${server.iconHtml || ''}<span>${escapeHtml(text)}</span>`;
                }

                function switchFileTabTo(tab, serverId) {
                    const server = findServer(serverId);
                    if (!tab || !server) {
                        return;
                    }

                    const dropped = abandonUploads(tab);
                    tab.serverId = server.id;
                    tab.name = server.name;
                    tab.protocol = server.protocol;
                    tab.iconHtml = server.iconHtml;
                    tab.iconKey = server.iconKey;
                    tab.target = server.target;
                    tab.fileAreaId = server.fileAreaId || '';
                    tab.filePath = '/';
                    tab.initialFilePath = '';
                    tab.uploadQueue = [];
                    const title = tab.tabMain ? tab.tabMain.querySelector('.session-tab-title') : null;
                    if (title) {
                        title.innerHTML = tabTitleHtml(server);
                    }

                    startFileTab(tab);
                    if (dropped) {
                        setFileMessage(tab, `${dropped} ${uiText.uploadCancelled || 'Abgebrochen'}`, 'error');
                    }

                    updateStatusBar();
                }

                function showFileArea(areaId) {
                    const server = findServer(areaId);
                    if (!server) {
                        return;
                    }

                    // The previous host is about to disappear - whatever it still wanted to upload
                    // has to be cancelled and reported instead of silently vanishing.
                    abandonUploads(fileAreaHost);
                    // Keeps the field at the top in step with the place being shown - even when the
                    // change came from somewhere else.
                    if (fileAreaDialogSelect.value !== server.id) {
                        fileAreaDialogSelect.value = server.id;
                    }
                    fileAreaHost = buildFileAreaHost(server);
                    fileAreaDialogBody.replaceChildren(fileAreaHost.panel);
                    startFileTab(fileAreaHost);
                }

                // Takes what is selected in the area and hands it to the session the dialog was opened
                // from. The files are fetched through the file API and then go down the ordinary upload
                // path - so they end up in the area the session asks for, one at a time, with the same
                // handling of a connection that drops halfway.
                async function sendSelectionIntoSession() {
                    const areaTab = fileAreaHost;
                    const sessionTab = tabs.get(activeTabId || '');
                    if (!areaTab || !sessionTab) {
                        return;
                    }

                    const paths = Array.from(areaTab.selectedFilePaths || []);
                    if (!paths.length) {
                        flashStatus(sessionTab, uiText.selectFilesFirst || 'Select the files first');
                        return;
                    }

                    const files = [];
                    for (const path of paths) {
                        try {
                            const response = await fetch(`/api/files/${areaTab.serverId}/download?path=${encodeURIComponent(path)}`);
                            if (!response.ok) {
                                continue;
                            }

                            const blob = await response.blob();
                            files.push(new File([blob], path.split('/').pop() || 'file', { type: blob.type }));
                        }
                        catch (e) {
                            // A single file that cannot be read must not stop the rest.
                        }
                    }

                    if (!files.length) {
                        flashStatus(sessionTab, uiText.xferUploadFailed || 'Upload failed');
                        return;
                    }

                    closeFileAreaDialog();
                    uploadFilesToSession(sessionTab, files);
                }

                function closeFileAreaDialog() {
                    // Nothing to put back and no tab to clean up - the dialog owned everything it used.
                    const dropped = abandonUploads(fileAreaHost);
                    if (dropped) {
                        const sessionTab = tabs.get(activeTabId || '');
                        if (sessionTab) {
                            flashStatus(sessionTab, `${dropped} ${uiText.uploadCancelled || 'Abgebrochen'}`);
                        }
                    }

                    fileAreaDialog.classList.add('hidden');
                    fileAreaDialogBody.replaceChildren();
                    fileAreaHost = null;
                }

                // Matgate's own engine: RDP and VNC as a screen, SSH as a terminal - each in
                // a page tab, steered by the session toolbar. Guacamole shows a connection only when it says so
                // (or when its own engine is not available here).
                function ownEnginePath(server) {
                    // A database opens in the database browser.
                    const kind = ((server && server.protocol) || '').toUpperCase();
                    if (kind === 'MSSQL' || kind === 'MYSQL' || kind === 'POSTGRES') {
                        return '/db/' + encodeURIComponent(server.id) + '/browser';
                    }

                    if (!server || server.engine !== 'matgate') {
                        return '';
                    }

                    const protocol = (server.protocol || '').toUpperCase();
                    if (protocol === 'RDP' || protocol === 'VNC') {
                        return '/display/' + encodeURIComponent(server.id) + '/screen';
                    }

                    return protocol === 'SSH' ? '/ssh/' + encodeURIComponent(server.id) + '/terminal' : '';
                }

                function openServer(serverId, filePath = '', tabId = '', another = false) {
                    const server = findServer(serverId);
                    const own = ownEnginePath(server);
                    if (own) {
                        // A tab of its own every time: two sessions to the same machine are two tabs.
                        openShellTab(
                            // "another": a second session on purpose - the page does not ask whether one is open already.
                            own + '?tab=' + Math.random().toString(36).slice(2, 10) + (another ? '&fresh=1' : ''),
                            server.name || '',
                            server.iconHtml || '',
                            (server.protocol || '') + ' ' + (server.target || ''));
                        return null;
                    }

                    if (server) {
                        return createTab(server, { filePath, tabId });
                    }

                    return null;
                }

                function CssClasses(baseClass, className = '') {
                    const extra = (className || '').toString().trim();
                    return extra ? `${baseClass} ${extra}` : baseClass;
                }

                function Attr(name, value) {
                    const text = value === null || value === undefined ? '' : value.toString();
                    return text ? ` ${name}="${escapeHtml(text)}"` : '';
                }

                function BoolAttr(name, value) {
                    return value ? ` ${name}` : '';
                }

                function Toolbar(className, ...groups) {
                    return `<div class="${escapeHtml(CssClasses('toolbar', className))}">${groups.filter(Boolean).join('')}</div>`;
                }

                function ToolbarGroup(className, ...items) {
                    return `<div class="${escapeHtml(CssClasses('toolbar-group', className))}">${items.filter(Boolean).join('')}</div>`;
                }

                function ToolbarButton(label, iconHtml, className = '', extraAttributes = '', disabled = false) {
                    const attrs = `${extraAttributes ? ` ${extraAttributes.trim()}` : ''}${BoolAttr('disabled', disabled)}`;
                    return `<button type="button" class="${escapeHtml(CssClasses('toolbar-button', className))}"${attrs}>${iconHtml || ''}<span>${escapeHtml(label || '')}</span></button>`;
                }

                function ToolbarIconButton(label, iconHtml, className = '', extraAttributes = '', disabled = false) {
                    const attrs = `${Attr('aria-label', label)}${extraAttributes ? ` ${extraAttributes.trim()}` : ''}${BoolAttr('disabled', disabled)}`;
                    return `<button type="button" class="${escapeHtml(CssClasses('toolbar-button toolbar-icon-button', className))}"${attrs}>${iconHtml || ''}</button>`;
                }

                function ToolbarInput(className, value, ariaLabel, readOnly = false, extraAttributes = '') {
                    const attrs = `${Attr('aria-label', ariaLabel)}${Attr('value', value)}${BoolAttr('readonly', readOnly)}${extraAttributes ? ` ${extraAttributes.trim()}` : ''}`;
                    return `<input type="text" class="${escapeHtml(CssClasses('toolbar-input', className))}"${attrs}>`;
                }

                // A button and the panel it opens. Not <details>: that element did not open in an iPhone
                // app installed to the home screen, and the two menus of the file manager were dead there.
                // How it behaves - a dropdown, or a sheet over the whole screen on a phone, and closing -
                // is the layout script's; it finds the button by data-menu-toggle.
                function ToolbarMenu(className, summaryClassName, summaryLabel, summaryIconHtml, summaryAttributes = '', ...items) {
                    const attrs = summaryAttributes ? ` ${summaryAttributes.trim()}` : '';
                    const chevron = fileIcon('chevronDown');
                    return `
                        <div class="${escapeHtml(CssClasses('toolbar-menu', className))}">
                            <button type="button" class="${escapeHtml(CssClasses('toolbar-button toolbar-menu-trigger', summaryClassName))}" data-menu-toggle aria-haspopup="true" aria-expanded="false"${attrs}>${summaryIconHtml || ''}<span>${escapeHtml(summaryLabel || '')}</span><span class="menu-caret">${chevron}</span></button>
                            <div class="toolbar-menu-panel file-menu-panel" role="menu" data-menu-title="${escapeHtml(summaryLabel || '')}" hidden>${items.filter(Boolean).join('')}</div>
                        </div>`;
                }

                function ToolbarMenuItem(label, iconHtml, className = '', extraAttributes = '', disabled = false) {
                    return ToolbarButton(label, iconHtml, CssClasses('toolbar-menu-item', className), extraAttributes, disabled);
                }

                function ToolbarUploadButton(label, iconHtml, className = '', inputClassName = '', inputAttributes = '') {
                    const attrs = inputAttributes ? ` multiple ${inputAttributes.trim()}` : ' multiple';
                    return `
                        <label class="${escapeHtml(CssClasses('toolbar-button toolbar-button--primary toolbar-upload-button', className))}" title="${escapeHtml(label || '')}">
                            ${iconHtml || ''}<span>${escapeHtml(label || '')}</span>
                            <input type="file" name="file" class="${escapeHtml(CssClasses('toolbar-upload-input file-upload-input', inputClassName))}"${attrs}>
                        </label>`;
                }

                function saveWorkspaceTabs() {
                    if (isPoppedWindow) { return; }
                    try {
                        const activeTab = tabs.get(activeTabId);
                        const orderedTabs = orderedSessionTabs();
                        const state = {
                            tabs: orderedTabs.map(tab => ({
                                tabId: tab.id,
                                serverId: tab.serverId,
                                filePath: isFileProtocol(tab.protocol) ? (tab.filePath || '/') : ''
                            })),
                            activeTabId: activeTab ? activeTab.id : '',
                            // What was in front of all tabs - this one, a page tab (Matgate's own engine, files, ...)
                            // or the start page - so it is that again after a restart.
                            front: activeTab ? 'tab' : (activeShellTabId ? 'page' : 'home')
                        };

                        localStorage.setItem(workspaceStorageKey, JSON.stringify(state));
                        scheduleTabStatePush();
                    }
                    catch {
                        // Local storage is optional; restoring tabs is a convenience.
                    }
                }

                function loadWorkspaceTabs() {
                    try {
                        const raw = localStorage.getItem(workspaceStorageKey);
                        if (!raw) {
                            return { tabs: [], activeTabId: '', activeServerId: '' };
                        }

                        const state = JSON.parse(raw);
                        const tabStates = Array.isArray(state.tabs) ? state.tabs : [];
                        return {
                            tabs: tabStates
                                .map(tabState => typeof tabState === 'string'
                                    ? { serverId: tabState, filePath: '', tabId: '' }
                                    : {
                                        tabId: tabState.tabId || tabState.tabID || tabState.id || '',
                                        serverId: tabState.serverId || tabState.id || '',
                                        filePath: tabState.filePath || tabState.path || ''
                                    })
                                .filter(tabState => Boolean(findServer(tabState.serverId))),
                            activeTabId: typeof state.activeTabId === 'string' ? state.activeTabId : '',
                            front: typeof state.front === 'string' ? state.front : '',
                            activeServerId: findServer(state.activeServerId) ? state.activeServerId : ''
                        };
                    }
                    catch {
                        return { tabs: [], activeTabId: '', activeServerId: '' };
                    }
                }

                async function fetchLaunch(tab) {
                    // Farm-website (VNC) sessions: send the client's viewport so the farm browser renders
                    // at the session's real resolution (RDP-style auto-size). The farm clamps the values.
                    let launchQuery = '';
                    if (tab.farmWebsite) {
                        const rect = tab.panel ? tab.panel.getBoundingClientRect() : null;
                        const rawW = Math.round(rect && rect.width ? rect.width : window.innerWidth);
                        const rawH = Math.round(rect && rect.height ? rect.height : window.innerHeight);
                        // Xvfb rounds the framebuffer UP to a multiple of 64; request a multiple of 64
                        // that is <= the panel so the remote size never exceeds (and clips) the display.
                        const floor64 = v => Math.max(64, Math.floor(v / 64) * 64);
                        const w = floor64(rawW);
                        const h = floor64(rawH);
                        if (w > 0 && h > 0) {
                            // Scale = the "Screen" preset (Fit=1 / Fit75=0.75 / Fit50=0.5): the farm
                            // renders the page at that device-scale so 75/50% shows more content.
                            const scale = fitScaleFor(tab.displayRes);
                            launchQuery = `?w=${w}&h=${h}&scale=${scale}`;
                            // Remember the RAW panel size this farm session was opened at, so a later
                            // window resize can smart-reconnect at the new size (VNC has no live resize).
                            tab.farmSize = { width: rawW, height: rawH };
                            tab.farmScale = scale;
                        }
                    }

                    const response = await fetch(`/api/connections/${tab.serverId}/launch${launchQuery}`, {
                        method: 'POST',
                        headers: { 'X-Matgate-Csrf': csrfToken }
                    });

                    if (!response.ok) {
                        let error = ui('connectionStartFailed');
                        try {
                            const payload = await response.json();
                            error = payload.error || error;
                        }
                        catch {
                            // Keep generic error.
                        }

                        throw new Error(error);
                    }

                    return await response.json();
                }

                async function authenticate(tab) {
                    const response = await fetch('/guacamole/api/tokens', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body: new URLSearchParams({ data: tab.encryptedData })
                    });

                    if (!response.ok) {
                        throw new Error('Guacamole hat den Starttoken abgelehnt.');
                    }

                    return await response.json();
                }

                function viewport(tab) {
                    if (isDesktopDisplayMode(tab)) {
                        const res = parseDisplayRes(tab.displayRes);
                        return { width: res.width, height: res.height, dpi: 96 };
                    }

                    const rect = tab.panel.getBoundingClientRect();
                    // Fit modes: request a proportionally larger remote resolution (fit75/fit50) so more
                    // content renders, then fitDisplay scales it down to fit the viewport.
                    const fitScale = fitScaleFor(tab && tab.displayRes);
                    return {
                        width: Math.max(320, Math.floor(rect.width / fitScale)),
                        height: Math.max(240, Math.floor(rect.height / fitScale)),
                        dpi: 96
                    };
                }

                // --- Pinch-to-zoom (touch) ------------------------------------------------
                // A purely client-side visual zoom applied to the scaler wrapper
                // (tab.displayScaler). It layers ON TOP of Guacamole's own display.scale
                // (which writes its transform to the inner element), so it never renegotiates
                // the remote resolution and survives fitDisplay (which only ever touches the
                // scaler's width/height, never its transform).
                function applyPinchTransform(tab) {
                    if (!tab || !tab.displayScaler) {
                        return;
                    }
                    const z = tab.pinchZoom || 1;
                    const x = tab.pinchPanX || 0;
                    const y = tab.pinchPanY || 0;
                    if (z <= 1 && x === 0 && y === 0) {
                        tab.displayScaler.style.transform = '';
                        tab.displayScaler.style.transformOrigin = '';
                        return;
                    }
                    tab.displayScaler.style.transformOrigin = '0 0';
                    tab.displayScaler.style.transform = 'translate(' + Math.round(x) + 'px, ' + Math.round(y) + 'px) scale(' + z + ')';
                }

                function resetPinchZoom(tab) {
                    if (!tab) {
                        return;
                    }
                    tab.pinchZoom = 1;
                    tab.pinchPanX = 0;
                    tab.pinchPanY = 0;
                    applyPinchTransform(tab);
                }

                // Keep the pan within roughly one viewport of the origin so content can't be
                // flung fully off-screen; also re-applied on resize/rotate so a stale pan can't
                // strand the view outside the (possibly resized) container.
                function clampPinchPan(tab) {
                    if (!tab || !tab.displayRoot) {
                        return;
                    }
                    const cont = tab.displayRoot.getBoundingClientRect();
                    tab.pinchPanX = Math.min(cont.width, Math.max(-cont.width, tab.pinchPanX || 0));
                    tab.pinchPanY = Math.min(cont.height, Math.max(-cont.height, tab.pinchPanY || 0));
                }

                function setupPinchZoom(tab) {
                    if (!isTouchDevice || !tab || !tab.displayRoot || tab.pinchReady) {
                        return;
                    }
                    tab.pinchReady = true;
                    tab.pinchZoom = tab.pinchZoom || 1;
                    tab.pinchPanX = tab.pinchPanX || 0;
                    tab.pinchPanY = tab.pinchPanY || 0;

                    const root = tab.displayRoot;
                    let active = false;   // exactly-two-finger gesture is being tracked
                    let mode = null;      // null=undecided, 'transform'=zoom/pan, 'scroll'=wheel to remote
                    let startDist = 1;
                    let startZoom = 1;
                    let startMidX = 0;
                    let startMidY = 0;
                    let lastMidX = 0;
                    let lastMidY = 0;
                    let scrollAccum = 0;
                    let tapStart = 0;         // timestamp of a two-finger touch (for tap = right-click)
                    let hadTwoFingers = false;
                    let tapCandidate = false; // still could be a two-finger tap (no move/zoom yet)
                    const SCROLL_STEP = 36; // px of two-finger travel per emulated wheel tick

                    const distance = touches => {
                        const dx = touches[0].clientX - touches[1].clientX;
                        const dy = touches[0].clientY - touches[1].clientY;
                        return Math.hypot(dx, dy) || 1;
                    };
                    const midpoint = touches => ({
                        x: (touches[0].clientX + touches[1].clientX) / 2,
                        y: (touches[0].clientY + touches[1].clientY) / 2
                    });
                    const swallow = event => {
                        event.preventDefault();
                        event.stopPropagation();
                        if (typeof event.stopImmediatePropagation === 'function') {
                            event.stopImmediatePropagation();
                        }
                    };
                    // Emulate one mouse-wheel tick at (x,y): dir < 0 = up, dir > 0 = down.
                    // The tick goes where the pointer is: with the touchpad that is where the cursor already
                    // stands, with direct touch under the fingers. It used to be sent with the raw screen
                    // position of the fingers, which is not a position in the remote at all - every two-finger
                    // scroll threw the cursor somewhere else.
                    const sendScroll = (x, y, dir) => {
                        if (!tab.client) {
                            return;
                        }
                        const at = (tab.pointerMode === 'touchpad' && tab.lastPointer)
                            ? tab.lastPointer
                            : (tab.remoteFromClient ? tab.remoteFromClient(x, y) : null);
                        const known = !!at;
                        const px = known ? at.x : Math.round(x);
                        const py = known ? at.y : Math.round(y);
                        const base = { x: px, y: py, left: false, middle: false, right: false, up: false, down: false };
                        tab.client.sendMouseState({ x: px, y: py, left: false, middle: false, right: false, up: dir < 0, down: dir > 0 }, !known);
                        tab.client.sendMouseState(base, !known);
                        if (known) {
                            tab.lastPointer = { x: px, y: py };
                        }
                    };
                    // Start tracking a clean two-finger gesture. We stay UNDECIDED (and let events reach
                    // Guacamole) until the fingers clearly spread/pinch (=> zoom) or clearly translate
                    // (=> scroll), so a two-finger scroll is not swallowed by the zoom handler. If the view
                    // is already zoomed, two fingers pan immediately.
                    const track = touches => {
                        active = true;
                        startDist = distance(touches);
                        startZoom = tab.pinchZoom || 1;
                        const m = midpoint(touches);
                        startMidX = lastMidX = m.x;
                        startMidY = lastMidY = m.y;
                        scrollAccum = 0;
                        tapStart = Date.now();
                        hadTwoFingers = true;
                        tapCandidate = true;
                        mode = (tab.pinchZoom || 1) > 1.02 ? 'transform' : null;
                    };

                    // In fixed-resolution mode the pinch gesture belongs to the session. Without
                    // this the browser zoomed the whole UI instead - sometimes yes, sometimes no,
                    // depending on where the fingers land, which is exactly the impression of
                    // "works partly". Scrolling still works with one finger.
                    // Two fingers in a fixed resolution: a pinch zooms around the fingers, dragging pans the
                    // view - the screen is bigger than the display, that is what this mode is - and when there
                    // is nothing to pan the same drag scrolls the remote, as it does in the fit modes. Until the
                    // fingers have clearly done one or the other the gesture is undecided.
                    let deskDist = 0;
                    let deskZoom = 1;
                    let deskMode = null;      // null = undecided, 'zoom', 'pan' or 'wheel'
                    let deskMid = { x: 0, y: 0 };
                    let deskLastMid = { x: 0, y: 0 };
                    let deskScroll = { left: 0, top: 0 };
                    let deskContent = { x: 0, y: 0 };   // what is under the fingers, in un-zoomed pixels
                    let deskCanPan = false;
                    let deskAccum = 0;
                    root.addEventListener('touchstart', event => {
                        if (isDesktopDisplayMode(tab)) {
                            if (event.touches.length === 2) {
                                deskDist = distance(event.touches);
                                deskZoom = tab.zoom || 1;
                                deskMode = null;
                                deskMid = midpoint(event.touches);
                                deskLastMid = deskMid;
                                deskScroll = { left: root.scrollLeft, top: root.scrollTop };
                                const box = root.getBoundingClientRect();
                                deskContent = {
                                    x: (root.scrollLeft + deskMid.x - box.left) / deskZoom,
                                    y: (root.scrollTop + deskMid.y - box.top) / deskZoom
                                };
                                deskCanPan = root.scrollWidth > root.clientWidth + 2 || root.scrollHeight > root.clientHeight + 2;
                                deskAccum = 0;
                                swallow(event);
                            }

                            return;
                        }

                        // Single-finger touches belong to Guacamole (remote cursor); leave them alone.
                        if (event.touches.length < 2) {
                            return;
                        }
                        if (event.touches.length === 2) {
                            track(event.touches);
                            if (mode) {
                                swallow(event);
                            }
                        }
                        else {
                            active = false; // 3+ fingers: wait until it settles to two
                        }
                    }, { passive: false, capture: true });

                    root.addEventListener('touchmove', event => {
                        if (isDesktopDisplayMode(tab)) {
                            if (event.touches.length === 2 && deskDist > 0) {
                                swallow(event);
                                const dist = distance(event.touches);
                                const m = midpoint(event.touches);
                                if (!deskMode) {
                                    if (Math.abs(dist / deskDist - 1) > 0.06) {
                                        deskMode = 'zoom';
                                    }
                                    else if (Math.hypot(m.x - deskMid.x, m.y - deskMid.y) > 10) {
                                        deskMode = deskCanPan ? 'pan' : 'wheel';
                                    }
                                    else {
                                        return;
                                    }
                                }

                                if (deskMode === 'zoom') {
                                    tab.zoom = Math.round(Math.min(3, Math.max(0.25, deskZoom * (dist / deskDist))) * 100) / 100;
                                    fitDisplay(tab);
                                    // What was under the fingers stays under them.
                                    const box = root.getBoundingClientRect();
                                    root.scrollLeft = deskContent.x * tab.zoom - (m.x - box.left);
                                    root.scrollTop = deskContent.y * tab.zoom - (m.y - box.top);
                                }
                                else if (deskMode === 'pan') {
                                    root.scrollLeft = deskScroll.left - (m.x - deskMid.x);
                                    root.scrollTop = deskScroll.top - (m.y - deskMid.y);
                                }
                                else {
                                    // Nothing to pan: the drag scrolls the remote. Fingers moving down scroll the content up.
                                    deskAccum += m.y - deskLastMid.y;
                                    while (Math.abs(deskAccum) >= SCROLL_STEP) {
                                        sendScroll(m.x, m.y, deskAccum > 0 ? -1 : 1);
                                        deskAccum -= deskAccum > 0 ? SCROLL_STEP : -SCROLL_STEP;
                                    }
                                }

                                deskLastMid = m;
                            }

                            return;
                        }

                        if (mode && event.touches.length < 2) {
                            swallow(event); // own the tail of a committed gesture
                            return;
                        }
                        if (event.touches.length < 2) {
                            return;
                        }
                        if (event.touches.length !== 2) {
                            if (mode) {
                                swallow(event);
                            }
                            active = false;
                            return;
                        }
                        if (!active) {
                            track(event.touches);
                            if (mode) {
                                swallow(event);
                            }
                            return;
                        }

                        const dist = distance(event.touches);
                        const m = midpoint(event.touches);
                        if (!mode) {
                            const distChange = Math.abs(dist / startDist - 1);
                            const midMove = Math.hypot(m.x - startMidX, m.y - startMidY);
                            if (distChange > 0.06 || midMove > 8) {
                                tapCandidate = false; // moved -> not a tap
                            }
                            if (distChange > 0.15) {
                                mode = 'transform';
                                startDist = dist;
                                startZoom = tab.pinchZoom || 1;
                                lastMidX = m.x;
                                lastMidY = m.y;
                            }
                            else if (midMove > 12) {
                                mode = 'scroll';
                                lastMidX = m.x;
                                lastMidY = m.y;
                                scrollAccum = 0;
                            }
                            else {
                                return; // undecided - let it fall through to Guacamole
                            }
                        }

                        swallow(event);

                        if (mode === 'scroll') {
                            scrollAccum += (m.y - lastMidY);
                            lastMidX = m.x;
                            lastMidY = m.y;
                            while (Math.abs(scrollAccum) >= SCROLL_STEP) {
                                // Fingers moving down scroll the content up (natural), and vice versa.
                                sendScroll(m.x, m.y, scrollAccum > 0 ? -1 : 1);
                                scrollAccum -= scrollAccum > 0 ? SCROLL_STEP : -SCROLL_STEP;
                            }
                            return;
                        }

                        // transform: zoom (distance) + pan (midpoint drag)
                        const rect = tab.displayScaler.getBoundingClientRect();
                        const z = tab.pinchZoom || 1;
                        const newZoom = Math.min(4, Math.max(1, startZoom * (dist / startDist)));
                        const focalFactor = 1 - newZoom / z;
                        tab.pinchPanX += (m.x - rect.left) * focalFactor;
                        tab.pinchPanY += (m.y - rect.top) * focalFactor;
                        tab.pinchPanX += (m.x - lastMidX);
                        tab.pinchPanY += (m.y - lastMidY);
                        tab.pinchZoom = newZoom;
                        lastMidX = m.x;
                        lastMidY = m.y;
                        clampPinchPan(tab);
                        applyPinchTransform(tab);
                    }, { passive: false, capture: true });

                    const end = event => {
                        // The gesture in fixed-resolution mode ends here, otherwise the next touch acts
                        // like a continuation of the previous one.
                        if (event.touches.length < 2) {
                            deskDist = 0;
                            deskMode = null;
                        }

                        if (mode) {
                            swallow(event); // own the tail touchend/touchcancel of a committed gesture
                        }
                        // Two-finger tap (no zoom/scroll/move, quick release) = right click at the cursor.
                        if (event.touches.length === 0 && hadTwoFingers && tapCandidate && !mode
                            && (Date.now() - tapStart) < 400) {
                            swallow(event);
                            sendRightClick(tab);
                        }
                        if (event.touches.length < 2) {
                            active = false;
                            if ((tab.pinchZoom || 1) <= 1.02) {
                                resetPinchZoom(tab);
                            }
                        }
                        if (event.touches.length === 0) {
                            mode = null; // gesture fully released; re-arm
                            hadTwoFingers = false;
                            tapCandidate = false;
                        }
                    };
                    root.addEventListener('touchend', end, { passive: false, capture: true });
                    root.addEventListener('touchcancel', end, { passive: false, capture: true });
                }

                function fitDisplay(tab) {
                    if (!tab || !tab.client) {
                        return;
                    }

                    const display = tab.client.getDisplay();
                    const width = display.getWidth();
                    const height = display.getHeight();
                    if (!width || !height) {
                        return;
                    }

                    // Stretch the framebuffer to fill the whole panel (X and Y scaled independently, may
                    // distort). Two cases: (1) the per-user "stretch to window" pref in fixed-resolution mode,
                    // and (2) a fit mode with auto-resize turned off - then a window resize must scale the
                    // existing framebuffer instead of renegotiating the remote. Farm VNC re-renders at the
                    // viewport size, so it never stretches.
                    const stretch = !tab.farmWebsite && (
                        (sessionPrefs.stretchToWindow && isDesktopDisplayMode(tab))
                        || (isFitMode(tab) && !tab.autoResize));
                    if (stretch) {
                        const rect = tab.panel.getBoundingClientRect();
                        display.scale(1);
                        if (tab.displayScaler) {
                            tab.displayScaler.style.width = '';
                            tab.displayScaler.style.height = '';
                            tab.displayScaler.style.transformOrigin = 'top left';
                            tab.displayScaler.style.transform = `scale(${rect.width / width}, ${rect.height / height})`;
                        }
                        tab.displayRoot.classList.remove('scrollable');
                        tab.displayRoot.classList.add('display-stretch');
                        return;
                    }
                    tab.displayRoot.classList.remove('display-stretch');
                    tab.displayRoot.classList.toggle('scrollable', isDesktopDisplayMode(tab));
                    if (tab.displayScaler) {
                        tab.displayScaler.style.transformOrigin = '';
                    }

                    if (isDesktopDisplayMode(tab)) {
                        const scale = Math.max(0.25, tab.zoom || 1);
                        display.scale(scale);
                        if (tab.displayScaler) {
                            tab.displayScaler.style.width = Math.round(width * scale) + 'px';
                            tab.displayScaler.style.height = Math.round(height * scale) + 'px';
                        }
                        clampPinchPan(tab);
                        applyPinchTransform(tab);
                        return;
                    }

                    const rect = tab.panel.getBoundingClientRect();
                    const scale = Math.min(1, rect.width / width, rect.height / height);
                    display.scale(Math.max(0.1, scale));
                    if (tab.displayScaler) {
                        if (tab.farmWebsite) {
                            // Farm VNC: the guac display element does not report an intrinsic size here,
                            // so the flex-centered scaler would collapse to 0x0 and the canvas would spill
                            // out from the centre and get clipped by the display's overflow:hidden. Pin the
                            // scaler to the (scaled) framebuffer so it centres and the canvas stays inside.
                            tab.displayScaler.style.width = Math.round(width * scale) + 'px';
                            tab.displayScaler.style.height = Math.round(height * scale) + 'px';
                        } else {
                            tab.displayScaler.style.width = '';
                            tab.displayScaler.style.height = '';
                        }
                    }
                    clampPinchPan(tab);
                    applyPinchTransform(tab);
                }

                function sendDisplaySize(tab, force) {
                    if (!tab || !tab.client) {
                        return;
                    }

                    // Auto-resize off (fit modes): don't renegotiate the remote on window resize - keep the
                    // framebuffer and just stretch it to fill (no reconnect). "Fit Now" / re-enabling passes
                    // force=true to renegotiate once.
                    if (!force && isFitMode(tab) && !tab.autoResize && !tab.farmWebsite) {
                        fitDisplay(tab);
                        return;
                    }

                    const size = viewport(tab);
                    if (tab.lastSentSize
                        && tab.lastSentSize.width === size.width
                        && tab.lastSentSize.height === size.height
                        && tab.lastSentSize.dpi === size.dpi) {
                        fitDisplay(tab);
                        return;
                    }

                    tab.lastSentSize = size;
                    tab.client.sendSize(size.width, size.height);
                    fitDisplay(tab);
                }

                function scheduleResize() {
                    window.clearTimeout(resizeTimer);
                    resizeTimer = window.setTimeout(() => sendDisplaySize(tabs.get(activeTabId)), 200);
                    const active = tabs.get(activeTabId);
                    if (active && active.farmWebsite) {
                        scheduleFarmReconnect(active);
                    }
                }

                // Smart-reconnect for browser-farm (VNC) sessions: VNC cannot renegotiate the remote
                // resolution live like RDP, so when the viewport changes enough we transparently release
                // the slot and reconnect - the farm then renders the page at the new size. Debounced so
                // it only fires once the user stops resizing.
                function scheduleFarmReconnect(tab) {
                    window.clearTimeout(tab.farmReconnectTimer);
                    tab.farmReconnectTimer = window.setTimeout(() => {
                        if (!tab || !tab.farmWebsite || tab.terminal || !tab.client) {
                            return;
                        }

                        if (tabs.get(activeTabId) !== tab) {
                            return;
                        }

                        const rect = tab.panel ? tab.panel.getBoundingClientRect() : null;
                        const w = Math.round(rect && rect.width ? rect.width : window.innerWidth);
                        const h = Math.round(rect && rect.height ? rect.height : window.innerHeight);
                        const prev = tab.farmSize || { width: 0, height: 0 };
                        // Ignore sub-threshold jitter (toolbar reflow, scrollbar, address-bar show/hide).
                        if (Math.abs(w - prev.width) < 32 && Math.abs(h - prev.height) < 32) {
                            return;
                        }

                        setOverlay(tab, ui('opening'), `${tab.name} ${uiText.isOpening || 'is opening'}.`, false);
                        releaseBrowserFarm(tab);
                        releaseSessionFiles(tab);
                        restartTab(tab);
                    }, 900);
                }

                async function measureGatewayLatency() {
                    const startedAt = performance.now();
                    try {
                        const response = await fetch(`/api/ping?t=${Date.now()}`, { cache: 'no-store' });
                        if (!response.ok) {
                            throw new Error('Ping failed');
                        }

                        gatewayLatencyMs = Math.round(performance.now() - startedAt);
                    }
                    catch {
                        gatewayLatencyMs = null;
                    }

                    updateStatusBar();
                }

                // The Guacamole client library is loaded via a <script> that proxies through the edge's
                // forward_auth to the guacamole webapp. If that request failed transiently (e.g. matgate
                // was mid-restart -> 502) or a broken response got cached, window.Guacamole is missing.
                // Re-fetch it on demand (cache-busted) instead of failing the whole connection.
                let guacLoadPromise = null;
                function ensureGuacamoleLoaded() {
                    if (window.Guacamole) {
                        return Promise.resolve(true);
                    }

                    if (guacLoadPromise) {
                        return guacLoadPromise;
                    }

                    // The guac client library is served by the Guacamole webapp through the edge's
                    // forward_auth. During a gateway restart that subrequest can briefly return
                    // 502/401, so retry a few times before giving up - this self-heals a short
                    // bounce instead of surfacing "The Guacamole web client could not be loaded".
                    guacLoadPromise = (async () => {
                        const attempts = 4;
                        for (let i = 0; i < attempts && !window.Guacamole; i++) {
                            if (i > 0) {
                                await new Promise(r => window.setTimeout(r, 2000));
                            }

                            await new Promise(resolve => {
                                let settled = false;
                                const finish = () => {
                                    if (!settled) {
                                        settled = true;
                                        resolve();
                                    }
                                };
                                const script = document.createElement('script');
                                script.src = '/guacamole/guacamole-common-js/all.min.js?reload=' + Date.now() + '-' + i;
                                script.addEventListener('load', finish);
                                script.addEventListener('error', finish);
                                document.head.appendChild(script);
                                window.setTimeout(finish, 6000);
                            });
                        }

                        guacLoadPromise = null;
                        return !!window.Guacamole;
                    })();
                    return guacLoadPromise;
                }

                // Visible connection diagnostics: builds a breadcrumb trail (lib -> launch -> auth ->
                // connect -> state) shown in the connection overlay + console, so a stuck/failed
                // connection screenshot pinpoints the exact stage. Enabled for browser-farm sessions.
                function pushDiag(tab, step) {
                    if (!tab || !tab.farmWebsite) {
                        return;
                    }

                    tab.diagTrail = tab.diagTrail || [];
                    tab.diagTrail.push(step);
                    // Console-only breadcrumb for troubleshooting; not shown in the UI.
                    try { console.log('[matgate-conn]', tab.name || '', step); } catch (e) { /* ignore */ }
                }

                function tunnelStateName(state) {
                    if (!window.Guacamole) {
                        return 'Unbekannt';
                    }

                    switch (state) {
                        case Guacamole.Tunnel.State.CONNECTING: return ui('connecting');
                        case Guacamole.Tunnel.State.OPEN: return uiText.open || 'Open';
                        case Guacamole.Tunnel.State.UNSTABLE: return uiText.unstable || 'Unstable';
                        case Guacamole.Tunnel.State.CLOSED: return uiText.closed || 'Closed';
                        default: return uiText.unknown || 'Unknown';
                    }
                }

                function formatAge(timestamp) {
                    if (!timestamp) {
                        return '-';
                    }

                    const seconds = Math.max(0, Math.round((Date.now() - timestamp) / 1000));
                    return seconds < 2 ? 'now' : `vor ${seconds}s`;
                }

                function normalizeStatus(status, fallback) {
                    if (!status) {
                        return fallback;
                    }

                    if (typeof status === 'string') {
                        return status;
                    }

                    const message = status.message || fallback;
                    return status.code ? `${message} (${status.code})` : message;
                }

                function shouldSuppressBrowserScroll(event) {
                    if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) {
                        return false;
                    }

                    switch (event.key) {
                        case ' ':
                        case 'Spacebar':
                        case 'Space':
                        case 'PageUp':
                        case 'PageDown':
                        case 'ArrowUp':
                        case 'ArrowDown':
                        case 'ArrowLeft':
                        case 'ArrowRight':
                        case 'Home':
                        case 'End':
                            return true;
                        default:
                            return false;
                    }
                }

                // ---- How busy an agent's machine is: processor and memory in the status bar while one of its tabs
                // is in front, asked every 3 seconds; a click shows the numbers in MB/GB. An agent from before this
                // (or on a system that cannot tell) answers that it cannot, and the status bar shows nothing.
                // var, not const: the status bar is updated before this part of the script has run.
                var systemButton = document.getElementById('status-system');
                var systemPanel = document.getElementById('status-system-panel');
                var systemServerId = '';
                var systemTimer = 0;
                var systemData = null;
                var systemAsking = false;
                function activeAgentServerId() {
                    const tab = tabs.get(activeTabId);
                    if (tab) {
                        return isAgentTab(tab) ? tab.serverId : '';
                    }
                    const shellTab = shellTabs.get(activeShellTabId);
                    const match = shellTab ? /^\/agent\/([0-9a-fA-F-]{36})\//.exec(shellTab.url || '') : null;
                    return match ? match[1] : '';
                }
                function formatBytes(bytes) {
                    if (!bytes || bytes < 0) {
                        return '0 MB';
                    }
                    const gb = bytes / 1073741824;
                    return gb >= 1 ? `${gb.toFixed(gb >= 100 ? 0 : 1)} GB` : `${Math.round(bytes / 1048576)} MB`;
                }
                function formatUptime(seconds) {
                    const days = Math.floor(seconds / 86400);
                    const hours = Math.floor(seconds % 86400 / 3600);
                    const minutes = Math.floor(seconds % 3600 / 60);
                    return days ? `${days} d ${hours} h` : hours ? `${hours} h ${minutes} min` : `${minutes} min`;
                }
                function renderSystem() {
                    if (!systemButton) {
                        return;
                    }
                    const data = systemData;
                    const shown = !!(systemServerId && data && data.available);
                    systemButton.hidden = !shown;
                    if (!shown) {
                        closeSystemPanel();
                        return;
                    }
                    const memPercent = data.memTotal ? Math.round(100 * data.memUsed / data.memTotal) : null;
                    const cpuText = data.cpu === null || data.cpu === undefined ? '-' : `${Math.round(data.cpu)} %`;
                    systemButton.querySelector('.status-system-cpu').textContent = `CPU ${cpuText}`;
                    systemButton.querySelector('.status-system-ram').textContent = `RAM ${memPercent === null ? '-' : memPercent + ' %'}`;
                    systemButton.title = ui('systemTitle');
                    systemButton.classList.toggle('is-high', (data.cpu || 0) >= 90 || (memPercent || 0) >= 90);
                    if (systemPanel.hidden) {
                        return;
                    }
                    const bar = (percent, label, detail) => {
                        const row = document.createElement('div');
                        row.className = 'status-system-row';
                        const head = document.createElement('div');
                        head.className = 'status-system-head';
                        const name = document.createElement('strong');
                        name.textContent = label;
                        const value = document.createElement('span');
                        value.textContent = percent === null ? '-' : `${percent} %`;
                        head.append(name, value);
                        const track = document.createElement('div');
                        track.className = 'status-system-track';
                        const fill = document.createElement('span');
                        fill.style.width = `${Math.max(0, Math.min(100, percent || 0))}%`;
                        fill.classList.toggle('is-high', (percent || 0) >= 90);
                        track.append(fill);
                        const small = document.createElement('small');
                        small.textContent = detail;
                        row.append(head, track, small);
                        return row;
                    };
                    const title = document.createElement('div');
                    title.className = 'status-system-title';
                    title.textContent = ui('systemTitle');
                    const rows = [
                        title,
                        bar(data.cpu === null || data.cpu === undefined ? null : Math.round(data.cpu), ui('systemCpu'), `${data.cores} ${ui('systemCores')}`),
                        bar(memPercent, ui('systemMemory'), `${formatBytes(data.memUsed)} ${ui('systemUsed')} ${ui('systemOf')} ${formatBytes(data.memTotal)} · ${formatBytes(data.memAvailable)} ${ui('systemFree')}`),
                    ];
                    if (data.swapTotal > 0) {
                        rows.push(bar(Math.round(100 * data.swapUsed / data.swapTotal), ui('systemSwap'), `${formatBytes(data.swapUsed)} ${ui('systemOf')} ${formatBytes(data.swapTotal)}`));
                    }
                    const foot = document.createElement('small');
                    foot.className = 'status-system-foot';
                    foot.textContent = `${ui('systemUptime')} ${formatUptime(data.uptime || 0)} · ${ui('systemHint')}`;
                    rows.push(foot);
                    systemPanel.replaceChildren(...rows);
                }
                async function askSystem() {
                    const id = systemServerId;
                    if (!id || systemAsking || document.hidden) {
                        return;
                    }
                    systemAsking = true;
                    try {
                        const response = await fetch(`/api/agent/${id}/system`, { credentials: 'same-origin', cache: 'no-store' });
                        const data = response.ok ? await response.json() : { available: false };
                        if (id === systemServerId) {
                            systemData = data;
                            renderSystem();
                        }
                    }
                    catch {
                        // No answer this time: the last numbers stay until the next one.
                    }
                    finally {
                        systemAsking = false;
                    }
                }
                function followSystemStats() {
                    if (!systemButton) {
                        return;
                    }
                    const id = activeAgentServerId();
                    if (id === systemServerId) {
                        return;
                    }
                    systemServerId = id;
                    systemData = null;
                    window.clearInterval(systemTimer);
                    systemTimer = 0;
                    renderSystem();
                    if (id) {
                        askSystem();
                        systemTimer = window.setInterval(askSystem, 3000);
                    }
                }
                function closeSystemPanel() {
                    if (systemPanel && !systemPanel.hidden) {
                        systemPanel.hidden = true;
                        systemButton.setAttribute('aria-expanded', 'false');
                    }
                }
                if (systemButton && systemPanel) {
                    // The click does not take the keyboard away from the session in front.
                    systemButton.addEventListener('pointerdown', event => event.preventDefault());
                    systemButton.addEventListener('click', () => {
                        if (!systemPanel.hidden) {
                            closeSystemPanel();
                            return;
                        }
                        // Just above the status bar, whatever its height (on a phone it is taller).
                        const bar = document.getElementById('session-statusbar');
                        if (bar) {
                            systemPanel.style.bottom = `${Math.max(8, Math.round(window.innerHeight - bar.getBoundingClientRect().top + 8))}px`;
                        }
                        systemPanel.hidden = false;
                        systemButton.setAttribute('aria-expanded', 'true');
                        renderSystem();
                    });
                    document.addEventListener('pointerdown', event => {
                        if (!systemPanel.hidden && !systemPanel.contains(event.target) && !systemButton.contains(event.target)) {
                            closeSystemPanel();
                        }
                    }, true);
                    document.addEventListener('keydown', event => {
                        if (event.key === 'Escape') {
                            closeSystemPanel();
                        }
                    });
                    // Into a session (its frame takes the focus): closed as well.
                    window.addEventListener('blur', closeSystemPanel);
                    document.addEventListener('visibilitychange', () => {
                        if (!document.hidden) {
                            askSystem();
                        }
                    });
                }

                // ---- The clipboard of this device, for the session in front. The status bar shows a button only
                // while something is known to be on it - a picture or text - and says which ("Bild · PNG 1280×720").
                // Known means: the browser lets the page look without a click (Chromium, once allowed); otherwise
                // the session toolbar's clipboard button is the way in. Both open the clipboard panel: what is in
                // it, and what to do with it - as text, as a file (PNG, JPG, TXT), as a picture; or something else,
                // typed there or picked from this device.
                // var, not const: the status bar is updated before this part of the script has run.
                var clipButton = document.getElementById('status-clip');
                var clipPanel = document.getElementById('clip-panel');
                var clipNote = null;
                var clipNoteTimer = 0;
                var clipKnown = null;
                // What the session in front can do with the clipboard. Null when nothing is in front.
                function clipTarget() {
                    const tab = tabs.get(activeTabId);
                    if (tab) {
                        if (!tab.client) {
                            return null;
                        }
                        return {
                            pasteText: text => pasteTextToRemote(tab, text),
                            typeText: text => typeTextToRemote(tab, text),
                            pasteFiles: tab.filesystem ? files => pasteFilesIntoSession(tab, { files, folders: [] }) : null,
                            pasteImage: null,
                            focus: () => tab.panel && tab.panel.focus(),
                        };
                    }
                    const shellTab = shellTabs.get(activeShellTabId);
                    if (!shellTab) {
                        return null;
                    }
                    const screen = agentScreenOf(shellTab);
                    const api = screen ? screen.api : (sshTerminalOf(shellTab) || {}).api;
                    if (!api) {
                        return null;
                    }
                    const can = name => typeof api['can' + name] !== 'function' || api['can' + name]();
                    return {
                        pasteText: text => (screen ? api.pasteText(text) : api.paste(text)),
                        typeText: null,
                        pasteFiles: typeof api.pasteFiles === 'function' && can('PasteFiles') ? files => api.pasteFiles(files) : null,
                        pasteImage: typeof api.pasteImage === 'function' && can('PasteImage') ? file => api.pasteImage(file) : null,
                        focus: () => api.focus && api.focus(),
                    };
                }
                function showClipNote(text) {
                    if (!clipNote) {
                        clipNote = document.createElement('div');
                        clipNote.className = 'status-clip-note';
                        clipNote.setAttribute('role', 'status');
                        document.body.appendChild(clipNote);
                    }
                    clipNote.textContent = text;
                    clipNote.hidden = false;
                    const box = (clipButton && !clipButton.hidden ? clipButton : document.getElementById('session-statusbar') || document.body).getBoundingClientRect();
                    clipNote.style.right = Math.max(8, window.innerWidth - box.right) + 'px';
                    clipNote.style.bottom = (window.innerHeight - box.top + 8) + 'px';
                    window.clearTimeout(clipNoteTimer);
                    clipNoteTimer = window.setTimeout(() => { clipNote.hidden = true; }, 6000);
                }
                const clipStamp = () => {
                    const now = new Date();
                    const pad2 = n => String(n).padStart(2, '0');
                    return `${now.getFullYear()}-${pad2(now.getMonth() + 1)}-${pad2(now.getDate())}-${pad2(now.getHours())}${pad2(now.getMinutes())}${pad2(now.getSeconds())}`;
                };
                const clipSize = bytes => bytes >= 1048576 ? (bytes / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
                // What is on this device's clipboard: a picture (with its type, size and dimensions) and/or text.
                // Throws when the browser does not allow reading.
                async function readClipboardContent() {
                    const items = await navigator.clipboard.read();
                    const found = { image: null, text: '', html: false };
                    for (const item of items) {
                        const imageType = item.types.find(type => type.startsWith('image/'));
                        if (imageType && !found.image) {
                            const blob = await item.getType(imageType);
                            let width = 0;
                            let height = 0;
                            try {
                                const bitmap = await createImageBitmap(blob);
                                width = bitmap.width;
                                height = bitmap.height;
                                bitmap.close && bitmap.close();
                            }
                            catch {
                            }
                            found.image = { blob, type: imageType, width, height };
                        }
                        if (item.types.includes('text/plain') && !found.text) {
                            found.text = await (await item.getType('text/plain')).text();
                        }
                        if (item.types.includes('text/html')) {
                            found.html = true;
                        }
                    }
                    return found;
                }
                // "Bild · PNG 1280×720" / "Text · 42 Zeichen" - what the button and the panel say it is.
                function describeClip(found) {
                    if (!found) {
                        return '';
                    }
                    if (found.image) {
                        const format = (found.image.type.split('/')[1] || '').toUpperCase().replace('JPEG', 'JPG');
                        return (uiText.clipKindImage || 'Picture') + ' · ' + format + (found.image.width ? ' ' + found.image.width + '×' + found.image.height : '') + ' · ' + clipSize(found.image.blob.size);
                    }
                    if (found.text) {
                        const lines = found.text.split('\n').length;
                        return (found.html ? (uiText.clipKindRich || 'Formatted text') : (uiText.clipKindText || 'Text')) + ' · ' + found.text.length + ' ' + (uiText.clipChars || 'characters') + (lines > 1 ? ' · ' + lines + ' ' + (uiText.clipLines || 'lines') : '');
                    }
                    return '';
                }
                const imageFile = (found, kind) => {
                    const name = (uiText.pastedImageName || 'Bild') + '-' + clipStamp();
                    if (kind === 'jpg') {
                        return createImageBitmap(found.image.blob).then(bitmap => {
                            const canvas = document.createElement('canvas');
                            canvas.width = bitmap.width;
                            canvas.height = bitmap.height;
                            const context = canvas.getContext('2d');
                            context.fillStyle = '#fff';
                            context.fillRect(0, 0, canvas.width, canvas.height);
                            context.drawImage(bitmap, 0, 0);
                            return new Promise(resolve => canvas.toBlob(blob => resolve(new File([blob], name + '.jpg', { type: 'image/jpeg' })), 'image/jpeg', 0.92));
                        });
                    }
                    const extension = (found.image.type.split('/')[1] || 'png').replace('jpeg', 'jpg');
                    return Promise.resolve(new File([found.image.blob], name + '.' + extension, { type: found.image.type }));
                };
                const textFile = text => new File([text], (uiText.pastedTextName || 'Text') + '-' + clipStamp() + '.txt', { type: 'text/plain' });
                function showClipState(found) {
                    clipKnown = found;
                    if (!clipButton) {
                        return;
                    }
                    const what = describeClip(found);
                    // Only with something known on the clipboard - and a session in front to take it.
                    clipButton.hidden = !what || !clipTarget();
                    clipButton.dataset.has = found && found.image ? 'image' : found && found.text ? 'text' : 'none';
                    clipButton.classList.toggle('has-file', !!(found && found.image));
                    clipButton.querySelector('.status-clip-label').textContent = what;
                    clipButton.title = (uiText.clipOpen || 'Clipboard') + ': ' + what;
                    clipButton.setAttribute('aria-label', clipButton.title);
                }
                // Without a click only where the browser already allows it (Chromium, once granted) - never a prompt.
                async function lookAtClipboard() {
                    if (!navigator.clipboard || !navigator.clipboard.read || !document.hasFocus()) {
                        return;
                    }
