                        transition: background-color .15s ease, border-color .15s ease, color .15s ease;
                    }
                    .toolbar-button:hover,
                    .toolbar-button:focus-visible,
                    .toolbar-menu-trigger:hover,
                    .toolbar-menu-trigger:focus-visible,
                    .website-tool-button:hover,
                    .website-tool-button:focus-visible,
                    .file-tool-button:hover,
                    .file-tool-button:focus-visible,
                    .toolbar-menu.is-open > .toolbar-menu-trigger {
                        background: var(--hover-bg);
                        border-color: var(--surface-3);
                        color: var(--text);
                    }
                    .toolbar-button .icon,
                    .toolbar-menu-trigger .icon,
                    .toolbar-upload-button .icon,
                    .website-tool-button .icon,
                    .file-tool-button .icon,
                    .file-upload-button .icon {
                        height: 15px;
                        width: 15px;
                    }
                    .toolbar-icon-button {
                        flex: 0 0 auto;
                        min-width: 32px;
                        padding: 0;
                        width: 32px;
                    }
                    .toolbar-button--primary,
                    .file-upload-button {
                        background: var(--accent);
                        border-color: var(--accent);
                        color: var(--bg);
                    }
                    .toolbar-button--primary:hover,
                    .toolbar-button--primary:focus-visible,
                    .toolbar-upload-button:hover,
                    .toolbar-upload-button:focus-visible,
                    .file-upload-button:hover,
                    .file-upload-button:focus-visible {
                        background: var(--primary-hover);
                        border-color: var(--primary-hover);
                        color: var(--bg);
                    }
                    .toolbar-button--danger {
                        background: var(--danger);
                        border-color: var(--danger);
                        color: var(--bg);
                    }
                    .toolbar-button--danger:hover,
                    .toolbar-button--danger:focus-visible {
                        background: var(--danger-hover);
                        border-color: var(--danger-hover);
                        color: var(--bg);
                    }
                    .toolbar-input,
                    .website-address,
                    .file-path-input {
                        flex: 1 1 220px;
                        font-family: Consolas, ui-monospace, monospace;
                        min-height: 32px;
                    }
                    .toolbar-menu,
                    .file-menu {
                        position: relative;
                    }
                    .toolbar-menu-panel,
                    .file-menu-panel {
                        background: var(--surface);
                        border: 1px solid var(--line);
                        border-radius: var(--radius);
                        box-shadow: var(--shadow-strong);
                        display: grid;
                        gap: 4px;
                        min-width: 240px;
                        padding: 6px;
                        position: absolute;
                        left: 0;
                        top: calc(100% + 8px);
                        z-index: 12;
                    }
                    .toolbar-menu-item,
                    .file-menu-item {
                        align-items: center;
                        /* The menu is the bordered surface; its entries need no border of their own.
                           own. The feedback on hover stays, that comes from the
                           surface. */
                        border: 0;
                        justify-content: flex-start;
                        width: 100%;
                    }
                    .website-toolbar {
                        align-items: center;
                        background: var(--surface);
                        border-bottom: 1px solid var(--line);
                        display: flex;
                        flex-wrap: wrap;
                        gap: 8px;
                        padding: 6px 8px;
                    }
                    .website-toolbar-group {
                        align-items: center;
                        display: flex;
                        gap: 2px;
                        min-width: 0;
                    }
                    .website-toolbar-address {
                        flex: 1 1 340px;
                    }
                    /* On a phone the browser's bar is one row, as a browser's is: back, forward, reload, the
                       address, open. It used to wrap into three and took a fifth of the screen. */
                    @media (max-width: 720px) {
                        .website-toolbar,
                        .website-toolbar-group {
                            flex-wrap: nowrap;
                            gap: 4px;
                        }
                        .website-toolbar-address {
                            flex: 1 1 0;
                            min-width: 0;
                        }
                        .website-toolbar .toolbar-group--end { margin-left: 0; }
                        .website-toolbar .website-address {
                            min-width: 0;
                            width: 100%;
                        }
                        .website-toolbar [data-website-action="open"] > span {
                            clip-path: inset(50%);
                            height: 1px;
                            overflow: hidden;
                            position: absolute;
                            white-space: nowrap;
                            width: 1px;
                        }
                    }
                    /* The address: one rounded field with a mark in front, as a browser's is. */
                    .website-toolbar-address { position: relative; }
                    .website-toolbar .website-address:not([type="checkbox"]):not([type="radio"]) {
                        background: var(--surface-2);
                        border-color: transparent;
                        border-radius: 999px;
                        font-size: 14px;
                        min-height: 36px;
                        padding: 6px 14px 6px 36px;
                    }
                    .website-toolbar .website-address:not([type="checkbox"]):not([type="radio"]):hover { border-color: var(--line); }
                    .website-toolbar .website-address:not([type="checkbox"]):not([type="radio"]):focus { background: var(--surface); border-color: var(--accent); }
                    .website-address-mark { color: var(--muted); display: inline-flex; left: 12px; pointer-events: none; position: absolute; top: 50%; transform: translateY(-50%); z-index: 1; }
                    .website-address-mark .icon { height: 15px; width: 15px; }
                    .website-address-lock, .is-secure .website-address-globe { display: none; }
                    .is-secure .website-address-lock { color: var(--accent); display: inline-flex; }
                    .website-address-globe { display: inline-flex; }
                    /* The buttons beside it: marks without a frame, until the pointer is on them. */
                    .website-tool-button {
                        align-items: center;
                        background: transparent;
                        border: 1px solid transparent;
                        border-radius: 10px;
                        box-shadow: none;
                        color: var(--muted);
                        cursor: pointer;
                        display: inline-flex;
                        gap: 7px;
                        justify-content: center;
                        min-height: 36px;
                        min-width: 36px;
                        padding: 4px 8px;
                    }
                    .website-tool-button:hover {
                        background: var(--hover-bg);
                        color: var(--text);
                    }
                    .website-tool-button:disabled { opacity: .4; }
                    /* "Open in a new tab" is its mark; the words are its title. */
                    .website-toolbar [data-website-action="open"] > span {
                        clip-path: inset(50%);
                        height: 1px;
                        overflow: hidden;
                        position: absolute;
                        white-space: nowrap;
                        width: 1px;
                    }
                    .website-frame {
                        border: 0;
                        flex: 1;
                        min-height: 0;
                        width: 100%;
                    }
                    /* An empty browser: a start page where the website will be. */
                    .website-shell--blank .website-frame { display: none; }
                    .website-start {
                        background: var(--bg);
                        display: grid;
                        flex: 1 1 auto;
                        min-height: 0;
                        overflow-y: auto;
                        padding: 32px 18px;
                        place-items: start center;
                    }
                    .website-start[hidden] { display: none; }
                    .website-start-box { display: grid; gap: 10px; justify-items: center; margin-top: min(9vh, 80px); max-width: 640px; text-align: center; width: 100%; }
                    .website-start-icon {
                        align-items: center;
                        background: color-mix(in srgb, var(--accent) 12%, var(--surface));
                        border-radius: 20px;
                        color: var(--accent);
                        display: inline-flex;
                        height: 68px;
                        justify-content: center;
                        width: 68px;
                    }
                    .website-start-icon .icon { height: 32px; width: 32px; }
                    .website-start-box h2 { font-size: 24px; margin: 6px 0 0; }
                    .website-start-box > p { line-height: 1.55; margin: 0; max-width: 46ch; }
                    .website-start-group { display: grid; gap: 8px; justify-items: stretch; margin-top: 18px; text-align: left; width: 100%; }
                    .website-start-group[hidden] { display: none; }
                    .website-start-group h3 { color: var(--muted); font-size: 12px; font-weight: 700; letter-spacing: .04em; margin: 0; text-transform: uppercase; }
                    .website-start-list { display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
                    .website-start-entry {
                        align-items: center;
                        background: var(--surface);
                        border: 1px solid var(--line);
                        border-radius: var(--radius);
                        display: flex;
                        gap: 12px;
                        justify-content: flex-start;
                        min-height: 52px;
                        padding: 8px 12px;
                        text-align: left;
                        width: 100%;
                    }
                    .website-start-entry:hover { border-color: var(--accent); }
                    .website-start-entry-icon {
                        align-items: center;
                        background: var(--surface-2);
                        border-radius: 10px;
                        color: var(--accent);
                        display: inline-flex;
                        flex: 0 0 auto;
                        height: 34px;
                        justify-content: center;
                        width: 34px;
                    }
                    .website-start-entry-icon .icon { height: 17px; width: 17px; }
                    .website-start-entry-text { display: grid; min-width: 0; }
                    .website-start-entry-text strong, .website-start-entry-text small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
                    .website-start-entry-text small { color: var(--muted); font-size: 12px; font-weight: 400; }
                    .website-start-clear { background: transparent; border: 0; box-shadow: none; color: var(--muted); font-size: 12.5px; justify-self: start; min-height: 32px; padding: 0 2px; text-decoration: underline; }
                    /* Read-only: away with everything that wants to write. Create, upload, the queue
                       for it, and in the action menu move and delete - copy and download stay, those
                       only take something out. */
                    .file-display--readonly .file-create-menu,
                    .file-display--readonly .file-upload-button,
                    .file-display--readonly .file-upload-queue-toggle,
                    .file-display--readonly .file-upload-queue-shell,
                    .file-display--readonly [data-file-action="move"],
                    .file-display--readonly [data-file-action="delete-selected"],
                    .file-display--readonly [data-file-action="rename"],
                    .file-display--readonly .file-action-delete,
                    .file-display--readonly .file-action-unzip,
                    .file-display--readonly [data-file-action="delete"] { display: none; }
                    .file-display {
                        background: var(--surface);
                        color: var(--text);
                        height: 100%;
                        overflow: hidden;
                        width: 100%;
                    }
                    .file-manager {
                        display: flex;
                        flex-direction: column;
                        gap: 0;
                        height: 100%;
